window.YC_MORE_QBANKS=window.YC_MORE_QBANKS||[];window.YC_MORE_QBANKS.push([{"id":"zz-30301","module":"zhengzhi","prompt":"哲学的基本派别划分为唯物主义和唯心主义，其划分标准是：","options":["是否承认世界是发展的","是否承认实践是认识的基础","是否承认世界的统一性","对思维和存在何者为第一性的不同回答"],"answer":3,"explanation":"划分唯物主义和唯心主义的唯一标准是对思维和存在何者为第一性的不同回答：凡主张存在第一性、思维第二性的是唯物主义，反之是唯心主义。是否承认世界统一性、是否承认发展均不是划分两大派别的标准，故选D。","__sub":"马原"},{"id":"zz-30302","module":"zhengzhi","prompt":"「心外无物，心外无理」这一命题在哲学上属于：","options":["古代朴素唯物主义","主观唯心主义","客观唯心主义","近代形而上学唯物主义"],"answer":1,"explanation":"「心外无物，心外无理」把人的「心」当作世界的本原，认为事物依赖于人的主观精神而存在，属于典型的主观唯心主义。客观唯心主义把「理」归结为独立于人之外的客观精神，与该命题把理系于心不同，故选B。","__sub":"马原"},{"id":"zz-30303","module":"zhengzhi","prompt":"「道生一，一生二，二生三，三生万物」这一观点在哲学上属于：","options":["主观唯心主义","古代朴素唯物主义","客观唯心主义","辩证唯物主义"],"answer":2,"explanation":"该命题把「道」这种独立于人的意识之外的客观精神当作世界万物的本原，属于客观唯心主义。古代朴素唯物主义以某种具体物质形态为本原，与此不同；主观唯心主义以人的主观精神为本原，也与此不同，故选C。","__sub":"马原"},{"id":"zz-30304","module":"zhengzhi","prompt":"「气者，理之依也」这一命题体现的哲学立场是：","options":["客观唯心主义","形而上学唯物主义","古代朴素唯物主义","不可知论"],"answer":2,"explanation":"「气者，理之依也」认为「理」依赖于「气」而存在，即精神依赖于物质，以「气」这种具体物质形态作为世界本原，属于古代朴素唯物主义。客观唯心主义主张理在气先，与此相反，故选C。","__sub":"马原"},{"id":"zz-30305","module":"zhengzhi","prompt":"近代形而上学唯物主义的局限性之一是用孤立、静止的观点看问题，其另一个重要缺陷是：","options":["否认世界的可知性","把世界本原归结为某种具体物质形态","具有机械性和不彻底性，在历史观上陷入唯心主义","否认世界的物质性"],"answer":2,"explanation":"近代形而上学唯物主义以机械力学解释一切，具有机械性，并把自然科学意义上的原子当作本原，且在历史观上仍是唯心主义的，即「半截子唯物主义」。它并不否认世界物质性，把本原归结为具体物质形态的是古代朴素唯物主义，故选C。","__sub":"马原"},{"id":"zz-30306","module":"zhengzhi","prompt":"运动是物质的根本属性，是指：","options":["运动是物质的存在方式和根本属性","物质是运动的形式和表现","静止是运动的特殊状态这一说法是错误的","运动是物质的唯一特性"],"answer":0,"explanation":"运动是物质的存在方式和根本属性，物质都是运动着的物质，脱离运动的物质是不存在的。物质的唯一特性是客观实在性而非运动；静止确实是运动的特殊状态，该说法本身成立，C、D均错误，故选A。","__sub":"马原"},{"id":"zz-30307","module":"zhengzhi","prompt":"「人一次也不能踏进同一条河流」这一命题的错误在于：","options":["夸大了相对静止，否认了绝对运动","否认了物质运动的客观性","把运动归结为外力推动","夸大了绝对运动，否认了相对静止"],"answer":3,"explanation":"该命题只承认河流的绝对运动而否认相对静止的存在，夸大运动否认静止，会导致相对主义诡辩论。夸大静止否认运动是形而上学不变论，方向正好相反，故选D。","__sub":"马原"},{"id":"zz-30308","module":"zhengzhi","prompt":"「风定花犹落，鸟鸣山更幽」这一诗句体现的哲学道理是：","options":["实践与认识的统一","内因与外因的统一","绝对运动与相对静止的统一","矛盾的普遍性与特殊性的统一"],"answer":2,"explanation":"「风定」是相对静止，「花犹落」是绝对运动；「鸟鸣」是动，「山更幽」以动衬静，整句体现了绝对运动与相对静止的辩证统一。题干未涉及矛盾普遍性特殊性、实践认识或内外因关系，故选C。","__sub":"马原"},{"id":"zz-30309","module":"zhengzhi","prompt":"时间和空间是物质运动的存在形式，这一命题表明：","options":["物质运动的内在环节","物质运动的唯一原因","人感知世界的先验形式","物质运动的存在形式"],"answer":3,"explanation":"时间和空间是物质运动的存在形式：时间是物质运动的持续性和顺序性，空间是物质运动的广延性和方位性，二者都离不开物质运动。时间空间不是独立于物质之外的容器，也不是人的先验形式，故选D。","__sub":"马原"},{"id":"zz-30310","module":"zhengzhi","prompt":"「机不可失，时不再来」这句俗语强调的是：","options":["空间的广延性","物质的统一性","时间的客观性","时间的不可逆性"],"answer":3,"explanation":"时间的特点是一维性即不可逆性，时间流逝一去不返，「机不可失，时不再来」正是强调时间一去不复返、要珍惜时机的不可逆性。题干未涉及空间广延性，也未直接强调时间的客观性或物质统一性，故选D。","__sub":"马原"},{"id":"zz-30311","module":"zhengzhi","prompt":"「天行有常，不为尧存，不为桀亡」这一命题表明：","options":["人不能认识和利用规律","规律的客观性不以人的意志为转移","自然规律与人无关","社会发展没有规律可循"],"answer":1,"explanation":"该命题指出自然界的运行有其固有规律，不因统治者的好坏而改变，说明规律的客观性不以人的意志为转移。规律是客观的但人可以认识和利用它，「与人无关」「无规律」均属错误表述，故选B。","__sub":"马原"},{"id":"zz-30312","module":"zhengzhi","prompt":"「揠苗助长」这一寓言违背的哲学原理是：","options":["规律具有客观性，发挥主观能动性必须尊重规律","矛盾具有普遍性","物质决定意识","意识具有能动作用"],"answer":0,"explanation":"禾苗生长有其自身规律，「揠苗助长」违背规律强行加速生长，说明发挥主观能动性必须以尊重客观规律为前提，否则会受到规律的惩罚。题干强调的是能动性与规律的关系，而非物质与意识或矛盾普遍性问题，故选A。","__sub":"马原"},{"id":"zz-30313","module":"zhengzhi","prompt":"「草木无情，有时飘零」与「人有悲欢离合」的对比说明，意识是：","options":["独立于物质之外的精神实体","客观内容与主观形式的统一","一切物质都具有的属性","人脑的分泌物"],"answer":1,"explanation":"意识是人脑的机能，是对客观存在的反映，其内容来自客观世界，形式是主观的，是客观内容与主观形式的统一。意识不是人脑的分泌物（那是庸俗唯物论），也不是一切物质都具有的属性，故选B。","__sub":"马原"},{"id":"zz-30314","module":"zhengzhi","prompt":"「仁者见仁，智者见智」这一说法表明：","options":["客观事物随人的认识而改变","意识是主观自生的","认识没有客观标准","同一客观内容在不同主体那里的反映具有差异性"],"answer":3,"explanation":"「仁者见仁，智者见智」说明认识受主体立场、知识结构、思维方式等影响，对同一对象的反映会有差异，体现了意识形式的主观性，但内容仍来自客观。它不表明意识主观自生、事物随认识改变或认识无客观标准，故选D。","__sub":"马原"},{"id":"zz-30315","module":"zhengzhi","prompt":"「日有所思，夜有所梦」这一现象说明：","options":["梦的内容归根到底来源于客观现实","意识可以脱离物质而存在","梦境是独立于意识的客观存在","梦是超自然的启示"],"answer":0,"explanation":"「日有所思」表明梦是睡眠中大脑对日常所思所感的加工，其素材归根到底来源于客观现实生活。梦不是客观存在本身，更不是超自然启示，意识也不能脱离物质，故选A。","__sub":"马原"},{"id":"zz-30316","module":"zhengzhi","prompt":"人工智能可以模拟人的部分思维活动，这表明：","options":["意识活动可以完全还原为物理过程","人工智能已经全面超越人类思维","思维是人脑的机能，人工智能只是对人类思维的模拟","人工智能与人类思维在本质上相同"],"answer":2,"explanation":"人工智能在特定领域能模拟和延伸人的部分思维功能，但它是人制造的机器对人类思维的模拟，不具有人类意识的社会性、创造性等本质特征，不能全面超越人类思维，与人类思维有本质区别，故选C。","__sub":"马原"},{"id":"zz-30317","module":"zhengzhi","prompt":"「坐地日行八万里，巡天遥看一千河」这一诗句蕴含的哲理是：","options":["量变与质变的统一","现象与本质的统一","原因与结果的统一","绝对运动与相对静止的统一"],"answer":3,"explanation":"人「坐地」是相对静止，而随地球自转「日行八万里」是绝对运动，诗句生动体现了绝对运动与相对静止的辩证统一。题干不涉及量变质变、现象本质或因果关系，故选D。","__sub":"马原"},{"id":"zz-30318","module":"zhengzhi","prompt":"「动中有静，静中有动」这一命题说明：","options":["静止是运动的根本属性","运动和静止没有区别","运动是相对的，静止是绝对的","运动和静止相互包含，绝对运动中有相对静止"],"answer":3,"explanation":"「动中有静，静中有动」说明绝对运动中包含相对静止，相对静止中包含绝对运动，二者相互包含、相互依赖。静止不是运动的根本属性（运动才是），运动是绝对的、静止是相对的，B、C、D均错误，故选D。","__sub":"马原"},{"id":"zz-30319","module":"zhengzhi","prompt":"「刻舟求剑」这一寓言在哲学上的错误在于：","options":["否认了意识的能动作用","否认了运动的绝对性，用静止观点看问题","否认了矛盾的普遍性","夸大了意识的能动作用"],"answer":1,"explanation":"船已行而剑未动，「刻舟求剑」以静止的观点看待运动变化的事物，否认了运动的绝对性，是形而上学不变论的典型。题干不涉及意识能动作用或矛盾普遍性问题，故选B。","__sub":"马原"},{"id":"zz-30320","module":"zhengzhi","prompt":"「人定胜天」这一命题的合理之处在于肯定了：","options":["人可以随意支配自然","自然规律服从人的意志","规律可以被人改变","意识的能动作用"],"answer":3,"explanation":"「人定胜天」的合理内核是肯定了人的意识具有能动作用，人可以认识和利用规律改造世界。但它若被理解为随意支配自然、改变规律，则夸大了能动性；规律是客观的，不能被人改变或服从人的意志，故选D。","__sub":"马原"},{"id":"zz-30321","module":"zhengzhi","prompt":"「唇亡齿寒」这一成语体现的哲学道理是：","options":["矛盾具有特殊性","事物是变化发展的","认识对实践具有反作用","事物是普遍联系的"],"answer":3,"explanation":"嘴唇与牙齿相互依存，唇亡则齿寒，说明事物之间存在相互影响、相互制约的关系，体现了联系的普遍性。题干不涉及发展、矛盾特殊性或认识反作用，故选D。","__sub":"马原"},{"id":"zz-30322","module":"zhengzhi","prompt":"「牵一发而动全身」这一说法说明：","options":["部分离不开整体，整体也离不开部分这一说法不成立","整体与部分没有区别","整体功能等于部分功能之和","关键部分对整体功能起决定作用"],"answer":3,"explanation":"「牵一发而动全身」说明在特定条件下，关键部分的变化会对整体功能产生决定性影响，要求我们重视关键部分。整体功能不等于部分功能之和（可能大于或小于），整体与部分相互依存、有严格区别，故选D。","__sub":"马原"},{"id":"zz-30323","module":"zhengzhi","prompt":"「花在树则生，离枝则死」这一比喻说明：","options":["部分依赖于整体，脱离整体的部分就失去其原来的意义","整体是部分的简单相加","部分的变化一定引起整体的变化","整体依赖于部分而存在"],"answer":0,"explanation":"花离开树便失去生机，说明部分是整体中的部分，脱离整体的部分就失去其作为该部分的功能和意义，体现了部分对整体的依赖性。题干强调的是部分离不开整体，而非整体依赖部分或部分简单相加，故选A。","__sub":"马原"},{"id":"zz-30324","module":"zhengzhi","prompt":"「一叶障目，不见泰山」这一成语启示我们：","options":["要重视量的积累","要重视内因的作用","要用联系的、全面的观点看问题","要抓住主要矛盾"],"answer":2,"explanation":"「一叶障目，不见泰山」讽刺只见局部不见整体的片面观点，启示我们要用联系的、全面的观点看问题，反对孤立地、片面地看问题。题干不涉及内外因、主要矛盾或量的积累，故选C。","__sub":"马原"},{"id":"zz-30325","module":"zhengzhi","prompt":"「士别三日，即更刮目相待」与「用发展的眼光看问题」相一致，而与之相对立的错误观点是：","options":["相对主义诡辩论","庸俗进化论","不可知论","形而上学的不变论"],"answer":3,"explanation":"「刮目相待」承认事物是变化发展的，与之相对立的错误观点是否认发展、用静止眼光看问题的形而上学不变论。相对主义诡辩论夸大运动否认静止，庸俗进化论否认质变，均与题干方向不同，故选D。","__sub":"马原"},{"id":"zz-30326","module":"zhengzhi","prompt":"「千里之堤，溃于蚁穴」这一成语体现的哲学道理是：","options":["矛盾是事物发展的动力","质变是量变的必然结果，小问题积累会酿成大祸","现象是本质的外部表现","事物发展是前进性与曲折性的统一"],"answer":1,"explanation":"蚁穴虽小，积累到一定程度会导致大堤溃决，说明量变积累到一定程度必然引起质变，启示我们重视量的积累、防微杜渐。题干不涉及矛盾动力、前进性曲折性或现象本质，故选B。","__sub":"马原"},{"id":"zz-30327","module":"zhengzhi","prompt":"「行百里者半九十」这一古语蕴含的哲理是：","options":["质变是量变的总和","事物发展是循环往复的","量变达到一定程度才能引起质变，最后阶段尤为关键","量变与质变没有区别"],"answer":2,"explanation":"走一百里路走到九十里才算走了一半，说明越接近质变越不能松懈，量变必须积累到一定程度才能引起质变，最后阶段尤为关键。事物发展不是循环往复，质变也不是量变的简单总和，故选C。","__sub":"马原"},{"id":"zz-30328","module":"zhengzhi","prompt":"「破茧成蝶」的过程说明，质变是：","options":["事物数量的增减和位置的移动","事物数量的增减","事物根本性质的变化","事物位置的移动"],"answer":2,"explanation":"质变是事物根本性质的变化，是事物由一种质态向另一种质态的飞跃，如毛毛虫破茧成蝶。数量的增减和位置的移动属于量变而非质变，故选C。","__sub":"马原"},{"id":"zz-30329","module":"zhengzhi","prompt":"「勿以恶小而为之，勿以善小而不为」这一古训的哲学依据是：","options":["意识对物质具有反作用","量变积累到一定程度会引起质变","矛盾双方相互转化","实践是认识的来源"],"answer":1,"explanation":"小恶小善看似无关紧要，但不断积累会引起人的品行的质变，其哲学依据是量变积累到一定程度必然引起质变，要求我们重视量的积累。题干不涉及矛盾转化、意识反作用或实践认识关系，故选B。","__sub":"马原"},{"id":"zz-30330","module":"zhengzhi","prompt":"「物极必反」这一命题体现的哲学道理是：","options":["矛盾双方相互排斥","量变与质变没有关系","事物发展是直线前进的","矛盾双方在一定条件下相互转化"],"answer":3,"explanation":"「物极必反」说明事物发展到极端会向相反方向转化，体现了矛盾双方在一定条件下相互转化的原理。矛盾双方还有相互依存的一面，事物发展是螺旋式上升而非直线前进，量变质变密切相关，故选D。","__sub":"马原"},{"id":"zz-30331","module":"zhengzhi","prompt":"「祸兮福之所倚，福兮祸之所伏」这一命题说明：","options":["矛盾双方相互依存并在一定条件下相互转化","矛盾双方绝对对立","矛盾不可调和","祸福由天注定"],"answer":0,"explanation":"老子这句话指出祸与福相互依存，并在一定条件下相互转化，体现了矛盾双方既对立又统一的辩证关系。矛盾双方不是绝对对立，祸福也不是天定，矛盾在一定条件下可以解决，故选A。","__sub":"马原"},{"id":"zz-30332","module":"zhengzhi","prompt":"「世异则事异，事异则备变」这一观点表明：","options":["规律因人而异","要用发展的观点看问题，根据变化了的实际调整对策","矛盾具有普遍性","认识决定实践"],"answer":1,"explanation":"时代变化则事情随之变化，事情变化则措施也要调整，说明要用发展的观点看问题，一切以时间、地点、条件为转移，根据变化了的实际调整对策。题干不涉及矛盾普遍性，认识决定实践是错误表述，规律也不因人而异，故选B。","__sub":"马原"},{"id":"zz-30333","module":"zhengzhi","prompt":"「沧海桑田」这一成语蕴含的哲学道理是：","options":["事物是绝对静止的","联系是主观的","事物是变化发展的，发展具有普遍性","矛盾具有特殊性"],"answer":2,"explanation":"「沧海桑田」形容自然界发生巨大变化，说明事物是变化发展的，发展的观点要求我们用变化的眼光看待事物。题干不涉及矛盾特殊性，联系是客观的而非主观的，故选C。","__sub":"马原"},{"id":"zz-30334","module":"zhengzhi","prompt":"「量体裁衣」「因材施教」共同体现的哲学道理是：","options":["具体问题具体分析，矛盾具有特殊性","事物是普遍联系的","矛盾具有普遍性","实践决定认识"],"answer":0,"explanation":"「量体裁衣」「因材施教」都强调根据对象的具体情况采取相应办法，体现了矛盾的特殊性要求具体问题具体分析。题干不涉及矛盾普遍性、普遍联系或实践认识关系，故选A。","__sub":"马原"},{"id":"zz-30335","module":"zhengzhi","prompt":"「对症下药」与「量体裁衣」体现的哲学道理是：","options":["矛盾具有普遍性","主要矛盾决定事物发展进程","矛盾具有特殊性，要具体问题具体分析","内因是事物发展的根本原因"],"answer":2,"explanation":"「对症下药」「量体裁衣」都强调针对不同对象采取不同办法，体现矛盾的特殊性要求具体问题具体分析。题干不涉及主要矛盾或内外因问题，故选C。","__sub":"马原"},{"id":"zz-30336","module":"zhengzhi","prompt":"「眉毛胡子一把抓」这一做法在哲学上的错误在于：","options":["否认了联系的多样性","否认了矛盾的普遍性","夸大了意识的能动作用","没有抓住主要矛盾，不分主次"],"answer":3,"explanation":"在复杂事物的诸多矛盾中，主要矛盾处于支配地位、对事物发展起决定作用，「眉毛胡子一把抓」不分主次，没有抓住主要矛盾。题干不涉及矛盾普遍性、联系多样性或意识能动作用，故选D。","__sub":"马原"},{"id":"zz-30337","module":"zhengzhi","prompt":"「擒贼先擒王」这一做法体现的哲学道理是：","options":["矛盾双方相互转化","抓主要矛盾，抓重点，抓关键","量变引起质变","具体问题具体分析"],"answer":1,"explanation":"「擒贼先擒王」说明解决问题要抓住主要矛盾、抓住重点和关键，主要矛盾对事物发展起决定作用，抓住了它其他矛盾就容易解决。题干不涉及矛盾转化、量变质变或具体问题具体分析，故选B。","__sub":"马原"},{"id":"zz-30338","module":"zhengzhi","prompt":"「一个篱笆三个桩，一个好汉三个帮」这一俗语说明：","options":["量变与质变的统一","矛盾双方相互转化","外因是事物发展的条件","内因是事物发展的根本原因"],"answer":2,"explanation":"好汉再能干也需要他人帮助，说明外因是事物变化发展的条件，对事物发展起加速或延缓作用。内因是根本原因，题干强调的是外部帮助，不涉及矛盾转化或量变质变，故选C。","__sub":"马原"},{"id":"zz-30339","module":"zhengzhi","prompt":"「近朱者赤，近墨者黑」与「出淤泥而不染」分别强调：","options":["外因决定事物的发展方向","外因是变化的条件，内因是变化的根据","内因和外因都不重要","内因和外因同等重要"],"answer":1,"explanation":"「近朱者赤，近墨者黑」强调外部环境的影响，说明外因是变化的条件；「出淤泥而不染」强调内在品质的决定作用，说明内因是变化的根据，外因通过内因起作用。二者结合说明内因是根据、外因是条件，故选B。","__sub":"马原"},{"id":"zz-30340","module":"zhengzhi","prompt":"「塞翁失马，焉知非福」这一典故体现的哲学道理是：","options":["矛盾双方绝对对立","内因与外因相互独立","事物发展是直线的","矛盾双方在一定条件下相互转化"],"answer":3,"explanation":"「塞翁失马」说明祸与福相互依存并在一定条件下相互转化，好事可以变坏事，坏事也可以变好事，体现了矛盾双方相互转化的原理。矛盾双方不是绝对对立，发展也不是直线式的，故选D。","__sub":"马原"},{"id":"zz-30341","module":"zhengzhi","prompt":"「纸上得来终觉浅，绝知此事要躬行」这一诗句强调：","options":["认识对实践具有反作用","读书无用","实践是认识的来源","认识可以脱离实践"],"answer":2,"explanation":"「纸上得来」是间接经验，「躬行」是亲身实践，诗句强调要真正理解事物必须亲自实践，体现了实践是认识的来源。题干不涉及认识反作用，认识不能脱离实践，诗句也不是否定读书，故选C。","__sub":"马原"},{"id":"zz-30342","module":"zhengzhi","prompt":"「实践、认识、再实践、再认识」这一过程说明：","options":["认识是循环往复的","实践与认识相互脱离","认识是一次完成的","认识运动是反复上升的过程"],"answer":3,"explanation":"认识运动从实践到认识、再从认识到实践，循环往复以至无穷，而每一次循环都进到高一级程度，说明认识是反复上升、不断深化的过程，不是一次完成也不是简单循环，故选D。","__sub":"马原"},{"id":"zz-30343","module":"zhengzhi","prompt":"真理的客观性是指：","options":["真理是权威人士的论断","真理是多数人承认的认识","真理因人而异","真理的内容是客观的，检验标准也是客观的"],"answer":3,"explanation":"真理的客观性指真理的内容是客观的（反映客观事物及其规律），检验真理的标准（实践）也是客观的。真理不因多数人承认、权威论断或个人差异而改变其客观性，故选D。","__sub":"马原"},{"id":"zz-30344","module":"zhengzhi","prompt":"「真理向前多走一步，哪怕是同一方向，也会变成谬误」这一命题说明：","options":["真理是有条件的，超出适用范围就会变成谬误","真理和谬误没有区别","真理会自动变成谬误","谬误是真理的来源"],"answer":0,"explanation":"任何真理都有自己特定的适用范围和条件，超出这个范围哪怕方向相同也会变成谬误，说明真理是有条件的、具体的。真理和谬误有本质区别，谬误不是真理的来源，故选A。","__sub":"马原"},{"id":"zz-30345","module":"zhengzhi","prompt":"「实践是检验真理的唯一标准」，这是因为：","options":["实践是认识的目的","实践具有社会历史性","实践具有直接现实性","实践是人的有目的的活动"],"answer":2,"explanation":"实践之所以是检验真理的唯一标准，是因为实践具有直接现实性，能把主观认识同客观实际联系起来加以对照，使认识得到现实的检验。社会历史性、目的性是实践的特点但不是原因，实践是认识的目的与检验标准是两个问题，故选C。","__sub":"马原"},{"id":"zz-30346","module":"zhengzhi","prompt":"「真理和谬误相比较而存在，相斗争而发展」这一命题说明：","options":["真理和谬误可以相互替代","真理和谬误没有本质区别","谬误可以脱离真理而存在","真理和谬误相互依存，并在斗争中发展"],"answer":3,"explanation":"真理和谬误是认识中的一对矛盾，二者相互依存（相比较而存在），并在斗争中发展（相斗争而发展）。二者有本质区别，不能相互替代，谬误也不能脱离真理而孤立存在，故选D。","__sub":"马原"},{"id":"zz-30347","module":"zhengzhi","prompt":"「社会生活在本质上是实践的」这一命题的提出者是：","options":["毛泽东","恩格斯","马克思","列宁"],"answer":2,"explanation":"「社会生活在本质上是实践的」出自马克思《关于费尔巴哈的提纲》，是马克思主义哲学关于社会本质的重要论断，强调实践是社会生活的基础。恩格斯、列宁、毛泽东均非该命题的提出者，故选C。","__sub":"马原"},{"id":"zz-30348","module":"zhengzhi","prompt":"「历史是任人打扮的小姑娘」这一观点的错误在于：","options":["否认了历史事实的客观性","否认了历史的发展性","否认了人的主观能动性","夸大了历史规律的作用"],"answer":0,"explanation":"该观点认为历史可以随意解释和涂抹，否认了历史事实的客观性，属于历史唯心主义的相对主义倾向。历史事实是客观存在的，不以人的主观解释而改变，题干不涉及历史发展性或规律问题，故选A。","__sub":"马原"},{"id":"zz-30349","module":"zhengzhi","prompt":"「时势造英雄」这一观点在历史观上强调：","options":["英雄人物决定历史发展方向","英雄人物的出现是历史条件的产物","历史发展没有规律","英雄人物可以超越历史条件"],"answer":1,"explanation":"「时势造英雄」说明英雄人物的出现是特定历史条件的产物，时势即历史条件造就英雄，体现了历史唯物主义关于个人作用受历史条件制约的观点。英雄不能决定历史方向、超越历史条件，历史发展有规律，故选B。","__sub":"马原"},{"id":"zz-30350","module":"zhengzhi","prompt":"「人民，只有人民，才是创造世界历史的动力」这一论断表明：","options":["英雄人物推动历史发展","人民群众的创造不受历史条件制约","历史由杰出人物主导","人民群众是历史的创造者"],"answer":3,"explanation":"该论断明确指出人民群众是历史的创造者，是社会物质财富、精神财富的创造者和社会变革的决定力量。英雄史观是唯心主义的，人民群众的创造活动也受历史条件制约，故选D。","__sub":"马原"},{"id":"zz-30351","module":"zhengzhi","prompt":"「仓廪实而知礼节，衣食足而知荣辱」这一古语蕴含的哲理是：","options":["社会存在决定社会意识","生产力决定生产关系","意识具有相对独立性","社会意识决定社会存在"],"answer":0,"explanation":"粮仓充实、衣食充足（社会存在）才会懂得礼节荣辱（社会意识），说明社会存在决定社会意识。题干不涉及社会意识决定社会存在（那是唯心史观），也未直接涉及意识相对独立性或生产力生产关系，故选A。","__sub":"马原"},{"id":"zz-30352","module":"zhengzhi","prompt":"「经济上落后的国家在哲学上仍然能够演奏第一提琴」这一论断说明：","options":["社会意识具有相对独立性，可能先于社会存在而发展","哲学与社会存在无关","经济发展水平决定哲学水平","社会意识决定社会存在"],"answer":0,"explanation":"恩格斯这一论断说明社会意识具有相对独立性，其发展与社会存在的发展不完全同步，经济落后的国家在思想理论上可能领先。社会意识归根到底由社会存在决定，但不是机械对应，故选A。","__sub":"马原"},{"id":"zz-30353","module":"zhengzhi","prompt":"「手推磨产生的是封建主的社会，蒸汽磨产生的是工业资本家的社会」这一论断说明：","options":["社会制度与生产工具无关","生产工具决定一切社会制度","生产工具是生产力发展水平的标志，生产力决定生产关系","生产关系决定生产力"],"answer":2,"explanation":"马克思这一论断说明生产工具是生产力发展水平的主要标志，有什么样的生产力就有什么样的生产关系，生产力决定生产关系。生产工具不能「决定一切」，生产关系也不能决定生产力，故选C。","__sub":"马原"},{"id":"zz-30354","module":"zhengzhi","prompt":"「不是人们的意识决定人们的存在，相反，是人们的社会存在决定人们的意识」这一论断的提出者是：","options":["黑格尔","恩格斯","列宁","马克思"],"answer":3,"explanation":"这一论断出自马克思《〈政治经济学批判〉序言》，是历史唯物主义关于社会存在决定社会意识的经典表述。恩格斯、列宁均非该论断的原始出处，黑格尔是唯心主义者，故选D。","__sub":"马原"},{"id":"zz-30355","module":"zhengzhi","prompt":"「上层建筑一旦形成，就具有相对独立性」这一命题说明：","options":["上层建筑对经济基础具有反作用","上层建筑可以脱离经济基础而独立存在","经济基础决定上层建筑这一说法不成立","上层建筑与经济基础无关"],"answer":0,"explanation":"上层建筑具有相对独立性，能反作用于经济基础，先进的上层建筑促进经济基础发展，落后的则阻碍。上层建筑不能脱离经济基础独立存在，经济基础决定上层建筑的原理依然成立，故选A。","__sub":"马原"},{"id":"zz-30356","module":"zhengzhi","prompt":"「人们首先必须吃、喝、住、穿，然后才能从事政治、科学、艺术、宗教等活动」这一论断说明：","options":["物质生产活动是社会存在和发展的基础","人的需要决定社会发展","精神生产与物质生产无关","政治活动决定经济活动"],"answer":0,"explanation":"恩格斯这一论断说明物质资料的生产活动是社会存在和发展的基础，人们必须先解决吃穿住等物质生活问题才能从事政治、科学等精神活动。政治不能决定经济，精神生产以物质生产为基础，故选A。","__sub":"马原"},{"id":"zz-30357","module":"zhengzhi","prompt":"「阶级斗争是阶级社会发展的直接动力」这一论断表明：","options":["社会基本矛盾在阶级社会中通过阶级斗争表现出来并推动社会发展","阶级斗争是社会发展的根本动力","阶级斗争贯穿一切社会形态","阶级斗争可以解决一切社会问题"],"answer":0,"explanation":"社会基本矛盾（生产力与生产关系、经济基础与上层建筑的矛盾）在阶级社会中表现为阶级矛盾，通过阶级斗争推动社会发展。社会发展的根本动力是社会基本矛盾而非阶级斗争，阶级斗争只存在于阶级社会，故选A。","__sub":"马原"},{"id":"zz-30358","module":"zhengzhi","prompt":"「改革是社会主义制度的自我完善和发展」这一论断说明：","options":["改革可以解决一切社会矛盾","改革是社会主义社会发展的直接动力","改革是推翻社会主义制度的革命","改革与社会主义制度无关"],"answer":1,"explanation":"改革是在坚持社会主义基本制度前提下，调整生产关系中不适应生产力的方面和环节，是社会主义制度的自我完善和发展，是社会主义社会发展的直接动力。改革不是推翻制度本身，也不能解决一切矛盾，故选B。","__sub":"马原"},{"id":"zz-30359","module":"zhengzhi","prompt":"「人的本质不是单个人所固有的抽象物，在其现实性上，它是一切社会关系的总和」这一论断的提出者是：","options":["费尔巴哈","恩格斯","马克思","黑格尔"],"answer":2,"explanation":"这一论断出自马克思《关于费尔巴哈的提纲》，指出人的本质在其现实性上是一切社会关系的总和，强调人的社会性。费尔巴哈把人的本质理解为抽象的类本质，黑格尔则归结为自我意识，故选C。","__sub":"马原"},{"id":"zz-30360","module":"zhengzhi","prompt":"「自由是对必然的认识和对客观世界的改造」这一命题表明：","options":["人永远无法获得自由","自由就是随心所欲","必然与自由绝对对立","自由是认识必然、改造世界的能力和状态"],"answer":3,"explanation":"恩格斯指出自由是对必然的认识和对客观世界的改造，人认识了必然规律并运用它改造世界，就获得了自由。自由不是随心所欲，必然与自由可以统一，人在认识必然的基础上可以获得自由，故选D。","__sub":"马原"},{"id":"zz-30361","module":"zhengzhi","prompt":"「感觉到了的东西，我们不能立刻理解它，只有理解了的东西才能更深刻地感觉它」这一论断说明：","options":["感性认识比理性认识更重要","感性认识有待于发展到理性认识，理性认识又能深化感性认识","理性认识可以脱离感性认识","认识过程只有一次飞跃"],"answer":1,"explanation":"毛泽东这一论断说明感性认识是认识的起点，但必须上升到理性认识才能把握本质；理性认识形成后又能更深刻地指导感性认识，体现了感性认识与理性认识的辩证统一。二者不可相互脱离，认识过程有两次飞跃，故选B。","__sub":"马原"},{"id":"zz-30362","module":"zhengzhi","prompt":"「从群众中来，到群众中去」这一领导方法与认识论原理的对应关系是：","options":["从感性认识到理性认识的过程","从理性认识到感性认识的过程","从认识到实践、从实践到认识的循环上升过程","实践与认识相互脱离的过程"],"answer":2,"explanation":"「从群众中来」是把群众分散的意见集中起来化为系统的认识（实践到认识），「到群众中去」是把认识回到实践中指导实践并接受检验（认识到实践），体现了认识运动的循环上升过程，故选C。","__sub":"马原"},{"id":"zz-30363","module":"zhengzhi","prompt":"「没有革命的理论，就没有革命的运动」这一论断强调：","options":["理论决定实践","理论可以脱离实践","科学理论对实践具有指导作用","实践是理论的来源"],"answer":2,"explanation":"列宁这一论断强调科学理论对实践具有重要的指导作用，先进的理论能指导革命运动取得成功。理论来源于实践但不能脱离实践，理论也不能「决定」实践，故选C。","__sub":"马原"},{"id":"zz-30364","module":"zhengzhi","prompt":"「真理是具体的」这一命题是指：","options":["真理因人而异","真理是主观的","真理都有自己适用的范围和条件","真理是模糊的"],"answer":2,"explanation":"真理的具体性指任何真理都是在一定时间、地点、条件下的真理，有特定的适用范围，离开具体条件真理就会变成谬误。真理是客观的、明确的，不因人而异，故选C。","__sub":"马原"},{"id":"zz-30365","module":"zhengzhi","prompt":"「凡是有利于增强人民获得感的改革就要坚决推进」这一要求体现的哲学道理是：","options":["改革可以脱离人民意愿","改革与人民利益无关","改革由少数人决定","人民群众是历史的创造者，改革要坚持以人民为中心"],"answer":3,"explanation":"改革是否推进以是否有利于增强人民获得感为标准，体现了人民群众是历史的创造者，改革必须坚持以人民为中心的发展思想。改革不能脱离人民意愿，也不是由少数人决定，故选D。","__sub":"马原"},{"id":"zz-30366","module":"zhengzhi","prompt":"「社会形态的发展是一种自然历史过程」这一命题说明：","options":["社会规律与自然规律完全相同","社会发展是自发进行的","社会发展与人的活动无关","社会发展有其客观规律，不以人的意志为转移"],"answer":3,"explanation":"马克思这一论断说明社会形态的发展同自然界一样有其客观规律，不以人的意志为转移。社会发展离不开人的有目的的活动，但整体趋势是客观的；社会规律通过人的活动实现，与自然规律表现形式不同，故选D。","__sub":"马原"},{"id":"zz-30367","module":"zhengzhi","prompt":"「生产力中也包括科学」这一论断表明：","options":["科学技术是生产力中的重要因素","科学决定生产关系","科学可以脱离生产而存在","科学是独立的生产力要素"],"answer":0,"explanation":"马克思指出生产力中包括科学，说明科学技术是生产力中的重要因素，科学技术渗透于生产力各要素之中，转化为现实生产力。科学不是与劳动者、劳动资料、劳动对象并列的独立要素，故选A。","__sub":"马原"},{"id":"zz-30368","module":"zhengzhi","prompt":"「物质可以变成精神，精神可以变成物质」这一命题说明：","options":["精神决定物质","物质与精神是同一的","物质与意识相互独立","物质与意识在实践基础上相互转化"],"answer":3,"explanation":"毛泽东这一论断说明在实践中物质可以转化为精神（认识世界），精神可以转化为物质（改造世界），体现了物质与意识在实践基础上的辩证统一。物质与意识不是相互独立，精神也不决定物质，故选D。","__sub":"马原"},{"id":"zz-30369","module":"zhengzhi","prompt":"「矛盾着的对立面相互依存，互为存在的前提」这一命题说明：","options":["矛盾双方绝对同一","矛盾双方相互依存，一方的存在以另一方的存在为前提","矛盾双方相互脱离","矛盾双方没有区别"],"answer":1,"explanation":"矛盾的同一性指矛盾双方相互依存、相互贯通，一方的存在以另一方的存在为前提，双方共处于一个统一体中。矛盾双方不是相互脱离、绝对同一或没有区别，故选B。","__sub":"马原"},{"id":"zz-30370","module":"zhengzhi","prompt":"「具体问题具体分析」之所以是马克思主义活的灵魂，是因为：","options":["矛盾具有特殊性，只有具体分析才能找到解决矛盾的正确方法","矛盾具有普遍性","矛盾分析可以代替一切方法","矛盾可以自行解决"],"answer":0,"explanation":"矛盾的特殊性要求具体问题具体分析，只有分析矛盾的特殊性才能找到解决矛盾的正确方法，因此列宁称具体地分析具体的情况是马克思主义活的灵魂。矛盾普遍性不构成这一命题的依据，故选A。","__sub":"马原"},{"id":"zz-30371","module":"zhengzhi","prompt":"「两点论」与「重点论」相统一的方法论要求是：","options":["平均用力不分主次","既要全面看问题，又要抓住重点","只抓重点不顾其余","只看全面不抓关键"],"answer":1,"explanation":"「两点论」要求全面看问题，看到主要矛盾和次要矛盾、矛盾的主要方面和次要方面；「重点论」要求抓住主要矛盾和矛盾的主要方面。二者统一，反对只抓重点不顾其余、平均用力或只看全面不抓关键，故选B。","__sub":"马原"},{"id":"zz-30373","module":"zhengzhi","prompt":"「实事求是」中的「是」指的是：","options":["客观事物的内部联系，即规律性","人的主观愿望","书本上的结论","权威人士的观点"],"answer":0,"explanation":"毛泽东对「实事求是」的解释是：「实事」就是客观存在着的一切事物，「是」就是客观事物的内部联系即规律性，「求」就是我们去研究。「是」不是主观愿望、书本结论或权威观点，故选A。","__sub":"马原"},{"id":"zz-30374","module":"zhengzhi","prompt":"「世界是过程的集合体」这一命题表明：","options":["过程与结果无关","发展是循环往复的","事物是永恒不变的","一切事物都处在产生、发展和灭亡的过程中"],"answer":3,"explanation":"恩格斯指出世界不是既成事物的集合体，而是过程的集合体，一切事物都处在生成和灭亡的变化过程中，体现了发展的观点。事物不是永恒不变的，发展也不是简单循环，故选D。","__sub":"马原"},{"id":"zz-30375","module":"zhengzhi","prompt":"「新事物必然战胜旧事物」这一命题的哲学依据是：","options":["新事物符合客观规律，具有强大生命力和远大前途","新事物与旧事物没有联系","新事物数量多于旧事物","新事物是对旧事物的彻底否定"],"answer":0,"explanation":"新事物符合客观规律、代表事物发展方向，具有强大生命力和远大前途，因而必然战胜旧事物。新事物战胜旧事物不靠数量优势，辩证否定是扬弃而非彻底否定，新事物与旧事物有历史联系，故选A。","__sub":"马原"},{"id":"zz-30376","module":"zhengzhi","prompt":"「前途是光明的，道路是曲折的」这一论断说明：","options":["事物发展是一帆风顺的","前进性与曲折性相互对立","事物发展是前进性与曲折性的统一","事物发展是倒退的"],"answer":2,"explanation":"事物发展的总趋势是前进的、上升的，道路是曲折的、迂回的，是前进性与曲折性的统一，要求我们既对未来充满信心又准备走曲折的路。发展不是一帆风顺也不是倒退，二者不是对立关系，故选C。","__sub":"马原"},{"id":"zz-30377","module":"zhengzhi","prompt":"「辩证的否定」的实质是：","options":["全盘继承","扬弃，即既克服又保留","全盘抛弃","简单叠加"],"answer":1,"explanation":"辩证的否定是事物的自我否定，是发展的环节和联系的环节，实质是「扬弃」，即既克服旧事物中消极的东西，又保留其积极的东西。全盘抛弃或全盘继承都是形而上学的否定观，故选B。","__sub":"马原"},{"id":"zz-30378","module":"zhengzhi","prompt":"「绝对运动与相对静止」的关系是：","options":["二者相互对立、互不包含","动中有静、静中有动，二者相互包含","绝对运动可以脱离相对静止","相对静止可以脱离绝对运动"],"answer":1,"explanation":"绝对运动与相对静止是辩证统一的，动中有静、静中有动，任何事物都是绝对运动与相对静止的统一。二者不能相互脱离，也不是对立互不包含的关系，故选B。","__sub":"马原"},{"id":"zz-30379","module":"zhengzhi","prompt":"「一切以条件、地点和转移」这一说法强调：","options":["联系是主观的","联系可以随意创造","联系具有多样性，要具体分析事物之间的各种联系","联系是单一的"],"answer":2,"explanation":"「一切以条件、地点和转移」说明事物的联系是多样的、有条件的，要求我们具体分析事物所处的各种条件，一切以时间、地点、条件为转移。联系是客观的、多样的，不能随意创造，故选C。","__sub":"马原"},{"id":"zz-30380","module":"zhengzhi","prompt":"「整体性」与「部分」的关系是：","options":["整体由部分构成，但整体功能不等于部分功能的简单相加","整体功能等于部分功能之和","整体与部分相互独立","部分决定整体"],"answer":0,"explanation":"整体由部分构成，但各部分以合理结构构成整体时，整体功能大于部分功能之和；结构不合理时可能小于。整体居于主导地位，部分不能决定整体，整体与部分相互依存而非独立，故选A。","__sub":"马原"},{"id":"zz-30381","module":"zhengzhi","prompt":"「本质」与「现象」的关系是：","options":["本质可以脱离现象而存在","本质通过现象表现出来，现象是本质的外部表现","本质与现象无关","现象就是本质"],"answer":1,"explanation":"本质是事物的根本性质和内部联系，现象是本质的外部表现，任何本质都要通过现象表现出来，任何现象都从一定方面表现本质。本质不能脱离现象孤立存在，现象也不等于本质，故选B。","__sub":"马原"},{"id":"zz-30382","module":"zhengzhi","prompt":"「原因」与「结果」的关系是：","options":["原因引起结果，结果反作用于原因，二者在一定条件下相互转化","原因与结果相互独立","结果决定原因","原因与结果没有区别"],"answer":0,"explanation":"因果联系是先行现象引起后行现象的关系，原因引起结果，结果又会反作用于原因，二者在一定条件下相互转化（同一事物在此关系中是因，在彼关系中是果）。因果不能相互独立或混淆，结果也不决定原因，故选A。","__sub":"马原"},{"id":"zz-30383","module":"zhengzhi","prompt":"「必然」与「偶然」的关系是：","options":["偶然决定必然","必然与偶然没有区别","必然通过偶然表现出来，偶然背后隐藏着必然","必然与偶然相互独立"],"answer":2,"explanation":"必然性通过大量偶然性表现出来并为自己开辟道路，偶然性背后隐藏着必然性，偶然性是必然性的表现形式和补充。二者不能相互独立或混淆，偶然也不决定必然，故选C。","__sub":"马原"},{"id":"zz-30384","module":"zhengzhi","prompt":"「可能」与「现实」的关系是：","options":["可能与现实相互独立","现实是可能实现的，可能是尚未实现的现实，二者在一定条件下相互转化","可能与现实没有区别","现实决定于可能"],"answer":1,"explanation":"可能是事物中预示发展前途的种种趋势，现实是已经实现的东西；可能经过努力可以变成现实，现实中又孕育着新的可能，二者在一定条件下相互转化。可能与现实不能相互独立或混淆，故选B。","__sub":"马原"},{"id":"zz-30385","module":"zhengzhi","prompt":"「形式」与「内容」的关系是：","options":["内容与形式相互独立","形式决定内容","内容决定形式，形式反作用于内容","内容与形式没有区别"],"answer":2,"explanation":"内容是构成事物的一切要素的总和，形式是这些要素的结构和表现方式；内容决定形式，形式反作用于内容，适合内容的形式促进内容发展。形式不能决定内容，二者也不能相互独立或混淆，故选C。","__sub":"马原"},{"id":"zz-30386","module":"zhengzhi","prompt":"「社会意识」与「社会存在」的关系是：","options":["社会意识决定社会存在","社会存在决定社会意识，社会意识具有相对独立性","二者相互独立","社会意识与社会存在无关"],"answer":1,"explanation":"社会存在决定社会意识，社会意识是社会存在的反映；同时社会意识具有相对独立性，可以反作用于社会存在。社会意识不能决定社会存在，二者也不能相互独立或无关，故选B。","__sub":"马原"},{"id":"zz-30387","module":"zhengzhi","prompt":"「生产关系一定要适合生产力状况」这一规律表明：","options":["生产力决定生产关系，生产关系反作用于生产力","生产关系可以随意选择","生产关系决定生产力","生产力与生产关系相互独立"],"answer":0,"explanation":"生产力决定生产关系，有什么样的生产力就要求有什么样的生产关系；生产关系反作用于生产力，适合时促进生产力发展，不适合时阻碍。生产关系不能决定生产力，也不能随意选择，故选A。","__sub":"马原"},{"id":"zz-30389","module":"zhengzhi","prompt":"「人民群众」这一概念的含义是：","options":["一切对社会历史发展起推动作用的人们","全体社会成员","劳动人民中的先进分子","从事体力劳动的人们"],"answer":0,"explanation":"人民群众是指一切对社会历史发展起推动作用的人们，其主体是从事物质资料生产的劳动群众。人民群众不等于全体社会成员，也不限于先进分子或体力劳动者，故选A。","__sub":"马原"},{"id":"zz-30390","module":"zhengzhi","prompt":"「群众观点」与「群众路线」的关系是：","options":["群众观点是群众路线的思想基础，群众路线是群众观点的具体运用","真理与价值无关","价值决定真理","真理与价值相互对立"],"answer":1,"explanation":"群众观点（相信群众、依靠群众、为群众服务）是坚持群众路线的思想基础，群众路线（一切为了群众、一切依靠群众，从群众中来、到群众中去）是群众观点在实际工作中的具体运用，二者辩证统一，故选B。","__sub":"马原"},{"id":"zz-30391","module":"zhengzhi","prompt":"「价值观」与「真理观」的关系是：","options":["真理是一元的，价值是多元的，二者在实践中统一","二者相互独立","群众观点可以脱离群众路线","群众路线决定群众观点"],"answer":0,"explanation":"真理是一元的（对同一对象的正确认识只有一个），价值是多元的（不同主体需要不同），但二者在实践基础上可以统一，正确的价值选择必须以真理为前提。真理与价值不是对立或无关的，故选A。","__sub":"马原"},{"id":"zz-30392","module":"zhengzhi","prompt":"「人的全面发展」与「社会发展」的关系是：","options":["人的全面发展与社会发展相互促进、辩证统一","人的全面发展与社会发展相互对立","人的发展可以脱离社会发展","社会发展可以脱离人的发展"],"answer":0,"explanation":"社会发展为人的全面发展创造条件，人的全面发展又推动社会发展，二者相互促进、辩证统一。二者不能相互对立或脱离，故选A。","__sub":"马原"},{"id":"zz-30393","module":"zhengzhi","prompt":"「实践标准」的确定性与不确定性是指：","options":["实践标准可以被推翻","实践是检验真理的唯一标准（确定性），但具体实践有历史局限性（不确定性）","实践标准是绝对不变的","实践标准因人而异"],"answer":1,"explanation":"实践标准的确定性指实践是检验真理的唯一标准，最终能鉴别认识真伪；不确定性指具体实践有历史局限性，一定阶段的实践不能完全证实或驳倒一切认识。实践标准不会被推翻，也不因人而异，故选B。","__sub":"马原"},{"id":"zz-30394","module":"zhengzhi","prompt":"「认识」与「实践」的关系是：","options":["认识与实践无关","认识决定实践","实践决定认识，认识反作用于实践","二者相互独立"],"answer":2,"explanation":"实践是认识的基础（来源、动力、目的、检验标准），决定认识；认识反作用于实践，科学理论指导实践。认识不能决定实践，二者也不能相互独立或无关，故选C。","__sub":"马原"},{"id":"zz-30395","module":"zhengzhi","prompt":"「感性认识」与「理性认识」的关系是：","options":["二者相互独立","理性认识可以脱离感性认识","感性认识比理性认识更可靠","感性认识是理性认识的基础，理性认识是感性认识的升华"],"answer":3,"explanation":"感性认识是认识的初级阶段，是理性认识的基础；理性认识是认识的高级阶段，是感性认识的升华和深化。二者相互渗透、不能割裂，也不能说谁更可靠，故选D。","__sub":"马原"},{"id":"zz-30396","module":"zhengzhi","prompt":"「归纳」与「演绎」的关系是：","options":["归纳比演绎更可靠","二者相互独立","归纳是演绎的基础，演绎指导归纳，二者相互补充","演绎可以脱离归纳"],"answer":2,"explanation":"归纳是从个别到一般，演绎是从一般到个别；归纳为演绎提供前提，演绎为归纳提供指导，二者相互联系、相互补充。二者不能相互独立或割裂，也不能简单说谁更可靠，故选C。","__sub":"马原"},{"id":"zz-30397","module":"zhengzhi","prompt":"「分析与综合」的关系是：","options":["二者相互独立","综合可以脱离分析","分析比综合更重要","分析是综合的基础，综合是分析的完成，二者相互依存"],"answer":3,"explanation":"分析是把整体分解为部分加以研究，综合是把各部分联结为整体加以把握；分析是综合的基础，综合是分析的完成，二者相互依存、辩证统一。二者不能相互独立或割裂，故选D。","__sub":"马原"},{"id":"zz-30398","module":"zhengzhi","prompt":"「抽象」与「具体」的关系是：","options":["抽象与具体相互独立","抽象比具体更真实","从抽象上升到具体是思维把握具体的辩证方法","具体可以脱离抽象而存在"],"answer":2,"explanation":"思维具体是许多规定的综合和多样性的统一，从抽象上升到具体是辩证思维把握具体对象的基本方法。具体不能脱离抽象孤立存在，二者也不是相互独立或谁更真实的问题，故选C。","__sub":"马原"},{"id":"zz-30399","module":"zhengzhi","prompt":"「逻辑与历史」的关系是：","options":["逻辑决定历史","逻辑与历史相一致，逻辑是历史的理论再现","逻辑与历史相互独立","历史可以脱离逻辑"],"answer":1,"explanation":"逻辑的（理论）进程与历史的（实际）进程相一致，逻辑分析是历史过程的理论再现，历史是逻辑的基础。逻辑不能决定历史，二者也不能相互独立，故选B。","__sub":"马原"},{"id":"zz-30400","module":"zhengzhi","prompt":"「真理的力量」与「人格的力量」的关系是：","options":["人格决定真理","二者相辅相成，真理靠人格传播，人格靠真理支撑","真理与人格无关","二者相互对立"],"answer":1,"explanation":"真理的力量与人格的力量相辅相成：掌握真理的人以人格魅力传播真理，坚定的人格又以真理为支撑。二者不是对立或无关的，人格也不能决定真理，故选B。","__sub":"马原"},{"id":"zz-30401","module":"zhengzhi","prompt":"「实践」与「主体」的关系是：","options":["实践与主体无关","实践可以脱离主体","主体是实践活动的承担者，实践是主体的存在方式","主体决定实践的一切内容"],"answer":2,"explanation":"实践的主体是人，是实践活动的承担者和发起者；实践是人的存在方式，人在实践中生成和发展。实践不能脱离主体，主体也不能脱离实践而存在，故选C。","__sub":"马原"},{"id":"zz-30402","module":"zhengzhi","prompt":"「自在世界」与「人类世界」的关系是：","options":["人类世界可以脱离自在世界","自在世界是人类世界的前提，人类世界在实践基础上生成","自在世界就是人类世界","二者相互独立"],"answer":1,"explanation":"自在世界（未被人化的自然界）是人类世界（人化自然与人类社会）存在和发展的前提，人类世界在实践基础上从自在世界中分化生成。二者不能相互独立或等同，故选B。","__sub":"马原"},{"id":"zz-30403","module":"zhengzhi","prompt":"「人的活动」与「历史规律」的关系是：","options":["历史规律可以脱离人的活动","人的活动可以随意改变历史规律","历史规律形成并实现于人的活动之中，又制约着人的活动","历史规律与人的活动无关"],"answer":2,"explanation":"社会历史规律形成并实现于人的有目的的活动之中，同时又作为一种客观力量制约着人的活动，使历史呈现合规律性。历史规律不能脱离人的活动，人的活动也不能随意改变规律，故选C。","__sub":"马原"},{"id":"zz-30404","module":"zhengzhi","prompt":"「社会发展的决定力量」与「社会发展的最终决定力量」的区别是：","options":["二者都是上层建筑","前者是生产方式，后者是生产力","二者都是生产关系","前者是生产力，后者是生产关系"],"answer":1,"explanation":"生产方式是社会发展的决定力量，其中生产力是社会发展的最终决定力量，生产关系对生产力有反作用。生产关系和上层建筑都不是最终决定力量，故选B。","__sub":"马原"},{"id":"zz-30405","module":"zhengzhi","prompt":"「科学技术是第一生产力」这一论断的提出者是：","options":["恩格斯","马克思","习近平","邓小平"],"answer":3,"explanation":"「科学技术是第一生产力」是邓小平在1988年提出的论断，深化了马克思「生产力中也包括科学」的思想，强调科技在现代生产力发展中的首要作用。马克思、恩格斯未提出该论断，故选D。","__sub":"马原"},{"id":"zz-30406","module":"zhengzhi","prompt":"「社会形态」这一概念的含义是：","options":["社会意识形态的总和","社会生产力的总和","同生产力发展一定阶段相适应的经济基础与上层建筑的统一体","社会生产关系的总和"],"answer":2,"explanation":"社会形态是同生产力发展一定阶段相适应的经济基础与上层建筑的统一体，包括经济形态、政治形态和意识形态。它不是生产力、生产关系或意识形态的单一总和，故选C。","__sub":"马原"},{"id":"zz-30408","module":"zhengzhi","prompt":"「改革」与「革命」的区别是：","options":["改革是制度的自我完善，革命是根本制度的变革","改革与革命没有区别","革命是制度的自我完善","改革比革命更彻底"],"answer":0,"explanation":"改革是在坚持基本制度前提下对具体体制的调整和完善，是制度的自我完善；革命是推翻旧制度、建立新制度的根本变革。二者性质不同，改革并非比革命更彻底，故选A。","__sub":"马原"},{"id":"zz-30409","module":"zhengzhi","prompt":"「人的价值」与「物的价值」的根本区别是：","options":["物的价值高于人的价值","人的价值在于创造价值并承担社会责任，物的价值在于满足人的需要","人的价值在于占有更多物品","二者没有区别"],"answer":1,"explanation":"人的价值在于通过实践创造价值满足社会需要，同时享有社会对其贡献的承认，是自我价值与社会价值的统一；物的价值只在于满足人的需要。人的价值不能以占有物品多少衡量，故选B。","__sub":"马原"},{"id":"zz-30410","module":"zhengzhi","prompt":"「人生价值」的评价标准是：","options":["对社会的责任和贡献","社会地位的高低","个人愿望的实现程度","占有财富的多少"],"answer":0,"explanation":"评价人生价值的根本标准是对社会的责任和贡献，即个人对社会发展的积极作用。财富、地位、个人愿望都不是评价人生价值的标准，故选A。","__sub":"马原"},{"id":"zz-30411","module":"zhengzhi","prompt":"「自我价值」与「社会价值」的关系是：","options":["社会价值可以脱离自我价值","二者辩证统一，社会价值是自我价值的基础","二者相互对立","自我价值高于社会价值"],"answer":1,"explanation":"人的自我价值（社会对个人的尊重和满足）与社会价值（个人对社会的责任和贡献）辩证统一，社会价值是自我价值的基础，实现社会价值的同时实现自我价值。二者不能相互对立或割裂，故选B。","__sub":"马原"},{"id":"zz-30412","module":"zhengzhi","prompt":"「理想」与「现实」的关系是：","options":["理想脱离现实","现实决定理想的一切内容","理想与现实无关","理想源于现实又高于现实，理想可以转化为现实"],"answer":3,"explanation":"理想源于现实又高于现实，是在现实基础上对未来美好状态的设想，通过实践可以转化为现实。理想不能脱离现实，现实也不决定理想的一切内容，故选D。","__sub":"马原"},{"id":"zz-30413","module":"zhengzhi","prompt":"「认识世界」与「改造世界」的关系是：","options":["认识世界是为了改造世界，改造世界又深化对世界的认识","二者相互独立","认识世界可以脱离改造世界","改造世界可以脱离认识世界"],"answer":0,"explanation":"认识世界的目的在于改造世界，改造世界的实践又深化对世界的认识，二者在实践基础上辩证统一。认识与改造不能相互脱离或独立，故选A。","__sub":"马原"},{"id":"zz-30414","module":"zhengzhi","prompt":"「主观辩证法」与「客观辩证法」的关系是：","options":["主观辩证法决定客观辩证法","主观辩证法是客观辩证法的反映","客观辩证法可以脱离主观辩证法","二者相互独立"],"answer":1,"explanation":"客观辩证法是客观事物本身的辩证运动，主观辩证法（辩证思维）是客观辩证法在人脑中的反映，二者在内容上同一、形式上不同。主观不能决定客观，二者也不能相互独立，故选B。","__sub":"马原"},{"id":"zz-30415","module":"zhengzhi","prompt":"「辩证思维方法」与「科学思维方法」的关系是：","options":["辩证思维方法已经过时","科学思维方法可以代替辩证思维方法","辩证思维方法是科学思维方法的方法论前提","二者相互独立"],"answer":2,"explanation":"辩证思维方法（归纳演绎、分析综合、抽象具体、逻辑历史统一等）为各门科学的思维方法提供世界观和方法论前提，科学思维方法是辩证思维方法在具体领域的运用。二者不能相互独立或替代，故选C。","__sub":"马原"},{"id":"zz-30416","module":"zhengzhi","prompt":"「矛盾分析方法」在唯物辩证法中的地位是：","options":["它只适用于社会领域","它是认识事物的根本方法，是唯物辩证法的实质和核心的运用","它是一种次要方法","它与辩证法无关"],"answer":1,"explanation":"对立统一规律是唯物辩证法的实质和核心，矛盾分析方法是这一规律在认识方法上的运用，是认识事物的根本方法，贯穿于辩证思维方法之中。它不是次要方法，也不限于社会领域，故选B。","__sub":"马原"},{"id":"zz-30417","module":"zhengzhi","prompt":"「度」这一哲学范畴的含义是：","options":["事物保持自己质的稳定性的量的界限","事物的数量变化","事物的位置移动","事物的本质属性"],"answer":0,"explanation":"度是事物保持自己质的稳定性的量的界限，即事物量变不引起质变的范围或幅度，超出度就发生质变。数量变化和位置移动是量变的表现，本质属性是质的规定性，故选A。","__sub":"马原"},{"id":"zz-30418","module":"zhengzhi","prompt":"「适度原则」的哲学依据是：","options":["量变与质变无关","质变可以随意发生","度可以随意改变","量变超过一定限度会引起质变"],"answer":3,"explanation":"适度原则要求做事保持事物的质不变，其依据是量变超过度的界限就会引起质变，因此在需要保持事物性质稳定的场合要把握分寸、防止过犹不及。量变质变密切相关，度是客观的，故选D。","__sub":"马原"},{"id":"zz-30419","module":"zhengzhi","prompt":"「质」这一哲学范畴的含义是：","options":["事物的运动状态","事物的外部联系","一事物成为它自身并区别于其他事物的内在规定性","事物的数量变化"],"answer":2,"explanation":"质是一事物成为它自身并区别于其他事物的内在规定性，与事物直接同一。数量变化属于量，外部联系和运动状态都不是质的规定性，故选C。","__sub":"马原"},{"id":"zz-30420","module":"zhengzhi","prompt":"「量」这一哲学范畴的含义是：","options":["事物的内在规定性","事物存在和发展的规模、程度、速度等可以用数量表示的规定性","事物的外部表现","事物的本质属性"],"answer":1,"explanation":"量是事物存在和发展的规模、程度、速度以及构成事物的成分在空间上的排列等可以用数量表示的规定性，与事物不直接同一。内在规定性和本质属性属于质，故选B。","__sub":"马原"},{"id":"zz-30421","module":"zhengzhi","prompt":"「规律」这一范畴的含义是：","options":["事物运动发展中本质的、必然的、稳定的联系","事物之间偶然的联系","事物外部现象的联系","人为设定的规则"],"answer":0,"explanation":"规律是事物运动发展中本质的、必然的、稳定的联系，具有客观性、普遍性、必然性和稳定性。偶然联系、现象联系不是规律，规律也不是人为设定的规则，故选A。","__sub":"马原"},{"id":"zz-30422","module":"zhengzhi","prompt":"「意识」的能动作用表现在：","options":["意识可以脱离物质而存在","意识对物质不起任何作用","意识能够能动地认识世界和改造世界","意识可以直接改变客观事物"],"answer":2,"explanation":"意识的能动作用表现为：能够能动地认识世界（目的性、计划性、创造性）和能动地改造世界（通过实践把观念的东西变成现实的东西）。意识不能直接改变客观事物，必须通过实践；意识也不能脱离物质，故选C。","__sub":"马原"},{"id":"zz-30423","module":"zhengzhi","prompt":"「正确的意识」与「错误的意识」的区别在于：","options":["是否如实地反映了客观实际","是否为多数人接受","是否出自权威","是否符合个人利益"],"answer":0,"explanation":"意识的正确与错误之分在于其内容是否如实地反映了客观实际：如实反映的是正确意识，歪曲反映的是错误意识。意识的对错与是否出自权威、是否被多数接受或是否符合个人利益无关，故选A。","__sub":"马原"},{"id":"zz-30424","module":"zhengzhi","prompt":"「物质文明」与「精神文明」的关系是：","options":["精神文明决定物质文明","物质文明可以脱离精神文明","二者相互独立","物质文明为精神文明提供物质基础，精神文明为物质文明提供思想保证"],"answer":3,"explanation":"物质文明是精神文明的基础，为精神文明提供物质条件；精神文明为物质文明提供思想保证、精神动力和智力支持，二者相互促进、协调发展。二者不能相互独立或割裂，故选D。","__sub":"马原"},{"id":"zz-30425","module":"zhengzhi","prompt":"「实践」的三种基本形式是：","options":["生产实践、阶级斗争、科学实验","劳动、学习、生活","物质生产实践、社会政治实践、科学文化实践","经济活动、政治活动、文化活动"],"answer":2,"explanation":"实践的三种基本形式是物质生产实践（最基本）、社会政治实践和科学文化实践。生产实践、阶级斗争、科学实验是毛泽东对实践形式的另一种概括，但教材通行表述为前三种，故选C。","__sub":"马原"},{"id":"zz-30426","module":"zhengzhi","prompt":"「实践」的基本特征是：","options":["主观性、能动性、独立性","客观物质性、自觉能动性、社会历史性","客观性、被动性、永恒性","主观性、随意性、历史性"],"answer":1,"explanation":"实践具有客观物质性（要素和过程是客观的）、自觉能动性（有目的有意识的活动）和社会历史性（受历史条件制约并发展）。实践不是主观随意的，也不是被动的，故选B。","__sub":"马原"},{"id":"zz-30427","module":"zhengzhi","prompt":"「认识」的主体是：","options":["客观事物","从事实践活动的人","人的大脑","认识工具"],"answer":1,"explanation":"认识的主体是从事实践活动的人，人具有认识能力并通过实践获得认识。大脑是认识的器官而非主体本身，客观事物是认识的对象，认识工具是中介，故选B。","__sub":"马原"},{"id":"zz-30428","module":"zhengzhi","prompt":"「认识」的客体是：","options":["认识主体本身","认识工具","人的大脑","进入主体认识和实践范围的客观事物"],"answer":3,"explanation":"认识的客体是进入主体认识和实践活动范围的客观事物，即被认识的对象。并非一切客观事物都是认识客体，只有与主体发生认识关系的才是，故选D。","__sub":"马原"},{"id":"zz-30429","module":"zhengzhi","prompt":"「真理」与「价值」在实践中的统一是指：","options":["真理与价值可以相互替代","成功的实践必然遵循真理尺度与价值尺度的统一","价值尺度可以脱离真理尺度","真理尺度可以脱离价值尺度"],"answer":1,"explanation":"成功的实践必须同时遵循真理尺度（符合客观规律）和价值尺度（满足人的需要），二者在实践中统一。真理与价值不能相互替代，任一尺度都不能脱离另一尺度，故选B。","__sub":"马原"},{"id":"zz-30430","module":"zhengzhi","prompt":"「社会进步」与「人的发展」的关系是：","options":["社会进步可以脱离人的发展","人的发展与社会进步无关","二者相互对立","社会进步是人的发展的前提，人的发展是社会进步的标志"],"answer":3,"explanation":"社会进步为人的发展创造物质和精神条件，是人的发展的前提；人的全面发展程度又是社会进步的重要标志。二者不能相互对立或脱离，故选D。","__sub":"马原"},{"id":"zz-30431","module":"zhengzhi","prompt":"「自由王国」与「必然王国」的关系是：","options":["人类从必然王国向自由王国的飞跃是一个历史过程","自由王国可以脱离必然王国","必然王国是人类的最终归宿","二者相互独立"],"answer":0,"explanation":"人类在必然王国中受盲目必然性支配，通过实践不断认识必然、获得自由，从必然王国向自由王国的飞跃是一个长期历史过程。二者不能相互独立，自由王国的实现以认识必然为前提，故选A。","__sub":"马原"},{"id":"zz-30432","module":"zhengzhi","prompt":"「历史合力论」的含义是：","options":["历史由单个人物决定","历史发展是无数个人意志相互作用形成的合力的结果","个人意志对历史毫无作用","历史发展没有规律"],"answer":1,"explanation":"恩格斯的历史合力论指出，历史发展是无数相互交错的个人意志和活动形成的「合力」的结果，任何个人意志都对历史有作用，但历史结果不取决于单个人。历史发展有规律，个人意志也非毫无作用，故选B。","__sub":"马原"},{"id":"zz-30433","module":"zhengzhi","prompt":"「地理环境」与「社会发展」的关系是：","options":["地理环境决定社会性质","地理环境与社会发展无关","地理环境是社会存在的必要条件，能加速或延缓社会发展，但不能决定社会性质","地理环境可以随意改变"],"answer":2,"explanation":"地理环境是社会存在和发展的必要条件，通过影响生产发展速度等加速或延缓社会发展，但不能决定社会的性质和发展方向（决定社会性质的是生产方式）。地理环境是客观的，不能随意改变，故选C。","__sub":"马原"},{"id":"zz-30434","module":"zhengzhi","prompt":"「人口因素」与「社会发展」的关系是：","options":["人口因素是社会存在的必要条件，合理的人口状况促进社会发展","人口越多社会发展越快","人口因素与社会发展无关","人口数量决定社会性质"],"answer":0,"explanation":"人口因素是社会物质生活的必要条件，合理的人口数量、结构和质量能促进社会发展，但人口因素不能决定社会性质（决定社会性质的是生产方式）。人口并非越多越好，故选A。","__sub":"马原"},{"id":"zz-30435","module":"zhengzhi","prompt":"「生产方式」这一概念的含义是：","options":["社会意识形态","人们获取物质生活资料的方式，是生产力与生产关系的统一","自然地理条件","社会政治制度"],"answer":1,"explanation":"生产方式是人们获取物质生活资料的方式，是生产力与生产关系的统一，是社会存在和发展的决定力量。政治制度属于上层建筑，意识形态是观念上层建筑，故选B。","__sub":"马原"},{"id":"zz-30436","module":"zhengzhi","prompt":"「国体」与「政体」的关系是：","options":["政体决定国体","二者相互独立","政体与国体无关","国体决定政体，政体反作用于国体"],"answer":3,"explanation":"国体是国家性质（社会各阶级在国家中的地位），政体是国家政权组织形式；国体决定政体，政体反作用于国体。政体不能决定国体，二者也不能相互独立，故选D。","__sub":"马原"},{"id":"zz-30437","module":"zhengzhi","prompt":"「社会心理」与「思想体系」的关系是：","options":["社会心理是思想体系的基础，思想体系是社会心理的升华","二者相互独立","社会心理比思想体系更深刻","思想体系可以脱离社会心理"],"answer":0,"explanation":"社会心理是低层次的社会意识（情感、风俗、习惯等），思想体系是高层次的社会意识（系统化理论化的观念）；社会心理是思想体系的基础材料，思想体系是社会心理的升华。二者不能相互独立，思想体系更深刻系统，故选A。","__sub":"马原"},{"id":"zz-30438","module":"zhengzhi","prompt":"「意识形态」与非意识形态的社会意识形式的区别是：","options":["是否反映并服务于特定经济基础","是否可以传承","是否属于观念形态","是否系统化"],"answer":0,"explanation":"意识形态（政治法律思想、道德、艺术、宗教、哲学等）反映并服务于特定经济基础，具有阶级性；自然科学、语言学、逻辑学等非意识形态的社会意识形式不反映特定经济基础，无阶级性。二者都属于观念形态、都可以系统化和传承，故选A。","__sub":"马原"},{"id":"zz-30439","module":"zhengzhi","prompt":"「文化」与「文明」的关系是：","options":["文化等同于文明","二者相互独立","文明可以脱离文化","文明是文化发展的积极成果，文化是文明的基础"],"answer":3,"explanation":"文化是人类改造世界的成果总和，文明是文化发展的积极成果和进步状态，文化是文明的基础，文明是文化的升华。二者不能相互独立或等同，故选D。","__sub":"马原"},{"id":"zz-30440","module":"zhengzhi","prompt":"「人的本质」与「人的属性」的关系是：","options":["本质决定属性，属性表现本质","本质与属性无关","二者相互独立","属性决定本质"],"answer":0,"explanation":"人的本质（一切社会关系的总和）决定人的各种属性（自然属性、社会属性等），属性是本质的外在表现。本质不能脱离属性孤立存在，属性也不能决定本质，故选A。","__sub":"马原"},{"id":"zz-30441","module":"zhengzhi","prompt":"「历史人物」与「普通个人」的关系是：","options":["普通个人对历史毫无作用","历史人物对历史发展起重要作用，但历史归根到底是人民群众创造的","历史人物决定历史发展","历史人物与普通个人作用相同"],"answer":1,"explanation":"历史人物（杰出人物）对历史发展起加速或延缓的重要作用，但历史发展的决定力量是人民群众，任何个人都不能决定历史发展方向。历史人物与普通个人的作用有大小之分，普通个人也参与历史创造，故选B。","__sub":"马原"},{"id":"zz-30442","module":"zhengzhi","prompt":"「评价历史人物」的科学方法是：","options":["以成败论英雄","以现代标准苛求古人","历史分析方法和阶级分析方法","以个人好恶评价"],"answer":2,"explanation":"评价历史人物的科学方法是历史分析方法（放在特定历史条件下考察）和阶级分析方法（分析其阶级归属和作用），反对以成败论英雄、凭个人好恶或用现代标准苛求古人，故选C。","__sub":"马原"},{"id":"zz-30443","module":"zhengzhi","prompt":"「群众路线」的核心内容是：","options":["只服务群众不发动群众","只依靠群众不依靠干部","一切为了群众，一切依靠群众，从群众中来，到群众中去","群众说了算，不需要集中"],"answer":2,"explanation":"群众路线的核心内容是「一切为了群众，一切依靠群众，从群众中来，到群众中去」，前两句是党的根本工作路线的价值取向，后两句是领导方法。只依靠不集中、只服务不发动都是片面的，故选C。","__sub":"马原"},{"id":"zz-30444","module":"zhengzhi","prompt":"「社会存在」这一概念的含义是：","options":["社会的政治制度","社会生活的物质方面，包括自然地理环境、人口因素和物质生产方式","社会生活的精神方面","社会的风俗习惯"],"answer":1,"explanation":"社会存在是社会生活的物质方面，包括自然地理环境、人口因素和物质生产方式，其中生产方式是社会历史发展的决定力量。社会生活的精神方面属于社会意识，政治制度和风俗习惯属于上层建筑或社会意识，故选B。","__sub":"马原"},{"id":"zz-30445","module":"zhengzhi","prompt":"「社会意识」这一概念的含义是：","options":["社会的自然环境","社会生活的物质方面","社会的经济制度","社会生活的精神方面，是社会存在的反映"],"answer":3,"explanation":"社会意识是社会生活的精神方面，包括政治法律思想、道德、艺术、宗教、哲学等观念形态，是社会存在的反映。社会生活的物质方面是社会存在，经济制度和自然环境不属于社会意识，故选D。","__sub":"马原"},{"id":"zz-30446","module":"zhengzhi","prompt":"「历史唯物主义」与「历史唯心主义」的根本分歧是：","options":["是否承认文化有传承","是否承认社会有历史","是否承认个人有作用","是否承认社会存在决定社会意识"],"answer":3,"explanation":"历史唯物主义与历史唯心主义的根本分歧在于是否承认社会存在决定社会意识：承认的是历史唯物主义，主张社会意识决定社会存在的是历史唯心主义。是否承认历史、个人作用、文化传承都不是根本分歧，故选D。","__sub":"马原"},{"id":"zz-30447","module":"zhengzhi","prompt":"「唯物史观」的创立者是：","options":["马克思和恩格斯","列宁和斯大林","黑格尔和费尔巴哈","毛泽东和邓小平"],"answer":0,"explanation":"唯物史观由马克思和恩格斯共同创立，是马克思主义哲学的重要组成部分，实现了社会历史观的伟大变革。黑格尔是客观唯心主义者，费尔巴哈是半截子唯物主义者，均未创立唯物史观，故选A。","__sub":"马原"},{"id":"zz-30448","module":"zhengzhi","prompt":"「马克思主义哲学」的直接理论来源是：","options":["德国古典哲学","古希腊哲学","法国空想社会主义","英国古典政治经济学"],"answer":0,"explanation":"马克思主义哲学的直接理论来源是德国古典哲学，特别是黑格尔的辩证法和费尔巴哈的唯物主义。英国古典政治经济学是马克思主义政治经济学的来源，法国空想社会主义是科学社会主义的来源之一，故选A。","__sub":"马原"},{"id":"zz-30449","module":"zhengzhi","prompt":"「马克思主义哲学」与「旧哲学」的根本区别在于：","options":["它以实践为基础实现了唯物主义与辩证法的统一、自然观与历史观的统一","它比旧哲学更古老","它只研究自然界","它否认世界的可知性"],"answer":0,"explanation":"马克思主义哲学以科学的实践观为基础，实现了唯物主义与辩证法的有机统一、唯物主义自然观与唯物主义历史观的统一，这是它与一切旧哲学的根本区别。它并不否认世界可知性，也不只研究自然界，故选A。","__sub":"马原"},{"id":"zz-30450","module":"zhengzhi","prompt":"「哲学」与「具体科学」的关系是：","options":["二者相互独立、互不相关","哲学与具体科学是一般与个别的关系，二者相互联系、相互促进","具体科学可以代替哲学","哲学可以代替具体科学"],"answer":1,"explanation":"哲学与具体科学是一般与个别、共性与个性的关系：具体科学为哲学提供基础，哲学为具体科学提供世界观和方法论指导，二者相互联系、相互促进。哲学不能代替具体科学，具体科学也不能代替哲学，故选B。","__sub":"马原"},{"id":"zz-30451","module":"zhengzhi","prompt":"运动是物质的存在方式和根本属性，物质与运动不可分。离开运动谈物质，会犯的错误是：","options":["唯心主义的错误","不可知论的错误","相对主义的错误","形而上学的错误"],"answer":3,"explanation":"离开运动谈物质，把物质看作静止不动的存在，是形而上学的错误；离开物质谈运动则是唯心主义的错误。二者都不符合辩证唯物主义的物质观。故本题选A。","__sub":"马原"},{"id":"zz-30452","module":"zhengzhi","prompt":"「坐地日行八万里，巡天遥看一千河」体现的哲学道理是：","options":["实践与认识的统一","物质与意识的统一","绝对运动与相对静止的统一","矛盾普遍性与特殊性的统一"],"answer":2,"explanation":"人「坐地」是相对静止，「日行八万里」是随地球自转的绝对运动，诗句生动体现了绝对运动与相对静止的辩证统一。故本题选A。","__sub":"马原"},{"id":"zz-30453","module":"zhengzhi","prompt":"时间和空间是物质运动的存在形式，其中时间的突出特点是：","options":["三维性","一维性","无限性","客观性"],"answer":1,"explanation":"时间的特点是一维性，即一去不复返的不可逆性；空间的特点是三维性。二者都具有客观性和无限性，但时间区别于空间的突出特点是一维性。故本题选B。","__sub":"马原"},{"id":"zz-30454","module":"zhengzhi","prompt":"「斗转星移」「沧海桑田」的变化过程表明：","options":["物质是运动的承担者","运动是物质的固有属性","空间随人的意识而改变","静止是运动的特殊状态"],"answer":1,"explanation":"天体运行、海陆变迁都是物质形态的运动，说明运动是物质固有的根本属性，没有离开物质的运动。C项是唯心主义观点，D项表述正确但与题干主旨不符。故本题选B。","__sub":"马原"},{"id":"zz-30455","module":"zhengzhi","prompt":"意识是客观世界的主观映象，这一命题表明意识在内容上是：","options":["客观的","虚幻的","主观的","先验的"],"answer":0,"explanation":"意识是客观世界的主观映象，说明意识的形式是主观的，但内容是客观的，是对客观存在的反映。否认内容客观性会走向唯心主义。故本题选B。","__sub":"马原"},{"id":"zz-30456","module":"zhengzhi","prompt":"「观念的东西不外是移入人的头脑并在人的头脑中改造过的物质的东西而已」，这一论断说明：","options":["意识就是物质","意识可以脱离物质而存在","物质依赖于意识而存在","意识依赖于物质并对物质进行加工改造"],"answer":3,"explanation":"马克思这一论断表明意识来源于物质（移入头脑），又经过头脑的加工改造（主观映象），体现了意识对物质的依赖性和能动加工。A项抹杀了意识与物质的原则区别。故本题选B。","__sub":"马原"},{"id":"zz-30457","module":"zhengzhi","prompt":"人工智能可以模拟人的部分思维活动，但与人类思维有本质区别。其本质区别在于：","options":["运算速度的快慢","是否具有社会性和创造性","存储容量的大小","是否需要能量供给"],"answer":1,"explanation":"人工智能是人类智能的物化和模拟，只有逻辑运算能力，不具有人类思维的社会性、目的性和创造性，不能真正「理解」世界。A、C、D均非本质区别。故本题选B。","__sub":"马原"},{"id":"zz-30458","module":"zhengzhi","prompt":"「凡事预则立，不预则废」之外，下列同样体现意识能动作用的是：","options":["运筹帷幄之中，决胜千里之外","水到渠成","近朱者赤，近墨者黑","种瓜得瓜，种豆得豆"],"answer":0,"explanation":"「运筹帷幄」指事先谋划部署从而取胜，体现了意识活动的目的性、计划性及其对实践的指导作用。A、D强调客观规律性，C强调外部环境影响。故本题选B。","__sub":"马原"},{"id":"zz-30459","module":"zhengzhi","prompt":"发挥主观能动性必须以尊重客观规律为前提，这一命题的哲学依据是：","options":["规律的客观性与主观能动性的辩证统一","意识决定物质","认识决定实践","运动是绝对的"],"answer":0,"explanation":"规律是客观的，不以人的意志为转移；人可以认识和利用规律，但必须以尊重规律为前提，二者是辩证统一的关系。A、C是唯心主义观点。故本题选B。","__sub":"马原"},{"id":"zz-30460","module":"zhengzhi","prompt":"「揠苗助长」的寓言给我们的哲学启示是：","options":["要抓住主要矛盾","要充分发挥主观能动性","要重视意识的反作用","要尊重客观规律，不能急于求成"],"answer":3,"explanation":"拔苗人违背了禾苗生长的客观规律，仅凭主观愿望强行干预，结果适得其反，启示我们发挥主观能动性必须尊重客观规律。故本题选B。","__sub":"马原"},{"id":"zz-30461","module":"zhengzhi","prompt":"联系的普遍性是指：","options":["任何两个事物之间都是直接联系的","世界是相互联系的整体，联系具有客观性","联系可以由人随意建立","联系是主观精神的产物"],"answer":1,"explanation":"联系的普遍性指任何事物都不能孤立存在，都处于普遍联系之中，整个世界是相互联系的统一整体，且联系是客观的。A项混淆了普遍联系与直接联系，C项否认联系的客观性。故本题选B。","__sub":"马原"},{"id":"zz-30462","module":"zhengzhi","prompt":"「牵一发而动全身」体现的哲学道理是：","options":["整体与部分相互转化","整体由部分构成，关键部分对整体起决定作用","部分离不开整体","整体功能大于部分功能之和"],"answer":1,"explanation":"「一发」是关键部分，「全身」是整体，牵一发而动全身说明关键部分的变化会对整体功能产生重大影响。B项本身正确但题干未体现整体功能比较。故本题选A。","__sub":"马原"},{"id":"zz-30463","module":"zhengzhi","prompt":"「国兴则家兴，国破则家亡」体现的哲学道理是：","options":["部分之间相互孤立","部分决定整体","整体与部分毫无关联","整体居于主导地位，统率着部分"],"answer":3,"explanation":"「国」是整体，「家」是部分，国的兴衰决定家的命运，说明整体居于主导地位、统率着部分，部分离不开整体。A项颠倒了二者关系。故本题选B。","__sub":"马原"},{"id":"zz-30464","module":"zhengzhi","prompt":"系统观念要求坚持「整体大于部分之和」，其哲学依据是：","options":["整体是部分的简单相加","系统内部结构的有序性使整体功能优化","部分功能之和总小于整体","整体可以脱离部分而存在"],"answer":1,"explanation":"系统的整体功能不是部分的简单相加，而是通过内部各要素的有序结合与结构优化产生新的功能。B项是机械整体观，D项否认了部分的构成作用。故本题选A。","__sub":"马原"},{"id":"zz-30465","module":"zhengzhi","prompt":"「一叶落而知天下秋」体现的哲学方法是：","options":["从整体中把握部分","从部分联系中把握整体趋势","用发展的眼光看问题","透过现象认识本质"],"answer":1,"explanation":"由一片落叶推知秋天将至，是从事物的部分联系把握整体趋势，体现了联系的观点和推理方法。A项方向相反，B项强调现象与本质，均与题意不符。故本题选D。","__sub":"马原"},{"id":"zz-30466","module":"zhengzhi","prompt":"「士别三日，即更刮目相待」与「用发展的眼光看问题」的哲学依据相同，即：","options":["矛盾具有特殊性","事物是普遍联系的","实践是认识的基础","事物是变化发展的，要用发展的观点看事物"],"answer":3,"explanation":"吕蒙的变化说明事物处于不断变化发展中，不能用静止的眼光看人看事，其哲学依据正是发展的观点。B、C、D虽是正确观点但与题干主旨不符。故本题选A。","__sub":"马原"},{"id":"zz-30467","module":"zhengzhi","prompt":"「青山遮不住，毕竟东流去」蕴含的哲学道理是：","options":["新事物必然战胜旧事物","量变必然引起质变","矛盾是事物发展的动力","认识需要反复实践"],"answer":0,"explanation":"江水东流不可阻挡，比喻历史发展的必然趋势不可逆转，说明新事物符合客观规律、具有强大生命力，必然战胜旧事物。故本题选A。","__sub":"马原"},{"id":"zz-30468","module":"zhengzhi","prompt":"「芳林新叶催陈叶，流水前波让后波」体现的哲学道理是：","options":["矛盾双方相互转化","事物的联系是多种多样的","新事物代替旧事物是事物发展的必然趋势","认识随实践发展而深化"],"answer":2,"explanation":"新叶催陈叶、后波让前波，形象地说明了新事物代替旧事物是事物发展的必然趋势，发展是新事物的产生和旧事物的灭亡。故本题选A。","__sub":"马原"},{"id":"zz-30469","module":"zhengzhi","prompt":"「行百里者半九十」给我们的哲学启示是：","options":["矛盾双方可以相互转化","质变是量变的必然结果","要重视外部条件的作用","量变是质变的必要准备，要坚持不懈积累"],"answer":3,"explanation":"走一百里路，走了九十里才算走了一半，说明越接近成功越艰难，必须重视量的积累、坚持到底才能实现质变，半途而废则前功尽弃。故本题选A。","__sub":"马原"},{"id":"zz-30470","module":"zhengzhi","prompt":"「千里之堤，溃于蚁穴」体现的哲学道理是：","options":["内因是变化的根据","质变是量变的必然结果，要防微杜渐","事物发展是前进性与曲折性的统一","要抓住时机促成飞跃"],"answer":1,"explanation":"小小的蚁穴（量变）积累到一定程度会导致大堤溃决（质变），启示我们重视量的积累、防止不良因素积累导致恶变质变。故本题选A。","__sub":"马原"},{"id":"zz-30471","module":"zhengzhi","prompt":"「宜将剩勇追穷寇，不可沽名学霸王」体现的哲学道理是：","options":["要重视量的积累","要不失时机地促成事物的质变","要坚持适度原则","要具体问题具体分析"],"answer":1,"explanation":"毛泽东此句告诫要抓住战机、穷追猛打、彻底胜利，即当量变积累到临界点时，要不失时机地促成质变，防止功亏一篑。C项强调防止过犹不及，与题意相反。故本题选A。","__sub":"马原"},{"id":"zz-30472","module":"zhengzhi","prompt":"「火候不到，众口难调；火候一到，众口称赞」体现的哲学道理是：","options":["量变比质变更重要","坚持适度原则，把握分寸火候","矛盾具有特殊性","认识决定实践"],"answer":1,"explanation":"烹饪讲究火候，过了或不及都做不好菜，说明做事要把握分寸、坚持适度原则，防止「过」与「不及」。故本题选A。","__sub":"马原"},{"id":"zz-30473","module":"zhengzhi","prompt":"「祸兮福之所倚，福兮祸之所伏」体现的哲学道理是：","options":["矛盾具有普遍性","事物发展是曲折的","内因是事物发展的根据","矛盾双方在一定条件下相互转化"],"answer":3,"explanation":"老子此语说明祸与福作为矛盾双方相互依存，并在一定条件下向对立面转化，要求人们居安思危、防患未然。故本题选A。","__sub":"马原"},{"id":"zz-30474","module":"zhengzhi","prompt":"「虚心使人进步，骄傲使人落后」体现的哲学道理是：","options":["矛盾双方在一定条件下相互转化","矛盾具有特殊性","量变与质变的统一","实践决定认识"],"answer":0,"explanation":"虚心与进步、骄傲与落后是矛盾双方，条件（虚心或骄傲的态度）不同，事物会向相反方向转化，体现了矛盾双方在一定条件下相互转化的原理。故本题选A。","__sub":"马原"},{"id":"zz-30475","module":"zhengzhi","prompt":"「同病异治、异病同治」体现的哲学道理主要是：","options":["矛盾普遍性与特殊性的辩证统一","矛盾双方相互依存","量变质变规律","否定之否定规律"],"answer":0,"explanation":"「同病」是共性（普遍性），「异治」是个性（特殊性）；「异病同治」则是在个性中把握共性。二者结合体现了矛盾普遍性与特殊性的辩证统一，要求具体问题具体分析。故本题选A。","__sub":"马原"},{"id":"zz-30476","module":"zhengzhi","prompt":"「一把钥匙开一把锁」给我们的方法论启示是：","options":["坚持两点论与重点论的统一","坚持具体问题具体分析","坚持从实际出发","坚持实践第一的观点"],"answer":1,"explanation":"不同的锁需要不同的钥匙，比喻不同事物的矛盾各有特点，解决矛盾必须具体问题具体分析，用不同的方法解决不同的矛盾。故本题选A。","__sub":"马原"},{"id":"zz-30477","module":"zhengzhi","prompt":"「射人先射马，擒贼先擒王」体现的哲学道理是：","options":["抓主要矛盾，抓中心工作","矛盾双方相互转化","重视内因的作用","坚持联系的多样性"],"answer":0,"explanation":"复杂事物中存在诸多矛盾，其中主要矛盾居于支配地位、对事物发展起决定作用，「先射马」「先擒王」正是抓主要矛盾、抓重点的方法。故本题选A。","__sub":"马原"},{"id":"zz-30478","module":"zhengzhi","prompt":"「好钢用在刀刃上」体现的哲学道理是：","options":["矛盾具有特殊性","集中力量解决主要矛盾","量变引起质变","事物是普遍联系的"],"answer":1,"explanation":"「刀刃」是刀发挥功能的关键部位，把好钢用在刀刃上，比喻把有限资源集中用于关键环节，即集中力量解决主要矛盾。故本题选A。","__sub":"马原"},{"id":"zz-30479","module":"zhengzhi","prompt":"「金无足赤，人无完人」给我们的方法论启示是：","options":["坚持两点论，全面地看问题","坚持重点论，抓主要矛盾","坚持适度原则","坚持发展的观点"],"answer":0,"explanation":"金没有十足之赤，人没有完美无缺，说明任何事物都包含既对立又统一的两个方面，要求我们坚持两点论、全面地看问题，既看到优点也看到不足。故本题选A。","__sub":"马原"},{"id":"zz-30480","module":"zhengzhi","prompt":"「兼听则明」与「偏信则暗」的对比说明，认识事物要：","options":["坚持适度原则","全面地看问题，反对片面性","透过现象看本质","重视感性认识"],"answer":1,"explanation":"「兼听」是全面听取各方面意见，「偏信」是只听一面之词，对比说明认识事物必须坚持全面性，反对以偏概全的片面性错误。故本题选A。","__sub":"马原"},{"id":"zz-30481","module":"zhengzhi","prompt":"「沧海桑田」的变化中蕴含着「扬弃」的思想。辩证否定观的实质是：","options":["全盘抛弃旧事物","外力对事物的否定","扬弃，即既克服又保留","对旧事物的一概肯定"],"answer":2,"explanation":"辩证否定是事物自身的否定，其实质是「扬弃」，即既克服旧事物中消极的东西，又保留其积极的东西，而不是全盘抛弃或全盘肯定。故本题选B。","__sub":"马原"},{"id":"zz-30482","module":"zhengzhi","prompt":"「去粗取精、去伪存真」体现的哲学道理是：","options":["辩证否定即批判地继承","认识决定实践","量变必然引起质变","矛盾具有普遍性"],"answer":0,"explanation":"对旧事物「去粗取精、去伪存真」，即否定其糟粕、吸收其精华，正是辩证否定观「扬弃」的方法论体现。故本题选A。","__sub":"马原"},{"id":"zz-30483","module":"zhengzhi","prompt":"「推陈出新，革故鼎新」体现的哲学道理是：","options":["事物的发展是辩证否定的过程","外因通过内因起作用","矛盾具有特殊性","认识需要不断反复"],"answer":0,"explanation":"「推陈出新」「革故鼎新」都是在旧事物基础上产生新事物，是既克服又保留的辩证否定过程，体现了发展是新事物代替旧事物的实质。故本题选A。","__sub":"马原"},{"id":"zz-30484","module":"zhengzhi","prompt":"事物发展是前进性与曲折性的统一，其根本原因是：","options":["新事物对旧事物的否定是辩证否定","外力推动事物前进","人的意志决定发展方向","量变与质变的交替"],"answer":0,"explanation":"发展的总趋势是前进的，因为新事物必然战胜旧事物；道路是曲折的，因为新事物的成长要经历不完善的过程并遭到旧势力抵抗，根源在于辩证否定是既克服又保留的过程。故本题选A。","__sub":"马原"},{"id":"zz-30485","module":"zhengzhi","prompt":"「文王拘而演《周易》；仲尼厄而作《春秋》」给我们的哲学启示是：","options":["要重视意识的反作用","事物发展是前进性与曲折性的统一，要正确对待挫折","要抓住主要矛盾","量变是质变的必要准备"],"answer":1,"explanation":"文王、仲尼身处逆境而成就伟业，说明事物发展道路曲折，逆境中孕育着转机，要坚定信心、正确对待困难和挫折。故本题选A。","__sub":"马原"},{"id":"zz-30486","module":"zhengzhi","prompt":"「实践、认识、再实践、再认识」循环往复以至无穷，这表明：","options":["实践是认识的最终目的","认识是实践的来源","认识运动是无限发展的过程","认识可以脱离实践"],"answer":2,"explanation":"认识运动从实践到认识、再从认识到实践的循环往复中不断深化，说明认识运动是螺旋式上升、波浪式前进的无限发展过程。B项颠倒了实践与认识的关系。故本题选A。","__sub":"马原"},{"id":"zz-30487","module":"zhengzhi","prompt":"「纸上得来终觉浅，绝知此事要躬行」体现的哲学道理是：","options":["感性认识高于理性认识","认识决定实践","读书无用","实践是认识的来源和检验标准"],"answer":3,"explanation":"从书本得来的认识是间接经验，比较浅薄，要真正理解必须亲身实践，说明实践是认识的来源、动力和检验标准。C项颠倒了认识的两个层次。故本题选A。","__sub":"马原"},{"id":"zz-30488","module":"zhengzhi","prompt":"「近水知鱼性，近山识鸟音」体现的哲学道理是：","options":["矛盾具有特殊性","认识可以超前于实践","实践出真知，实践是认识的来源","真理是具体的有条件的"],"answer":2,"explanation":"靠近水才能了解鱼的习性，靠近山才能识别鸟的声音，说明只有亲身实践、深入实际才能获得真知，实践是认识的来源。故本题选A。","__sub":"马原"},{"id":"zz-30489","module":"zhengzhi","prompt":"「路遥知马力，日久见人心」体现的哲学道理是：","options":["认识需要长期积累和检验","实践是检验认识的标准","矛盾具有特殊性","量变与质变的统一"],"answer":0,"explanation":"路途遥远才能检验马的力气，相处长久才能看清人的内心，说明对人和事物的认识需要经过长期的实践检验和积累，不能凭一时印象下结论。故本题选B。","__sub":"马原"},{"id":"zz-30490","module":"zhengzhi","prompt":"感性认识与理性认识的根本区别在于：","options":["是否把握了事物的本质和规律","是否可以指导实践","是否来源于实践","是否正确反映事物"],"answer":0,"explanation":"感性认识是对事物现象、外部联系的直接反映，理性认识是对事物本质、内部联系的间接反映，二者的根本区别在于是否把握了事物的本质和规律。A、C、D均非根本区别。故本题选B。","__sub":"马原"},{"id":"zz-30491","module":"zhengzhi","prompt":"「感觉到了的东西，我们不能立刻理解它，只有理解了的东西才能更深刻地感觉它」，这句话说明：","options":["认识可以没有实践基础","理性认识脱离感性认识","感性认识不可靠","感性认识有待于发展和深化为理性认识"],"answer":3,"explanation":"毛泽东此语说明感性认识只有上升到理性认识才能更深刻地把握事物，体现了感性认识有待于发展、深化为理性认识的原理。B、C、D均为错误观点。故本题选A。","__sub":"马原"},{"id":"zz-30492","module":"zhengzhi","prompt":"「秀才不出门，全知天下事」在认识论上的合理性在于：","options":["认识可以脱离实践","书本知识比实践更可靠","间接经验也是获得认识的重要途径","理性认识高于感性认识"],"answer":2,"explanation":"通过读书、学习他人总结的知识（间接经验），不出门也能了解天下大事，说明学习间接经验是获得认识的重要途径。但间接经验归根到底也来源于他人的实践，B项错误。故本题选A。","__sub":"马原"},{"id":"zz-30493","module":"zhengzhi","prompt":"「真理往前多走一步，哪怕是同一方向的一小步，也会变成谬误」，这句话说明：","options":["真理与谬误没有区别","真理是有条件的，超出条件适用范围就变成谬误","真理会不断被推翻","谬误可以转化为真理"],"answer":1,"explanation":"真理都有自己适用的条件和范围，超出这个条件和范围，哪怕多走一小步，真理也会变成谬误，说明真理是具体的有条件的。故本题选A。","__sub":"马原"},{"id":"zz-30494","module":"zhengzhi","prompt":"实践是检验真理的唯一标准，这是由：","options":["认识对象的性质决定的","人的主观意志决定的","理论体系的完整性决定的","真理的本性和实践的特点决定的"],"answer":3,"explanation":"真理的本性是主观与客观相符合，实践具有直接现实性，能把主观认识与客观实际联系起来加以对照，因此只有实践能充当检验真理的标准。故本题选A。","__sub":"马原"},{"id":"zz-30495","module":"zhengzhi","prompt":"「真理是时间的女儿，不是权力的女儿」，这句名言强调：","options":["权力可以裁决真理","真理会随权力更替而变化","真理需要权力来维护","真理具有客观性，不因权势而改变"],"answer":3,"explanation":"真理是客观的，其内容不依赖于任何个人、集团或权力的意志，权力不能创造或消灭真理，经得起时间检验的才是真理。故本题选A。","__sub":"马原"},{"id":"zz-30496","module":"zhengzhi","prompt":"「社会生活在本质上是实践的」，这一命题的哲学依据是：","options":["劳动创造了人本身","实践决定意识","实践是认识的来源","实践是社会存在和发展的基础，是社会生活的本质"],"answer":3,"explanation":"马克思指出社会生活在本质上是实践的，因为物质生产实践是社会存在和发展的基础，人的社会关系在实践中形成，社会生活的全部内容都根源于实践。故本题选A。","__sub":"马原"},{"id":"zz-30497","module":"zhengzhi","prompt":"生产力中最活跃的因素是：","options":["劳动对象","劳动资料","劳动者","科学技术"],"answer":2,"explanation":"劳动者是生产力中最活跃的因素，因为劳动者是生产力中能动的主体，其素质和积极性直接决定生产力的发挥。劳动资料和劳动对象是物的要素。故本题选A。","__sub":"马原"},{"id":"zz-30498","module":"zhengzhi","prompt":"衡量生产力发展水平的客观尺度是：","options":["劳动者的技能","生产工具的发展水平","劳动对象的状况","科学技术的进步"],"answer":1,"explanation":"生产工具是人们在生产过程中作用于劳动对象的物质手段，是生产力发展水平的主要标志和客观尺度。故本题选B。","__sub":"马原"},{"id":"zz-30500","module":"zhengzhi","prompt":"「仓廪实而知礼节，衣食足而知荣辱」主要说明：","options":["经济基础与上层建筑无关","物质资料的生产方式决定社会生活","意识可以脱离物质","礼节荣辱是社会的决定力量"],"answer":1,"explanation":"粮仓充实、衣食充足（物质生活条件）是知礼节、知荣辱（社会意识）的基础，说明社会存在决定社会意识，物质资料的生产是社会生活的基础。故本题选A。","__sub":"马原"},{"id":"zz-30501","module":"zhengzhi","prompt":"社会意识相对独立性的突出表现是：","options":["社会意识无阶级性","社会意识决定社会存在","社会意识没有历史继承性","社会意识与社会存在发展不完全同步"],"answer":3,"explanation":"社会意识有时落后于社会存在，有时又先于社会存在而变化发展，这是社会意识相对独立性的突出表现。B项颠倒了二者的关系。故本题选A。","__sub":"马原"},{"id":"zz-30502","module":"zhengzhi","prompt":"「先天下之忧而忧，后天下之乐而乐」体现的社会意识形式是：","options":["社会意识决定社会存在","先进的道德观念对社会存在的积极反作用","社会意识与社会存在同步","个人意识决定社会意识"],"answer":1,"explanation":"范仲淹此语表达以天下为己任的道德情操，作为先进的社会意识能够对社会存在起积极的反作用，激励人们担当奉献。故本题选A。","__sub":"马原"},{"id":"zz-30503","module":"zhengzhi","prompt":"人民群众是历史的创造者，这一命题的根据是：","options":["人民群众是社会物质财富和精神财富的创造者，是社会变革的决定力量","人民群众的意志决定历史","英雄人物没有作用","人民群众可以随心所欲创造历史"],"answer":0,"explanation":"人民群众是社会物质财富和精神财富的创造者，是社会变革的决定力量，这是唯物史观的基本观点。B项夸大了意志的作用，C项否认了杰出人物的作用。故本题选A。","__sub":"马原"},{"id":"zz-30504","module":"zhengzhi","prompt":"「政之所兴在顺民心，政之所废在逆民心」体现的唯物史观道理是：","options":["社会意识与社会存在无关","民心决定社会形态","英雄人物决定历史进程","人民群众是历史的创造者，要坚持以人民为中心"],"answer":3,"explanation":"政权的兴衰取决于民心向背，说明人民群众的拥护与否决定政治成败，体现了人民群众是历史创造者的唯物史观原理。故本题选A。","__sub":"马原"},{"id":"zz-30505","module":"zhengzhi","prompt":"「时势造英雄」与「英雄造时势」两种观点的根本分歧在于：","options":["是否承认矛盾普遍性","是否承认社会存在决定社会意识","是否承认量变质变规律","是否承认意识的能动作用"],"answer":1,"explanation":"「时势造英雄」承认英雄人物由社会历史条件造就，坚持了社会存在决定社会意识；「英雄造时势」则夸大个人意志的作用，属于唯心史观。故本题选A。","__sub":"马原"},{"id":"zz-30506","module":"zhengzhi","prompt":"人的本质在其现实性上是：","options":["抽象人性的统一","自然属性的体现","一切社会关系的总和","理性与情感的结合"],"answer":2,"explanation":"马克思指出人的本质不是单个人所固有的抽象物，在其现实性上是一切社会关系的总和，强调人的社会性。故本题选A。","__sub":"马原"},{"id":"zz-30507","module":"zhengzhi","prompt":"「人的价值在于奉献，而不是索取」，这一观点的哲学依据是：","options":["索取是人的本质","人的社会价值与自我价值的统一，以奉献为首要","个人价值与社会价值对立","人的价值由天赋决定"],"answer":1,"explanation":"人的价值包括自我价值与社会价值两个方面，社会价值（奉献）是人的价值的首要方面，自我价值（索取）以社会价值的实现为前提，二者统一于奉献社会。故本题选A。","__sub":"马原"},{"id":"zz-30508","module":"zhengzhi","prompt":"「从群众中来，到群众中去」的哲学基础是：","options":["认识来源于实践并接受实践检验的原理","社会意识决定社会存在","矛盾特殊性原理","量变质变规律"],"answer":0,"explanation":"「从群众中来」即从群众实践中集中起来形成正确认识，「到群众中去」即回到实践中检验和落实，其哲学基础是认识来源于实践并接受实践检验。故本题选A。","__sub":"马原"},{"id":"zz-30509","module":"zhengzhi","prompt":"「因地制宜」「因材施教」共同体现的哲学道理是：","options":["坚持两点论与重点论的统一","一切从实际出发，具体问题具体分析","坚持适度原则","坚持辩证否定观"],"answer":1,"explanation":"「因地制宜」是根据各地实际，「因材施教」是根据学生特点，二者都强调从客观实际出发，针对矛盾的特殊性采取不同方法。故本题选A。","__sub":"马原"},{"id":"zz-30510","module":"zhengzhi","prompt":"「解放思想、实事求是」中的「实事求是」体现了：","options":["大胆设想，不受约束","一切从客观实际出发，探求事物内部规律","按主观愿望办事","照搬书本教条"],"answer":1,"explanation":"「实事求是」指从客观实际出发，探求事物内部的规律性，是辩证唯物主义世界观的集中体现，是党的思想路线的核心。故本题选A。","__sub":"马原"},{"id":"zz-30511","module":"zhengzhi","prompt":"「一个巴掌拍不响」这一俗语体现的哲学道理是：","options":["内因决定外因","矛盾双方相互依存，一方的存在以另一方为前提","量变引起质变","矛盾具有特殊性"],"answer":1,"explanation":"一个巴掌拍不响，说明矛盾双方相互依存、互为存在条件，一方的存在以另一方的存在为前提，双方共处于一个统一体中。故本题选A。","__sub":"马原"},{"id":"zz-30512","module":"zhengzhi","prompt":"「失败乃成功之母」体现的哲学道理是：","options":["矛盾具有普遍性","内因是事物发展的根据","矛盾双方在一定条件下相互转化","量变质变规律"],"answer":2,"explanation":"失败与成功是矛盾双方，总结失败教训、创造条件，失败可以转化为成功，体现了矛盾双方在一定条件下相互转化的原理。故本题选A。","__sub":"马原"},{"id":"zz-30513","module":"zhengzhi","prompt":"「亡羊补牢，犹未为晚」给我们的哲学启示是：","options":["要防微杜渐","错误不可避免","要善于从错误中吸取教训，变坏事为好事","要抓住时机"],"answer":2,"explanation":"丢了羊之后修补羊圈，防止继续损失，说明认识到错误后及时纠正，可以防止矛盾向坏的方向转化，变坏事为好事。故本题选A。","__sub":"马原"},{"id":"zz-30514","module":"zhengzhi","prompt":"「不登高山，不知天之高也；不临深溪，不知地之厚也」，这句话强调：","options":["理性认识高于感性认识","认识先于实践","间接经验不可靠","亲身实践才能获得真切的直接经验"],"answer":3,"explanation":"荀子此语说明只有亲身登高、临溪，才能真切认识天之高、地之厚，强调实践是获得直接经验的途径。故本题选A。","__sub":"马原"},{"id":"zz-30515","module":"zhengzhi","prompt":"「实践是检验真理的唯一标准」与「实践标准的不确定性」并不矛盾，因为：","options":["真理没有客观性","真理会不断被推翻","实践标准不可靠","实践是发展的，检验是一个过程"],"answer":3,"explanation":"实践标准是确定的（唯一标准），但实践本身是发展的，一定历史阶段的实践有局限性，对真理的检验是一个不断发展的过程，二者是确定性与不确定性的统一。故本题选A。","__sub":"马原"},{"id":"zz-30516","module":"zhengzhi","prompt":"「真理和谬误相比较而存在，相斗争而发展」，这句话说明：","options":["真理与谬误没有界限","谬误是真理的来源","真理与谬误是对立统一的，真理在斗争中发展","真理可以脱离谬误孤立存在"],"answer":2,"explanation":"真理与谬误作为矛盾双方相互依存、相互斗争，真理正是在同谬误的斗争中不断发展的。B、C、D均为错误观点。故本题选A。","__sub":"马原"},{"id":"zz-30517","module":"zhengzhi","prompt":"「任何真理都是绝对性与相对性的统一」，其中真理的绝对性是指：","options":["真理不需要再发展","真理是永恒不变的","真理适用于一切条件","真理的内容具有不依赖于人的客观性，认识每前进一步都是对无限发展着的物质世界的接近"],"answer":3,"explanation":"真理的绝对性指真理内容的客观性和认识每前进一步都获得对客观世界的正确认识；真理的相对性指其在广度和深度上的有限性。B、C、D否认了真理的发展性和条件性。故本题选A。","__sub":"马原"},{"id":"zz-30518","module":"zhengzhi","prompt":"「一切以时间、地点、条件为转移」，这一命题体现的哲学道理是：","options":["矛盾没有普遍性","联系是主观任意的","事物是静止不动的","联系是多样的、有条件的，要具体分析"],"answer":3,"explanation":"时间、地点、条件不同，事物的联系和性质就不同，说明联系具有多样性和条件性，要求我们一切以时间、地点、条件为转移。故本题选A。","__sub":"马原"},{"id":"zz-30519","module":"zhengzhi","prompt":"「种瓜得瓜，种豆得豆」与「橘生淮南则为橘，生于淮北则为枳」共同说明：","options":["外因决定事物性质","内外因无关","内因可以脱离外因","内因是变化的根据，外因是变化的条件"],"answer":3,"explanation":"种瓜得瓜说明内因（种子）决定事物性质；橘变为枳说明外因（水土）影响事物发展，外因通过内因起作用，二者共同说明内因是根据、外因是条件。故本题选A。","__sub":"马原"},{"id":"zz-30520","module":"zhengzhi","prompt":"「近朱者赤，近墨者黑」与「出淤泥而不染」的对比说明：","options":["外因通过内因起作用，内因是变化的根据","外因决定事物性质","内因可以脱离外因","环境毫无作用"],"answer":0,"explanation":"「近朱者赤」强调环境影响（外因），「出淤泥而不染」强调自身操守（内因），对比说明外因是变化的条件，内因是根据，外因通过内因起作用。故本题选A。","__sub":"马原"},{"id":"zz-30521","module":"zhengzhi","prompt":"「社会形态的发展是一种自然历史过程」，这一命题的含义是：","options":["社会发展与自然发展完全相同","社会发展没有人的参与","社会发展与自然发展一样有其客观规律","社会发展是随意的"],"answer":2,"explanation":"马克思此语说明社会发展虽有人参与，但同样受客观规律支配，是不以人的意志为转移的自然历史过程。B项抹杀了二者的区别。故本题选A。","__sub":"马原"},{"id":"zz-30522","module":"zhengzhi","prompt":"「人们自己创造自己的历史，但是他们并不是随心所欲地创造」，这一论断说明：","options":["人在规律面前无能为力","历史由英雄决定","历史规律的客观性与人的活动的能动性的统一","历史发展没有规律"],"answer":2,"explanation":"马克思此语说明历史是人们活动的结果（能动性），但人们的活动受既定条件和规律制约（客观性），二者辩证统一。故本题选A。","__sub":"马原"},{"id":"zz-30523","module":"zhengzhi","prompt":"「物质可以变成精神，精神可以变成物质」，这一论断说明：","options":["精神可以脱离物质","精神决定物质","物质与意识在实践中相互转化","物质与精神没有区别"],"answer":2,"explanation":"毛泽东此语说明在实践中人们可以认识客观世界（物质变精神），又以正确的认识指导实践改造世界（精神变物质），体现了物质与意识在实践基础上的辩证转化。故本题选A。","__sub":"马原"},{"id":"zz-30524","module":"zhengzhi","prompt":"「只要再多走一小步，仿佛是向同一方向迈的一小步，真理便会变成错误」，这句话给我们的启示是：","options":["错误可以变成真理","要敢于突破一切界限","量变无关紧要","要坚持适度原则，防止真理变成谬误"],"answer":3,"explanation":"真理有自己适用的条件和范围，超出这个范围哪怕一小步，真理也会变成谬误，启示我们把握分寸、坚持适度原则。故本题选A。","__sub":"马原"},{"id":"zz-30525","module":"zhengzhi","prompt":"「历史是人民写的」，这句话的哲学含义是：","options":["历史没有规律","历史由文人书写","人民群众是历史的创造者和历史发展的决定力量","个人可以决定历史方向"],"answer":2,"explanation":"「历史是人民写的」强调人民群众是物质财富、精神财富的创造者和社会变革的决定力量，是唯物史观群众史观的通俗表达。故本题选A。","__sub":"马原"},{"id":"zz-30526","module":"zhengzhi","prompt":"「从实际出发，不是从原则出发」，这一命题的哲学依据是：","options":["原则可以脱离实际","物质第一性，意识第二性","意识第一性","实践决定认识"],"answer":1,"explanation":"「实际」是客观存在的物质世界，「原则」是主观的认识，从实际出发而非从原则出发，体现了物质第一性、意识第二性的唯物主义基本立场。故本题选A。","__sub":"马原"},{"id":"zz-30527","module":"zhengzhi","prompt":"「矛盾是事物发展的源泉和动力」，其中内因与外因在事物发展中的作用是：","options":["内因是根据，外因是条件，外因通过内因起作用","外因是根据，内因是条件","二者同等重要，不分主次","内因可以脱离外因独立起作用"],"answer":0,"explanation":"内因是事物变化发展的根据和第一位原因，外因是变化的条件，外因必须通过内因才能起作用，二者缺一不可但地位不同。故本题选A。","__sub":"马原"},{"id":"zz-30528","module":"zhengzhi","prompt":"「历史从哪里开始，思想进程也应当从哪里开始」，这一论断说明：","options":["思想决定历史","认识来源于客观历史进程","历史与思想无关","思想可以超前于历史"],"answer":1,"explanation":"恩格斯此语说明理论逻辑（思想进程）是对历史进程的反映，认识来源于客观的历史和实践进程，而不是相反。故本题选A。","__sub":"马原"},{"id":"zz-30529","module":"zhengzhi","prompt":"「如果现象与本质完全一致，一切科学研究就都成为多余的了」，这句话说明：","options":["现象与本质有区别，科学研究才能透过现象把握本质","现象就是本质","本质不可认识","科学研究没有意义"],"answer":0,"explanation":"现象是事物的外部表现，本质是事物的内部联系，二者有区别，正因为如此，科学研究才需要透过现象认识本质。故本题选A。","__sub":"马原"},{"id":"zz-30530","module":"zhengzhi","prompt":"「本质在表现为现象，现象从反面表现本质」，这句话说明：","options":["现象是虚假的","现象与本质相互脱离","本质不可认识","现象与本质相互依存，本质通过现象表现出来"],"answer":3,"explanation":"本质总要表现为一定的现象，现象总是从特定方面表现本质，二者相互依存，人们可以通过现象认识本质。故本题选A。","__sub":"马原"},{"id":"zz-30531","module":"zhengzhi","prompt":"「必然性通过偶然性为自己开辟道路」，这句话说明：","options":["只有偶然性没有必然性","偶然性决定必然性","必然性通过偶然性表现出来，偶然性背后隐藏着必然性","必然性与偶然性无关"],"answer":2,"explanation":"必然性支配着偶然性，但必然性要通过大量偶然性表现出来并为自己开辟道路，偶然性背后隐藏着必然性，二者是对立统一的。故本题选A。","__sub":"马原"},{"id":"zz-30532","module":"zhengzhi","prompt":"「可能性和现实性是对立统一的」，其中可能性是指：","options":["已经存在的东西","人的主观愿望","永远不会实现的东西","包含在事物中、预示事物发展前途的种种趋势"],"answer":3,"explanation":"可能性是事物中包含的、预示着事物发展前途的种种趋势，是潜在的尚未实现的东西；现实性是已经存在和出现的东西。故本题选A。","__sub":"马原"},{"id":"zz-30533","module":"zhengzhi","prompt":"「只要功夫深，铁杵磨成针」与「守株待兔」的对比说明：","options":["要区分必然性与偶然性，把努力放在必然性上","偶然性可以依赖","努力没有意义","必然性可以脱离偶然性"],"answer":0,"explanation":"「铁杵磨成针」是坚持努力（把握必然性）的结果；「守株待兔」把偶然事件当作必然，终将失败，对比说明要把握必然性，不能依赖偶然。故本题选A。","__sub":"马原"},{"id":"zz-30534","module":"zhengzhi","prompt":"「生产力是人类社会发展的最终决定力量」，这一命题的根据是：","options":["生产力决定生产关系，进而决定社会形态的更替","生产力由人的意志决定","生产关系决定生产力","上层建筑决定社会发展"],"answer":0,"explanation":"生产力决定生产关系，生产关系（经济基础）决定上层建筑，生产力与生产关系、经济基础与上层建筑的矛盾运动推动社会形态更替，因此生产力是最终决定力量。故本题选A。","__sub":"马原"},{"id":"zz-30535","module":"zhengzhi","prompt":"「改革是社会主义制度的自我完善和发展」，其哲学依据是：","options":["改革是推翻根本制度","社会基本矛盾不可调和","社会基本矛盾可以通过改革得到调整和解决","上层建筑决定经济基础"],"answer":2,"explanation":"社会主义社会的基本矛盾仍然是生产力与生产关系、经济基础与上层建筑的矛盾，但它是非对抗性的，可以通过改革加以调整和解决，从而推动制度自我完善。故本题选A。","__sub":"马原"},{"id":"zz-30536","module":"zhengzhi","prompt":"「科学技术是第一生产力」，这一论断表明：","options":["科学技术日益成为生产力发展的决定性因素","科学技术可以脱离生产实践","科学技术决定生产关系","科学技术是唯一的生产力要素"],"answer":0,"explanation":"邓小平此论断强调科学技术渗透于生产力各要素之中，日益成为推动生产力发展的决定性因素，但科技不能脱离生产实践，也不是唯一要素。故本题选A。","__sub":"马原"},{"id":"zz-30537","module":"zhengzhi","prompt":"「人的全面发展」与「社会的全面发展」的关系是：","options":["相互依存、相互促进的辩证统一","人的发展决定社会发展","社会发展与个人无关","二者相互对立"],"answer":0,"explanation":"人的发展离不开社会发展提供的条件，社会的发展也离不开人的素质提高和能动创造，二者相互依存、相互促进，统一于社会实践。故本题选A。","__sub":"马原"},{"id":"zz-30538","module":"zhengzhi","prompt":"「物质资料的生产方式是社会存在和发展的基础」，其中生产方式是：","options":["劳动与资本的统一","经济基础与上层建筑的统一","生产力与生产关系的统一","城市与乡村的统一"],"answer":2,"explanation":"生产方式是人们获取物质资料的方式，是生产力与生产关系的统一，它决定社会的性质和面貌，是社会存在和发展的基础。故本题选A。","__sub":"马原"},{"id":"zz-30539","module":"zhengzhi","prompt":"「一切社会变迁和政治变革的终极原因，不应当到人们的头脑中寻找，而应当到生产方式和交换方式的变更中去寻找」，这一论断说明：","options":["政治变革与经济无关","社会变革的根源在于物质生产方式的变更","社会变革由思想决定","观念可以决定社会变迁"],"answer":1,"explanation":"恩格斯此语说明社会变迁和政治变革的根源不在人们的头脑（观念）中，而在生产方式和交换方式（物质经济）的变更中，坚持了唯物史观。故本题选A。","__sub":"马原"},{"id":"zz-30540","module":"zhengzhi","prompt":"「日往则月来，月往则日来，日月相推而明生焉」，这句话体现的哲学道理是：","options":["事物的运动变化是有规律的","日月运动没有规律","意识决定物质","静止是绝对的"],"answer":0,"explanation":"《周易》此语说明日月交替运行有其固有序列和规律，昼夜明暗随之产生，体现了事物运动变化的规律性。故本题选A。","__sub":"马原"},{"id":"zz-30541","module":"zhengzhi","prompt":"「天行有常，不为尧存，不为桀亡」，这句话表明：","options":["自然规律具有客观性，不以人的意志为转移","人可以改变自然规律","规律因人而异","自然与人事无关"],"answer":0,"explanation":"荀子此语说明自然界的运行有其固有规律，不因尧的贤明而存在，也不因桀的暴虐而消亡，强调规律的客观性。故本题选A。","__sub":"马原"},{"id":"zz-30542","module":"zhengzhi","prompt":"「制天命而用之」与「天行有常」相结合，体现的哲学道理是：","options":["主观能动性决定规律","人可以消灭规律","人在规律面前无能为力","在尊重客观规律的基础上发挥主观能动性"],"answer":3,"explanation":"荀子既承认「天行有常」（规律客观），又主张「制天命而用之」（利用规律），体现了尊重客观规律与发挥主观能动性的统一。故本题选A。","__sub":"马原"},{"id":"zz-30543","module":"zhengzhi","prompt":"「物是感觉的集合」，这一命题属于：","options":["辩证唯物主义","客观唯心主义","古代朴素唯物主义","主观唯心主义"],"answer":3,"explanation":"贝克莱把「感觉」当作世界的本原，认为事物是感觉的集合，把人的主观精神夸大为第一性，属于主观唯心主义。故本题选A。","__sub":"马原"},{"id":"zz-30544","module":"zhengzhi","prompt":"「理在事先」「未有天地之先，毕竟也只是理」，这一命题属于：","options":["主观唯心主义","客观唯心主义","形而上学唯物主义","庸俗唯物主义"],"answer":1,"explanation":"朱熹把「理」当作天地万物的本原，认为理先于天地而存在，把某种客观精神当作世界的本原，属于客观唯心主义。故本题选A。","__sub":"马原"},{"id":"zz-30545","module":"zhengzhi","prompt":"「气者，理之依也」与「理在气先」的分歧在于：","options":["是否承认运动","物质与意识何者为第一性","是否承认矛盾","是否承认实践"],"answer":1,"explanation":"王夫之「气者理之依也」认为气（物质）是理（精神）的依托，坚持物质第一性；朱熹「理在气先」则主张理（精神）第一性，二者的分歧是哲学基本问题。故本题选A。","__sub":"马原"},{"id":"zz-30546","module":"zhengzhi","prompt":"「静者，动之静也」，这一命题表明：","options":["运动与静止无关","静止是绝对的","运动是静止的表现","静止是运动的特殊状态，是相对的"],"answer":3,"explanation":"王夫之认为「静」是「动之静」，即静止是运动的一种特殊状态，说明静止是相对的、有条件的，运动才是绝对的。故本题选A。","__sub":"马原"},{"id":"zz-30547","module":"zhengzhi","prompt":"「世界则处在永恒的运动变化中，而运动变化的原因在于事物内部的矛盾性」，这句话表明：","options":["外力推动事物运动","矛盾是事物发展的动力","运动没有规律","静止决定运动"],"answer":1,"explanation":"事物运动变化的根源不在外部，而在于事物内部对立面的统一和斗争，即内部矛盾是事物发展的根本动力。故本题选A。","__sub":"马原"},{"id":"zz-30548","module":"zhengzhi","prompt":"「任何个别（不论怎样）都是一般」，这一命题表明：","options":["一般是虚幻的","个别脱离一般","矛盾的普遍性与特殊性相互联结","个别与一般绝对对立"],"answer":2,"explanation":"列宁此语说明任何个别事物都包含着一般（共性），一般只能在个别中存在，矛盾的普遍性与特殊性相互联结、不可分割。故本题选A。","__sub":"马原"},{"id":"zz-30549","module":"zhengzhi","prompt":"「人的思维是否具有客观的真理性，这不是一个理论的问题，而是一个实践的问题」，这一论断说明：","options":["认识不需要检验","思维可以自证真理性","理论问题与实践无关","实践是检验认识真理性的唯一标准"],"answer":3,"explanation":"马克思《关于费尔巴哈的提纲》指出，思维是否具有客观真理性不能靠理论争论解决，只能由实践来证明，体现了实践是检验真理的唯一标准。故本题选A。","__sub":"马原"},{"id":"zz-30550","module":"zhengzhi","prompt":"「世界统一于物质」这一命题的哲学含义是：","options":["世界统一于人的意识","世界统一于某种具体物质形态","世界的本原是物质，物质是第一性的","世界没有统一性"],"answer":2,"explanation":"世界的物质统一性原理是马克思主义哲学的基石，指世界的本原是物质，意识是物质的产物和反映，物质是第一性的。B项把物质等同于具体形态，是旧唯物主义的局限。故本题选A。","__sub":"马原"},{"id":"zz-30551","module":"zhengzhi","prompt":"「一切物质形态的共同特性是客观实在性」，其中「客观实在性」是指：","options":["永远不变","看得见摸得着","不依赖于人的意识而存在并能为人的意识所反映","只存在于自然界"],"answer":2,"explanation":"列宁指出物质的唯一特性是客观实在性，即独立于人的意识之外、又能被人的意识所反映，这是从万事万物中抽象出来的共同本质。故本题选A。","__sub":"马原"},{"id":"zz-30552","module":"zhengzhi","prompt":"意识的形式是主观的，其「主观性」是指：","options":["意识的形式（感性、理性）是主观世界特有的，但内容客观","意识可以脱离客观内容","意识由人的愿望决定","意识没有客观来源"],"answer":0,"explanation":"意识的形式（感觉、知觉、概念、判断等）是主观世界特有的加工方式，但其反映的内容来自客观世界，主观形式与客观内容是统一的。故本题选A。","__sub":"马原"},{"id":"zz-30553","module":"zhengzhi","prompt":"「意识是社会的产物」，这一命题的根据是：","options":["劳动和社会交往促进了意识的产生和发展","意识由个人独处产生","意识是天生的","意识与劳动无关"],"answer":0,"explanation":"意识的产生离不开社会性的劳动和语言，劳动和社会交往促进了人脑的发育和语言的形成，进而推动意识产生和发展。故本题选A。","__sub":"马原"},{"id":"zz-30554","module":"zhengzhi","prompt":"「意识活动具有创造性」，这一特点是指：","options":["意识活动没有客观依据","意识可以凭空创造物质","意识的创造不受任何限制","意识不仅能反映事物的外部现象，还能把握本质和规律，并能创造理想世界"],"answer":3,"explanation":"意识的创造性表现在既能反映现象又能把握本质规律，还能在观念中建构理想世界指导实践，但其创造必须以客观存在为依据。故本题选A。","__sub":"马原"},{"id":"zz-30555","module":"zhengzhi","prompt":"「物质生产实践是最基本的实践形式」，这是因为：","options":["其他实践形式不存在","物质生产是人类生存和社会发展的基础，决定其他实践形式","精神实践高于物质生产","物质生产与精神活动无关"],"answer":1,"explanation":"实践包括物质生产实践、社会政治实践和科学文化实践等形式，其中物质生产实践是人类最基本的实践活动，是社会存在和发展的基础。故本题选A。","__sub":"马原"},{"id":"zz-30556","module":"zhengzhi","prompt":"「实践的中介性」是指：","options":["实践只属于客观领域","实践与主客观无关","实践只属于主观领域","实践把主观与客观联系起来并加以对照"],"answer":3,"explanation":"实践是主观见之于客观的活动，它把主观认识与客观世界联系起来加以对照，因此能充当检验真理的标准。故本题选A。","__sub":"马原"},{"id":"zz-30557","module":"zhengzhi","prompt":"「联系的观点」与「孤立的观点」的对立，属于：","options":["唯物主义与唯心主义的分歧","辩证法与形而上学的分歧之一","可知论与不可知论的分歧","一元论与二元论的分歧"],"answer":1,"explanation":"辩证法用联系的、发展的、全面的观点看世界，形而上学则用孤立的、静止的、片面的观点看世界，联系与孤立的观点是二者的分歧之一。故本题选A。","__sub":"马原"},{"id":"zz-30558","module":"zhengzhi","prompt":"「发展」的实质是：","options":["新事物的产生和旧事物的灭亡","数量的增加","位置的移动","循环往复"],"answer":0,"explanation":"发展是前进的、上升的运动，其实质是新事物的产生和旧事物的灭亡，而不是简单的数量增减或位置变化。故本题选A。","__sub":"马原"},{"id":"zz-30559","module":"zhengzhi","prompt":"「新事物之所以必然战胜旧事物」，从哲学上看是因为：","options":["新事物没有缺陷","新事物力量一开始就强大","新事物符合客观规律，具有旧事物不可比拟的优越性","旧事物自动退出历史舞台"],"answer":2,"explanation":"新事物否定了旧事物中消极腐朽的东西，保留了其积极合理的因素，并增添了旧事物不能容纳的新内容，符合客观规律和历史趋势，因而必然战胜旧事物。故本题选A。","__sub":"马原"},{"id":"zz-30560","module":"zhengzhi","prompt":"「度」是事物保持自己质的稳定性的：","options":["内部联系","本质属性","外部表现","数量的界限或范围"],"answer":3,"explanation":"度是保持事物质的稳定性的数量界限或范围，在此范围内量变不引起质变，超出度的界限，事物就发生质变。故本题选A。","__sub":"马原"},{"id":"zz-30561","module":"zhengzhi","prompt":"「火候不到，众口难调；火候过了，美味变糟」，这启示我们做事要：","options":["把握分寸，坚持适度原则","追求越快越好","忽视量的积累","放弃主观努力"],"answer":0,"explanation":"烹饪讲究火候，不及或过头都做不好菜，说明做事要把握分寸、坚持适度原则，把量变控制在度的范围内。故本题选A。","__sub":"马原"},{"id":"zz-30562","module":"zhengzhi","prompt":"「矛盾的特殊性」是指：","options":["矛盾只存在于特殊事物中","具体事物的矛盾及每一个矛盾的各个方面都有自己的特点","矛盾可以回避","矛盾双方没有同一性"],"answer":1,"explanation":"矛盾的特殊性指不同事物的矛盾各有特点，同一事物的矛盾在不同发展阶段也各有特点，要求具体问题具体分析。故本题选A。","__sub":"马原"},{"id":"zz-30563","module":"zhengzhi","prompt":"「矛盾的同一性」是指：","options":["矛盾双方相互依存、相互贯通的性质和趋势","矛盾双方相互对立的性质","矛盾双方毫不相干","矛盾一方的消灭"],"answer":0,"explanation":"矛盾的同一性指矛盾双方相互依存、相互贯通（相互渗透、相互转化）的性质和趋势；斗争性则指相互排斥、相互对立的性质和趋势。故本题选A。","__sub":"马原"},{"id":"zz-30564","module":"zhengzhi","prompt":"「矛盾的斗争性」在事物发展中的作用是：","options":["斗争性决定同一性","斗争性可以脱离同一性","斗争越激烈越好","推动矛盾双方力量对比变化，实现事物的转化和发展"],"answer":3,"explanation":"斗争性推动矛盾双方力量对比发生变化，促成旧的统一体瓦解和新的统一体建立，从而推动事物发展，但斗争性离不开同一性。故本题选A。","__sub":"马原"},{"id":"zz-30565","module":"zhengzhi","prompt":"「主要矛盾」与「次要矛盾」的关系是：","options":["次要矛盾决定事物性质","主次矛盾固定不变","相互影响，并在一定条件下相互转化","二者毫无关联"],"answer":2,"explanation":"主要矛盾居于支配地位、起决定作用，次要矛盾处于从属地位，但二者相互影响并在一定条件下相互转化，要求我们统筹兼顾。故本题选A。","__sub":"马原"},{"id":"zz-30566","module":"zhengzhi","prompt":"「矛盾的主要方面」是指：","options":["永远正确的一方","数量占优的一方","在矛盾双方中处于支配地位、起主导作用的方面","被支配的一方"],"answer":2,"explanation":"矛盾双方力量不平衡，其中处于支配地位、起主导作用的方面是矛盾的主要方面，事物的性质主要由矛盾的主要方面决定。故本题选A。","__sub":"马原"},{"id":"zz-30567","module":"zhengzhi","prompt":"「认识论」与「本体论」的关系是：","options":["本体论是认识论的基础，认识论离不开本体论","认识论决定本体论","二者毫无关系","本体论已过时"],"answer":0,"explanation":"对世界本原（本体）的回答决定了对认识可能性及其途径的回答，本体论是认识论的前提和基础。故本题选A。","__sub":"马原"},{"id":"zz-30568","module":"zhengzhi","prompt":"「反映论」与「先验论」的根本对立在于：","options":["认识是否需要逻辑","认识是否需要语言","认识是否来源于客观世界","认识是否有用"],"answer":2,"explanation":"反映论主张认识是对客观世界的反映，先验论主张认识先于经验、先于客观世界而存在，二者的对立是认识论中两条路线的根本对立。故本题选A。","__sub":"马原"},{"id":"zz-30569","module":"zhengzhi","prompt":"「能动的反映论」与「机械反映论」的区别在于：","options":["是否承认认识过程的能动性和辩证性","是否承认认识来源于客观世界","是否承认物质第一性","是否承认世界可知"],"answer":0,"explanation":"机械反映论把认识看作消极被动的镜子式反映，能动的反映论则把认识看作在实践基础上主体对客体的能动反映，包含选择、建构和创造。故本题选A。","__sub":"马原"},{"id":"zz-30570","module":"zhengzhi","prompt":"「感性认识的三种形式」是：","options":["经验、常识、科学","概念、判断、推理","假设、理论、体系","感觉、知觉、表象"],"answer":3,"explanation":"感性认识是认识的初级阶段，包括感觉、知觉、表象三种形式，其特点是直接性和具体性。概念、判断、推理是理性认识的形式。故本题选A。","__sub":"马原"},{"id":"zz-30571","module":"zhengzhi","prompt":"「理性认识的三种形式」是：","options":["观察、实验、调查","感觉、知觉、表象","直觉、灵感、顿悟","概念、判断、推理"],"answer":3,"explanation":"理性认识是认识的高级阶段，包括概念、判断、推理三种形式，其特点是间接性和抽象性，把握的是事物的本质和规律。故本题选A。","__sub":"马原"},{"id":"zz-30572","module":"zhengzhi","prompt":"「从感性认识到理性认识的飞跃」需要的基本条件是：","options":["占有丰富真实的感性材料，运用科学方法加工制作","凭空想象","照搬书本","等待灵感"],"answer":0,"explanation":"实现第一次飞跃，必须深入实践获取十分丰富、合乎实际的感性材料，并运用科学的思维方法对材料进行「去粗取精、去伪存真、由此及彼、由表及里」的加工。故本题选A。","__sub":"马原"},{"id":"zz-30573","module":"zhengzhi","prompt":"「从理性认识到实践的飞跃」的意义在于：","options":["认识只有回到实践才能得到检验和发展，实现改造世界的目的","理性认识没有意义","实践可以没有理论指导","认识过程到此结束"],"answer":0,"explanation":"理性认识只有回到实践中，才能接受检验、得到丰富和发展，并实现指导实践、改造世界的目的，这是认识过程中意义更重大的第二次飞跃。故本题选A。","__sub":"马原"},{"id":"zz-30574","module":"zhengzhi","prompt":"「真理的客观性」是指：","options":["真理由多数人决定","真理的形式没有主观性","真理因人而异","真理的内容不依赖于人的主观意志"],"answer":3,"explanation":"真理的客观性指其内容是对客观事物及其规律的正确反映，不依赖于任何人的主观意志，凡真理都是客观真理。故本题选A。","__sub":"马原"},{"id":"zz-30575","module":"zhengzhi","prompt":"「实践标准的确定性」是指：","options":["实践标准随时改变","实践是检验真理的唯一标准，最终能够鉴别认识的真理性","实践标准因人而异","实践标准可以替代"],"answer":1,"explanation":"实践标准的确定性（绝对性）指实践是检验真理的唯一标准，离开实践没有别的标准；不确定性（相对性）指一定阶段的实践有局限性，检验是一个过程。故本题选A。","__sub":"马原"},{"id":"zz-30576","module":"zhengzhi","prompt":"「社会存在」是指：","options":["政治法律制度","社会意识的总和","社会生活的物质方面，包括自然地理环境、人口因素和物质生产方式","风俗习惯"],"answer":2,"explanation":"社会存在是社会生活的物质方面，包括自然地理环境、人口因素和物质生产方式，其中物质生产方式是社会存在和发展的决定力量。故本题选A。","__sub":"马原"},{"id":"zz-30577","module":"zhengzhi","prompt":"「社会意识」包括：","options":["自然地理环境","物质生产方式","政治法律思想、道德、艺术、宗教、哲学、科学等意识形式","人口因素"],"answer":2,"explanation":"社会意识是社会生活的精神方面，包括政治法律思想、道德、艺术、宗教、哲学、科学等意识形式和风俗习惯等社会心理。故本题选A。","__sub":"马原"},{"id":"zz-30578","module":"zhengzhi","prompt":"「生产关系」是指：","options":["人们在物质生产过程中形成的不以人的意志为转移的经济关系","政治上的领导与被领导关系","血缘亲属关系","思想文化交流关系"],"answer":0,"explanation":"生产关系是人们在物质生产过程中形成的经济关系，包括生产资料所有制关系、生产中人与人的关系和产品分配关系。故本题选A。","__sub":"马原"},{"id":"zz-30579","module":"zhengzhi","prompt":"「上层建筑」包括：","options":["物质文明与精神文明","经济基础与生产力","生产力与生产关系","政治上层建筑与观念上层建筑"],"answer":3,"explanation":"上层建筑建立在一定经济基础之上，包括政治上层建筑（国家政权、军队、法律制度等）和观念上层建筑（政治法律思想、道德、宗教、哲学等）。故本题选A。","__sub":"马原"},{"id":"zz-30580","module":"zhengzhi","prompt":"「国家」的实质是：","options":["超阶级的仲裁机构","全民意志的体现","阶级统治的工具，一个阶级压迫另一个阶级的机器","单纯的地理概念"],"answer":2,"explanation":"马克思主义认为，国家是阶级矛盾不可调和的产物，其实质是阶级统治的工具，是经济上占统治地位的阶级进行统治的暴力机器。故本题选A。","__sub":"马原"},{"id":"zz-30581","module":"zhengzhi","prompt":"「社会革命」的实质是：","options":["统治阶级内部的权力更替","革命阶级推翻反动阶级的统治，实现社会形态的更替","社会生活的局部改善","思想观念的更新"],"answer":1,"explanation":"社会革命是社会形态的质变，其实质是革命阶级推翻反动阶级的统治，用新的社会制度代替旧的社会制度。故本题选A。","__sub":"马原"},{"id":"zz-30582","module":"zhengzhi","prompt":"「改革」与「革命」的区别在于：","options":["二者没有区别","改革是同一社会形态内的自我完善，革命是社会形态的根本变革","改革推翻根本制度","革命不改变社会形态"],"answer":1,"explanation":"改革是在同一社会形态内部调整生产关系和上层建筑中不适应的部分，是制度的自我完善；革命则是社会形态的根本质变。故本题选A。","__sub":"马原"},{"id":"zz-30583","module":"zhengzhi","prompt":"「科学技术是先进生产力的集中体现和主要标志」，这是因为：","options":["科学技术渗透于生产力各要素并转化为现实生产力","科技可以脱离生产","科技决定生产关系","科技与生产力无关"],"answer":0,"explanation":"科学技术通过提高劳动者素质、改进生产工具、扩展劳动对象等途径渗透到生产力各要素中，转化为现实生产力，成为先进生产力的集中体现。故本题选A。","__sub":"马原"},{"id":"zz-30584","module":"zhengzhi","prompt":"「群众观点」的基本内容是：","options":["一切服从领导","坚信人民群众自己解放自己的观点，全心全意为人民服务，向群众学习等","群众自动解决问题","精英替群众做主"],"answer":1,"explanation":"群众观点是无产阶级政党的根本观点，包括坚信人民群众自己解放自己、全心全意为人民服务、向人民群众负责、向人民群众学习等内容。故本题选A。","__sub":"马原"},{"id":"zz-30585","module":"zhengzhi","prompt":"「群众路线」的基本内容是：","options":["一切为了群众，一切依靠群众，从群众中来，到群众中去","一切由群众自发的路线","只依靠群众的路线","脱离群众的路线"],"answer":0,"explanation":"群众路线是无产阶级政党的根本工作路线，其基本内容是一切为了群众、一切依靠群众，从群众中来、到群众中去，是群众观点的贯彻和体现。故本题选A。","__sub":"马原"},{"id":"zz-30586","module":"zhengzhi","prompt":"「人的价值」与「物的价值」的根本区别在于：","options":["物的价值高于人的价值","人的价值由市场决定","人的价值具有创造性，能够创造价值满足社会和自身需要","二者没有区别"],"answer":2,"explanation":"物的价值是满足人的需要的属性，人的价值则在于通过实践创造价值，既满足社会需要（社会价值），也满足自身需要（自我价值），具有创造性和目的性。故本题选A。","__sub":"马原"},{"id":"zz-30587","module":"zhengzhi","prompt":"「人生价值的评价」的根本尺度是：","options":["是否对社会发展和人类进步事业作出贡献","财富多少","地位高低","名声大小"],"answer":0,"explanation":"评价人生价值的根本尺度是看个人的实践活动是否符合社会发展的客观规律，是否对社会发展和人类进步事业作出贡献。故本题选A。","__sub":"马原"},{"id":"zz-30588","module":"zhengzhi","prompt":"「必然王国」与「自由王国」的关系是：","options":["必然王国不可超越","二者绝对对立","自由王国可以一蹴而就","人类从必然王国向自由王国的飞跃是一个不断发展的历史过程"],"answer":3,"explanation":"在必然王国中人们受盲目必然性支配，通过不断认识规律、改造世界，人类逐步获得自由，从必然王国向自由王国的飞跃是不断发展的历史过程。故本题选A。","__sub":"马原"},{"id":"zz-30589","module":"zhengzhi","prompt":"「共产主义社会」的基本特征之一是：","options":["物质财富极大丰富，实行各尽所能、按需分配","实行按劳分配","保留阶级差别","生产力低下"],"answer":0,"explanation":"共产主义社会是物质财富极大丰富、人民精神境界极大提高、实行各尽所能按需分配、每个人自由而全面发展的社会，是人类社会发展的最高形态。故本题选A。","__sub":"马原"},{"id":"zz-30590","module":"zhengzhi","prompt":"「劳动」在人类起源中的作用是：","options":["劳动与人的起源无关","劳动创造了人本身，是人与动物区别开来的决定性环节","语言先于劳动产生","直立行走与劳动无关"],"answer":1,"explanation":"恩格斯指出劳动创造了人本身，劳动促进了手的进化和语言的产生，进而推动大脑发展，是人与动物区别开来的决定性环节。故本题选A。","__sub":"马原"},{"id":"zz-30591","module":"zhengzhi","prompt":"「地理环境」在社会发展中的作用是：","options":["影响社会发展，但不决定社会的性质和发展方向","决定社会性质","与社会发展无关","可以随意改变社会形态"],"answer":0,"explanation":"地理环境提供社会生产和生活资料的来源，影响生产部门的分布和发展速度，但不能决定社会的性质和社会形态的更替。故本题选A。","__sub":"马原"},{"id":"zz-30592","module":"zhengzhi","prompt":"「人口因素」在社会发展中的作用是：","options":["决定社会性质","影响社会发展，但不决定社会的性质","与社会发展无关","可以随意改变社会形态"],"answer":1,"explanation":"人口因素是社会物质生活的必要条件，人口的数量、质量、结构影响生产的发展，但不能决定社会的性质和发展方向。故本题选A。","__sub":"马原"},{"id":"zz-30593","module":"zhengzhi","prompt":"「生产资料所有制关系」在生产关系体系中的地位是：","options":["与生产关系无关","是生产关系的次要方面","是生产关系的基础，决定生产关系的性质","由分配关系决定"],"answer":2,"explanation":"生产资料所有制关系是生产关系的基础和核心，决定生产关系的性质，也决定人们在生产中的地位和产品的分配方式。故本题选A。","__sub":"马原"},{"id":"zz-30594","module":"zhengzhi","prompt":"「统治阶级的思想在每一时代都是占统治地位的思想」，这句话说明：","options":["意识形态具有阶级性，反映统治阶级的利益","思想没有阶级属性","思想决定经济基础","被统治阶级没有思想"],"answer":0,"explanation":"马克思恩格斯指出，支配物质生产资料的阶级同时也支配着精神生产资料，统治阶级的思想是占统治地位的思想，说明意识形态具有阶级性。故本题选A。","__sub":"马原"},{"id":"zz-30595","module":"zhengzhi","prompt":"「政治法律思想」与「道德」的区别在于：","options":["政治法律思想依靠国家强制力维护，道德依靠社会舆论和内心信念维护","二者没有区别","道德依靠强制力维护","政治法律思想没有阶级性"],"answer":0,"explanation":"政治法律思想是观念上层建筑的政治部分，与国家政权紧密结合，靠强制力推行；道德则靠社会舆论、传统习惯和内心信念来维系。故本题选A。","__sub":"马原"},{"id":"zz-30596","module":"zhengzhi","prompt":"「意识形态」的阶级性是指：","options":["意识形态与经济无关","意识形态没有阶级属性","所有意识形态完全相同","在阶级社会中，意识形态反映一定阶级的利益和要求"],"answer":3,"explanation":"在阶级社会中，意识形态作为观念上层建筑，总是反映一定阶级的利益、愿望和要求，具有鲜明的阶级性。故本题选A。","__sub":"马原"},{"id":"zz-30597","module":"zhengzhi","prompt":"「社会形态更替的统一性与多样性」是指：","options":["社会发展没有规律","各国发展道路完全相同","人类社会发展遵循共同规律，但具体道路因国情不同而多样","发展道路由个人决定"],"answer":2,"explanation":"社会形态更替遵循生产力决定生产关系等共同规律（统一性），但各国因历史条件、文化传统不同，发展道路呈现多样性。故本题选A。","__sub":"马原"},{"id":"zz-30598","module":"zhengzhi","prompt":"「社会形态更替的曲折性」是指：","options":["倒退是最终结局","社会发展一帆风顺","社会发展中可能出现倒退和反复，但总趋势是前进的","前进与倒退没有区别"],"answer":2,"explanation":"社会形态的更替不是直线的，可能因各种原因出现停滞、倒退，但从历史长河看，前进、上升是总趋势，曲折性不改变前进性。故本题选A。","__sub":"马原"},{"id":"zz-30599","module":"zhengzhi","prompt":"「历史合力论」认为：","options":["个人意志与历史无关","历史由单一意志决定","历史结果是无数个人意志相互作用形成的合力的产物","历史是随机的"],"answer":2,"explanation":"恩格斯指出，历史结果是无数相互交错的个人意志和活动形成的「合力」的产物，任何个人意志都不能决定历史的最终结果，但都参与了合力的形成。故本题选A。","__sub":"马原"},{"id":"zz-30600","module":"zhengzhi","prompt":"「人的自由而全面的发展」实现的前提是：","options":["回到自然状态","个人脱离社会","消灭一切劳动","社会生产力的高度发展和旧式分工的消灭"],"answer":3,"explanation":"人的自由全面发展以生产力高度发展、物质财富极大丰富、旧式分工消灭、人的社会关系极大丰富为前提，是共产主义社会的特征。故本题选A。","__sub":"马原"},{"id":"zz-30601","module":"zhengzhi","prompt":"「万物都在运动，但只是在概念中运动」，这一观点属于：","options":["辩证唯物主义","客观唯心主义","古代朴素唯物主义","主观唯心主义"],"answer":3,"explanation":"毕尔生认为万物只在概念中运动，否认物质自身的运动，把运动归于主观概念，属于主观唯心主义的运动观。故本题选A。","__sub":"马原"},{"id":"zz-30602","module":"zhengzhi","prompt":"「野旷天低树，江清月近人」中「月近人」的景象说明：","options":["月亮真的靠近人","意识对客观事物的反映具有主观特征","意识决定物质","客观事物随人的感受改变"],"answer":1,"explanation":"江水清澈使水中月影清晰，让人产生「月近人」的感受，说明意识对客观对象的反映受主体状态和条件影响，具有主观特征，但内容仍源于客观。故本题选A。","__sub":"马原"},{"id":"zz-30603","module":"zhengzhi","prompt":"「仁者见仁，智者见智」，这一说法在哲学上表明：","options":["真理因人而异","受主体因素影响，人们对同一对象的反映有差异","客观事物没有共同本质","认识无法达到真理"],"answer":1,"explanation":"对同一对象，仁者、智者因立场、知识、经验不同而有不同理解，说明认识受主体状况影响，但真理仍有客观标准，B、C、D均错误。故本题选A。","__sub":"马原"},{"id":"zz-30604","module":"zhengzhi","prompt":"「日有所思，夜有所梦」，这一俗语体现的哲学道理是：","options":["梦可以预测未来","梦是独立于现实的","梦也是对客观现实的反映，只是形式虚幻","梦与意识无关"],"answer":2,"explanation":"白天的所思所想（源于现实）会进入梦境，说明梦的内容归根到底来自客观现实，只是以虚幻歪曲的形式反映。故本题选A。","__sub":"马原"},{"id":"zz-30605","module":"zhengzhi","prompt":"「世界上没有不可认识之物，只有尚未认识之物」，这一论断属于：","options":["怀疑论的观点","不可知论的观点","可知论的观点","相对主义的观点"],"answer":2,"explanation":"该论断承认世界可以被认识，只是认识有一个过程，尚未认识不等于不可认识，坚持了可知论的立场。故本题选A。","__sub":"马原"},{"id":"zz-30606","module":"zhengzhi","prompt":"「感觉是人与外界事物之间的屏障」，这一观点的错误在于：","options":["否认了感觉是认识的桥梁，走向不可知论","夸大了理性认识的作用","承认了世界的可知性","坚持了唯物主义反映论"],"answer":0,"explanation":"休谟认为人只能认识感觉，感觉之外是否真实存在不可知，把感觉当作人与世界之间的屏障，割断了认识与客观世界的联系，走向不可知论。故本题选A。","__sub":"马原"},{"id":"zz-30607","module":"zhengzhi","prompt":"「物质与意识的对立，只有在非常有限的范围内才有绝对的意义」，这一「有限的范围」是指：","options":["回答规律是否客观时","回答世界是否运动时","回答认识是否可靠时","回答谁是本原的问题时"],"answer":3,"explanation":"恩格斯指出物质与意识的对立只是在回答何者为本原这一哲学基本问题时才有绝对意义，超出这个范围，二者的对立是相对的，意识可以反作用于物质。故本题选A。","__sub":"马原"},{"id":"zz-30608","module":"zhengzhi","prompt":"「一切物质都具有类似感觉的反应特性」，这一命题说明：","options":["物质都有意识","意识是物质世界长期发展的产物","感觉与物质等同","意识先于物质"],"answer":1,"explanation":"从无生命物质的反应特性到低等生物的刺激感应、动物的感觉心理，再到人类意识，说明意识是物质世界长期演化的产物。B项混淆了反应特性与意识。故本题选A。","__sub":"马原"},{"id":"zz-30609","module":"zhengzhi","prompt":"「意识是人脑的机能」，这一命题表明：","options":["人脑是意识的物质器官，意识依赖于高度发达的物质","意识可以脱离人脑","一切动物都有意识","意识就是人脑"],"answer":0,"explanation":"人脑是高度发达的物质系统，是意识的物质器官，意识是人脑的机能，说明意识对物质的依赖性，但不能把意识等同于人脑本身。故本题选A。","__sub":"马原"},{"id":"zz-30610","module":"zhengzhi","prompt":"「观念的产生离不开语言」，这一命题说明：","options":["意识与语言无关","语言决定意识内容","语言是意识的物质外壳，是意识表达和传播的工具","语言先于意识产生"],"answer":2,"explanation":"意识的表达、固定和传播离不开语言这一物质外壳，语言随劳动和社会交往而产生，与意识相互依存，但语言不决定意识的内容。故本题选A。","__sub":"马原"},{"id":"zz-30611","module":"zhengzhi","prompt":"「精神生产」随着物质生产的改造而改造，这一命题说明：","options":["精神生产独立于物质生产","精神生产决定物质生产","二者互不影响","物质生产决定精神生产"],"answer":3,"explanation":"马克思恩格斯在《德意志意识形态》中指出，精神生产随物质生产的改造而改造，说明物质生产是精神生产的基础，精神生产随其变化而变化。故本题选A。","__sub":"马原"},{"id":"zz-30612","module":"zhengzhi","prompt":"「客观规律性与主观能动性」的关系中，「自由」是指：","options":["对必然的认识和改造，而非摆脱必然","随心所欲不受约束","摆脱一切规律","意志的绝对自由"],"answer":0,"explanation":"自由不是摆脱客观规律，而是在认识和把握必然性的基础上改造世界、实现目的，自由以必然为前提。故本题选A。","__sub":"马原"},{"id":"zz-30613","module":"zhengzhi","prompt":"「巧妇难为无米之炊」之外，「有米之炊」还需巧妇，这体现的哲学道理是：","options":["尊重客观规律与发挥主观能动性相结合","客观条件毫无作用","主观努力决定一切","二者可以偏废其一"],"answer":0,"explanation":"「米」是客观条件，「巧妇」是主观能动性，做成饭二者缺一不可，说明既要尊重客观条件，又要发挥主观能动性，二者相结合。故本题选A。","__sub":"马原"},{"id":"zz-30614","module":"zhengzhi","prompt":"「人定胜天」这一命题的科学含义是：","options":["人在认识和遵循规律的基础上可以改造自然","人可以随意征服自然","自然规律可以废除","人与自然绝对对立"],"answer":0,"explanation":"「人定胜天」的科学含义是在认识自然规律、顺应规律的前提下利用和改造自然，而非无视规律的盲目征服，否则会遭到自然的报复。故本题选A。","__sub":"马原"},{"id":"zz-30615","module":"zhengzhi","prompt":"「整体性是系统的基本特征」，系统的整体性是指：","options":["部分可以脱离整体","整体等于部分之和","系统的整体功能不是各要素功能的简单相加","整体没有结构"],"answer":2,"explanation":"系统的整体性指整体与部分相互依存，整体通过内部结构优化产生各要素单独不具备的新功能，整体功能不等于部分功能的简单相加。故本题选A。","__sub":"马原"},{"id":"zz-30616","module":"zhengzhi","prompt":"「一着不慎，满盘皆输」，这一俗语体现的哲学道理是：","options":["关键部分的变化对整体功能起决定作用","任何部分都决定整体","整体与部分无关","整体功能必然大于部分之和"],"answer":0,"explanation":"「一着」是关键部分，「满盘」是整体，关键部分处理不当会导致全局失败，说明关键部分对整体功能起决定作用。故本题选A。","__sub":"马原"},{"id":"zz-30617","module":"zhengzhi","prompt":"「万物并育而不相害，道并行而不相悖」，这一古语体现的哲学道理是：","options":["矛盾双方绝对对立","矛盾双方相互依存、和谐共生","事物互不联系","发展没有规律"],"answer":1,"explanation":"万物共同生长而不相妨害，道理并行而不相冲突，说明矛盾双方相互依存、统一体和谐共生，体现了矛盾的同一性思想。故本题选A。","__sub":"马原"},{"id":"zz-30618","module":"zhengzhi","prompt":"「天下大事，必作于细」，这一古语体现的哲学道理是：","options":["大事与小事无关","细节决定一切","质变比量变重要","量变是质变的必要准备，要重视细节积累"],"answer":3,"explanation":"老子此语说明大事由细节积累而成，要成就大事必须从细小处做起，体现了量变是质变的必要准备。故本题选A。","__sub":"马原"},{"id":"zz-30619","module":"zhengzhi","prompt":"「图难于其易，为大于其细」，这一古语体现的方法论是：","options":["急于求成","回避困难","循序渐进，从易处和细处着手解决难题","贪大求全"],"answer":2,"explanation":"老子主张处理难题从容易处入手，成就大事从细微处着手，体现了循序渐进、重视量的积累的方法论。故本题选A。","__sub":"马原"},{"id":"zz-30620","module":"zhengzhi","prompt":"「合抱之木，生于毫末；九层之台，起于累土」，这一古语体现的哲学道理是：","options":["量变没有意义","质变先于量变","量变积累到一定程度必然引起质变","质变与量变无关"],"answer":2,"explanation":"大树由幼苗长成，高台由泥土垒起，说明事物的发展从量的积累开始，量变积累到一定程度必然引起质变。故本题选A。","__sub":"马原"},{"id":"zz-30621","module":"zhengzhi","prompt":"「物极必反，器满则倾」，这一古语体现的哲学道理是：","options":["量变超过度的界限就会引起质变","量变不会引起质变","质变没有条件","度可以无限突破"],"answer":0,"explanation":"事物发展到极端就会向相反方向转化，器皿水满则溢出倾覆，说明量变超过度的界限必然引起质变。故本题选A。","__sub":"马原"},{"id":"zz-30622","module":"zhengzhi","prompt":"「将欲取之，必先予之」，这一古语体现的哲学道理是：","options":["矛盾双方在一定条件下相互转化","矛盾双方绝对对立","予与取没有联系","转化不需要条件"],"answer":0,"explanation":"想要获取必先给予，通过「予」创造条件促成向「取」的转化，说明矛盾双方在一定条件下相互转化，要善于创造条件促成转化。故本题选A。","__sub":"马原"},{"id":"zz-30623","module":"zhengzhi","prompt":"「曲则全，枉则直，洼则盈，敝则新」，这一古语体现的哲学道理是：","options":["事物静止不变","矛盾双方相互依存并可以向对立面转化","对立面不能转化","矛盾双方毫无联系"],"answer":1,"explanation":"委屈反而能保全，弯曲反而能伸直，低洼反而能充盈，破旧反而能生新，说明矛盾双方相互依存并向对立面转化。故本题选A。","__sub":"马原"},{"id":"zz-30624","module":"zhengzhi","prompt":"「尺有所短，寸有所长」，这一古语体现的哲学道理是：","options":["事物只有一面性","尺与寸没有区别","矛盾具有特殊性，要一分为二地看问题","评价标准绝对统一"],"answer":2,"explanation":"尺虽长但有短处，寸虽短但有长处，说明任何事物都包含对立的两个方面，各有其长与短，要一分为二地全面看问题。故本题选A。","__sub":"马原"},{"id":"zz-30625","module":"zhengzhi","prompt":"「和而不唱，出而不入」之外，「和而不同」这一古语体现的哲学道理是：","options":["和谐排斥差异","同一就是完全相同","斗争就是消灭对方","矛盾的同一性与斗争性相统一，统一体中包含差异"],"answer":3,"explanation":"「和而不同」指和谐共处但不强求同一，承认差异和分歧的存在，体现了矛盾同一性（和谐）与斗争性（差异）相统一的思想。故本题选A。","__sub":"马原"},{"id":"zz-30626","module":"zhengzhi","prompt":"「万物负阴而抱阳，冲气以为和」，这一古语体现的哲学道理是：","options":["事物只有一面","任何事物都包含阴阳两个对立面，矛盾具有普遍性","阴阳绝对对立","矛盾可以消灭"],"answer":1,"explanation":"老子认为万物都背负阴而怀抱阳，阴阳二气相互作用达到和谐，说明任何事物内部都包含对立面，矛盾具有普遍性。故本题选A。","__sub":"马原"},{"id":"zz-30627","module":"zhengzhi","prompt":"「一分为二」与「合二而一」的关系是：","options":["前者正确后者错误","二者相互对立","前者错误后者正确","前者强调矛盾双方的对立，后者强调矛盾双方的统一，二者统一于矛盾分析法"],"answer":3,"explanation":"「一分为二」强调看到矛盾双方的对立，「合二而一」强调矛盾双方的统一，二者是矛盾分析法的两个方面，统一于对矛盾的正确把握。故本题选A。","__sub":"马原"},{"id":"zz-30628","module":"zhengzhi","prompt":"「具体地分析具体的情况」，这一方法论的哲学依据是：","options":["矛盾的特殊性原理","矛盾的普遍性原理","量变质变规律","否定之否定规律"],"answer":0,"explanation":"矛盾的特殊性要求对具体事物的矛盾进行具体分析，采取不同的解决方法，列宁称之为马克思主义活的灵魂。故本题选A。","__sub":"马原"},{"id":"zz-30629","module":"zhengzhi","prompt":"「一般号召与个别指导相结合」的工作方法，其哲学依据是：","options":["否定之否定规律","矛盾的对立性","量变质变规律","矛盾普遍性与特殊性的辩证关系"],"answer":3,"explanation":"「一般号召」体现普遍性（共性），「个别指导」体现特殊性（个性），二者结合体现了从个别到一般、再由一般指导个别的辩证关系。故本题选A。","__sub":"马原"},{"id":"zz-30630","module":"zhengzhi","prompt":"「解剖麻雀」这一工作方法的哲学依据是：","options":["一般脱离个别","通过个别认识一般，矛盾的普遍性寓于特殊性之中","个别没有共性","普遍性可以脱离特殊性"],"answer":1,"explanation":"通过深入解剖一个典型（个别），可以认识同类事物的共同规律（一般），因为矛盾的普遍性寓于特殊性之中，并通过特殊性表现出来。故本题选A。","__sub":"马原"},{"id":"zz-30631","module":"zhengzhi","prompt":"「弹钢琴要十个指头都动作，但不能同时按下去」，这一比喻说明：","options":["十个指头各自为政","只抓重点不顾其余","平均用力不分主次","既要统筹兼顾，又要分清主次节奏"],"answer":3,"explanation":"毛泽东以弹钢琴作比喻，说明干工作既要十个指头都动（统筹兼顾），又要有节奏、有先后（分清主次），是两点论与重点论统一的形象表达。故本题选A。","__sub":"马原"},{"id":"zz-30632","module":"zhengzhi","prompt":"「眉毛胡子一把抓」的做法，其方法论错误在于：","options":["具体问题具体分析","只抓重点","坚持了两点论","不分主次，违背了重点论"],"answer":3,"explanation":"「眉毛胡子一把抓」比喻不分轻重缓急、平均用力，违背了重点论的要求，没有抓住主要矛盾和矛盾的主要方面。故本题选A。","__sub":"马原"},{"id":"zz-30633","module":"zhengzhi","prompt":"「单打一」的工作方法，其方法论错误在于：","options":["分清主次","面面俱到","统筹兼顾","只抓一点不及其余，违背了两点论"],"answer":3,"explanation":"「单打一」比喻只抓一点而不顾其他，只看到矛盾的一个方面，违背了两点论全面看问题的要求。故本题选A。","__sub":"马原"},{"id":"zz-30634","module":"zhengzhi","prompt":"「扬弃」作为辩证否定的实质，其特点是：","options":["外力强加的否定","全盘肯定或全盘否定","既克服又保留，是联系的环节和发展的环节","抛弃一切旧事物"],"answer":2,"explanation":"辩证否定既克服旧事物中消极过时的东西，又保留其积极合理的因素，是新事物代替旧事物的环节，也是新旧事物联系的环节。故本题选A。","__sub":"马原"},{"id":"zz-30635","module":"zhengzhi","prompt":"「在批判旧世界中发现新世界」，这一命题体现的哲学道理是：","options":["新事物凭空产生","新旧事物毫无联系","辩证否定是发展的环节，新事物在批判旧事物中产生","旧事物不可超越"],"answer":2,"explanation":"马克思指出要在批判旧世界中发现新世界，说明对新事物的否定不是简单抛弃，而是在批判中孕育新事物，体现了辩证否定的发展环节。故本题选A。","__sub":"马原"},{"id":"zz-30636","module":"zhengzhi","prompt":"「前途是光明的，道路是曲折的」，这一论断的哲学依据是：","options":["否定之否定规律揭示的事物发展的前进性与曲折性的统一","量变质变规律","对立统一规律","联系的普遍性"],"answer":0,"explanation":"否定之否定规律揭示了事物发展经过两次否定、三个阶段，呈现前进性与曲折性的统一，故前途光明而道路曲折。故本题选A。","__sub":"马原"},{"id":"zz-30637","module":"zhengzhi","prompt":"「螺旋式上升」「波浪式前进」，这两个比喻共同说明：","options":["发展是循环的","发展是直线的","事物发展的总方向是前进的，具体道路是曲折的","发展没有方向"],"answer":2,"explanation":"螺旋式上升、波浪式前进形象地说明事物发展不是直线，而是前进性与曲折性的统一，总方向前进上升，具体道路迂回曲折。故本题选A。","__sub":"马原"},{"id":"zz-30638","module":"zhengzhi","prompt":"「实践的观点是辩证唯物论的认识论之第一的和基本的观点」，这是因为：","options":["认识决定实践","实践决定意识","实践是认识的来源、动力、标准和目的","认识可以脱离实践"],"answer":2,"explanation":"实践是认识的来源、发展动力、检验标准和最终目的，贯穿认识运动的全过程，因此是认识论的第一的和基本的观点。故本题选A。","__sub":"马原"},{"id":"zz-30639","module":"zhengzhi","prompt":"「你要有知识，你就得参加变革现实的实践。你要知道梨子的滋味，你就得变革梨子，亲口吃一吃」，这段话说明：","options":["实践可以脱离认识","书本知识无用","认识不需要学习","实践是认识的来源，直接经验靠亲身实践获得"],"answer":3,"explanation":"毛泽东以「吃梨子」作比喻，说明要获得对事物的认识必须亲身参加变革该事物的实践，实践是认识的来源。故本题选A。","__sub":"马原"},{"id":"zz-30640","module":"zhengzhi","prompt":"「认识从实践始，经过实践得到了理论的认识，还须再回到实践去」，这句话说明：","options":["认识运动是从实践到认识、再从认识到实践的辩证过程","认识与实践无关","认识可以脱离实践","实践可以脱离认识"],"answer":0,"explanation":"毛泽东此语概括了认识运动的全过程：从实践中获得感性认识，上升为理性认识，再回到实践中接受检验和指导实践。故本题选A。","__sub":"马原"},{"id":"zz-30641","module":"zhengzhi","prompt":"「感觉到了的东西不能立刻理解它，只有理解了的东西才能更深刻地感觉它」，这句话说明：","options":["理性认识脱离感性","感性认识无用","感性认识与理性认识相互渗透、相互依赖","二者绝对对立"],"answer":2,"explanation":"感性认识有待上升为理性认识，理性认识又使感性认识更深刻，说明二者相互渗透、相互依赖，统一于认识过程。故本题选A。","__sub":"马原"},{"id":"zz-30642","module":"zhengzhi","prompt":"「只有理解了的东西才能更深刻地感觉它」之外，「跟着感觉走」的错误在于：","options":["否认实践决定认识","夸大理性认识","否认感性认识","夸大感性认识，否认理性认识的指导作用"],"answer":3,"explanation":"「跟着感觉走」把认识停留在感性阶段，否认理性认识对感性认识的指导和深化作用，容易导致片面和错误。故本题选A。","__sub":"马原"},{"id":"zz-30643","module":"zhengzhi","prompt":"「教条主义」与「经验主义」的共同错误在于：","options":["都否认实践","割裂了感性认识与理性认识的辩证统一","都否认理性认识","都否认感性认识"],"answer":1,"explanation":"教条主义夸大书本知识（理性认识），轻视实际经验（感性认识）；经验主义夸大个人经验（感性认识），轻视理论（理性认识），二者都割裂了感性认识与理性认识的统一。故本题选A。","__sub":"马原"},{"id":"zz-30644","module":"zhengzhi","prompt":"「真理是标志主观同客观相符合的哲学范畴」，这一命题表明：","options":["真理是主观自生的","真理的本性是主观与客观相符合","真理是客观世界本身","真理与客观无关"],"answer":1,"explanation":"真理是人们对客观事物及其规律的正确反映，其本性在于主观认识与客观实际相符合，既不是主观自生的，也不是客观世界本身。故本题选A。","__sub":"马原"},{"id":"zz-30645","module":"zhengzhi","prompt":"「真理的相对性」是指：","options":["真理随时被推翻","真理是错误的","真理在广度和深度上的有限性，有待扩展和深化","真理没有客观内容"],"answer":2,"explanation":"真理的相对性指任何真理都只是对客观世界一定范围、一定程度的正确反映，在广度和深度上有待扩展和深化，但不是错误。故本题选A。","__sub":"马原"},{"id":"zz-30646","module":"zhengzhi","prompt":"「实践作为检验真理的标准，既是确定的，又是不确定的」，其中「不确定性」是指：","options":["实践标准可以替代","实践标准不可靠","一定历史阶段的实践有局限性，检验是一个过程","实践标准因人而异"],"answer":2,"explanation":"实践标准的不确定性（相对性）指一定历史阶段的实践水平有限，对真理的检验不能一次完成，需要随实践发展而不断深化。故本题选A。","__sub":"马原"},{"id":"zz-30647","module":"zhengzhi","prompt":"「真理是一个过程」，这一命题表明：","options":["真理在实践中不断扩展、深化和发展","真理一成不变","真理可以一次穷尽","真理与过程无关"],"answer":0,"explanation":"认识是从相对真理走向绝对真理的过程，每一真理都在实践中不断扩展、深化和发展，永远不会终结。故本题选A。","__sub":"马原"},{"id":"zz-30648","module":"zhengzhi","prompt":"「价值评价」的根本标准是：","options":["是否符合客观规律和人民利益","是否符合个人喜好","是否新颖独特","是否流行时尚"],"answer":0,"explanation":"价值评价要以真理为前提，以人民利益为标准，符合客观规律和最广大人民根本利益的价值评价才是正确的。故本题选A。","__sub":"马原"},{"id":"zz-30649","module":"zhengzhi","prompt":"「社会存在决定社会意识」与「社会意识具有相对独立性」的关系是：","options":["二者相互矛盾","前者是基础，后者是社会意识自身特点的表现，二者不矛盾","后者否认前者","前者否认后者"],"answer":1,"explanation":"社会存在决定社会意识是唯物史观的基础，社会意识的相对独立性（如不完全同步、相互影响、能动反作用）是在这一决定作用前提下的自身特点，二者不矛盾。故本题选A。","__sub":"马原"},{"id":"zz-30650","module":"zhengzhi","prompt":"「先进的社会意识对社会发展起积极的推动作用」，这是因为：","options":["社会意识决定社会存在","先进社会意识正确反映了社会发展的客观规律","社会意识可以脱离社会存在","社会意识没有能动性"],"answer":1,"explanation":"先进的社会意识之所以能推动社会发展，是因为它正确反映了社会发展的客观规律和趋势，能够指导人们的实践。故本题选A。","__sub":"马原"},{"id":"zz-30651","module":"zhengzhi","prompt":"「生产力与生产关系的矛盾运动」中，生产关系对生产力的反作用表现为：","options":["反作用无关紧要","生产关系决定生产力","适应生产力时促进发展，不适应时阻碍发展","反作用总是积极的"],"answer":2,"explanation":"生产关系对生产力的反作用具有两面性：适应生产力状况时起促进作用，不适应时起阻碍作用。故本题选A。","__sub":"马原"},{"id":"zz-30652","module":"zhengzhi","prompt":"「上层建筑一定要适合经济基础状况」的规律，其内容是：","options":["上层建筑决定经济基础","经济基础决定上层建筑，上层建筑反作用于经济基础","二者互不影响","上层建筑可以脱离经济基础"],"answer":1,"explanation":"这一规律揭示了经济基础与上层建筑的辩证关系：经济基础决定上层建筑的产生、性质和变化，上层建筑反作用于经济基础。故本题选A。","__sub":"马原"},{"id":"zz-30653","module":"zhengzhi","prompt":"「阶级斗争是阶级社会发展的直接动力」，这是因为：","options":["阶级斗争与社会发展无关","阶级斗争决定生产力","阶级斗争可以取代生产","阶级斗争推动了社会形态的更替和社会进步"],"answer":3,"explanation":"在阶级社会中，阶级斗争是解决社会基本矛盾的重要形式，推动社会形态的更替和社会的进步，但最终根源仍是生产力的发展。故本题选A。","__sub":"马原"},{"id":"zz-30654","module":"zhengzhi","prompt":"「社会基本矛盾」在社会发展中的作用是：","options":["是社会发展的根本动力，贯穿人类社会发展的始终","只在阶级社会起作用","可以人为取消","与社会形态更替无关"],"answer":0,"explanation":"生产力与生产关系、经济基础与上层建筑的矛盾是社会基本矛盾，贯穿人类社会发展始终，是社会发展的根本动力。故本题选A。","__sub":"马原"},{"id":"zz-30655","module":"zhengzhi","prompt":"「人民群众」这一概念的最本质规定是：","options":["仅指体力劳动者","量的规定性（多数人）与质的规定性（推动历史发展）的统一","仅指知识分子","仅指统治阶级"],"answer":1,"explanation":"人民群众从量的规定性看是社会人口中的大多数，从质的规定性看是一切对社会发展起推动作用的人们，其中劳动群众是主体。故本题选A。","__sub":"马原"},{"id":"zz-30656","module":"zhengzhi","prompt":"「杰出人物」在历史上的作用是：","options":["可以取消历史规律","可以决定历史发展的总趋势","与历史发展无关","可以加速或延缓历史进程，但不能改变历史发展的总趋势"],"answer":3,"explanation":"杰出人物顺应历史趋势、反映群众要求，能够加速历史进程，但不能改变历史发展的总趋势和客观规律。故本题选A。","__sub":"马原"},{"id":"zz-30657","module":"zhengzhi","prompt":"「个人在历史上的作用」问题上的两种错误倾向是：","options":["否认历史规律","夸大群众作用","否认群众作用","夸大个人作用的历史唯心主义和否认个人作用的宿命论"],"answer":3,"explanation":"历史唯心主义夸大个人（英雄）的作用，宿命论则否认个人的能动作用，二者都是片面的，正确观点是个人作用与历史规律的统一。故本题选A。","__sub":"马原"},{"id":"zz-30658","module":"zhengzhi","prompt":"「劳动是人的存在方式」，这一命题表明：","options":["劳动与人的本质无关","劳动是人的负担","人在劳动中创造自身、发展自身，劳动是人的本质活动","人可以脱离劳动"],"answer":2,"explanation":"人在劳动中改造自然、创造物质财富，同时也发展自身的能力和社会关系，劳动是人的本质活动和存在方式。故本题选A。","__sub":"马原"},{"id":"zz-30659","module":"zhengzhi","prompt":"「社会进步」的根本标准和最高标准是：","options":["军事力量强弱","经济增长速度","人的发展和社会的全面进步相统一，最终以人的自由全面发展为最高标准","领土面积大小"],"answer":2,"explanation":"社会进步最终体现在人的发展上，人的自由全面发展是社会进步的最高标准，经济增长等只是实现这一目标的手段。故本题选A。","__sub":"马原"},{"id":"zz-30660","module":"zhengzhi","prompt":"「必然王国」向「自由王国」飞跃的根本途径是：","options":["消灭一切规律","等待自然恩赐","脱离社会实践","通过实践不断认识规律、改造世界，发展生产力"],"answer":3,"explanation":"只有通过实践不断认识必然、改造客观世界、发展生产力，人类才能逐步获得自由，实现从必然王国向自由王国的飞跃。故本题选A。","__sub":"马原"},{"id":"zz-30661","module":"zhengzhi","prompt":"「一切从实际出发，实事求是」与「解放思想」的关系是：","options":["二者相互对立","解放思想是实事求是的前提，实事求是是解放思想的目的，二者统一","解放思想可以脱离实际","实事求是束缚思想"],"answer":1,"explanation":"解放思想使主观摆脱教条束缚，才能做到实事求是；实事求是使解放思想有客观依据，不偏离实际，二者辩证统一于实践。故本题选A。","__sub":"马原"},{"id":"zz-30662","module":"zhengzhi","prompt":"「矛盾的同一性是相对的，斗争性是绝对的」，其中「斗争性绝对」是指：","options":["斗争性可以脱离同一性","斗争性不需要条件","斗争性无条件地存在于一切事物和过程中","斗争性决定一切"],"answer":2,"explanation":"矛盾的斗争性是无条件的、绝对的，它贯穿于事物发展的始终；同一性是有条件的、相对的，二者相互结合推动事物发展。故本题选A。","__sub":"马原"},{"id":"zz-30663","module":"zhengzhi","prompt":"「矛盾的同一性是相对的」，其中「同一性相对」是指：","options":["同一性可以脱离斗争性","同一性不存在","同一性是有条件的，受特定条件制约","同一性决定一切"],"answer":2,"explanation":"矛盾的同一性是有条件的、相对的，矛盾双方的相互依存和转化都需要一定条件，条件消失，统一体即瓦解。故本题选A。","__sub":"马原"},{"id":"zz-30664","module":"zhengzhi","prompt":"「内因与外因」在事物发展中的作用，正确表述是：","options":["外因是根据，内因是条件","内因是根据，外因是条件，二者缺一不可","二者可以互相替代","内因可以脱离外因独立存在"],"answer":1,"explanation":"内因是事物变化发展的根据和第一位原因，外因是变化的条件，外因通过内因起作用，二者缺一不可但地位不同。故本题选A。","__sub":"马原"},{"id":"zz-30665","module":"zhengzhi","prompt":"「质」与「量」的区别在于：","options":["二者没有区别","质可以脱离事物","量是事物的本质","质是事物成为自身的规定性，量是事物存在和发展的规模程度速度等"],"answer":3,"explanation":"质是一事物区别于他事物的内在规定性，与事物直接同一；量是事物存在和发展的规模、程度、速度等可以用数量表示的规定性，与事物不直接同一。故本题选A。","__sub":"马原"},{"id":"zz-30666","module":"zhengzhi","prompt":"「质变」的形式是多样的，其中包括：","options":["量变的简单延续","爆发式飞跃与非爆发式飞跃","循环往复","原地踏步"],"answer":1,"explanation":"质变即飞跃，其形式因事物性质和条件不同而异，包括爆发式飞跃（如火山爆发、革命）和非爆发式飞跃（如物种演化、语言更新）。故本题选A。","__sub":"马原"},{"id":"zz-30667","module":"zhengzhi","prompt":"「部分质变」是指：","options":["与质变无关","根本质变","纯粹的量变","在总的量变过程中，事物的某些方面或局部发生的质变"],"answer":3,"explanation":"部分质变是在总的量变过程中发生的局部性、阶段性质变，包括阶段性部分质变和局部性部分质变，不改变事物的根本性质。故本题选A。","__sub":"马原"},{"id":"zz-30668","module":"zhengzhi","prompt":"「扬弃」与「抛弃」的区别在于：","options":["扬弃是全盘肯定","二者没有区别","抛弃更彻底","扬弃包含着肯定和保留，抛弃是全盘否定"],"answer":3,"explanation":"扬弃是辩证否定，既克服又保留，包含着肯定因素；抛弃则是全盘否定、割断联系，是形而上学的否定观。故本题选A。","__sub":"马原"},{"id":"zz-30669","module":"zhengzhi","prompt":"「实践的主体」与「实践的客体」的关系是：","options":["客体决定主体的一切","主体决定客体的一切","主体改造客体，客体制约主体，二者在实践中相互作用","二者没有关系"],"answer":2,"explanation":"实践的主体是有思维能力、从事实践活动的人，客体是实践所指向的对象，主体改造客体，客体又制约和影响主体，二者相互作用。故本题选A。","__sub":"马原"},{"id":"zz-30670","module":"zhengzhi","prompt":"「认识的中介」是指：","options":["认识主体与客体之间的各种物质工具和信息手段","认识主体本身","认识客体本身","认识的结果"],"answer":0,"explanation":"认识的中介包括各种物质工具（仪器、设备）和信息手段（语言、理论框架等），它们延伸了主体的认识能力，是主客体联系的桥梁。故本题选A。","__sub":"马原"},{"id":"zz-30671","module":"zhengzhi","prompt":"「认识过程的第二次飞跃」比第一次飞跃意义更重大，这是因为：","options":["实践可以没有认识","第一次飞跃没有意义","理性认识不重要","只有回到实践，认识才能实现其目的并得到检验和发展"],"answer":3,"explanation":"理性认识只有回到实践中，才能指导实践、改造世界，并接受实践检验、得到丰富和发展，因此第二次飞跃意义更重大。故本题选A。","__sub":"马原"},{"id":"zz-30672","module":"zhengzhi","prompt":"「真理与价值」的关系是：","options":["二者相互对立","价值决定真理","真理原则与价值原则在实践中辩证统一，真理是价值实现的前提","真理与价值无关"],"answer":2,"explanation":"人类活动遵循真理原则（按客观规律办事）和价值原则（满足人的需要），真理是价值实现的前提和基础，价值是真理追求的目的，二者辩证统一。故本题选A。","__sub":"马原"},{"id":"zz-30673","module":"zhengzhi","prompt":"「社会存在」与「社会意识」的划分标准是：","options":["是否重要","是否可以看见","是否属于社会生活的物质方面","是否变化"],"answer":2,"explanation":"社会存在是社会生活的物质方面（自然地理环境、人口因素、物质生产方式），社会意识是社会生活的精神方面，划分标准是物质与精神的区别。故本题选A。","__sub":"马原"},{"id":"zz-30674","module":"zhengzhi","prompt":"「物质生产方式」是社会发展的决定力量，这是因为：","options":["它是唯一的社会现象","它由人的意志决定","它与社会形态无关","它决定社会的性质、面貌和结构，是社会存在和发展的基础"],"answer":3,"explanation":"物质生产方式决定社会的性质、面貌和社会形态的更替，是社会政治、精神生活的基础，因此是社会发展的决定力量。故本题选A。","__sub":"马原"},{"id":"zz-30675","module":"zhengzhi","prompt":"「生产力」的基本要素包括：","options":["科学技术与教育","生产关系与上层建筑","经济基础与国家政权","劳动者、劳动资料、劳动对象"],"answer":3,"explanation":"生产力的基本要素是劳动者（主体）、劳动资料（以生产工具为主）和劳动对象，科学技术渗透其中并日益成为决定性因素。故本题选A。","__sub":"马原"},{"id":"zz-30676","module":"zhengzhi","prompt":"「生产关系」的三方面内容中，最基本的是：","options":["生产中人与人的关系","生产资料所有制关系","产品分配关系","消费关系"],"answer":1,"explanation":"生产资料所有制关系是生产关系的基础和核心，决定生产关系的性质，也决定生产中人与人的关系和产品分配方式。故本题选A。","__sub":"马原"},{"id":"zz-30677","module":"zhengzhi","prompt":"「国家政权」在上层建筑中的地位是：","options":["由上层建筑决定一切","是上层建筑的边缘部分","与上层建筑无关","是上层建筑的核心，具有决定性作用"],"answer":3,"explanation":"国家政权是政治上层建筑的核心，掌握国家政权是阶级统治得以实现的关键，国家政权的性质决定上层建筑的性质。故本题选A。","__sub":"马原"},{"id":"zz-30678","module":"zhengzhi","prompt":"「社会革命」的根源在于：","options":["偶然事件","领导人的意志","外部势力的干预","社会基本矛盾的尖锐化"],"answer":3,"explanation":"社会革命的根源在于生产力与生产关系、经济基础与上层建筑矛盾的尖锐化，当生产关系成为生产力发展的桎梏时，革命就会到来。故本题选A。","__sub":"马原"},{"id":"zz-30679","module":"zhengzhi","prompt":"「改革」在社会发展中的作用是：","options":["是同一社会形态内部的自我调整和完善，推动社会发展","是推翻根本制度的手段","与社会发展无关","只改变上层建筑不改经济基础"],"answer":0,"explanation":"改革是在同一社会形态内调整生产关系和上层建筑中不适应的部分，是制度的自我完善和发展，能够解放生产力、推动社会发展。故本题选A。","__sub":"马原"},{"id":"zz-30680","module":"zhengzhi","prompt":"「科学技术」作为生产力，其特点是：","options":["只影响精神生活","是独立的生产力要素","与生产力无关","是渗透性要素，通过转化为现实生产力发挥作用"],"answer":3,"explanation":"科学技术不是独立的实体要素，而是渗透性要素，通过提高劳动者素质、改进生产工具、扩展劳动对象等途径转化为现实生产力。故本题选A。","__sub":"马原"},{"id":"zz-30681","module":"zhengzhi","prompt":"「人民群众创造历史」的活动受历史条件的制约，这些条件包括：","options":["只有经济条件","经济条件、政治条件和精神文化条件","只有政治条件","不受任何条件制约"],"answer":1,"explanation":"人民群众创造历史的活动受所处时代的经济条件（生产力水平）、政治条件（阶级地位、政治制度）和精神文化条件（科学文化水平）的制约。故本题选A。","__sub":"马原"},{"id":"zz-30682","module":"zhengzhi","prompt":"「人的本质是一切社会关系的总和」这一论断的方法论意义是：","options":["要从社会关系特别是生产关系出发认识人，反对抽象人性论","从抽象人性出发","从生物本能出发","从主观愿望出发"],"answer":0,"explanation":"马克思的论断要求从现实的社会关系（特别是生产关系）出发认识人的本质，反对脱离社会条件的抽象人性论。故本题选A。","__sub":"马原"},{"id":"zz-30683","module":"zhengzhi","prompt":"「人的价值」的实现途径是：","options":["通过社会实践，在为社会作贡献的同时实现自身发展","脱离社会实践","等待他人给予","依赖天赋"],"answer":0,"explanation":"人的价值只有通过社会实践才能实现，在为社会作贡献（社会价值）的同时满足自身需要（自我价值），二者统一于实践。故本题选A。","__sub":"马原"},{"id":"zz-30684","module":"zhengzhi","prompt":"「自由」与「必然」的辩证关系是：","options":["自由与必然绝对对立","必然是自由的前提，自由是对必然的认识和改造","必然束缚自由","自由可以摆脱必然"],"answer":1,"explanation":"自由以必然为前提，认识和把握必然是获得自由的基础；自由又是对必然的超越和改造，通过实践改造世界实现自由。故本题选A。","__sub":"马原"},{"id":"zz-30685","module":"zhengzhi","prompt":"「历史唯物主义」与「历史唯心主义」的根本分歧在于：","options":["是否承认认识来源于实践","是否承认意识的能动作用","是否承认社会存在决定社会意识","是否承认矛盾普遍性"],"answer":2,"explanation":"历史唯物主义坚持社会存在决定社会意识，历史唯心主义则主张社会意识决定社会存在，这是二者的根本分歧。故本题选A。","__sub":"马原"},{"id":"zz-30686","module":"zhengzhi","prompt":"「社会形态」是：","options":["同生产力发展阶段相适应的经济基础与上层建筑的统一体","单纯的经济制度","单纯的政治制度","单纯的文化体系"],"answer":0,"explanation":"社会形态是关于社会运动的具体形式，是同生产力发展阶段相适应的经济基础与上层建筑的统一体，包括经济、政治、文化等方面。故本题选A。","__sub":"马原"},{"id":"zz-30687","module":"zhengzhi","prompt":"「五种社会形态依次更替」体现了：","options":["社会发展没有规律","各国发展道路完全相同","社会形态更替的统一性与客观规律性","发展道路由个人选择"],"answer":2,"explanation":"原始社会、奴隶社会、封建社会、资本主义社会、共产主义社会（社会主义是其初级阶段）的依次更替，体现了人类社会发展的统一性和客观规律性。故本题选A。","__sub":"马原"},{"id":"zz-30688","module":"zhengzhi","prompt":"「跨越式发展」的可能性依据是：","options":["历史可以任意选择","社会形态更替没有规律","发展道路完全随机","社会形态更替的多样性与历史的选择性"],"answer":3,"explanation":"某些国家和民族在特定历史条件下可以跨越某种社会形态而向前发展，体现了社会形态更替的多样性和历史的选择性，但选择仍以客观规律为前提。故本题选A。","__sub":"马原"},{"id":"zz-30689","module":"zhengzhi","prompt":"「现实的人」与「抽象的人」的区别在于：","options":["现实的人是处于一定社会关系中从事实践活动的人","现实的人有血有肉","抽象的人有思想","二者没有区别"],"answer":0,"explanation":"「现实的人」是处于一定社会关系中、从事实践活动的人，马克思主张从现实的人出发研究历史；「抽象的人」是脱离社会条件的抽象观念。故本题选A。","__sub":"马原"},{"id":"zz-30690","module":"zhengzhi","prompt":"「历史合力」的形成机制是：","options":["历史是随机的","单一意志决定历史","个人意志与历史无关","无数个人意志和活动相互作用形成历史合力"],"answer":3,"explanation":"恩格斯指出，历史结果是无数相互交错的个人意志和活动形成的合力的产物，每个人的意志都参与其中，但任何人都不能单独决定历史。故本题选A。","__sub":"马原"},{"id":"zz-30691","module":"zhengzhi","prompt":"「社会有机体」这一概念表明：","options":["社会各部分互不相关","社会是各部分的机械相加","社会是由各要素相互联系构成的有机整体","社会没有结构"],"answer":2,"explanation":"马克思把社会比作有机体，说明社会是由经济、政治、文化等要素相互联系、相互作用构成的有机整体，具有自我组织和发展的能力。故本题选A。","__sub":"马原"},{"id":"zz-30692","module":"zhengzhi","prompt":"「自然的人化」与「人的自然化」的关系是：","options":["人与自然绝对对立","在实践中人与自然相互改造、和谐统一","人可以任意征服自然","自然决定人的一切"],"answer":1,"explanation":"「自然的人化」指人在实践中改造自然，使自然成为人化的自然；「人的自然化」指人在改造自然的同时也受自然制约、与自然和谐，二者统一于实践。故本题选A。","__sub":"马原"},{"id":"zz-30693","module":"zhengzhi","prompt":"「生态文明」建设的哲学依据是：","options":["自然与人无关","人可以任意支配自然","人与自然是有机统一的整体，必须尊重自然规律","发展必然破坏自然"],"answer":2,"explanation":"人与自然是生命共同体，自然界是人类生存和发展的基础，必须尊重自然、顺应自然、保护自然，实现人与自然和谐共生。故本题选A。","__sub":"马原"},{"id":"zz-30694","module":"zhengzhi","prompt":"「社会存在」与「自然存在」的区别在于：","options":["社会存在与人的活动无关","社会存在通过人的实践活动形成，打上了人的烙印","自然存在由人创造","二者没有区别"],"answer":1,"explanation":"自然存在先于人类而存在，社会存在则是人类实践活动的产物，打上了人的目的和意志的烙印，但同样具有客观性。故本题选A。","__sub":"马原"},{"id":"zz-30695","module":"zhengzhi","prompt":"「历史规律」与「自然规律」的区别在于：","options":["历史规律通过人的有目的的活动实现，自然规律自发地起作用","历史规律没有客观性","自然规律可以人为改变","二者没有区别"],"answer":0,"explanation":"历史规律形成并实现于人的有目的的实践活动中，具有「人为性」；自然规律自发地起作用。但二者都具有客观性，不以人的意志为转移。故本题选A。","__sub":"马原"},{"id":"zz-30696","module":"zhengzhi","prompt":"「社会规律的客观性」是指：","options":["社会规律可以人为废除","社会规律的形成和作用不以人的意志为转移","社会规律因人而异","社会规律没有客观性"],"answer":1,"explanation":"社会规律虽然通过人的活动实现，但其形成和作用具有客观性，不以人的意志为转移，人们只能认识和利用规律，不能创造或消灭规律。故本题选A。","__sub":"马原"},{"id":"zz-30697","module":"zhengzhi","prompt":"「历史观」与「价值观」的关系是：","options":["二者毫无关系","价值观决定历史观","历史观决定价值观的基本取向，价值观影响历史评价","历史观与价值观无关"],"answer":2,"explanation":"对历史的根本看法（历史观）决定了对社会价值的基本取向，价值观又影响人们对历史事件和人物的评价，二者相互影响。故本题选A。","__sub":"马原"},{"id":"zz-30698","module":"zhengzhi","prompt":"「从群众中来，到群众中去」的认识论基础是：","options":["认识决定实践","认识来源于实践并接受实践检验","实践可以脱离认识","认识是主观自生的"],"answer":1,"explanation":"「从群众中来」即从群众实践中获取认识，「到群众中去」即回到实践中检验和落实，其认识论基础是实践与认识的辩证关系。故本题选A。","__sub":"马原"},{"id":"zz-30699","module":"zhengzhi","prompt":"「理论创新」与「实践创新」的关系是：","options":["实践创新为理论创新提供源泉，理论创新为实践创新提供指导","理论创新决定实践创新","二者互不影响","理论创新可以脱离实践"],"answer":0,"explanation":"实践是理论的源泉和动力，实践创新推动理论创新；理论创新又反过来指导实践创新，二者相互促进、辩证统一。故本题选A。","__sub":"马原"},{"id":"zz-30700","module":"zhengzhi","prompt":"「社会基本矛盾」的解决途径是：","options":["无法解决","自动消失","靠个人意志解决","通过革命、改革等社会实践方式加以解决"],"answer":3,"explanation":"社会基本矛盾通过相应的社会实践方式加以解决，在阶级社会主要通过阶级斗争和社会革命，在社会主义社会主要通过改革。故本题选A。","__sub":"马原"},{"id":"zz-30701","module":"zhengzhi","prompt":"「生产力标准」的内涵是：","options":["以经济增长速度为唯一标准","是否有利于解放和发展生产力是衡量社会进步的根本标准","以军事力量为标准","以人口数量为标准"],"answer":1,"explanation":"生产力是社会发展的最终决定力量，是否有利于解放和发展生产力是衡量社会进步的根本标准，但不是唯一标准。故本题选A。","__sub":"马原"},{"id":"zz-30702","module":"zhengzhi","prompt":"「物质决定意识」与「意识具有能动作用」的关系是：","options":["前者是前提和基础，后者是在此前提下的能动表现，二者不矛盾","二者相互矛盾","后者否认前者","前者否认后者"],"answer":0,"explanation":"物质决定意识是唯物主义的前提和基础，意识的能动作用是在这一前提下的能动表现，承认能动作用不等于否认物质的决定作用。故本题选A。","__sub":"马原"},{"id":"zz-30703","module":"zhengzhi","prompt":"「一切从实际出发」与「一切从原则出发」的根本区别在于：","options":["前者坚持物质第一性，后者颠倒了物质与意识的关系","前者重视理论","后者重视实际","二者没有区别"],"answer":0,"explanation":"「实际」是客观存在的物质世界，「原则」是主观的认识，从实际出发坚持了物质第一性；从原则出发则颠倒了物质与意识的关系，是唯心主义的表现。故本题选A。","__sub":"马原"},{"id":"zz-30704","module":"zhengzhi","prompt":"「规律」与「规则」的区别在于：","options":["规律可以修改","规律是客观的，规则是人们制定的，可以修改或废除","规则是客观的","二者没有区别"],"answer":1,"explanation":"规律是事物运动过程中固有的本质的必然的稳定的联系，具有客观性；规则是人们根据需要制定的，可以修改或废除。故本题选A。","__sub":"马原"},{"id":"zz-30705","module":"zhengzhi","prompt":"「联系」与「区别」的关系是：","options":["区别否认联系","联系否认区别","联系以区别为前提，区别以联系为条件，二者相互依存","二者绝对对立"],"answer":2,"explanation":"事物之间的联系以彼此的区别为前提，没有区别就无所谓联系；区别又以联系为条件，没有联系的区别是孤立的，二者相互依存。故本题选A。","__sub":"马原"},{"id":"zz-30706","module":"zhengzhi","prompt":"「运动」与「静止」的关系是：","options":["运动是绝对的，静止是相对的，静止是运动的特殊状态","静止是绝对的","运动是相对的","二者绝对对立"],"answer":0,"explanation":"运动是物质的根本属性和存在方式，是绝对的、无条件的；静止是运动的特殊状态，是相对的、有条件的。故本题选A。","__sub":"马原"},{"id":"zz-30707","module":"zhengzhi","prompt":"「承认相对静止」的意义在于：","options":["否认运动","是认识事物的前提，也是衡量运动的尺度","夸大运动","与认识无关"],"answer":1,"explanation":"承认相对静止才能把事物区别开来加以认识，才能理解运动的多样性，相对静止也是衡量运动的尺度。故本题选A。","__sub":"马原"},{"id":"zz-30708","module":"zhengzhi","prompt":"「时间」与「空间」的共同特点是：","options":["具有客观性和无限性","具有主观性","可以脱离物质运动","有始有终"],"answer":0,"explanation":"时间和空间都是物质运动的存在形式，具有客观性（不依赖于人的意识）和无限性（时间无始无终，空间无边无际）。故本题选A。","__sub":"马原"},{"id":"zz-30709","module":"zhengzhi","prompt":"「意识」与「物质」的关系中，「意识」的能动作用表现在：","options":["可以脱离物质","可以创造物质","能够能动地认识世界和改造世界","决定物质"],"answer":2,"explanation":"意识的能动作用表现在能够能动地认识世界（把握本质规律）和能动地改造世界（通过实践把观念的东西变成现实的东西）。故本题选A。","__sub":"马原"},{"id":"zz-30710","module":"zhengzhi","prompt":"「意识活动的目的性」是指：","options":["意识活动是盲目的","意识活动没有目的","目的由客观决定一切","人在反映客观世界时总是带有一定的目的和计划"],"answer":3,"explanation":"人在认识和实践之前总是先在观念中确定目标、设计方案，意识活动具有目的性和计划性，这是意识能动性的表现之一。故本题选A。","__sub":"马原"},{"id":"zz-30711","module":"zhengzhi","prompt":"「意识活动的自觉选择性」是指：","options":["选择完全由客观决定","意识活动没有选择性","人在反映客观对象时总是根据需要有所选择","意识活动是被动的"],"answer":2,"explanation":"人在反映客观对象时总是根据主体的需要、兴趣、目的有所选择、有所侧重，这是意识能动性的又一表现。故本题选A。","__sub":"马原"},{"id":"zz-30712","module":"zhengzhi","prompt":"「一切唯物主义」都主张：","options":["世界不可知","意识第一性","物质与意识并重","物质第一性，意识第二性"],"answer":3,"explanation":"一切唯物主义（古代朴素唯物主义、近代形而上学唯物主义、辩证唯物主义）都主张物质第一性、意识第二性，这是唯物主义的共同立场。故本题选A。","__sub":"马原"},{"id":"zz-30713","module":"zhengzhi","prompt":"「古代朴素唯物主义」的局限性在于：","options":["把物质归结为具体物质形态，缺乏科学论证","否认物质第一性","否认世界可知","夸大意识作用"],"answer":0,"explanation":"古代朴素唯物主义以水、火、气等具体物质形态解释世界本原，坚持了唯物方向但缺乏科学论证，具有直观性和猜测性。故本题选A。","__sub":"马原"},{"id":"zz-30714","module":"zhengzhi","prompt":"「近代形而上学唯物主义」的局限性在于：","options":["否认世界可知","否认物质第一性","机械性、形而上学性和不彻底性","夸大意识作用"],"answer":2,"explanation":"近代形而上学唯物主义以原子为物质本原，具有机械性（用力学解释一切）、形而上学性（孤立静止看问题）和不彻底性（历史观上陷入唯心主义）。故本题选A。","__sub":"马原"},{"id":"zz-30715","module":"zhengzhi","prompt":"「辩证唯物主义」与「旧唯物主义」的根本区别在于：","options":["是否承认意识存在","是否承认物质第一性","是否承认世界可知","是否以实践为基础，是否辩证地看问题"],"answer":3,"explanation":"旧唯物主义缺乏实践观点和辩证思想，辩证唯物主义以实践为基础，用联系、发展、全面的观点看世界，实现了唯物论与辩证法的统一。故本题选A。","__sub":"马原"},{"id":"zz-30716","module":"zhengzhi","prompt":"「主观唯心主义」与「客观唯心主义」的共同点是：","options":["都认为意识（精神）是世界的本原","都认为物质是世界的本原","都承认世界可知","都否认意识的作用"],"answer":0,"explanation":"主观唯心主义把人的主观精神（感觉、经验、心灵）当作世界本原，客观唯心主义把客观精神（理、理念、绝对精神）当作世界本原，共同点是意识第一性。故本题选A。","__sub":"马原"},{"id":"zz-30717","module":"zhengzhi","prompt":"「一元论」与「二元论」的区别在于：","options":["是否承认实践","是否承认世界可知","是否承认矛盾","是否承认世界只有一个本原"],"answer":3,"explanation":"一元论认为世界只有一个本原（物质或精神），二元论认为物质与精神是两个独立并行的本原，二者的区别在于本原的数目。故本题选A。","__sub":"马原"},{"id":"zz-30718","module":"zhengzhi","prompt":"「可知论」与「不可知论」的区别在于：","options":["是否承认矛盾","是否承认物质第一性","是否承认思维能够正确认识存在","是否承认实践"],"answer":2,"explanation":"可知论主张思维能够正确认识存在，世界可以被认识；不可知论否认认识世界的可能性或彻底性，二者的区别在于世界是否可知。故本题选A。","__sub":"马原"},{"id":"zz-30719","module":"zhengzhi","prompt":"「唯物辩证法」与「形而上学」的分歧焦点在于：","options":["是否承认物质第一性","是否承认矛盾是事物发展的动力","是否承认世界可知","是否承认实践"],"answer":1,"explanation":"唯物辩证法主张用联系、发展、全面的观点看问题，承认矛盾是事物发展的动力；形而上学则用孤立、静止、片面的观点看问题，否认矛盾，二者的分歧焦点在于是否承认矛盾。故本题选A。","__sub":"马原"},{"id":"zz-30720","module":"zhengzhi","prompt":"「矛盾的同一性」与「矛盾的斗争性」的关系是：","options":["斗争性可以脱离同一性","二者相互脱离","同一性可以脱离斗争性","同一性以斗争性为前提，斗争性寓于同一性之中"],"answer":3,"explanation":"矛盾的同一性与斗争性相互依存、不可分割：同一以差别和对立为前提，斗争寓于同一之中，二者结合推动事物发展。故本题选A。","__sub":"马原"},{"id":"zz-30721","module":"zhengzhi","prompt":"「矛盾」的两种基本属性是：","options":["普遍性和特殊性","同一性和斗争性","绝对性和相对性","客观性和主观性"],"answer":1,"explanation":"矛盾是事物内部或事物之间既对立又统一的关系，其两种基本属性是同一性（相互依存、相互贯通）和斗争性（相互排斥、相互对立）。故本题选A。","__sub":"马原"},{"id":"zz-30722","module":"zhengzhi","prompt":"「矛盾的普遍性」与「矛盾的特殊性」的关系是：","options":["普遍性脱离特殊性","普遍性寓于特殊性之中，特殊性包含普遍性","特殊性否认普遍性","二者毫无关系"],"answer":1,"explanation":"矛盾的普遍性（共性）寓于特殊性（个性）之中，并通过特殊性表现出来；特殊性包含普遍性，比普遍性更丰富。故本题选A。","__sub":"马原"},{"id":"zz-30723","module":"zhengzhi","prompt":"「主要矛盾」在复杂事物中的地位是：","options":["处于从属地位","居于支配地位，对事物发展起决定作用","与事物发展无关","可以随时取消"],"answer":1,"explanation":"复杂事物中存在多个矛盾，其中主要矛盾居于支配地位、对事物发展起决定作用，次要矛盾处于从属地位，要求我们抓重点、抓关键。故本题选A。","__sub":"马原"},{"id":"zz-30724","module":"zhengzhi","prompt":"「矛盾的主要方面」决定：","options":["事物的形式","事物的数量","事物的位置","事物的性质"],"answer":3,"explanation":"矛盾双方力量不平衡，其中处于支配地位、起主导作用的方面是矛盾的主要方面，事物的性质主要由矛盾的主要方面决定。故本题选A。","__sub":"马原"},{"id":"zz-30725","module":"zhengzhi","prompt":"「两点论」与「重点论」的关系是：","options":["重点论否认两点论","二者相互对立","两点论包含重点论，重点论以两点论为前提，二者相互包含","两点论否认重点论"],"answer":2,"explanation":"两点论是有重点的两点论，重点论是两点中的重点论，二者相互包含、辩证统一，反对形而上学的一点论和均衡论。故本题选A。","__sub":"马原"},{"id":"zz-30726","module":"zhengzhi","prompt":"「量变」与「质变」的关系是：","options":["量变决定一切","量变是质变的必要准备，质变是量变的必然结果，质变又为新的量变开辟道路","质变可以脱离量变","二者毫无关系"],"answer":1,"explanation":"量变积累到一定程度必然引起质变，质变又为新的量变开辟道路，事物在量变质变的交替中发展。故本题选A。","__sub":"马原"},{"id":"zz-30727","module":"zhengzhi","prompt":"「质变」在事物发展中的作用是：","options":["是旧事物向新事物转变的决定性环节","无关紧要","只有量变才有意义","质变阻碍发展"],"answer":0,"explanation":"质变是事物性质的根本变化，是旧事物向新事物转变的决定性环节，只有质变才能实现事物的飞跃和发展。故本题选A。","__sub":"马原"},{"id":"zz-30728","module":"zhengzhi","prompt":"「肯定」与「否定」的关系是：","options":["二者绝对对立","肯定就是全盘肯定","否定就是全盘否定","肯定中包含否定，否定中包含肯定，二者相互渗透"],"answer":3,"explanation":"辩证的肯定不是全盘肯定，其中包含着否定的因素；辩证的否定不是全盘否定，其中包含着肯定的因素，二者相互渗透。故本题选A。","__sub":"马原"},{"id":"zz-30729","module":"zhengzhi","prompt":"「否定之否定」阶段的特点是：","options":["在更高阶段回复肯定阶段的某些特征，是事物发展的完成","回到原点","与肯定阶段完全相同","与肯定阶段毫无关系"],"answer":0,"explanation":"否定之否定阶段是在更高阶段上向肯定阶段的回复，仿佛回到原点，但已包含新的内容，是事物发展的完成阶段。故本题选A。","__sub":"马原"},{"id":"zz-30730","module":"zhengzhi","prompt":"「实践」与「认识」的关系是：","options":["认识决定实践","实践决定认识，认识反作用于实践","二者互不影响","实践可以脱离认识"],"answer":1,"explanation":"实践是认识的来源、动力、检验标准和目的，决定认识；认识反作用于实践，正确的认识指导实践取得成功。故本题选A。","__sub":"马原"},{"id":"zz-30731","module":"zhengzhi","prompt":"「感性认识」与「理性认识」统一的基础是：","options":["经验","逻辑","实践","直觉"],"answer":2,"explanation":"感性认识与理性认识统一的基础是实践：感性认识来源于实践，理性认识是感性材料的加工，二者在实践基础上统一起来。故本题选A。","__sub":"马原"},{"id":"zz-30732","module":"zhengzhi","prompt":"「真理」与「谬误」的关系是：","options":["相互对立又相互依存，真理在斗争中发展","真理可以脱离谬误","谬误是真理的来源","二者没有界限"],"answer":0,"explanation":"真理与谬误相互对立（性质相反），又相互依存（相比较而存在），真理正是在同谬误的斗争中发展的。故本题选A。","__sub":"马原"},{"id":"zz-30733","module":"zhengzhi","prompt":"「实践标准」与「逻辑证明」的关系是：","options":["逻辑证明是实践标准的补充，但不是检验真理的最终标准","逻辑证明可以取代实践","二者毫无关系","逻辑证明是唯一标准"],"answer":0,"explanation":"逻辑证明在认识过程中起重要作用，是实践标准的补充，但逻辑证明的前提和结论最终要靠实践检验，不能取代实践标准。故本题选A。","__sub":"马原"},{"id":"zz-30734","module":"zhengzhi","prompt":"「社会存在」与「社会意识」的关系是：","options":["二者互不影响","社会意识决定社会存在","社会存在决定社会意识，社会意识反作用于社会存在","社会意识可以脱离社会存在"],"answer":2,"explanation":"社会存在决定社会意识的产生、性质和变化，社会意识反作用于社会存在，先进的社会意识推动社会发展。故本题选A。","__sub":"马原"},{"id":"zz-30735","module":"zhengzhi","prompt":"「社会意识」的「相对独立性」最突出的表现是：","options":["与社会存在完全同步","对社会存在具有能动的反作用","没有历史继承性","没有阶级性"],"answer":1,"explanation":"社会意识相对独立性的最突出表现是对社会存在具有能动的反作用，先进的社会意识推动社会发展，落后的社会意识阻碍社会发展。故本题选A。","__sub":"马原"},{"id":"zz-30736","module":"zhengzhi","prompt":"「生产力」与「生产关系」的关系是：","options":["生产力决定生产关系，生产关系反作用于生产力","生产关系决定生产力","二者互不影响","生产关系可以脱离生产力"],"answer":0,"explanation":"生产力决定生产关系的性质和变化，生产关系反作用于生产力，适应时促进，不适应时阻碍，二者的矛盾运动推动社会发展。故本题选A。","__sub":"马原"},{"id":"zz-30737","module":"zhengzhi","prompt":"「人民群众」创造历史的活动，其「决定作用」表现在：","options":["只决定社会变革","只创造物质财富","创造物质财富、创造精神财富、决定社会变革","与历史无关"],"answer":2,"explanation":"人民群众是历史的创造者，表现在：是社会物质财富的创造者，是社会精神财富的创造者，是社会变革的决定力量。故本题选A。","__sub":"马原"},{"id":"zz-30738","module":"zhengzhi","prompt":"「个人」与「历史」的关系是：","options":["个人可以摆脱历史规律","个人决定历史","历史与个人无关","个人参与历史活动，历史规律制约个人活动，二者辩证统一"],"answer":3,"explanation":"历史是人们活动的结果，每个人都参与历史活动；但历史规律制约个人活动，个人不能随心所欲地创造历史，二者辩证统一。故本题选A。","__sub":"马原"},{"id":"zz-30739","module":"zhengzhi","prompt":"「人的价值」的两个方面是：","options":["个人价值与集体价值","物质价值与精神价值","经济价值与政治价值","社会价值（贡献）与自我价值（满足）"],"answer":3,"explanation":"人的价值包括社会价值（个人对社会的责任和贡献）和自我价值（社会对个人的尊重和满足），社会价值是首要方面。故本题选A。","__sub":"马原"},{"id":"zz-30740","module":"zhengzhi","prompt":"「人生价值」的评价标准中，「劳动」的地位是：","options":["劳动可以脱离贡献","劳动与价值无关","劳动是唯一标准","劳动是人的价值实现的根本途径"],"answer":3,"explanation":"人的价值通过劳动创造来实现，劳动是人的价值实现的根本途径，通过劳动为社会作贡献，同时实现自身的发展。故本题选A。","__sub":"马原"},{"id":"zz-30741","module":"zhengzhi","prompt":"「共产主义」的实现条件包括：","options":["仅靠主观愿望","生产力高度发展、社会关系高度和谐、人的素质极大提高","仅靠制度变革","仅靠精神宣传"],"answer":1,"explanation":"共产主义的实现需要物质条件（生产力高度发展、物质财富极大丰富）、社会条件（阶级消灭、社会关系和谐）和人的条件（素质极大提高、自由全面发展）。故本题选A。","__sub":"马原"},{"id":"zz-30742","module":"zhengzhi","prompt":"「必然王国」是指：","options":["人们获得自由的状态","人们受盲目必然性支配、特别是受自己创造的社会关系奴役的社会状态","理想的社会状态","生产力高度发展的状态"],"answer":1,"explanation":"必然王国指人们受盲目必然性支配、特别是受自己所创造的社会关系奴役的社会状态；自由王国则是人们摆脱盲目必然性、成为自身主人的人类解放状态。故本题选A。","__sub":"马原"},{"id":"zz-30743","module":"zhengzhi","prompt":"「实践」在「人与世界」关系中的地位是：","options":["实践是人与世界关系的基础，人在实践中改造世界和自身","实践与人与世界关系无关","人可以脱离实践","世界决定人的一切"],"answer":0,"explanation":"实践是人与世界关系的基础，人在实践中认识世界、改造世界，同时也改造自身、发展自身，实践是人与世界统一的基础。故本题选A。","__sub":"马原"},{"id":"zz-30744","module":"zhengzhi","prompt":"「日往则月来，月往则日来」，这一古语体现的哲学道理是：","options":["意识决定物质","日月运动没有规律","事物的运动变化是有规律的","静止是绝对的"],"answer":2,"explanation":"《周易》此语说明日月交替运行有其固有序列和规律，昼夜明暗随之产生，体现了事物运动变化的规律性。故本题选A。","__sub":"马原"},{"id":"zz-30745","module":"zhengzhi","prompt":"「天不为人之恶寒也辍冬，地不为人之恶辽远也辍广」，这句话表明：","options":["人可以改变自然规律","自然规律具有客观性，不以人的好恶为转移","规律因人而异","自然与人事无关"],"answer":1,"explanation":"荀子此语说明天地不会因人的好恶而改变其运行规律，强调自然规律的客观性，不以人的意志为转移。故本题选A。","__sub":"马原"},{"id":"zz-30746","module":"zhengzhi","prompt":"「望梅止渴」这一成语体现的哲学道理是：","options":["意识对人的生理活动具有调节和控制作用","意识可以代替物质","意识与生理无关","意识是虚幻的"],"answer":0,"explanation":"士兵想到梅子而分泌唾液，说明意识能够通过心理活动调节人的生理机能，体现了意识对生理活动的调节控制作用。故本题选A。","__sub":"马原"},{"id":"zz-30747","module":"zhengzhi","prompt":"「心外无物，心外无理」，这一命题属于：","options":["客观唯心主义","主观唯心主义","古代朴素唯物主义","辩证唯物主义"],"answer":1,"explanation":"王阳明认为「心」是万物的本原，物与理都在心中，把人的主观精神夸大为第一性，属于主观唯心主义。故本题选A。","__sub":"马原"},{"id":"zz-30748","module":"zhengzhi","prompt":"「生死有命，富贵在天」，这一命题属于：","options":["主观唯心主义","客观唯心主义","古代朴素唯物主义","辩证唯物主义"],"answer":1,"explanation":"此语把「天命」当作主宰人生的最高力量，把某种客观精神当作世界本原，属于客观唯心主义。故本题选A。","__sub":"马原"},{"id":"zz-30749","module":"zhengzhi","prompt":"「形存则神存，形谢则神灭」，这一命题属于：","options":["二元论","主观唯心主义","客观唯心主义","古代朴素唯物主义"],"answer":3,"explanation":"范缜以「形」（身体）与「神」（精神）的关系说明精神依赖于身体，形体存在精神才存在，坚持了物质第一性，属于古代朴素唯物主义。故本题选A。","__sub":"马原"},{"id":"zz-30750","module":"zhengzhi","prompt":"「世界是观念的集合」，这一命题属于：","options":["客观唯心主义","主观唯心主义","古代朴素唯物主义","辩证唯物主义"],"answer":1,"explanation":"贝克莱认为事物只是观念的集合，把人的主观观念当作世界的本原，属于主观唯心主义。故本题选A。","__sub":"马原"},{"id":"zz-30751","module":"zhengzhi","prompt":"「绝对精神」是世界的本原，这一命题属于：","options":["客观唯心主义","主观唯心主义","古代朴素唯物主义","辩证唯物主义"],"answer":0,"explanation":"黑格尔把「绝对精神」当作世界的本原，认为世界是绝对精神自我运动、自我展开的产物，把客观精神当作第一性，属于客观唯心主义。故本题选A。","__sub":"马原"},{"id":"zz-30752","module":"zhengzhi","prompt":"「水是万物的本原」，这一命题属于：","options":["古代朴素唯物主义","主观唯心主义","客观唯心主义","二元论"],"answer":0,"explanation":"泰勒斯以「水」这一具体物质形态解释世界本原，坚持了物质第一性，但缺乏科学论证，属于古代朴素唯物主义。故本题选A。","__sub":"马原"},{"id":"zz-30753","module":"zhengzhi","prompt":"「原子是世界的本原」，这一命题属于：","options":["主观唯心主义","古代朴素唯物主义","近代形而上学唯物主义","辩证唯物主义"],"answer":2,"explanation":"近代唯物主义以「原子」为世界本原，认为原子是不可再分的最小微粒，坚持了物质第一性但具有机械性，属于近代形而上学唯物主义。故本题选A。","__sub":"马原"},{"id":"zz-30754","module":"zhengzhi","prompt":"「物质是标志客观实在的哲学范畴」，这一物质定义的提出者是：","options":["列宁","马克思","恩格斯","毛泽东"],"answer":0,"explanation":"列宁在《唯物主义和经验批判主义》中给物质下了经典定义：物质是标志客观实在的哲学范畴，它不依赖于人的意识而存在，又可为人的意识所反映。故本题选A。","__sub":"马原"},{"id":"zz-30755","module":"zhengzhi","prompt":"「物质」与「意识」的关系中，「意识」的「反作用」是指：","options":["意识可以脱离物质","意识直接改变物质","意识通过实践指导人们改造客观世界","意识决定物质"],"answer":2,"explanation":"意识的反作用不是直接改变物质，而是通过指导实践，把观念的东西变成现实的东西，从而改造客观世界。故本题选A。","__sub":"马原"},{"id":"zz-30756","module":"zhengzhi","prompt":"「运动」与「物质」的关系是：","options":["物质可以脱离运动","运动可以脱离物质","运动是物质的固有属性和存在方式，物质是运动的承担者","二者互不相关"],"answer":2,"explanation":"物质都是运动着的物质，运动都是物质的运动，运动是物质的固有属性和存在方式，物质是运动的承担者（载体）。故本题选A。","__sub":"马原"},{"id":"zz-30757","module":"zhengzhi","prompt":"「静止」的两种情形是：","options":["空间位置相对不变和根本性质暂时未变","绝对不动","没有变化","与运动无关"],"answer":0,"explanation":"静止是运动的特殊状态，包括两种情形：一是事物之间空间位置相对不变，二是事物根本性质暂时未发生根本变化。故本题选A。","__sub":"马原"},{"id":"zz-30758","module":"zhengzhi","prompt":"「时间」的「一维性」是指：","options":["时间可以倒流","时间只有一个点","时间没有长短","时间只有一个方向，具有不可逆性"],"answer":3,"explanation":"时间的一维性指时间只有一个方向，从过去到现在再到未来，具有不可逆性，一去不复返。故本题选A。","__sub":"马原"},{"id":"zz-30759","module":"zhengzhi","prompt":"「空间」的「三维性」是指：","options":["空间可以折叠","空间有三个层次","空间具有长、宽、高三个方向","空间没有方向"],"answer":2,"explanation":"空间的三维性指任何物体的空间位置都具有长、宽、高三个方向，可以前后、左右、上下移动。故本题选A。","__sub":"马原"},{"id":"zz-30760","module":"zhengzhi","prompt":"「意识」的「能动性」与「动物心理」的区别在于：","options":["动物也有意识","人的意识具有目的性、计划性和创造性，动物心理是本能的","意识与动物心理相同","动物意识更高级"],"answer":1,"explanation":"人的意识具有目的性、计划性、自觉选择性和创造性，能够把握本质规律并指导实践；动物心理只是本能的、被动的反映。故本题选A。","__sub":"马原"},{"id":"zz-30761","module":"zhengzhi","prompt":"「实践」的「直接现实性」是指：","options":["实践没有现实结果","实践是观念活动","实践能把观念的东西变成现实的东西","实践与观念无关"],"answer":2,"explanation":"实践的直接现实性指实践是主观见之于客观的物质活动，能把观念的东西变成现实的东西，这是实践区别于认识活动的特点。故本题选A。","__sub":"马原"},{"id":"zz-30762","module":"zhengzhi","prompt":"「实践」的「自觉能动性」是指：","options":["实践没有目的","实践是本能活动","实践是有目的、有意识的活动","实践与意识无关"],"answer":2,"explanation":"实践的自觉能动性指实践是人在一定目的、计划指导下进行的有意识的活动，区别于动物的本能活动。故本题选A。","__sub":"马原"},{"id":"zz-30763","module":"zhengzhi","prompt":"「实践」的「社会历史性」是指：","options":["实践与历史无关","实践是孤立的","实践没有历史","实践在一定社会关系中展开，并随历史发展而发展"],"answer":3,"explanation":"实践不是孤立的个人活动，而是在一定社会关系中展开的，且随历史发展而发展，具有社会性和历史性。故本题选A。","__sub":"马原"},{"id":"zz-30764","module":"zhengzhi","prompt":"「联系」的「客观性」是指：","options":["联系是事物本身固有的，不以人的意志为转移","联系可以随意建立","联系是主观的","联系因人而异"],"answer":0,"explanation":"联系的客观性指联系是事物本身所固有的，不以人的意志为转移，人们只能根据事物固有的联系建立新的具体联系。故本题选A。","__sub":"马原"},{"id":"zz-30765","module":"zhengzhi","prompt":"「联系」的「多样性」是指：","options":["联系的形式是多种多样的，有直接间接、内部外部、必然偶然之分","联系只有一种形式","联系没有区别","联系是单一的"],"answer":0,"explanation":"联系的形式多种多样，包括直接联系与间接联系、内部联系与外部联系、必然联系与偶然联系、本质联系与非本质联系等。故本题选A。","__sub":"马原"},{"id":"zz-30766","module":"zhengzhi","prompt":"「发展」与「运动」的区别在于：","options":["二者没有区别","发展就是运动","运动比发展高级","发展是前进的上升的运动，运动不一定是发展"],"answer":3,"explanation":"运动是一般的变化，包括前进、倒退、循环等；发展是前进的、上升的运动，其实质是新事物的产生和旧事物的灭亡。故本题选A。","__sub":"马原"},{"id":"zz-30767","module":"zhengzhi","prompt":"「新事物」是指：","options":["新出现的事物","符合客观规律、具有强大生命力和远大前途的事物","力量强大的事物","形式新颖的事物"],"answer":1,"explanation":"新事物的判断标准不是出现时间的先后或形式的新旧，而是是否符合客观规律、是否具有强大生命力和远大前途。故本题选A。","__sub":"马原"},{"id":"zz-30768","module":"zhengzhi","prompt":"「量变」的基本形式包括：","options":["根本质变","性质的改变","数量的增减和场所的变更","循环往复"],"answer":2,"explanation":"量变是事物数量的增减和场所的变更，是微小的、不显著的变化，不改变事物的根本性质。故本题选A。","__sub":"马原"},{"id":"zz-30769","module":"zhengzhi","prompt":"「质变」的基本形式包括：","options":["爆发式飞跃和非爆发式飞跃","数量的增减","场所的变更","循环往复"],"answer":0,"explanation":"质变是事物性质的根本变化，其形式包括爆发式飞跃（如火山爆发、革命）和非爆发式飞跃（如物种演化、语言更新）。故本题选A。","__sub":"马原"},{"id":"zz-30770","module":"zhengzhi","prompt":"「度」的哲学含义是：","options":["事物的内部联系","事物的本质","事物的外部表现","保持事物质稳定性的数量界限或范围"],"answer":3,"explanation":"度是保持事物质的稳定性的数量界限或范围，在此范围内量变不引起质变，超出度的界限，事物就发生质变。故本题选A。","__sub":"马原"},{"id":"zz-30771","module":"zhengzhi","prompt":"「矛盾」的「对立统一」是指：","options":["矛盾双方只有统一","矛盾双方只有对立","矛盾双方既相互排斥又相互依存","矛盾双方毫无关系"],"answer":2,"explanation":"矛盾是事物内部或事物之间既对立又统一的关系，矛盾双方既相互排斥（斗争性）又相互依存（同一性）。故本题选A。","__sub":"马原"},{"id":"zz-30772","module":"zhengzhi","prompt":"「矛盾的普遍性」是指：","options":["矛盾只在某些阶段存在","矛盾只存在于特殊事物中","矛盾可以回避","矛盾存在于一切事物中，贯穿每一事物发展过程的始终"],"answer":3,"explanation":"矛盾的普遍性即矛盾的共性，指矛盾存在于一切事物中（事事有矛盾），贯穿每一事物发展过程的始终（时时有矛盾）。故本题选A。","__sub":"马原"},{"id":"zz-30773","module":"zhengzhi","prompt":"「矛盾的特殊性」的方法论要求是：","options":["具体问题具体分析","一概而论","平均用力","回避矛盾"],"answer":0,"explanation":"矛盾的特殊性要求对具体事物的矛盾进行具体分析，采取不同的解决方法，这是正确解决矛盾的关键。故本题选A。","__sub":"马原"},{"id":"zz-30774","module":"zhengzhi","prompt":"「主要矛盾」与「次要矛盾」的区分依据是：","options":["二者的数量多少","二者出现的时间先后","二者在事物发展中的地位和作用不同","二者的形式差异"],"answer":2,"explanation":"复杂事物中多个矛盾的地位和作用不平衡，其中居于支配地位、起决定作用的是主要矛盾，处于从属地位的是次要矛盾。故本题选A。","__sub":"马原"},{"id":"zz-30775","module":"zhengzhi","prompt":"「矛盾的主要方面」与「次要方面」的区分依据是：","options":["二者在矛盾统一体中的地位和作用不同","二者出现的时间先后","二者的数量多少","二者的形式差异"],"answer":0,"explanation":"矛盾双方在统一体中的地位和作用不平衡，其中处于支配地位、起主导作用的是矛盾的主要方面，处于被支配地位的是次要方面。故本题选A。","__sub":"马原"},{"id":"zz-30776","module":"zhengzhi","prompt":"「辩证否定」的「否定」是指：","options":["外力强加的否定","事物自身的否定，是发展的环节和联系的环节","全盘抛弃","全盘肯定"],"answer":1,"explanation":"辩证的否定是事物自身的否定，即事物内部矛盾运动的结果，是发展的环节（新事物代替旧事物）和联系的环节（保留积极因素）。故本题选A。","__sub":"马原"},{"id":"zz-30777","module":"zhengzhi","prompt":"「否定之否定」规律揭示的事物发展状态是：","options":["联系与发展","量变与质变的统一","对立与统一的结合","前进性与曲折性的统一"],"answer":3,"explanation":"否定之否定规律揭示了事物发展经过两次否定、三个阶段，呈现前进性与曲折性的统一，总方向前进上升，具体道路迂回曲折。故本题选A。","__sub":"马原"},{"id":"zz-30778","module":"zhengzhi","prompt":"「认识」的「主体」是指：","options":["认识的中介","认识的对象","从事认识和实践活动的现实的人","认识的结果"],"answer":2,"explanation":"认识的主体是从事认识和实践活动的现实的人，具有社会性、历史性和能动性，不是抽象的生物学意义上的人。故本题选A。","__sub":"马原"},{"id":"zz-30779","module":"zhengzhi","prompt":"「认识」的「客体」是指：","options":["认识主体本身","一切客观存在","主观意识","进入主体认识和实践范围的客观对象"],"answer":3,"explanation":"认识的客体是进入主体认识和实践范围的客观对象，不是一切客观存在，只有与主体发生认识关系的对象才是客体。故本题选A。","__sub":"马原"},{"id":"zz-30780","module":"zhengzhi","prompt":"「认识」的「中介」是指：","options":["连接主体与客体的各种物质工具和信息手段","主体本身","客体本身","认识的结果"],"answer":0,"explanation":"认识的中介包括各种物质工具（仪器、设备）和信息手段（语言、理论框架等），它们延伸了主体的认识能力，是主客体联系的桥梁。故本题选A。","__sub":"马原"},{"id":"zz-30781","module":"zhengzhi","prompt":"「感性认识」的特点是：","options":["间接性和抽象性","直接性和具体性","系统性和理论性","客观性和主观性"],"answer":1,"explanation":"感性认识是认识的初级阶段，通过感官直接获得对事物现象的认识，具有直接性和具体性的特点。故本题选A。","__sub":"马原"},{"id":"zz-30782","module":"zhengzhi","prompt":"「理性认识」的特点是：","options":["表面性和片面性","直接性和具体性","间接性和抽象性","主观性和随意性"],"answer":2,"explanation":"理性认识是认识的高级阶段，通过思维加工间接把握事物的本质和规律，具有间接性和抽象性的特点。故本题选A。","__sub":"马原"},{"id":"zz-30783","module":"zhengzhi","prompt":"「真理」的「绝对性」是指：","options":["真理是永恒不变的","真理的内容具有客观性，认识每前进一步都是对无限发展着的物质世界的接近","真理不需要再发展","真理适用于一切条件"],"answer":1,"explanation":"真理的绝对性指真理内容的客观性和认识每前进一步都获得对客观世界的正确认识，任何真理都包含着不依人的意志为转移的客观内容。故本题选A。","__sub":"马原"},{"id":"zz-30784","module":"zhengzhi","prompt":"「真理」的「相对性」是指：","options":["真理没有客观内容","真理是错误的","真理随时被推翻","真理在广度和深度上的有限性"],"answer":3,"explanation":"真理的相对性指任何真理都只是对客观世界一定范围、一定程度的正确反映，在广度和深度上有待扩展和深化。故本题选A。","__sub":"马原"},{"id":"zz-30785","module":"zhengzhi","prompt":"「实践」检验真理的「过程性」是指：","options":["实践检验一次完成","实践对真理的检验随实践发展而不断深化","实践检验不可靠","实践检验可以替代"],"answer":1,"explanation":"实践是发展的，一定历史阶段的实践有局限性，对真理的检验不能一次完成，需要随实践发展而不断深化，是一个过程。故本题选A。","__sub":"马原"},{"id":"zz-30786","module":"zhengzhi","prompt":"「价值」的「客观性」是指：","options":["价值完全主观","价值的客观基础是客体的属性和主体的需要都具有客观性","价值没有客观基础","价值因人而异没有标准"],"answer":1,"explanation":"价值的客观性指客体的属性和功能是客观的，主体的需要（如生存、发展）也是客观的，价值关系建立在客观基础上。故本题选A。","__sub":"马原"},{"id":"zz-30787","module":"zhengzhi","prompt":"「社会存在」的三个组成部分中，起决定作用的是：","options":["风俗习惯","自然地理环境","人口因素","物质生产方式"],"answer":3,"explanation":"社会存在包括自然地理环境、人口因素和物质生产方式，其中物质生产方式是社会存在和发展的决定力量。故本题选A。","__sub":"马原"},{"id":"zz-30788","module":"zhengzhi","prompt":"「社会意识」的「历史继承性」是指：","options":["每一时代的社会意识都继承前代的社会意识成果","社会意识没有历史","社会意识凭空产生","社会意识与历史无关"],"answer":0,"explanation":"每一时代的社会意识都不是凭空产生的，而是在继承前代社会意识成果的基础上发展起来的，具有历史继承性。故本题选A。","__sub":"马原"},{"id":"zz-30789","module":"zhengzhi","prompt":"「生产力」的「客观现实性」是指：","options":["生产力由人的意志决定","生产力是一种既得的物质力量，不以人的意志为转移","生产力可以随意选择","生产力与物质无关"],"answer":1,"explanation":"生产力是人们在 previous 世代积累的基础上获得的既得力量，具有客观现实性，人们不能随意选择或改变生产力。故本题选A。","__sub":"马原"},{"id":"zz-30790","module":"zhengzhi","prompt":"「生产关系」的「客观性」是指：","options":["生产关系可以随意选择","生产关系由人的意志决定","生产关系由生产力决定，不以人的意志为转移","生产关系与生产力无关"],"answer":2,"explanation":"生产关系由生产力决定，有什么样的生产力就有什么样的生产关系，人们不能随意选择生产关系。故本题选A。","__sub":"马原"},{"id":"zz-30791","module":"zhengzhi","prompt":"「阶级」的实质是：","options":["经济范畴，是一个集团占有另一个集团的劳动","政治范畴","文化范畴","思想范畴"],"answer":0,"explanation":"阶级首先是一个经济范畴，其实质是一个集团由于在生产关系中所处的地位不同而占有另一个集团的劳动。故本题选A。","__sub":"马原"},{"id":"zz-30792","module":"zhengzhi","prompt":"「国家」产生的根源是：","options":["自然形成的","社会契约的产物","人们协商的结果","阶级矛盾不可调和的产物"],"answer":3,"explanation":"马克思主义认为，国家不是从来就有的，它是阶级矛盾不可调和的产物和表现，随着阶级的产生而产生。故本题选A。","__sub":"马原"},{"id":"zz-30793","module":"zhengzhi","prompt":"「社会革命」的「根本问题」是：","options":["经济问题","国家政权问题","文化问题","军事问题"],"answer":1,"explanation":"社会革命的根本问题是国家政权问题，革命阶级只有夺取国家政权才能实现社会形态的根本变革。故本题选A。","__sub":"马原"},{"id":"zz-30794","module":"zhengzhi","prompt":"「改革」的「性质」是：","options":["推翻根本制度","社会主义制度的自我完善和发展","社会形态的根本变革","阶级斗争的形式"],"answer":1,"explanation":"改革是在坚持社会主义基本制度的前提下，调整生产关系和上层建筑中不适应的部分，是制度的自我完善和发展。故本题选A。","__sub":"马原"},{"id":"zz-30795","module":"zhengzhi","prompt":"「科学技术」在社会发展中的作用是：","options":["是先进生产力的集中体现和主要标志，是推动社会发展的革命性力量","与社会发展无关","只影响精神生活","是唯一的社会动力"],"answer":0,"explanation":"科学技术日益成为先进生产力的集中体现和主要标志，通过转化为现实生产力推动社会发展，是推动社会发展的革命性力量。故本题选A。","__sub":"马原"},{"id":"zz-30796","module":"zhengzhi","prompt":"习近平新时代中国特色社会主义思想是当代中国马克思主义、二十一世纪马克思主义，是中华文化和中国精神的时代精华，实现了：","options":["共产主义学说的最终完成","马克思主义的彻底重构","社会主义理论的根本转向","马克思主义中国化时代化新的飞跃"],"answer":3,"explanation":"党的十九届六中全会决议明确，习近平新时代中国特色社会主义思想实现了马克思主义中国化时代化新的飞跃。「彻底重构」「根本转向」否定了马克思主义的继承发展关系，「最终完成」违背理论不断发展的品格，故选D。","__sub":"习思想"},{"id":"zz-30797","module":"zhengzhi","prompt":"习近平新时代中国特色社会主义思想的核心要义是：","options":["坚持和发展中国特色社会主义","实现共产主义远大理想","建设社会主义现代化强国","实现全体人民共同富裕"],"answer":0,"explanation":"习近平新时代中国特色社会主义思想的核心要义是坚持和发展中国特色社会主义，这是新时代全部理论和实践的主题。其余选项是奋斗目标或任务，不是核心要义本身，故选A。","__sub":"习思想"},{"id":"zz-30800","module":"zhengzhi","prompt":"「两个确立」的具体内容是：","options":["确立党的基本路线，确立党的基本方略","确立习近平同志党中央的核心、全党的核心地位，确立习近平新时代中国特色社会主义思想的指导地位","确立以人民为中心，确立以发展为第一要务","确立全面建设小康社会，确立全面建设现代化国家"],"answer":1,"explanation":"党的十九届六中全会提出「两个确立」：确立习近平同志党中央的核心、全党的核心地位，确立习近平新时代中国特色社会主义思想的指导地位。其余选项均非「两个确立」的规范表述，故选B。","__sub":"习思想"},{"id":"zz-30801","module":"zhengzhi","prompt":"「四个自信」是指：","options":["政治自信、经济自信、文化自信、社会自信","道路自信、理论自信、制度自信、文化自信","理论自信、实践自信、制度自信、道路自信","道路自信、制度自信、法治自信、文化自信"],"answer":1,"explanation":"「四个自信」即道路自信、理论自信、制度自信、文化自信，是党的十八大以来党中央提出的规范表述。其余选项均属拼凑表述，故选B。","__sub":"习思想"},{"id":"zz-30802","module":"zhengzhi","prompt":"「四个意识」是指：","options":["政治意识、经济意识、文化意识、社会意识","大局意识、发展意识、安全意识、创新意识","政治意识、大局意识、核心意识、看齐意识","核心意识、看齐意识、纪律意识、规矩意识"],"answer":2,"explanation":"「四个意识」即政治意识、大局意识、核心意识、看齐意识，是党的十八届六中全会以来党中央对全党的要求。其余选项均非规范表述，故选C。","__sub":"习思想"},{"id":"zz-30803","module":"zhengzhi","prompt":"「两个维护」是指：","options":["维护国家主权，维护领土完整","维护党的团结，维护人民的利益","坚决维护习近平总书记党中央的核心、全党的核心地位，坚决维护党中央权威和集中统一领导","维护宪法权威，维护法律尊严"],"answer":2,"explanation":"「两个维护」的规范表述是坚决维护习近平总书记党中央的核心、全党的核心地位，坚决维护党中央权威和集中统一领导。其余选项均非规范表述，故选C。","__sub":"习思想"},{"id":"zz-30805","module":"zhengzhi","prompt":"「四个全面」战略布局的最新表述是：","options":["全面建设小康社会、全面深化改革、全面依法治国、全面从严治党","全面建设现代化国家、全面发展、全面稳定、全面开放","全面建成小康社会、全面深化改革、全面依法治国、全面从严治理","全面建设社会主义现代化国家、全面深化改革、全面依法治国、全面从严治党"],"answer":3,"explanation":"党的十九届五中全会后，「四个全面」战略布局表述更新为全面建设社会主义现代化国家、全面深化改革、全面依法治国、全面从严治党。小康社会已全面建成，B为旧表述，故选D。","__sub":"习思想"},{"id":"zz-30806","module":"zhengzhi","prompt":"「十四个坚持」基本方略中，居于统领地位的是：","options":["坚持新发展理念","坚持以人民为中心","坚持全面深化改革","坚持党对一切工作的领导"],"answer":3,"explanation":"「十四个坚持」第一条即坚持党对一切工作的领导，居于统领地位，其余各项都在党的领导下展开。以人民为中心是发展思想，深化改革和新发展理念是重要方略但非统领，故选D。","__sub":"习思想"},{"id":"zz-30807","module":"zhengzhi","prompt":"新时代坚持和发展中国特色社会主义的总任务是：","options":["实现全体人民共同富裕","实现社会主义现代化和中华民族伟大复兴","建设社会主义现代化强国","实现高水平科技自立自强"],"answer":1,"explanation":"新时代坚持和发展中国特色社会主义的总任务是实现社会主义现代化和中华民族伟大复兴，在全面建成小康社会的基础上分两步走。共同富裕是本质要求，科技自立自强是战略支撑，故选B。","__sub":"习思想"},{"id":"zz-30808","module":"zhengzhi","prompt":"全面建设社会主义现代化国家的「两步走」战略安排是：","options":["从2020年到2030年基本实现现代化，从2030年到2050年建成强国","从2020年到2035年全面建成小康社会，从2035年到2050年实现现代化","从2021年到2035年实现共同富裕，从2035年到2050年建成现代化强国","从2020年到2035年基本实现社会主义现代化，从2035年到本世纪中叶把我国建成富强民主文明和谐美丽的社会主义现代化强国"],"answer":3,"explanation":"党的十九大作出「两步走」安排：2020年到2035年基本实现社会主义现代化；2035年到本世纪中叶把我国建成富强民主文明和谐美丽的社会主义现代化强国。B错在小康社会2020年已建成，其余选项年份与目标均不准确，故选D。","__sub":"习思想"},{"id":"zz-30809","module":"zhengzhi","prompt":"「六个必须坚持」中，体现根本立场的是：","options":["必须坚持自信自立","必须坚持胸怀天下","必须坚持守正创新","必须坚持人民至上"],"answer":3,"explanation":"党的二十大报告概括「六个必须坚持」：必须坚持人民至上、自信自立、守正创新、问题导向、系统观念、胸怀天下。其中坚持人民至上体现党的根本立场，排在首位。其余选项虽属「六个必须坚持」但不体现「根本立场」这一定位，故选D。","__sub":"习思想"},{"id":"zz-30810","module":"zhengzhi","prompt":"「六个必须坚持」中，体现鲜明品格和风骨的是：","options":["必须坚持自信自立","必须坚持人民至上","必须坚持系统观念","必须坚持问题导向"],"answer":0,"explanation":"党的二十大报告指出，必须坚持自信自立，体现中国共产党人的鲜明品格和风骨。人民至上体现根本立场，系统观念和问题导向体现思想方法和工作方法，故选A。","__sub":"习思想"},{"id":"zz-30811","module":"zhengzhi","prompt":"「两个结合」是指把马克思主义基本原理同中国具体实际相结合、同：","options":["人民群众实践经验相结合","世界先进文明成果相结合","中华优秀传统文化相结合","现代科学技术相结合"],"answer":2,"explanation":"「两个结合」的规范表述是把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合。其余选项均非规范表述，故选C。","__sub":"习思想"},{"id":"zz-30812","module":"zhengzhi","prompt":"把马克思主义基本原理同中华优秀传统文化相结合，被称为：","options":["又一次的思想解放","一次的思想启蒙","理论的根本转向","实践的伟大转折"],"answer":0,"explanation":"习近平总书记在文化传承发展座谈会上指出，「第二个结合」是又一次的思想解放，让我们能够在更广阔的文化空间中充分运用中华优秀传统文化的宝贵资源。其余选项均非规范表述，故选A。","__sub":"习思想"},{"id":"zz-30813","module":"zhengzhi","prompt":"中国共产党领导是中国特色社会主义最本质的特征，这一特征直接体现为：","options":["党是最高政治领导力量","党领导一切经济活动","党包办一切社会事务","党直接管理企业经营"],"answer":0,"explanation":"党的领导地位直接体现为党是最高政治领导力量，总揽全局、协调各方。党领导经济工作但不包办企业经营，更不包办一切社会事务，故选A。","__sub":"习思想"},{"id":"zz-30814","module":"zhengzhi","prompt":"新时代我国社会主要矛盾发生变化，但没有改变的是：","options":["我国仍处于并将长期处于社会主义初级阶段的基本国情","我国是世界最大发展中国家的国际地位","社会主义初级阶段的基本国情","发展中国家的国际地位"],"answer":2,"explanation":"党的十九大指出，社会主要矛盾的变化没有改变我们对我国社会主义所处历史阶段的判断，即我国仍处于并将长期处于社会主义初级阶段的基本国情没有变，我国是世界最大发展中国家的国际地位没有变。","__sub":"习思想"},{"id":"zz-30815","module":"zhengzhi","prompt":"新时代我国社会主要矛盾的变化意味着：","options":["我国已进入发达国家行列","我国社会主要矛盾的变化没有改变我们对我国社会主义所处历史阶段的判断","我国仍处于新民主主义社会","社会主义初级阶段已经结束"],"answer":1,"explanation":"社会主要矛盾变化是关系全局的历史性变化，但没有改变我国仍处于并将长期处于社会主义初级阶段的基本判断，没有改变我国是世界最大发展中国家的国际地位。C、D明显错误，B与实际不符，故选B。","__sub":"习思想"},{"id":"zz-30816","module":"zhengzhi","prompt":"中国式现代化是人口规模巨大的现代化，其突出含义是：","options":["我国现代化只覆盖城市人口","我国人口增长速度最快","我国要优先发展人口密集产业","我国十四亿多人口整体迈进现代化社会，规模超过现有发达国家人口总和"],"answer":3,"explanation":"党的二十大报告指出，中国式现代化是人口规模巨大的现代化，十四亿多人口整体迈进现代化社会，规模超过现有发达国家人口的总和，艰巨性和复杂性前所未有。其余选项均属曲解，故选D。","__sub":"习思想"},{"id":"zz-30817","module":"zhengzhi","prompt":"中国式现代化是全体人民共同富裕的现代化，这一特征表明：","options":["共同富裕是中国特色社会主义的本质要求，防止两极分化","同步同速富裕","先富地区可以不管后富地区","共同富裕等于平均主义"],"answer":0,"explanation":"中国式现代化追求全体人民共同富裕，坚决防止两极分化，但共同富裕不是同步同速、不是平均主义，也不是放弃先富带后富。B、C、D均属对共同富裕的曲解，故选A。","__sub":"习思想"},{"id":"zz-30818","module":"zhengzhi","prompt":"中国式现代化是物质文明和精神文明相协调的现代化，其要求是：","options":["精神文明可以替代物质文明","物质文明优先于精神文明","只抓物质文明建设","物质富足、精神富有是社会主义现代化的根本要求"],"answer":3,"explanation":"党的二十大报告强调，物质富足、精神富有是社会主义现代化的根本要求，两个文明相协调、比翼齐飞。B、C、D都割裂了两个文明的关系，故选D。","__sub":"习思想"},{"id":"zz-30819","module":"zhengzhi","prompt":"中国式现代化是人与自然和谐共生的现代化，其理念依据是：","options":["人定胜天","先污染后治理","向自然无节制索取","绿水青山就是金山银山"],"answer":3,"explanation":"人与自然和谐共生的现代化坚持「绿水青山就是金山银山」理念，尊重自然、顺应自然、保护自然。B是发达国家走过的老路，C、D违背生态文明理念，故选D。","__sub":"习思想"},{"id":"zz-30820","module":"zhengzhi","prompt":"中国式现代化是走和平发展道路的现代化，其含义是：","options":["不走殖民掠夺的老路，在坚定维护世界和平与发展中谋求自身发展","依靠战争扩张实现现代化","与外部世界脱钩发展","先称霸后发展"],"answer":0,"explanation":"中国式现代化强调不走一些国家通过战争、殖民、掠夺等方式实现现代化的老路，坚定站在历史正确一边，在维护世界和平与发展中发展自己。B、C、D均与和平发展道路相悖，故选A。","__sub":"习思想"},{"id":"zz-30821","module":"zhengzhi","prompt":"中国式现代化创造了人类文明新形态，其「新」体现在：","options":["照搬西方现代化模式","完全抛弃人类文明共同成果","打破「现代化=西方化」的迷思，展现现代化的另一幅图景","只适用于中国不具借鉴意义"],"answer":2,"explanation":"中国式现代化蕴含的独特世界观、价值观、历史观、文明观、民主观、法治观等，打破「现代化=西方化」的迷思，为人类实现现代化提供了新的选择。它吸收人类文明共同成果而非抛弃，也不是照搬西方模式，故选C。","__sub":"习思想"},{"id":"zz-30822","module":"zhengzhi","prompt":"中国式现代化的本质要求中，「坚持中国共产党领导」居于：","options":["统领地位","从属地位","次要地位","补充地位"],"answer":0,"explanation":"党的二十大报告概括的中国式现代化本质要求中，坚持中国共产党领导居于统领地位，决定中国式现代化的根本性质和方向。其余选项均不符合规范表述，故选A。","__sub":"习思想"},{"id":"zz-30825","module":"zhengzhi","prompt":"新发展理念中，解决发展动力问题的是：","options":["协调","共享","开放","创新"],"answer":3,"explanation":"创新发展注重的是解决发展动力问题；协调发展解决发展不平衡问题；开放发展解决发展内外联动问题；共享发展解决社会公平正义问题。故选D。","__sub":"习思想"},{"id":"zz-30826","module":"zhengzhi","prompt":"从根本宗旨把握新发展理念，其核心要求是：","options":["坚持以人民为中心的发展思想","以资本增值为最高目标","以产量规模为唯一标准","以短期增速为唯一导向"],"answer":2,"explanation":"习近平总书记强调，从根本宗旨把握新发展理念，就是坚持以人民为中心的发展思想，让发展成果更多更公平惠及全体人民，扎实推进共同富裕。","__sub":"习思想"},{"id":"zz-30827","module":"zhengzhi","prompt":"新发展理念中，解决人与自然和谐问题的是：","options":["协调","创新","绿色","开放"],"answer":2,"explanation":"绿色发展注重的是解决人与自然和谐问题，要求形成绿色发展方式和生活方式。创新解决动力问题，协调解决不平衡问题，开放解决内外联动问题，故选C。","__sub":"习思想"},{"id":"zz-30828","module":"zhengzhi","prompt":"新发展理念中，解决社会公平正义问题的是：","options":["共享","创新","协调","绿色"],"answer":0,"explanation":"共享发展注重的是解决社会公平正义问题，体现以人民为中心的发展思想，全民共享、全面共享、共建共享、渐进共享。其余理念各有侧重，故选A。","__sub":"习思想"},{"id":"zz-30829","module":"zhengzhi","prompt":"新发展理念是一个整体，其中处于核心位置、作为第一动力的是：","options":["创新","协调","绿色","开放"],"answer":0,"explanation":"创新是引领发展的第一动力，在新发展理念中居于核心位置，坚持创新在我国现代化建设全局中的核心地位。其余理念均非第一动力，故选A。","__sub":"习思想"},{"id":"zz-30830","module":"zhengzhi","prompt":"构建新发展格局的关键在于：","options":["实现经济循环流转和产业关联畅通","扩大进口规模","增加财政赤字","放松宏观调控"],"answer":0,"explanation":"构建新发展格局的关键在于经济循环的畅通无阻，实现经济循环流转和产业关联畅通，不断提升供给体系的创新力和关联性。扩大进口、增加赤字、放松调控都不是关键所在，故选A。","__sub":"习思想"},{"id":"zz-30831","module":"zhengzhi","prompt":"构建新发展格局最本质的特征是：","options":["扩大对外开放","实现高水平的自立自强","发展对外贸易","吸引外资"],"answer":1,"explanation":"习近平总书记强调，构建新发展格局最本质的特征是实现高水平的自立自强。对外开放是重要条件，但自立自强才是最本质特征，故选B。","__sub":"习思想"},{"id":"zz-30832","module":"zhengzhi","prompt":"新发展格局的「国内大循环」主体地位的确立依据是：","options":["我国劳动力成本最低","我国超大规模市场和完备产业体系的优势","我国出口规模全球第一","我国储蓄率全球最高"],"answer":1,"explanation":"以国内大循环为主体，依据是我国拥有超大规模市场优势和完备产业体系，具备经济循环的主体条件。劳动力成本、出口规模、储蓄率都不是确立内循环主体的依据，故选B。","__sub":"习思想"},{"id":"zz-30833","module":"zhengzhi","prompt":"「国内大循环」与「国内国际双循环」的关系是：","options":["国内大循环可以脱离国际循环","双循环意味着关起门来搞建设","以国内大循环为主体、国内国际双循环相互促进","国际循环决定国内循环"],"answer":2,"explanation":"新发展格局是以国内大循环为主体、国内国际双循环相互促进的格局，绝不是封闭的国内循环。B、C把内循环理解为封闭运行，D颠倒了主次关系，故选C。","__sub":"习思想"},{"id":"zz-30834","module":"zhengzhi","prompt":"发展新质生产力，其核心要素是：","options":["科技创新","土地规模","劳动力数量","能源消耗"],"answer":3,"explanation":"习近平总书记指出，科技创新是发展新质生产力的核心要素，必须加强科技创新特别是原创性、颠覆性科技创新，加快实现高水平科技自立自强。","__sub":"习思想"},{"id":"zz-30835","module":"zhengzhi","prompt":"新质生产力的关键在于：","options":["速度快","量大","质优","价格低"],"answer":2,"explanation":"习近平总书记指出，新质生产力特点是创新，关键在质优，本质是先进生产力。量大、速度快、价格低均非其关键，故选C。","__sub":"习思想"},{"id":"zz-30836","module":"zhengzhi","prompt":"新质生产力的本质是：","options":["劳动密集型生产","高投入产出","资源密集型生产","先进生产力"],"answer":3,"explanation":"新质生产力的本质是先进生产力，由技术革命性突破、生产要素创新性配置、产业深度转型升级而催生。高投入、劳动密集、资源密集均与先进生产力相悖，故选D。","__sub":"习思想"},{"id":"zz-30837","module":"zhengzhi","prompt":"关于新质生产力与绿色发展的关系，正确的是：","options":["新质生产力本身就是绿色生产力","发展新质生产力必须先污染后治理","绿色发展与新质生产力相互对立","新质生产力只涉及数字经济领域"],"answer":1,"explanation":"习近平总书记指出，绿色发展是高质量发展的底色，新质生产力本身就是绿色生产力，必须加快发展方式绿色转型，助力碳达峰碳中和。","__sub":"习思想"},{"id":"zz-30838","module":"zhengzhi","prompt":"新质生产力中「新」的体现是：","options":["沿用传统生产方式","单纯扩大生产规模","简单增加要素投入","以科技创新为引擎催生新产业、新模式、新动能"],"answer":3,"explanation":"新质生产力之「新」在于以科技创新催生新产业、新模式、新动能，摆脱传统增长方式。扩大规模、增加投入、沿用旧方式都是旧发展路径，故选D。","__sub":"习思想"},{"id":"zz-30839","module":"zhengzhi","prompt":"「全过程人民民主」是：","options":["仅指选举环节的民主","全链条、全方位、全覆盖的民主，是最广泛、最真实、最管用的社会主义民主","仅指协商民主","西方代议民主的中国版"],"answer":1,"explanation":"习近平总书记指出，全过程人民民主是全链条、全方位、全覆盖的民主，是最广泛、最真实、最管用的社会主义民主，实现了过程民主和成果民主、程序民主和实质民主等相统一。B、C只截取一个环节，D抹杀了其社会主义性质，故选B。","__sub":"习思想"},{"id":"zz-30840","module":"zhengzhi","prompt":"在我国，人民行使国家权力的机关是：","options":["全国人民代表大会和地方各级人民代表大会","各级人民政府","各级监察委员会","各级政协组织"],"answer":0,"explanation":"宪法规定，人民行使国家权力的机关是全国人民代表大会和地方各级人民代表大会。各级人民政府由人大产生、对人大负责，政协是爱国统一战线组织而非国家权力机关。","__sub":"习思想"},{"id":"zz-30841","module":"zhengzhi","prompt":"下列属于我国一项基本政治制度的是：","options":["中国共产党领导的多党合作和政治协商制度","人民代表大会制度","社会主义市场经济体制","民主集中制"],"answer":0,"explanation":"中国共产党领导的多党合作和政治协商制度、民族区域自治制度、基层群众自治制度是我国的基本政治制度；人民代表大会制度是根本政治制度，二者层级不同。","__sub":"习思想"},{"id":"zz-30842","module":"zhengzhi","prompt":"习近平总书记指出，全面依法治国是：","options":["国家治理的一场深刻革命","可有可无的权宜之计","与改革相互对立的工作","只涉及司法部门的业务"],"answer":3,"explanation":"习近平总书记强调，全面依法治国是国家治理的一场深刻革命，关系党执政兴国、关系人民幸福安康、关系党和国家长治久安，必须更好发挥法治固根本、稳预期、利长远的保障作用。","__sub":"习思想"},{"id":"zz-30843","module":"zhengzhi","prompt":"法律的生命力在于：","options":["实施","文本数量","条文篇幅","宣示内容"],"answer":1,"explanation":"习近平总书记强调，法律的生命力在于实施，法律的权威也在于实施。如果法律得不到有效实施，再完备的法律体系也只是纸面规定。","__sub":"习思想"},{"id":"zz-30844","module":"zhengzhi","prompt":"全面依法治国必须坚持法治国家、法治政府、法治社会：","options":["分别推进","一体建设","先后建设","局部建设"],"answer":1,"explanation":"习近平法治思想强调坚持法治国家、法治政府、法治社会一体建设，统筹推进科学立法、严格执法、公正司法、全民守法。分别推进、先后建设、局部建设均与「一体建设」相悖，故选B。","__sub":"习思想"},{"id":"zz-30845","module":"zhengzhi","prompt":"全面依法治国中，法治的根基在：","options":["政党","政府","人民","法院"],"answer":2,"explanation":"习近平总书记指出，法治的根基在人民，必须坚持法治建设为了人民、依靠人民、造福人民、保护人民。政府、政党、法院都不是法治的根基，故选C。","__sub":"习思想"},{"id":"zz-30846","module":"zhengzhi","prompt":"「文化自信」的根基在于：","options":["网络文化","外来文化","流行文化","中华优秀传统文化、革命文化和社会主义先进文化"],"answer":3,"explanation":"文化自信的根基在于中华优秀传统文化、革命文化和社会主义先进文化，三者共同构成文化自信的深厚底蕴。外来文化、流行文化、网络文化都不是文化自信的根基，故选D。","__sub":"习思想"},{"id":"zz-30847","module":"zhengzhi","prompt":"社会主义核心价值观的三个层面是：","options":["政党、政府、公民","城市、乡村、家庭","经济、政治、文化","国家、社会、个人"],"answer":3,"explanation":"社会主义核心价值观分三个层面：国家层面富强、民主、文明、和谐；社会层面自由、平等、公正、法治；个人层面爱国、敬业、诚信、友善。其余选项均非规范表述，故选D。","__sub":"习思想"},{"id":"zz-30848","module":"zhengzhi","prompt":"社会主义核心价值观中，国家层面的价值目标是：","options":["创新、协调、绿色、开放","自由、平等、公正、法治","爱国、敬业、诚信、友善","富强、民主、文明、和谐"],"answer":3,"explanation":"国家层面价值目标是富强、民主、文明、和谐；自由、平等、公正、法治是社会层面；爱国、敬业、诚信、友善是个人层面；第四项是新发展理念，故选D。","__sub":"习思想"},{"id":"zz-30849","module":"zhengzhi","prompt":"社会主义核心价值观中，个人层面的价值准则是：","options":["富强、民主、文明、和谐","爱国、敬业、诚信、友善","自由、平等、公正、法治","创新、协调、绿色、开放"],"answer":1,"explanation":"个人层面价值准则是爱国、敬业、诚信、友善。富强、民主、文明、和谐是国家层面，自由、平等、公正、法治是社会层面，故选B。","__sub":"习思想"},{"id":"zz-30850","module":"zhengzhi","prompt":"意识形态工作是为国家立心、为民族立魂的工作，其根本任务是：","options":["发展文化产业","扩大文化消费","繁荣网络娱乐","建设具有强大凝聚力和引领力的社会主义意识形态"],"answer":3,"explanation":"建设具有强大凝聚力和引领力的社会主义意识形态，是新时代意识形态工作的根本任务。发展文化产业、扩大文化消费是文化建设的内容，网络娱乐繁荣更不是根本任务，故选D。","__sub":"习思想"},{"id":"zz-30851","module":"zhengzhi","prompt":"「国之大者」强调的是：","options":["短期经济指标","地方局部利益","个人政绩得失","事关党和国家前途命运、人民根本利益的重大问题"],"answer":3,"explanation":"「国之大者」要求对「国之大者」心中有数，关注党中央在关心什么、强调什么，即事关党和国家前途命运、人民根本利益的重大问题。局部利益、短期指标、个人政绩均与之相悖，故选D。","__sub":"习思想"},{"id":"zz-30852","module":"zhengzhi","prompt":"「人民对美好生活的向往就是我们的奋斗目标」体现的发展思想是：","options":["以人民为中心","以资本为中心","以增长为中心","以效率为中心"],"answer":0,"explanation":"这一重要论断体现以人民为中心的发展思想，把增进民生福祉作为发展的根本目的。以资本、增长、效率为中心均偏离了社会主义生产目的，故选A。","__sub":"习思想"},{"id":"zz-30853","module":"zhengzhi","prompt":"「共同富裕」的准确理解是：","options":["全体人民的富裕，是人民群众物质生活和精神生活都富裕，不是少数人的富裕","同步同速富裕","平均主义","只讲物质富裕"],"answer":0,"explanation":"共同富裕是全体人民的富裕，是人民群众物质生活和精神生活都富裕，不是少数人的富裕，也不是整齐划一的平均主义，允许有先富后富。B、C、D均为对共同富裕的曲解，故选A。","__sub":"习思想"},{"id":"zz-30854","module":"zhengzhi","prompt":"实现共同富裕首先要通过：","options":["限制高收入","行政手段均分财富","降低发展速度","全国人民共同奋斗把「蛋糕」做大做好"],"answer":3,"explanation":"实现共同富裕首先要通过全国人民共同奋斗把「蛋糕」做大做好，然后通过合理的制度安排把「蛋糕」切好分好。均分财富、限制收入、降低速度都不是正确路径，故选D。","__sub":"习思想"},{"id":"zz-30855","module":"zhengzhi","prompt":"「三次分配」中，慈善事业属于：","options":["第三次分配","第一次分配","第二次分配","第四次分配"],"answer":0,"explanation":"初次分配讲效率，再分配讲公平（通过税收、社保等），第三次分配发展慈善事业等社会公益，是补充性分配。慈善事业属于第三次分配，故选A。","__sub":"习思想"},{"id":"zz-30856","module":"zhengzhi","prompt":"「乡村振兴」战略的总要求是：","options":["脱贫、增收、致富、小康","产业兴旺、生态宜居、乡风文明、治理有效、生活富裕","农业强、农村美、农民富","生产发展、生活宽裕、乡风文明、村容整洁、管理民主"],"answer":1,"explanation":"党的十九大提出乡村振兴战略总要求是产业兴旺、生态宜居、乡风文明、治理有效、生活富裕。B是社会主义新农村建设的旧要求，C是目标形象表述而非总要求，故选B。","__sub":"习思想"},{"id":"zz-30857","module":"zhengzhi","prompt":"巩固拓展脱贫攻坚成果同乡村振兴有效衔接的关键是：","options":["减少农业投入","扩大城镇规模","防止规模性返贫","压缩农村人口"],"answer":2,"explanation":"过渡期内守住不发生规模性返贫底线，是巩固拓展脱贫攻坚成果同乡村振兴有效衔接的关键任务。扩大城镇、压缩人口、减少投入均与衔接要求相悖，故选C。","__sub":"习思想"},{"id":"zz-30858","module":"zhengzhi","prompt":"保障国家粮食安全的根本方针是：","options":["大量储备外汇","完全依赖进口","以我为主、立足国内、确保产能、适度进口、科技支撑","压缩粮食消费"],"answer":2,"explanation":"国家粮食安全战略是「以我为主、立足国内、确保产能、适度进口、科技支撑」，把中国人的饭碗牢牢端在自己手中。完全依赖进口会受制于人，其余选项均非方针，故选C。","__sub":"习思想"},{"id":"zz-30859","module":"zhengzhi","prompt":"「藏粮于地、藏粮于技」战略的核心要义是：","options":["限制粮食消费","守住耕地红线并依靠科技提高粮食生产能力","扩大粮食储备规模","大量进口粮食"],"answer":1,"explanation":"「藏粮于地」要求严守耕地红线、建设高标准农田，「藏粮于技」要求依靠科技进步提高单产，二者共同保障粮食产能。进口、储备、限购都不是该战略的核心要义，故选B。","__sub":"习思想"},{"id":"zz-30860","module":"zhengzhi","prompt":"「绿水青山就是金山银山」理念主要回答的问题是：","options":["如何处理政府与市场的关系","如何处理经济发展与生态环境保护的关系","如何处理城市与乡村的关系","如何处理国内与国际的关系"],"answer":1,"explanation":"「两山」理念深刻阐明了经济发展与生态环境保护的关系，保护生态环境就是保护生产力，改善生态环境就是发展生产力。政府与市场、城乡、内外关系均不是该理念直接回答的问题，故选B。","__sub":"习思想"},{"id":"zz-30861","module":"zhengzhi","prompt":"生态文明建设的核心原则是：","options":["人与自然和谐共生","先发展后治理","人类中心主义","征服自然"],"answer":0,"explanation":"习近平生态文明思想坚持人与自然和谐共生，把生态文明建设摆在全局工作的突出位置。先发展后治理是老路，人类中心主义、征服自然均与生态文明理念相悖，故选A。","__sub":"习思想"},{"id":"zz-30862","module":"zhengzhi","prompt":"「双碳」目标是指：","options":["碳交易、碳关税","碳税、碳配额","碳减排、碳封存","碳达峰、碳中和"],"answer":3,"explanation":"「双碳」目标即二氧化碳排放力争2030年前达到峰值、2060年前实现碳中和。碳交易、碳关税、碳税等是政策工具而非目标本身，故选D。","__sub":"习思想"},{"id":"zz-30863","module":"zhengzhi","prompt":"实现碳达峰碳中和，必须坚持的原则是：","options":["运动式减碳","先立后破，稳妥有序推进","一步到位","先破后立"],"answer":1,"explanation":"实现「双碳」目标要坚持全国统筹、节约优先、双轮驱动、内外畅通、防范风险，坚持先立后破，不能搞运动式减碳和「一刀切」。一步到位、运动式减碳、先破后立均违背稳妥推进原则，故选B。","__sub":"习思想"},{"id":"zz-30864","module":"zhengzhi","prompt":"「民生是人民幸福之基、社会和谐之本」，保障和改善民生的着力点是：","options":["提高税收水平","解决好人民群众急难愁盼问题","扩大投资规模","追求GDP增速"],"answer":1,"explanation":"保障和改善民生要抓住人民最关心最直接最现实的利益问题，即解决好急难愁盼问题，在幼有所育、学有所教、劳有所得、病有所医、老有所养、住有所居、弱有所扶上持续用力。GDP、投资、税收都不是民生工作的着力点，故选B。","__sub":"习思想"},{"id":"zz-30865","module":"zhengzhi","prompt":"「人民城市人民建、人民城市为人民」体现的城市治理理念是：","options":["以管理为中心","以人民为中心的城市治理","以建设为中心","以扩张为中心"],"answer":1,"explanation":"这一理念强调城市的核心是人，城市治理要坚持以人民为中心，让人民群众在城市生活更方便、更舒心、更美好。管理、建设、扩张都不是城市治理的根本理念，故选B。","__sub":"习思想"},{"id":"zz-30866","module":"zhengzhi","prompt":"新时代「枫桥经验」的核心理念是：","options":["事后追责","以罚代管","依靠群众、预防纠纷、化解矛盾、维护稳定","上交矛盾"],"answer":2,"explanation":"新时代「枫桥经验」坚持党的领导、人民主体，就地化解矛盾、不上交矛盾，实现小事不出村、大事不出镇、矛盾不上交。以罚代管、事后追责、上交矛盾均与「枫桥经验」相悖，故选C。","__sub":"习思想"},{"id":"zz-30867","module":"zhengzhi","prompt":"「把权力关进制度的笼子里」针对的核心问题是：","options":["权力缺乏有效制约和监督","权力过于分散","权力运行过慢","权力配置过低"],"answer":0,"explanation":"这一重要论述针对的是权力缺乏有效制约和监督的问题，要求构建不敢腐、不能腐、不想腐的体制机制，把权力关进制度的笼子。权力分散、过慢、过低均非针对的问题，故选A。","__sub":"习思想"},{"id":"zz-30868","module":"zhengzhi","prompt":"党的各项建设中，起基础性作用的是：","options":["思想建设","政治建设","纪律建设","制度建设"],"answer":0,"explanation":"思想建设是党的基础性建设，要坚持以习近平新时代中国特色社会主义思想武装全党，筑牢信仰之基、补足精神之钙；政治建设是统领，二者定位不同。","__sub":"习思想"},{"id":"zz-30869","module":"zhengzhi","prompt":"新时代党的建设总要求明确，党的政治建设的统领地位是指：","options":["政治建设从属于组织建设","政治建设可以替代其他建设","以党的政治建设为统领，把政治建设摆在首位","政治建设只管干部"],"answer":2,"explanation":"新时代党的建设以党的政治建设为统领，把政治建设摆在首位，保证全党服从中央、坚持党中央权威和集中统一领导。B、C、D均歪曲了政治建设的统领地位，故选C。","__sub":"习思想"},{"id":"zz-30870","module":"zhengzhi","prompt":"毛泽东在「窑洞对」中给出的跳出历史周期率的第一个答案是：","options":["让人民来监督政府","依靠严刑峻法","依赖官员自律","寄望外部监督"],"answer":2,"explanation":"毛泽东在延安回答黄炎培之问时指出，我们已经找到新路，就是民主，让人民来监督政府，政府才不敢松懈。经过百年奋斗特别是党的十八大以来新的实践，党又给出第二个答案，这就是自我革命。","__sub":"习思想"},{"id":"zz-30871","module":"zhengzhi","prompt":"跳出治乱兴衰历史周期率的第一个答案是：","options":["精简机构","让人民来监督政府","自我革命","发展经济"],"answer":1,"explanation":"1945年毛泽东在延安窑洞对中给出的第一个答案是让人民来监督政府，只有让人民来监督政府，政府才不敢松懈。自我革命是第二个答案，故选B。","__sub":"习思想"},{"id":"zz-30872","module":"zhengzhi","prompt":"全面从严治党中，「全面」的含义是：","options":["管全党、治全党，覆盖党的建设各个领域各个方面各部门","只管高级干部","只管基层党员","只管重点领域"],"answer":0,"explanation":"全面从严治党核心是加强党的领导，基础在全面，管全党、治全党，面向全体党员和各级组织，覆盖党的建设各领域。只管某一层级或某一方面都割裂了「全面」的含义，故选A。","__sub":"习思想"},{"id":"zz-30873","module":"zhengzhi","prompt":"「三严三实」中的「三严」是指：","options":["严以修身、严以用权、严以律己","严以对人、严以对己、严以对上","严管、严查、严罚","严要求、严标准、严考核"],"answer":1,"explanation":"「三严三实」即严以修身、严以用权、严以律己，谋事要实、创业要实、做人要实，是党员干部的修身之本、为政之道、成事之要。","__sub":"习思想"},{"id":"zz-30874","module":"zhengzhi","prompt":"「三严三实」的内容是：","options":["严以修身、严以用权、严以律己，谋事要实、创业要实、做人要实","严以律己、严以执法、严以治学，做事要实、做人要实、说话要实","严以治党、严以治国、严以治军，改革要实、发展要实、稳定要实","严以修身、严以齐家、严以治国，学习要实、工作要实、生活要实"],"answer":0,"explanation":"「三严三实」即严以修身、严以用权、严以律己，谋事要实、创业要实、做人要实，是习近平总书记提出的作风建设要求。其余选项均属拼凑，故选A。","__sub":"习思想"},{"id":"zz-30875","module":"zhengzhi","prompt":"中央八项规定精神重点解决的问题是：","options":["人口老龄化","经济结构失衡","形式主义、官僚主义、享乐主义和奢靡之风","区域发展差距"],"answer":2,"explanation":"中央八项规定及其实施细则精神重点纠治「四风」，即形式主义、官僚主义、享乐主义和奢靡之风。经济结构、区域差距、老龄化都不是八项规定针对的问题，故选C。","__sub":"习思想"},{"id":"zz-30876","module":"zhengzhi","prompt":"反腐败斗争的基本方针是：","options":["只教育不惩治","只惩治不预防","不敢腐、不能腐、不想腐一体推进","运动式反腐"],"answer":2,"explanation":"一体推进不敢腐（震慑）、不能腐（制度）、不想腐（自觉），是反腐败斗争的基本方针和新时代全面从严治党的重要方略。只惩不防、只教不惩、运动式反腐都割裂了三者关系，故选C。","__sub":"习思想"},{"id":"zz-30878","module":"zhengzhi","prompt":"在总体国家安全观中，作为国家安全根本的是：","options":["政治安全","人民安全","经济安全","军事安全"],"answer":0,"explanation":"总体国家安全观以政治安全为根本，核心是政权安全和制度安全。人民安全是宗旨，经济安全是基础，故选A。","__sub":"习思想"},{"id":"zz-30879","module":"zhengzhi","prompt":"总体国家安全观强调，国家安全的基础是：","options":["经济安全","军事安全","文化安全","社会安全"],"answer":0,"explanation":"总体国家安全观以经济安全为基础，发展是安全的基础，安全是发展的条件。军事、文化、社会安全是保障或重要方面，但不是基础，故选A。","__sub":"习思想"},{"id":"zz-30880","module":"zhengzhi","prompt":"「统筹发展和安全」的要求是：","options":["发展和安全并重，以安全保发展、以发展促安全","只重发展不顾安全","只重安全不谋发展","先发展后安全"],"answer":0,"explanation":"统筹发展和安全要求坚持发展和安全并重，实现高质量发展和高水平安全良性互动。只重一面或先后的思路都割裂了二者的辩证关系，故选A。","__sub":"习思想"},{"id":"zz-30881","module":"zhengzhi","prompt":"「一国两制」的根本宗旨是：","options":["放弃中央全面管治权","取消特别行政区制度","维护国家主权、安全、发展利益，保持香港、澳门长期繁荣稳定","改变内地与港澳的社会制度"],"answer":2,"explanation":"「一国两制」的根本宗旨是维护国家主权、安全、发展利益，保持香港、澳门长期繁荣稳定，二者缺一不可。其余选项均违背「一国两制」方针，故选C。","__sub":"习思想"},{"id":"zz-30882","module":"zhengzhi","prompt":"「一国两制」的前提和基础是：","options":["高度自治","两制并存","港人治港","一个中国"],"answer":3,"explanation":"「一国两制」的前提和基础是一个中国，即中华人民共和国，「两制」从属和派生于「一国」并统一于「一国」之内。两制并存、高度自治、港人治港都以「一国」为前提，故选D。","__sub":"习思想"},{"id":"zz-30883","module":"zhengzhi","prompt":"解决台湾问题的基本方针是：","options":["武力统一","和平统一、一国两制","维持现状","搁置统一"],"answer":1,"explanation":"「和平统一、一国两制」是解决台湾问题的基本方针，也是实现国家统一的最佳方式。同时我们决不承诺放弃使用武力，针对的是外部势力干涉和极少数「台独」分裂分子。B、C、D均非基本方针，故选B。","__sub":"习思想"},{"id":"zz-30884","module":"zhengzhi","prompt":"两岸关系和平发展的政治基础是：","options":["坚持一个中国原则","经济合作优先","文化交流频繁","民间往来密切"],"answer":0,"explanation":"坚持一个中国原则（「九二共识」）是两岸关系和平发展的政治基础，核心是两岸同属一个中国。经济、文化、民间往来是重要内容但不是政治基础，故选A。","__sub":"习思想"},{"id":"zz-30885","module":"zhengzhi","prompt":"「人类命运共同体」的核心要义是：","options":["划分势力范围","建立国家联盟","建设持久和平、普遍安全、共同繁荣、开放包容、清洁美丽的世界","输出发展模式"],"answer":2,"explanation":"人类命运共同体的核心要义是建设持久和平、普遍安全、共同繁荣、开放包容、清洁美丽的世界。结盟、输出模式、划分势力范围均与这一理念相悖，故选C。","__sub":"习思想"},{"id":"zz-30886","module":"zhengzhi","prompt":"「一带一路」倡议的核心内涵是：","options":["促进基础设施建设和互联互通，实现共同发展","建立军事同盟","输出意识形态","组建经济联盟"],"answer":0,"explanation":"「一带一路」倡议秉持共商共建共享原则，核心内涵是以基础设施建设为主线，加强互联互通，实现共同发展繁荣。结盟、输出意识形态、组建联盟均与倡议性质相悖，故选A。","__sub":"习思想"},{"id":"zz-30887","module":"zhengzhi","prompt":"全球安全倡议倡导的安全观是：","options":["共同、综合、合作、可持续的安全观","结盟对抗的安全观","弱肉强食的安全观","绝对安全、零和博弈的安全观"],"answer":0,"explanation":"全球安全倡议坚持共同、综合、合作、可持续的安全观，倡导以对话弥合分歧、以合作促安全，反对搞阵营对抗和零和博弈。","__sub":"习思想"},{"id":"zz-30888","module":"zhengzhi","prompt":"我国外交政策的宗旨是：","options":["建立军事同盟","维护世界和平、促进共同发展","输出革命","谋求地区霸权"],"answer":1,"explanation":"我国始终奉行独立自主的和平外交政策，其宗旨是维护世界和平、促进共同发展。霸权、输出革命、结盟均与我国外交宗旨相悖，故选B。","__sub":"习思想"},{"id":"zz-30889","module":"zhengzhi","prompt":"「全过程人民民主」的重要制度载体不包括：","options":["基层群众自治制度","人民代表大会制度","多党轮流执政","政治协商制度"],"answer":2,"explanation":"全过程人民民主的制度载体包括人民代表大会制度这一根本政治制度，多党合作和政治协商、民族区域自治、基层群众自治等基本政治制度。多党轮流执政是西方政治模式，不属于我国制度载体，故选C。","__sub":"习思想"},{"id":"zz-30890","module":"zhengzhi","prompt":"「协商民主」在我国民主形式中的定位是：","options":["选举民主的替代品","我国社会主义民主政治的特有形式和独特优势","可有可无的补充","西方专利"],"answer":1,"explanation":"协商民主是我国社会主义民主政治的特有形式和独特优势，与选举民主相辅相成，共同构成全过程人民民主。替代品、可有可无、西方专利均属错误定位，故选B。","__sub":"习思想"},{"id":"zz-30892","module":"zhengzhi","prompt":"习近平总书记强调，宗教工作的本质是：","options":["群众工作","商业工作","外事工作","安保工作"],"answer":2,"explanation":"习近平总书记指出，宗教工作的本质是群众工作，要全面贯彻党的宗教信仰自由政策，依法管理宗教事务，把广大信教群众团结在党和政府周围。","__sub":"习思想"},{"id":"zz-30893","module":"zhengzhi","prompt":"「学史明理、学史增信、学史崇德、学史力行」中，「学史力行」强调的是：","options":["了解历史事实","把学习成果转化为工作实效","坚定理想信念","传承道德规范"],"answer":1,"explanation":"党史学习教育要求学史明理、学史增信、学史崇德、学史力行，其中「力行」强调把学习成果转化为办实事、开新局的实际行动。了解事实、坚定信念、传承道德分别对应明理、增信、崇德，故选B。","__sub":"习思想"},{"id":"zz-30894","module":"zhengzhi","prompt":"党的二十大报告指出，从现在起党的中心任务是：","options":["团结带领全国各族人民全面建成社会主义现代化强国、实现第二个百年奋斗目标，以中国式现代化全面推进中华民族伟大复兴","以经济建设为中心再延续一百年不变","先解决温饱再谋发展","完成脱贫攻坚后转入休整"],"answer":1,"explanation":"党的二十大报告明确，从现在起党的中心任务就是团结带领全国各族人民全面建成社会主义现代化强国、实现第二个百年奋斗目标，以中国式现代化全面推进中华民族伟大复兴。","__sub":"习思想"},{"id":"zz-30895","module":"zhengzhi","prompt":"「伟大建党精神」的内容是：","options":["解放思想、实事求是，团结一致向前看","艰苦奋斗、自力更生，实事求是、群众路线","坚持真理、坚守理想，践行初心、担当使命，不怕牺牲、英勇斗争，对党忠诚、不负人民","爱国、进步、民主、科学"],"answer":2,"explanation":"伟大建党精神即坚持真理、坚守理想，践行初心、担当使命，不怕牺牲、英勇斗争，对党忠诚、不负人民，是中国共产党的精神之源。B是延安精神相关表述，C是十一届三中全会口号，D是五四精神，故选C。","__sub":"习思想"},{"id":"zz-30897","module":"zhengzhi","prompt":"「以中国式现代化全面推进中华民族伟大复兴」这一路径的确立场合是：","options":["党史学习教育动员大会","党的十九届六中全会","庆祝改革开放40周年大会","党的二十大"],"answer":3,"explanation":"党的二十大报告明确指出，从现在起中国共产党的中心任务就是团结带领全国各族人民全面建成社会主义现代化强国、实现第二个百年奋斗目标，以中国式现代化全面推进中华民族伟大复兴。故选D。","__sub":"习思想"},{"id":"zz-30898","module":"zhengzhi","prompt":"「高质量发展」与「新发展理念」的关系是：","options":["高质量发展是体现新发展理念的发展","高质量发展只讲速度","新发展理念只适用于经济领域","二者互不相关"],"answer":0,"explanation":"高质量发展是能够很好满足人民日益增长的美好生活需要的发展，是体现创新、协调、绿色、开放、共享新发展理念的发展。只讲速度是粗放发展，新发展理念贯穿各领域，故选A。","__sub":"习思想"},{"id":"zz-30899","module":"zhengzhi","prompt":"「供给侧结构性改革」的最终目的是：","options":["转移需求","扩大需求","抑制需求","满足需求"],"answer":3,"explanation":"供给侧结构性改革的最终目的是满足需求，主攻方向是提高供给质量，根本途径是深化改革。扩大、抑制、转移需求都不是其最终目的，故选D。","__sub":"习思想"},{"id":"zz-30900","module":"zhengzhi","prompt":"「创新」在我国现代化建设全局中的地位是：","options":["从属地位","边缘地位","补充地位","核心地位"],"answer":3,"explanation":"党的二十大报告强调坚持创新在我国现代化建设全局中的核心地位，加快实现高水平科技自立自强。其余选项均非规范表述，故选D。","__sub":"习思想"},{"id":"zz-30901","module":"zhengzhi","prompt":"实现高水平科技自立自强的关键举措是：","options":["依赖技术引进","减少科研投入","强化国家战略科技力量，打好关键核心技术攻坚战","放弃基础研究"],"answer":2,"explanation":"实现高水平科技自立自强，必须强化国家战略科技力量，发挥新型举国体制优势，打好关键核心技术攻坚战。减少投入、依赖引进、放弃基础研究都会受制于人，故选C。","__sub":"习思想"},{"id":"zz-30902","module":"zhengzhi","prompt":"「新型举国体制」的要义是：","options":["政府包办科研","完全依靠行政命令","完全依靠市场调节","发挥社会主义制度优势与市场机制作用的有机结合"],"answer":3,"explanation":"新型举国体制坚持党的集中统一领导，发挥社会主义制度集中力量办大事的优势与市场机制有机结合，协同攻关关键核心技术。完全行政化或完全市场化都偏离其要义，故选D。","__sub":"习思想"},{"id":"zz-30903","module":"zhengzhi","prompt":"「实体经济」在国民经济中的地位是：","options":["夕阳产业","可有可无","次要产业","立身之本、财富之源"],"answer":3,"explanation":"实体经济是一国经济的立身之本、财富之源，建设现代化经济体系必须把发展经济的着力点放在实体经济上。其余选项均错误定位了实体经济的地位，故选D。","__sub":"习思想"},{"id":"zz-30904","module":"zhengzhi","prompt":"「数字经济」与「实体经济」的关系是：","options":["促进数字经济和实体经济深度融合","数字经济替代实体经济","二者相互对立","数字经济只服务虚拟经济"],"answer":0,"explanation":"党的二十大报告要求加快发展数字经济，促进数字经济和实体经济深度融合，打造具有国际竞争力的数字产业集群。替代、对立、只服务虚拟经济均属错误理解，故选A。","__sub":"习思想"},{"id":"zz-30905","module":"zhengzhi","prompt":"「区域协调发展」的战略之一是：","options":["地方保护主义","区域封锁发展","京津冀协同发展、长江经济带发展、粤港澳大湾区建设等","同质化竞争"],"answer":2,"explanation":"我国实施区域协调发展战略，包括京津冀协同发展、长江经济带发展、粤港澳大湾区建设、长三角一体化发展、黄河流域生态保护和高质量发展等。区域封锁、地方保护、同质化竞争均与协调发展相悖，故选C。","__sub":"习思想"},{"id":"zz-30906","module":"zhengzhi","prompt":"「新型城镇化」的核心是：","options":["规模的城镇化","人的城镇化","房地产的城镇化","土地的城镇化"],"answer":1,"explanation":"新型城镇化坚持以人为核心，提高常住人口城镇化率的同时推进农业转移人口市民化，而不是片面追求土地、房地产或规模扩张。故选B。","__sub":"习思想"},{"id":"zz-30907","module":"zhengzhi","prompt":"「两个毫不动摇」是指：","options":["毫不动摇巩固和发展公有制经济，毫不动摇鼓励、支持、引导非公有制经济发展","毫不动摇发展国有经济，毫不动摇取消民营经济","毫不动摇扩大开放，毫不动摇收紧市场","毫不动摇政府主导，毫不动摇市场退出"],"answer":0,"explanation":"「两个毫不动摇」是党对基本经济制度的坚持：毫不动摇巩固和发展公有制经济，毫不动摇鼓励、支持、引导非公有制经济发展。B、C、D均属对基本经济制度的曲解，故选A。","__sub":"习思想"},{"id":"zz-30908","module":"zhengzhi","prompt":"「有效市场」和「有为政府」的关系是：","options":["政府与市场对立","政府包办一切","二者有机结合，既发挥市场在资源配置中的决定性作用，又更好发挥政府作用","市场万能论"],"answer":2,"explanation":"经济体制改革的核心问题是处理好政府和市场的关系，既要发挥市场在资源配置中的决定性作用，又要更好发挥政府作用，二者有机结合而非对立。政府包办、市场万能、相互对立均属片面认识，故选C。","__sub":"习思想"},{"id":"zz-30909","module":"zhengzhi","prompt":"「国家安全」的内涵在总体国家安全观中是：","options":["仅指军事安全","仅指政治安全","涵盖政治、军事、国土、经济、文化、社会、科技、网络、生态、资源、核、海外利益等领域的安全","仅指经济安全"],"answer":2,"explanation":"总体国家安全观坚持系统思维，国家安全内涵外延涵盖政治、军事、国土、经济、文化、社会、科技、网络、生态、资源、核、海外利益等诸多领域。仅指某一领域都缩小了其内涵，故选C。","__sub":"习思想"},{"id":"zz-30910","module":"zhengzhi","prompt":"「平安中国」建设的重点是：","options":["扩大警力规模","防范化解重大风险","限制人口流动","收紧社会管理"],"answer":1,"explanation":"平安中国建设坚持底线思维，重点是防范化解影响社会稳定的重大风险，健全社会治安防控体系。扩大警力、限制流动、收紧管理都不是重点方向，故选B。","__sub":"习思想"},{"id":"zz-30911","module":"zhengzhi","prompt":"「强军目标」的内容是：","options":["听党指挥、能打胜仗、作风优良","规模庞大、装备先进、待遇优厚","数量第一、速度第一、规模第一","攻防兼备、全球部署、快速反应"],"answer":0,"explanation":"党在新时代的强军目标是建设一支听党指挥、能打胜仗、作风优良的人民军队。听党指挥是灵魂，能打胜仗是核心，作风优良是保证。其余选项均非强军目标，故选A。","__sub":"习思想"},{"id":"zz-30912","module":"zhengzhi","prompt":"「政治建军」在强军兴军中的地位是：","options":["立军之本","权宜之计","次要手段","临时措施"],"answer":0,"explanation":"政治建军是立军之本，人民军队必须坚持党对军队的绝对领导，确保部队绝对忠诚、绝对纯洁、绝对可靠。其余选项均错误定位了政治建军的地位，故选A。","__sub":"习思想"},{"id":"zz-30913","module":"zhengzhi","prompt":"「一国两制」下，中央对特别行政区的全面管治权与高度自治权的关系是：","options":["全面管治权与高度自治权有机结合","高度自治权排斥全面管治权","全面管治权取消高度自治权","二者相互对立"],"answer":0,"explanation":"「一国两制」下，中央全面管治权与特别行政区高度自治权有机结合、统一衔接，特别行政区行使高度自治权以中央授权为前提。排斥、取消、对立均违背「一国两制」法理逻辑，故选A。","__sub":"习思想"},{"id":"zz-30914","module":"zhengzhi","prompt":"「爱国者治港」「爱国者治澳」的要求体现了：","options":["改变特别行政区制度","中央收紧自治权","取消选举制度","「一国两制」方针的内在要求"],"answer":3,"explanation":"必须坚持「爱国者治港」「爱国者治澳」，这是「一国两制」方针的内在要求，确保特别行政区管治权掌握在爱国者手中。收紧权力、改变制度、取消选举均属曲解，故选D。","__sub":"习思想"},{"id":"zz-30915","module":"zhengzhi","prompt":"「全球安全倡议」倡导的理念是：","options":["绝对安全观","共同、综合、合作、可持续的安全观","阵营对抗的安全观","零和博弈的安全观"],"answer":1,"explanation":"全球安全倡议倡导坚持共同、综合、合作、可持续的安全观，坚持尊重各国主权和领土完整等。零和博弈、阵营对抗、绝对安全均与倡议理念相悖，故选B。","__sub":"习思想"},{"id":"zz-30916","module":"zhengzhi","prompt":"「全球文明倡议」倡导的内容是：","options":["文明冲突论","尊重世界文明多样性，弘扬全人类共同价值，重视文明传承和创新，加强国际人文交流合作","文明优劣论","单一文明论"],"answer":1,"explanation":"全球文明倡议倡导尊重世界文明多样性，坚持文明平等、互鉴、对话、包容，弘扬和平、发展、公平、正义、民主、自由的全人类共同价值。文明优劣、冲突、单一论均与倡议相悖，故选B。","__sub":"习思想"},{"id":"zz-30917","module":"zhengzhi","prompt":"「全人类共同价值」的内容是：","options":["和平、发展、公平、正义、民主、自由","自由、平等、博爱","富强、民主、文明、和谐","爱国、敬业、诚信、友善"],"answer":0,"explanation":"习近平总书记提出弘扬和平、发展、公平、正义、民主、自由的全人类共同价值，凝聚了各国人民的价值共识。B是西方传统口号，C、D是社会主义核心价值观表述，故选A。","__sub":"习思想"},{"id":"zz-30918","module":"zhengzhi","prompt":"「中国式现代化」与「西方现代化」在实现方式上的区别是：","options":["中国式现代化依赖对外扩张","中国式现代化照搬西方模式","中国式现代化坚持独立自主、和平发展，不靠殖民掠夺","中国式现代化拒绝一切外来经验"],"answer":2,"explanation":"中国式现代化坚持独立自主、自力更生，走和平发展道路，与一些国家通过战争、殖民、掠夺实现现代化的老路形成鲜明对比。它吸收人类文明有益成果而非拒绝一切外来经验，故选C。","__sub":"习思想"},{"id":"zz-30919","module":"zhengzhi","prompt":"「第二个百年奋斗目标」的内容是：","options":["实现国内生产总值翻番","全面建成社会主义现代化强国","全面建成小康社会","建成中等收入国家"],"answer":1,"explanation":"「两个一百年」奋斗目标中，第二个百年目标是到本世纪中叶把我国建成富强民主文明和谐美丽的社会主义现代化强国。小康社会是第一个百年目标且已实现，故选B。","__sub":"习思想"},{"id":"zz-30921","module":"zhengzhi","prompt":"「全过程人民民主」中「全链条」的含义是：","options":["只涵盖协商环节","只涵盖选举环节","只涵盖监督环节","涵盖民主选举、民主协商、民主决策、民主管理、民主监督各环节"],"answer":3,"explanation":"「全链条」指民主贯穿选举、协商、决策、管理、监督各环节，形成完整的制度程序和参与实践。只涵盖某一环节都割裂了「全链条」的含义，故选D。","__sub":"习思想"},{"id":"zz-30922","module":"zhengzhi","prompt":"「基层治理」中「共建共治共享」的含义是：","options":["党委领导、政府负责、社会协同、公众参与、法治保障的社会治理体制","政府包办治理","群众自发无序治理","资本主导治理"],"answer":0,"explanation":"共建共治共享的社会治理制度要求完善党委领导、政府负责、民主协商、社会协同、公众参与、法治保障、科技支撑的社会治理体系。政府包办、无序治理、资本主导均偏离治理现代化方向，故选A。","__sub":"习思想"},{"id":"zz-30923","module":"zhengzhi","prompt":"「全过程人民民主」与「西式民主」的本质区别在于：","options":["程序是否复杂","形式是否热闹","人民是否真正当家作主，民主是否真实管用","口号是否响亮"],"answer":2,"explanation":"民主的评判标准是人民是否真正当家作主，民主是否真实、管用。全过程人民民主实现全链条全方位全覆盖，避免「选举时漫天许诺、选举后无人过问」。形式、程序、口号都不是本质区别所在，故选C。","__sub":"习思想"},{"id":"zz-30924","module":"zhengzhi","prompt":"「共同富裕」与「高质量发展」的关系是：","options":["高质量发展是共同富裕的前提和保障，共同富裕是高质量发展的目标导向","二者相互对立","共同富裕可以脱离高质量发展","高质量发展与共同富裕无关"],"answer":0,"explanation":"高质量发展为共同富裕奠定物质基础，共同富裕体现高质量发展的目标导向，二者辩证统一。对立、脱离、无关均割裂了二者的关系，故选A。","__sub":"习思想"},{"id":"zz-30925","module":"zhengzhi","prompt":"「生态文明」在「五位一体」总体布局中的地位是：","options":["独立于总体布局之外","从属于经济建设","可有可无","与经济建设、政治建设、文化建设、社会建设并列的重要组成"],"answer":3,"explanation":"生态文明建设是「五位一体」总体布局的重要组成部分，与经济建设、政治建设、文化建设、社会建设并列，把生态文明建设纳入中国特色社会主义事业总体布局。从属、可有可无、独立于布局之外均属错误定位，故选D。","__sub":"习思想"},{"id":"zz-30926","module":"zhengzhi","prompt":"「美丽中国」建设的目标是：","options":["实现资源开发最大化","实现城市化率最大化","实现工业产值最大化","实现人与自然和谐共生的现代化"],"answer":3,"explanation":"美丽中国建设的目标是实现人与自然和谐共生的现代化，形成节约资源和保护环境的空间格局、产业结构、生产方式。城市化、工业化、资源开发最大化均非其目标，故选D。","__sub":"习思想"},{"id":"zz-30927","module":"zhengzhi","prompt":"「教育强国」建设的根本任务是：","options":["科研经费","升学率","立德树人","校园规模"],"answer":2,"explanation":"教育的根本任务是立德树人，培养德智体美劳全面发展的社会主义建设者和接班人。升学率、经费、规模都不是根本任务，故选C。","__sub":"习思想"},{"id":"zz-30928","module":"zhengzhi","prompt":"「健康中国」战略把什么放在优先位置：","options":["医疗产业","药品利润","医院规模","人民健康"],"answer":3,"explanation":"健康中国战略把人民健康放在优先发展的战略位置，坚持预防为主，完善国民健康政策。医疗产业、医院规模、药品利润都不是战略优先方向，故选D。","__sub":"习思想"},{"id":"zz-30929","module":"zhengzhi","prompt":"「就业」在民生中的定位是：","options":["个人私事","次要民生","最大的民生","临时问题"],"answer":2,"explanation":"就业是最大的民生，是社会稳定的重要保障，实施就业优先战略，促进高质量充分就业。其余选项均错误定位了就业的重要性，故选C。","__sub":"习思想"},{"id":"zz-30930","module":"zhengzhi","prompt":"「房子是用来住的、不是用来炒的」定位表明：","options":["房地产与经济无关","取消房地产市场","房价只跌不涨","坚持房子居住属性，抑制房地产投机"],"answer":3,"explanation":"「房住不炒」定位强调坚持房子的居住属性，因城施策促进房地产市场平稳健康发展，遏制投机炒作。取消市场、只跌不涨、与经济无关均属曲解，故选D。","__sub":"习思想"},{"id":"zz-30931","module":"zhengzhi","prompt":"「老龄化」应对的国家战略是：","options":["放任老龄化","限制老龄化","积极应对人口老龄化，发展养老事业和养老产业","只靠家庭养老"],"answer":2,"explanation":"实施积极应对人口老龄化国家战略，发展养老事业和养老产业，优化孤寡老人服务，推动实现全体老年人享有基本养老服务。限制、放任、单一家庭养老均非国家战略，故选C。","__sub":"习思想"},{"id":"zz-30932","module":"zhengzhi","prompt":"「双减」政策针对的问题是：","options":["义务教育阶段学生作业负担和校外培训负担过重","高等教育质量不高","职业教育发展不足","学前教育供给不足"],"answer":0,"explanation":"「双减」政策针对义务教育阶段学生作业负担和校外培训负担过重的问题，促进学生全面发展和健康成长。高等教育、职业教育、学前教育均非「双减」直接对象，故选A。","__sub":"习思想"},{"id":"zz-30933","module":"zhengzhi","prompt":"「全过程人民民主」的「全方位」是指：","options":["只限国家层面","贯通国家政治生活和社会生活各层面各维度","只限基层层面","只限经济领域"],"answer":1,"explanation":"「全方位」指民主贯通国家政治生活和社会生活各层面各维度，从国家治理到基层治理都有民主参与。只限某一层面或领域都割裂了「全方位」的含义，故选B。","__sub":"习思想"},{"id":"zz-30934","module":"zhengzhi","prompt":"「中国式现代化」的领导力量和依靠力量分别是：","options":["多党竞争和资本主导","中国共产党领导和人民主体地位","精英治理和外资驱动","宗教团体和民间组织"],"answer":1,"explanation":"中国式现代化坚持中国共产党领导这一根本保证，坚持人民主体地位这一根本力量，二者缺一不可。多党竞争、资本主导、精英治理、宗教团体均不符合中国实际，故选B。","__sub":"习思想"},{"id":"zz-30935","module":"zhengzhi","prompt":"「新发展格局」中的「循环」是指：","options":["贸易单向流动","资金空转","物流单一环节","生产、分配、流通、消费各环节畅通的经济循环"],"answer":3,"explanation":"新发展格局中的经济循环指社会再生产的生产、分配、流通、消费各环节畅通无阻，供给和需求形成更高水平动态平衡。资金空转、单一环节、单向流动均非「循环」本意，故选D。","__sub":"习思想"},{"id":"zz-30936","module":"zhengzhi","prompt":"「扩大内需」与「深化供给侧结构性改革」的关系是：","options":["二者相互排斥","只抓需求侧","只抓供给侧","有机结合，供需两侧协同发力"],"answer":3,"explanation":"坚持扩大内需这个战略基点和深化供给侧结构性改革有机结合，供需两侧协同发力，实现需求牵引供给、供给创造需求的更高水平动态平衡。只抓一侧或相互排斥均属片面认识，故选D。","__sub":"习思想"},{"id":"zz-30937","module":"zhengzhi","prompt":"「制造业」在国家发展全局中的定位是：","options":["可选产业","过渡产业","立国之本、强国之基","淘汰产业"],"answer":2,"explanation":"制造业是立国之本、强国之基，要坚定不移建设制造强国，推进新型工业化。可选、过渡、淘汰等定位均不符合制造业的战略地位，故选C。","__sub":"习思想"},{"id":"zz-30938","module":"zhengzhi","prompt":"「粮食安全」与「耕地保护」的关系是：","options":["耕地可以随意占用","粮食安全靠进口解决","耕地是粮食生产的命根子，必须严守18亿亩耕地红线","耕地保护与粮食安全无关"],"answer":2,"explanation":"耕地是粮食生产的命根子，必须严守18亿亩耕地红线，落实最严格的耕地保护制度，确保谷物基本自给、口粮绝对安全。随意占地、依赖进口、忽视保护均威胁粮食安全，故选C。","__sub":"习思想"},{"id":"zz-30939","module":"zhengzhi","prompt":"「碳达峰」与「碳中和」的关系是：","options":["碳中和可以脱离碳达峰","二者相互独立","碳达峰是碳中和的前提和基础，碳中和是碳达峰后的目标方向","碳达峰就是碳中和"],"answer":2,"explanation":"实现碳中和必须先实现碳达峰，碳达峰是碳中和的前提和基础；碳中和是碳达峰后的更高目标，二者是递进关系而非等同或独立关系。故选C。","__sub":"习思想"},{"id":"zz-30940","module":"zhengzhi","prompt":"「生态保护红线」的含义是：","options":["可适度开发的区域","在生态空间范围内具有特殊重要生态功能、必须强制性严格保护的区域","可开发建设的区域","可自由使用的区域"],"answer":1,"explanation":"生态保护红线是具有特殊重要生态功能、必须强制性严格保护的区域，是维护生态安全的最后屏障。可开发、可适度开发、可自由使用均违背红线管控要求，故选B。","__sub":"习思想"},{"id":"zz-30941","module":"zhengzhi","prompt":"「长江十年禁渔」体现的治理理念是：","options":["用最严格制度最严密法治保护生态环境","放松生态管控","先污染后治理","开发优先"],"answer":0,"explanation":"长江十年禁渔是用最严格制度、最严密法治保护生态环境的标志性举措，体现了对母亲河的系统性保护。放松管控、先污染后治理、开发优先均与禁渔政策理念相悖，故选A。","__sub":"习思想"},{"id":"zz-30942","module":"zhengzhi","prompt":"「国家安全体系」中的「以人民安全为宗旨」是指：","options":["人民安全从属于其他安全","国家安全与人民无关","国家安全一切为了人民、一切依靠人民","人民安全可以牺牲"],"answer":2,"explanation":"以人民安全为宗旨，指国家安全工作一切为了人民、一切依靠人民，维护人民安全是国家安全工作的出发点和落脚点。与人民无关、从属他项、可以牺牲均违背人民安全宗旨，故选C。","__sub":"习思想"},{"id":"zz-30943","module":"zhengzhi","prompt":"「国防和军队现代化」的「三步走」目标是：","options":["先建一流后补现代化","一步到位建成一流军队","确保2027年实现建军一百年奋斗目标，2035年基本实现国防和军队现代化，本世纪中叶全面建成世界一流军队","只建现代化不建一流"],"answer":2,"explanation":"国防和军队现代化按「三步走」推进：确保2027年实现建军一百年奋斗目标，2035年基本实现国防和军队现代化，本世纪中叶全面建成世界一流军队。一步到位、只建一头、先后颠倒均不符合战略安排，故选C。","__sub":"习思想"},{"id":"zz-30944","module":"zhengzhi","prompt":"「一国两制」在实践中取得的成功之一是：","options":["澳门取消原有制度","香港放弃高度自治","香港实现由乱到治、由治及兴","两地制度完全同化"],"answer":2,"explanation":"香港国安法实施和完善选举制度后，香港实现由乱到治、由治及兴的重大转折，「一国两制」实践更加稳健。放弃自治、取消制度、完全同化均违背「一国两制」方针，故选C。","__sub":"习思想"},{"id":"zz-30945","module":"zhengzhi","prompt":"「新时代」的内涵之一是：","options":["我国退出国际舞台的时代","我国依附他国的时代","我国封闭发展的时代","我国日益走近世界舞台中央，不断为人类作出更大贡献的时代"],"answer":3,"explanation":"新时代是承前启后、继往开来，在新的历史条件下继续夺取中国特色社会主义伟大胜利的时代，也是我国日益走近世界舞台中央、不断为人类作出更大贡献的时代。退出舞台、封闭发展、依附他国均与新时代内涵相悖，故选D。","__sub":"习思想"},{"id":"zz-30946","module":"zhengzhi","prompt":"「四个伟大」中起决定性作用的是：","options":["伟大工程（党的建设）","伟大斗争","伟大事业","伟大梦想"],"answer":0,"explanation":"「四个伟大」中，伟大斗争、伟大工程、伟大事业、伟大梦想相互贯通，其中起决定性作用的是党的建设新的伟大工程。故选A。","__sub":"习思想"},{"id":"zz-30947","module":"zhengzhi","prompt":"「中国共产党领导的多党合作和政治协商制度」的基本方针是：","options":["长期共存、互相监督、肝胆相照、荣辱与共","轮流执政、联合组阁","一党专政、取消协商","多党竞争、议会博弈"],"answer":0,"explanation":"我国多党合作制度的基本方针是长期共存、互相监督、肝胆相照、荣辱与共，各民主党派是参政党不是反对党。轮流执政、一党专政、议会博弈均不符合我国政党制度，故选A。","__sub":"习思想"},{"id":"zz-30948","module":"zhengzhi","prompt":"「民族区域自治制度」的前提是：","options":["区域独立","民族独立","国家统一领导","自治体主权"],"answer":2,"explanation":"民族区域自治制度是在国家统一领导下，各少数民族聚居的地方实行区域自治，设立自治机关，行使自治权。国家统一领导是前提，民族独立、区域独立、自治体主权均违背制度设计，故选C。","__sub":"习思想"},{"id":"zz-30949","module":"zhengzhi","prompt":"「基层群众自治制度」的主要内容是：","options":["村民委员会、居民委员会等群众自治组织依法实行自我管理、自我服务","政府直接管理基层事务","企业自主经营","社会组织独立立法"],"answer":0,"explanation":"基层群众自治制度以村民委员会、居民委员会等为主要形式，实行自我管理、自我教育、自我服务、自我监督。政府直接管理、企业自主经营、社会组织立法均不属于该制度内容，故选A。","__sub":"习思想"},{"id":"zz-30950","module":"zhengzhi","prompt":"「全过程人民民主」的制度保障是：","options":["取消制度约束","依靠个人自觉","坚持和完善人民代表大会制度等一系列制度安排","依赖国际监督"],"answer":2,"explanation":"全过程人民民主靠坚持和完善人民代表大会制度、中国共产党领导的多党合作和政治协商制度、民族区域自治制度、基层群众自治制度等制度程序保障实现。取消制度、个人自觉、国际监督均非制度保障，故选C。","__sub":"习思想"},{"id":"zz-30952","module":"zhengzhi","prompt":"「国家治理体系和治理能力」的关系是：","options":["二者相互独立","治理能力可以脱离治理体系","治理体系是制度载体，治理能力是制度执行，二者相辅相成","治理体系可以脱离治理能力"],"answer":2,"explanation":"国家治理体系是制度管理国家的体系，治理能力是运用制度管理国家的能力，二者相辅相成，好的体系需要好的能力来执行。相互独立、相互脱离均割裂了二者的统一关系，故选C。","__sub":"习思想"},{"id":"zz-30953","module":"zhengzhi","prompt":"「中国式现代化」对世界现代化的贡献之一是：","options":["输出中国模式","为广大发展中国家独立自主迈向现代化提供了全新选择","建立中国主导的秩序","取代西方现代化"],"answer":1,"explanation":"中国式现代化拓展了发展中国家走向现代化的途径，给世界上那些既希望加快发展又希望保持自身独立性的国家和民族提供了全新选择。输出模式、建立秩序、取代西方均与我国外交理念相悖，故选B。","__sub":"习思想"},{"id":"zz-30954","module":"zhengzhi","prompt":"「新发展理念」中「开放」发展注重解决的问题是：","options":["发展不平衡问题","发展动力问题","发展内外联动问题","社会公平正义问题"],"answer":2,"explanation":"开放发展注重解决发展内外联动问题，坚持对外开放基本国策，形成更大范围、更宽领域、更深层次对外开放格局。动力、不平衡、公平正义分别对应创新、协调、共享，故选C。","__sub":"习思想"},{"id":"zz-30955","module":"zhengzhi","prompt":"「人类文明新形态」的创造主体是：","options":["西方发达国家","中国共产党领导的人民","国际组织","跨国公司"],"answer":1,"explanation":"人类文明新形态是中国共产党领导中国人民在中国式现代化进程中创造的，体现了社会主义文明的新发展。西方、国际组织、跨国公司均非创造主体，故选B。","__sub":"习思想"},{"id":"zz-30956","module":"zhengzhi","prompt":"「中国式现代化」九条本质要求中，物质层面的要求是：","options":["实现高质量发展","发展全过程人民民主","丰富人民精神世界","促进人与自然和谐共生"],"answer":0,"explanation":"中国式现代化本质要求包括坚持中国共产党领导、坚持中国特色社会主义、实现高质量发展、发展全过程人民民主、丰富人民精神世界、实现全体人民共同富裕、促进人与自然和谐共生、推动构建人类命运共同体、创造人类文明新形态。其中实现高质量发展是物质层面的要求，故选A。","__sub":"习思想"},{"id":"zz-30957","module":"zhengzhi","prompt":"「全过程人民民主」与「党的领导」的关系是：","options":["二者相互对立","党的领导削弱民主","民主排斥党的领导","党的领导是全过程人民民主的根本保证"],"answer":3,"explanation":"党的领导是发展全过程人民民主的根本保证，确保民主发展的正确方向；发展全过程人民民主是党的领导的重要体现。削弱、排斥、对立均割裂了二者的统一关系，故选D。","__sub":"习思想"},{"id":"zz-30958","module":"zhengzhi","prompt":"「国家安全」与「经济发展」的关系是：","options":["二者互不相干","安全阻碍发展","安全是发展的前提，发展是安全的保障","发展可以牺牲安全"],"answer":2,"explanation":"安全是发展的前提，发展是安全的保障，二者如车之两轮、鸟之两翼，必须统筹兼顾。安全阻碍发展、牺牲安全、互不相干均割裂了二者的辩证关系，故选C。","__sub":"习思想"},{"id":"zz-30959","module":"zhengzhi","prompt":"「自我革命」与「社会革命」的关系是：","options":["二者相互独立","以党的自我革命引领社会革命","社会革命可以脱离自我革命","自我革命与社会革命无关"],"answer":1,"explanation":"党的自我革命是引领社会革命的强大动力，以党的自我革命引领社会革命，确保党始终成为坚强领导核心。相互独立、脱离、无关均割裂了二者的关系，故选B。","__sub":"习思想"},{"id":"zz-30960","module":"zhengzhi","prompt":"「全面从严治党」与「党的自我革命」的关系是：","options":["二者相互独立","自我革命可以脱离全面从严治党","全面从严治党是党的自我革命的伟大实践","全面从严治党与自我革命无关"],"answer":2,"explanation":"全面从严治党是党的自我革命的伟大实践，通过自我净化、自我完善、自我革新、自我提高，确保党不变质、不变色、不变味。相互独立、脱离、无关均割裂了二者的关系，故选C。","__sub":"习思想"},{"id":"zz-30961","module":"zhengzhi","prompt":"「四个自我」的内容是：","options":["自我净化、自我完善、自我革新、自我提高","自我批评、自我检讨、自我反省、自我改进","自我管理、自我服务、自我教育、自我监督","自我发展、自我创新、自我突破、自我超越"],"answer":0,"explanation":"「四个自我」即自我净化、自我完善、自我革新、自我提高，是党的自我革命的基本内涵。其余选项均属拼凑，故选A。","__sub":"习思想"},{"id":"zz-30962","module":"zhengzhi","prompt":"「政治过硬、本领高强」对干部的要求是：","options":["政治与能力取其一","只要政治好不要能力","只要能力强不要政治","既要政治素质过硬，又要能力本领高强"],"answer":3,"explanation":"新时代干部必须政治过硬、本领高强，二者相辅相成，缺一不可。只要政治不要能力或只要能力不要政治都是片面的，故选D。","__sub":"习思想"},{"id":"zz-30963","module":"zhengzhi","prompt":"「斗争精神」的要求是：","options":["无原则争斗","回避矛盾","坚持原则、敢于亮剑，依靠顽强斗争打开事业发展新天地","妥协退让"],"answer":2,"explanation":"发扬斗争精神要求坚持原则、敢于亮剑，在重大风险挑战面前敢于斗争、善于斗争，依靠顽强斗争打开事业发展新天地。无原则争斗、回避矛盾、妥协退让均与斗争精神相悖，故选C。","__sub":"习思想"},{"id":"zz-30964","module":"zhengzhi","prompt":"「底线思维」的含义是：","options":["凡事从最坏处准备，努力争取最好的结果","只看最好情况","盲目乐观","消极悲观"],"answer":0,"explanation":"底线思维要求凡事从最坏处准备、做最充分准备，努力争取最好的结果，牢牢掌握主动权。只看最好、盲目乐观、消极悲观均违背底线思维，故选A。","__sub":"习思想"},{"id":"zz-30965","module":"zhengzhi","prompt":"「系统观念」的方法论要求是：","options":["顾此失彼","单兵突进","统筹兼顾、综合平衡，整体推进各项工作","碎片化治理"],"answer":2,"explanation":"系统观念要求统筹兼顾、综合平衡，加强前瞻性思考、全局性谋划、战略性布局、整体性推进。单兵突进、顾此失彼、碎片化治理均违背系统观念，故选C。","__sub":"习思想"},{"id":"zz-30966","module":"zhengzhi","prompt":"「问题导向」的要求是：","options":["回避问题","拖延问题","掩盖问题","聚焦突出问题，奔着问题去、对着问题改"],"answer":3,"explanation":"坚持问题导向要求聚焦实践遇到的新问题、改革发展稳定存在的深层次问题、人民群众急难愁盼问题等，奔着问题去、对着问题改。回避、掩盖、拖延均与问题导向相悖，故选D。","__sub":"习思想"},{"id":"zz-30967","module":"zhengzhi","prompt":"「胸怀天下」体现的是：","options":["输出意识形态","只顾本国利益","干涉他国内政","中国共产党为人类谋进步、为世界谋大同的天下情怀"],"answer":3,"explanation":"坚持胸怀天下体现中国共产党为人类谋进步、为世界谋大同的天下情怀，推动构建人类命运共同体。只顾本国、干涉内政、输出意识形态均与胸怀天下相悖，故选D。","__sub":"习思想"},{"id":"zz-30968","module":"zhengzhi","prompt":"「守正创新」中「守正」与「创新」的关系是：","options":["创新否定守正","守正是创新的前提和基础，创新是守正的路径和动力","守正排斥创新","二者相互独立"],"answer":1,"explanation":"守正才能不迷失方向、不犯颠覆性错误，创新才能把握时代、引领时代；守正是创新的前提和基础，创新是守正的路径和动力。排斥、否定、独立均割裂了二者的辩证关系，故选B。","__sub":"习思想"},{"id":"zz-30969","module":"zhengzhi","prompt":"「自信自立」的要求是：","options":["照搬外国模式","依附他国发展","坚持对马克思主义的坚定信仰、对中国特色社会主义的坚定信念，走自己的路","放弃独立自主"],"answer":2,"explanation":"坚持自信自立要求坚定信仰信念，坚持把国家和民族发展放在自己力量的基点上，坚持走自己的路。照搬外国、依附他国、放弃自主均与自信自立相悖，故选C。","__sub":"习思想"},{"id":"zz-30970","module":"zhengzhi","prompt":"「人民至上」的要求是：","options":["只依靠精英","只顾少数人利益","只服务资本","一切为了人民、一切依靠人民，把人民利益放在首位"],"answer":3,"explanation":"坚持人民至上要求一切为了人民、一切依靠人民，把人民利益放在首位，尊重人民首创精神，汇聚人民智慧。依靠精英、服务资本、只顾少数均违背人民至上，故选D。","__sub":"习思想"},{"id":"zz-30971","module":"zhengzhi","prompt":"「中国式现代化」的推进方式是：","options":["反复折腾","一步到位","大起大落","坚持稳中求进、循序渐进、持续推进"],"answer":3,"explanation":"中国式现代化坚持稳中求进工作总基调，分阶段、有步骤地持续推进，不搞一步到位、大起大落和反复折腾。故选D。","__sub":"习思想"},{"id":"zz-30972","module":"zhengzhi","prompt":"「高质量发展」与「全面建设社会主义现代化国家」的关系是：","options":["高质量发展与现代化建设无关","高质量发展是全面建设社会主义现代化国家的首要任务","现代化建设可以脱离高质量发展","高质量发展只是经济任务"],"answer":1,"explanation":"党的二十大报告明确，高质量发展是全面建设社会主义现代化国家的首要任务，贯穿经济、社会、文化、生态等各领域。无关、脱离、仅经济任务均属错误理解，故选B。","__sub":"习思想"},{"id":"zz-30973","module":"zhengzhi","prompt":"「科技自立自强」与「开放合作」的关系是：","options":["自立自强等于闭关锁国","二者相互对立","开放合作放弃自主","自立自强不是闭门造车，要在开放合作中提升自主创新能力"],"answer":3,"explanation":"科技自立自强强调把创新主动权掌握在自己手中，同时坚持开放创新，在开放合作中提升自主创新能力。闭门造车、放弃自主、相互对立均割裂了二者的关系，故选D。","__sub":"习思想"},{"id":"zz-30974","module":"zhengzhi","prompt":"「全过程人民民主」中「最管用」的含义是：","options":["民主程序最复杂","民主形式最花哨","民主口号最响亮","民主能切实解决人民需要解决的问题"],"answer":3,"explanation":"「最管用」指民主不是装饰品，而是要用来解决人民需要解决的问题，切实转化为治理效能。形式花哨、程序复杂、口号响亮都不是「管用」的体现，故选D。","__sub":"习思想"},{"id":"zz-30975","module":"zhengzhi","prompt":"「一国两制」的制度安排中，特别行政区的高度自治权来源于：","options":["特别行政区自定","中央授权","国际条约","历史惯例"],"answer":1,"explanation":"特别行政区的高度自治权来源于中央授权，不存在「剩余权力」问题，中央对高度自治权的行使具有监督权。自定、国际条约、历史惯例均非权力来源，故选B。","__sub":"习思想"},{"id":"zz-30976","module":"zhengzhi","prompt":"「祖国完全统一」的必然性依据是：","options":["国际组织裁决","外部势力授权","中华民族的历史传统和全体中华儿女的共同愿望","单方面宣布"],"answer":2,"explanation":"解决台湾问题、实现祖国完全统一，是中华民族的历史传统和全体中华儿女的共同愿望，是中华民族伟大复兴的必然要求。外部授权、国际裁决、单方面宣布均非依据，故选C。","__sub":"习思想"},{"id":"zz-30977","module":"zhengzhi","prompt":"「人类命运共同体」的构建路径之一是：","options":["坚持共商共建共享的全球治理观","建立霸权秩序","输出单一模式","划分势力范围"],"answer":0,"explanation":"构建人类命运共同体要坚持共商共建共享的全球治理观，推动国际关系民主化，维护以联合国为核心的国际体系。霸权秩序、单一模式、势力范围均与构建路径相悖，故选A。","__sub":"习思想"},{"id":"zz-30978","module":"zhengzhi","prompt":"「独立自主的和平外交政策」的核心是：","options":["输出模式","依附大国","结盟对抗","坚持从我国人民和世界人民根本利益出发，根据是非曲直决定立场"],"answer":3,"explanation":"独立自主的和平外交政策的核心是从我国人民和世界人民根本利益出发，根据事情本身的是非曲直决定立场和政策。依附、结盟、输出均违背独立自主原则，故选D。","__sub":"习思想"},{"id":"zz-30979","module":"zhengzhi","prompt":"「全过程人民民主」的实践形式之一是：","options":["精英代议","封闭决策","网络投票定案","人大代表联络站、基层立法联系点等"],"answer":3,"explanation":"人大代表联络站、基层立法联系点等是全过程人民民主的重要实践形式，畅通民意表达渠道。封闭决策、精英代议、网络投票定案均非规范实践形式，故选D。","__sub":"习思想"},{"id":"zz-30980","module":"zhengzhi","prompt":"「共同富裕」的时间安排是：","options":["一次性实现","分阶段促进共同富裕，允许一部分人先富起来，先富带后富","平均富裕","同步富裕"],"answer":1,"explanation":"共同富裕是长期历史过程，要分阶段推进，允许一部分人先富起来，先富带后富、帮后富。同步、平均、一次性实现均违背共同富裕的规律性认识，故选B。","__sub":"习思想"},{"id":"zz-30981","module":"zhengzhi","prompt":"「乡村振兴」与「新型城镇化」的关系是：","options":["此消彼长","双轮驱动、协调发展","相互对立","互不相关"],"answer":1,"explanation":"乡村振兴与新型城镇化要双轮驱动、协调发展，城乡融合发展，让城乡在规划布局、要素配置、产业发展等方面相互融合。对立、消长、无关均割裂了二者的关系，故选B。","__sub":"习思想"},{"id":"zz-30982","module":"zhengzhi","prompt":"「国家安全」中「以军事、科技、文化、社会安全为保障」的含义是：","options":["这些领域安全可以放弃","这些领域安全从属于经济安全","这些领域安全为国家安全提供重要支撑和保障条件","这些领域安全与国家安全无关"],"answer":2,"explanation":"总体国家安全观以军事、科技、文化、社会安全为保障，这些领域安全为国家安全提供重要支撑和保障条件。放弃、从属、无关均错误理解了「保障」的含义，故选C。","__sub":"习思想"},{"id":"zz-30983","module":"zhengzhi","prompt":"「网络强国」建设的要求是：","options":["网络空间安全和发展同步推进，网上网下同心聚力","只重发展不重安全","只重安全不重发展","网络空间法外之地"],"answer":0,"explanation":"网络强国建设要求安全和发展同步推进，没有网络安全就没有国家安全，没有信息化就没有现代化。只重一面、法外之地均割裂了网络空间治理的辩证关系，故选A。","__sub":"习思想"},{"id":"zz-30984","module":"zhengzhi","prompt":"「全过程人民民主」中「最真实」的含义是：","options":["民主只属于少数人","民主只停留在口头","民主只做表面文章","民主不是形式主义的，而是有制度程序保障的真实实践"],"answer":3,"explanation":"「最真实」指民主有完整的制度程序和参与实践作保障，不是形式主义、口头承诺或表面文章。口头化、表面化、少数人化均与「最真实」相悖，故选D。","__sub":"习思想"},{"id":"zz-30985","module":"zhengzhi","prompt":"「中国式现代化」与「中华民族伟大复兴」的关系是：","options":["现代化与复兴无关","中国式现代化是全面推进中华民族伟大复兴的路径","复兴可以脱离现代化","二者相互独立"],"answer":1,"explanation":"党的二十大报告明确，以中国式现代化全面推进中华民族伟大复兴，中国式现代化是实现复兴的正确路径。独立、脱离、无关均割裂了二者的关系，故选B。","__sub":"习思想"},{"id":"zz-30986","module":"zhengzhi","prompt":"「新发展理念」的整体性要求是：","options":["五大理念相互贯通、相互促进，是具有内在联系的集合体","各理念孤立运用","只抓一个理念","随意取舍理念"],"answer":0,"explanation":"新发展理念是一个系统的理论体系，五大理念相互贯通、相互促进，必须完整、准确、全面贯彻，不能孤立运用或随意取舍。孤立、只抓一个、随意取舍均违背整体性要求，故选A。","__sub":"习思想"},{"id":"zz-30987","module":"zhengzhi","prompt":"「高质量发展」的评价标准之一是：","options":["只看出口数量","只看GDP增速","只看投资规模","是否体现新发展理念、是否满足人民美好生活需要"],"answer":3,"explanation":"高质量发展以是否体现新发展理念、是否满足人民日益增长的美好生活需要为重要评价标准，不是单一GDP、投资或出口指标可以衡量的。故选D。","__sub":"习思想"},{"id":"zz-30988","module":"zhengzhi","prompt":"「新质生产力」与传统生产力的区别在于：","options":["新质生产力以科技创新为主导，摆脱传统增长方式","新质生产力投入更大","新质生产力规模更大","新质生产力速度更快"],"answer":0,"explanation":"新质生产力以科技创新为主导，摆脱传统经济增长方式和生产力发展路径，具有高科技、高效能、高质量特征。投入、规模、速度的单纯增大不是其区别所在，故选A。","__sub":"习思想"},{"id":"zz-30989","module":"zhengzhi","prompt":"「全过程人民民主」中「最广泛」的含义是：","options":["只限城市人口","只限特定党派","只限精英群体","参与主体涵盖全体人民，不分地域、职业、民族"],"answer":3,"explanation":"「最广泛」指民主参与主体涵盖全体人民，不分地域、职业、民族，人人都有参与民主实践的机会。只限城市、精英、特定党派均与「最广泛」相悖，故选D。","__sub":"习思想"},{"id":"zz-30990","module":"zhengzhi","prompt":"「中国式现代化」的文化底蕴是：","options":["宗教文化的复兴","外来文化的移植","流行文化的堆砌","中华优秀传统文化的深厚底蕴"],"answer":3,"explanation":"中国式现代化赋予中华文明以现代力量，中华文明赋予中国式现代化以深厚底蕴，二者相互成就。移植外来文化、复兴宗教文化、堆砌流行文化均非其文化底蕴，故选D。","__sub":"习思想"},{"id":"zz-30991","module":"zhengzhi","prompt":"「全面从严治党」永远在路上表明：","options":["阶段工作","一时之举","临时任务","全面从严治党是长期战略，必须常抓不懈"],"answer":3,"explanation":"全面从严治党永远在路上，党的自我革命永远在路上，表明这是长期战略而非一时之举、临时任务或阶段工作，必须常抓不懈、久久为功。故选D。","__sub":"习思想"},{"id":"zz-30992","module":"zhengzhi","prompt":"「党的领导」与「依法治国」的关系是：","options":["法治排斥党的领导","党的领导取代法治","党的领导是依法治国的根本保证，依法治国是党领导治国理政的基本方式","二者相互对立"],"answer":2,"explanation":"党的领导是依法治国的根本保证，依法治国是党领导人民治理国家的基本方式，二者有机统一。取代、排斥、对立均割裂了二者的关系，故选C。","__sub":"习思想"},{"id":"zz-30993","module":"zhengzhi","prompt":"「全过程人民民主」中「民主协商」的领域是：","options":["只限文化领域","只限政治领域","只限经济领域","涵盖政治、经济、文化、社会等各领域"],"answer":3,"explanation":"协商民主涵盖政治、经济、文化、社会等各领域，有事好商量、众人的事情由众人商量，找到全社会意愿和要求的最大公约数。只限某一领域均割裂了协商民主的广泛性，故选D。","__sub":"习思想"},{"id":"zz-30994","module":"zhengzhi","prompt":"「中国式现代化」的推进主体是：","options":["国际组织","中国共产党领导下的全体人民","外资企业","少数精英"],"answer":1,"explanation":"中国式现代化是中国共产党领导人民推进的伟大事业，人民是现代化建设的主体力量和最终受益者。少数精英、外资企业、国际组织均非推进主体，故选B。","__sub":"习思想"},{"id":"zz-30995","module":"zhengzhi","prompt":"「新发展理念」中「协调」发展的内涵之一是：","options":["只抓经济","城乡协调、区域协调、物质文明和精神文明协调","只抓城市","只抓物质"],"answer":1,"explanation":"协调发展包括城乡协调、区域协调、经济与社会协调、物质文明与精神文明协调等，增强发展的整体性协调性。只抓城市、经济、物质均违背协调发展内涵，故选B。","__sub":"习思想"},{"id":"zz-30996","module":"zhengzhi","prompt":"「人类命运共同体」与「中国式现代化」的关系是：","options":["现代化排斥国际合作","二者相互独立","共同体建设阻碍现代化","中国式现代化走和平发展道路，为构建人类命运共同体提供实践支撑"],"answer":3,"explanation":"中国式现代化坚持走和平发展道路，在自身发展的同时为世界提供发展机遇，为构建人类命运共同体提供实践支撑。独立、排斥、阻碍均割裂了二者的关系，故选D。","__sub":"习思想"},{"id":"zz-30997","module":"zhengzhi","prompt":"「国家安全」中「以促进国际安全为依托」的含义是：","options":["在维护本国安全的同时，推动构建普遍安全的世界","只顾本国安全","干涉他国安全","输出安全模式"],"answer":0,"explanation":"总体国家安全观以促进国际安全为依托，坚持共同安全，在维护本国安全的同时推动构建普遍安全的人类命运共同体。只顾本国、干涉他国、输出模式均与「依托」的含义相悖，故选A。","__sub":"习思想"},{"id":"zz-30998","module":"zhengzhi","prompt":"「中国式现代化」的「并联式」发展特征是指：","options":["重复建设","单一环节推进","工业化、信息化、城镇化、农业现代化叠加推进","循环倒退"],"answer":2,"explanation":"我国现代化是并联式发展，工业化、信息化、城镇化、农业现代化叠加推进，不同于西方的串联式、顺序发展。单一环节、重复建设、循环倒退均非并联式特征，故选C。","__sub":"习思想"},{"id":"zz-30999","module":"zhengzhi","prompt":"「全过程人民民主」的制度程序与参与实践的关系是：","options":["二者相互脱离","完整的制度程序和完整的参与实践相统一","只有实践没有制度","只有制度没有实践"],"answer":1,"explanation":"全过程人民民主实现了完整的制度程序和完整的参与实践相统一，既有制度保障又有实践载体，二者缺一不可。只有制度、只有实践、相互脱离均割裂了二者的统一关系，故选B。","__sub":"习思想"},{"id":"zz-31000","module":"zhengzhi","prompt":"「中国式现代化」的推进节奏是：","options":["朝令夕改","频繁更换蓝图","坚持一张蓝图绘到底，一茬接着一茬干","半途而废"],"answer":2,"explanation":"中国式现代化坚持一张蓝图绘到底，一茬接着一茬干，保持战略定力和历史耐心。频繁更换、朝令夕改、半途而废均与推进节奏相悖，故选C。","__sub":"习思想"},{"id":"zz-31001","module":"zhengzhi","prompt":"「新发展理念」中「共享」发展的内涵之一是：","options":["一步到位共享","全民共享、全面共享、共建共享、渐进共享","部分领域共享","少数人共享"],"answer":1,"explanation":"共享发展内涵包括全民共享（人人享有）、全面共享（各方面成果）、共建共享（共同建设）、渐进共享（分阶段推进）。少数人、部分领域、一步到位均违背共享发展内涵，故选B。","__sub":"习思想"},{"id":"zz-31002","module":"zhengzhi","prompt":"「中国式现代化」与「全体人民共同富裕」的关系是：","options":["二者互不相关","现代化可以脱离共同富裕","共同富裕阻碍现代化","共同富裕是中国式现代化的重要特征和本质要求"],"answer":3,"explanation":"中国式现代化是全体人民共同富裕的现代化，共同富裕是其重要特征和本质要求。脱离、阻碍、无关均割裂了二者的关系，故选D。","__sub":"习思想"},{"id":"zz-31003","module":"zhengzhi","prompt":"「国家安全」中「以经济安全为基础」的含义是：","options":["经济安全为国家安全提供物质基础和保障","经济安全可以放弃","经济安全从属于军事安全","经济安全与国家安全无关"],"answer":0,"explanation":"总体国家安全观以经济安全为基础，经济是国家的命脉，经济安全为国家安全提供物质基础和保障。放弃、从属、无关均错误理解了「基础」的含义，故选A。","__sub":"习思想"},{"id":"zz-31004","module":"zhengzhi","prompt":"「党的自我革命」的目的是：","options":["改变党的性质","削弱党的领导","放弃党的宗旨","确保党永远不变质、不变色、不变味"],"answer":3,"explanation":"党的自我革命的目的是确保党永远不变质、不变色、不变味，始终保持党的先进性和纯洁性。削弱领导、改变性质、放弃宗旨均与自我革命目的相悖，故选D。","__sub":"习思想"},{"id":"zz-31005","module":"zhengzhi","prompt":"「中国式现代化」的文明观是：","options":["文明替代论","文明优越论","文明冲突论","文明交流互鉴，倡导不同文明包容共存"],"answer":3,"explanation":"中国式现代化倡导文明交流互鉴，不同文明包容共存、互学互鉴，反对文明优越、冲突、替代论。故选D。","__sub":"习思想"},{"id":"zz-31006","module":"zhengzhi","prompt":"「全过程人民民主」中「民主决策」的要求是：","options":["随意决策","少数人拍板","封闭决策","重大决策广泛听取意见，科学民主依法决策"],"answer":3,"explanation":"民主决策要求重大决策广泛听取人民群众和社会各界意见，坚持科学决策、民主决策、依法决策。少数人拍板、封闭决策、随意决策均违背民主决策要求，故选D。","__sub":"习思想"},{"id":"zz-31007","module":"zhengzhi","prompt":"「中国式现代化」的生态观是：","options":["污染换发展","人与自然和谐共生，绿色发展","透支资源","征服自然"],"answer":1,"explanation":"中国式现代化坚持人与自然和谐共生的生态观，走生产发展、生活富裕、生态良好的文明发展道路。征服自然、透支资源、污染换发展均与生态观相悖，故选B。","__sub":"习思想"},{"id":"zz-31008","module":"zhengzhi","prompt":"「国家安全」中「以军事、科技、文化、社会安全为保障」与「以政治安全为根本」的关系是：","options":["政治安全可以脱离其他安全","政治安全是根本，其他安全是保障，二者相辅相成","其他安全可以取代政治安全","二者相互对立"],"answer":1,"explanation":"总体国家安全观中，政治安全是根本（核心是政权和制度安全），军事、科技、文化、社会安全是保障，二者相辅相成、缺一不可。脱离、取代、对立均割裂了二者的关系，故选B。","__sub":"习思想"},{"id":"zz-31009","module":"zhengzhi","prompt":"「中国式现代化」的民主观是：","options":["全过程人民民主，人民当家作主","精英民主","资本民主","形式民主"],"answer":0,"explanation":"中国式现代化发展全过程人民民主，确保人民当家作主，实现最广泛、最真实、最管用的民主。精英民主、资本民主、形式民主均与民主观相悖，故选A。","__sub":"习思想"},{"id":"zz-31010","module":"zhengzhi","prompt":"「新发展理念」中「绿色」发展的内涵之一是：","options":["高耗能发展","先污染后治理","粗放式发展","形成绿色发展方式和生活方式"],"answer":3,"explanation":"绿色发展要求形成节约资源和保护环境的绿色发展方式和生活方式，建设美丽中国。先污染后治理、高耗能、粗放式均与绿色发展相悖，故选D。","__sub":"习思想"},{"id":"zz-31011","module":"zhengzhi","prompt":"「中国式现代化」的历史观是：","options":["英雄史观","历史虚无主义","坚持大历史观，把握历史规律和历史主动","宿命论"],"answer":2,"explanation":"中国式现代化坚持大历史观，把握历史规律、增强历史主动，顺应历史大势。历史虚无主义、宿命论、英雄史观均与历史观相悖，故选C。","__sub":"习思想"},{"id":"zz-31012","module":"zhengzhi","prompt":"「全过程人民民主」中「民主监督」的要求是：","options":["让权力在阳光下运行，接受人民监督","封闭运行","暗箱操作","拒绝监督"],"answer":0,"explanation":"民主监督要求让权力在阳光下运行，把权力关进制度的笼子，确保人民赋予的权力始终用来为人民谋利益。封闭运行、暗箱操作、拒绝监督均违背民主监督要求，故选A。","__sub":"习思想"},{"id":"zz-31013","module":"zhengzhi","prompt":"「中国式现代化」的价值观是：","options":["以物为中心","以资本为中心","以人民为中心，实现人的全面发展","以少数人为中心"],"answer":2,"explanation":"中国式现代化坚持以人民为中心的价值观，促进人的全面发展和社会全面进步。以资本、物、少数人为中心均与价值观相悖，故选C。","__sub":"习思想"},{"id":"zz-31014","module":"zhengzhi","prompt":"「新发展理念」中「创新」发展的内涵之一是：","options":["只抓技术创新","科技创新、制度创新、文化创新等各方面创新","只抓制度创新","只抓文化创新"],"answer":1,"explanation":"创新发展涵盖科技创新、制度创新、文化创新等各方面创新，以科技创新为核心带动全面创新。只抓某一方面的创新均割裂了创新发展的整体性，故选B。","__sub":"习思想"},{"id":"zz-31015","module":"zhengzhi","prompt":"「中国式现代化」的安全观是：","options":["只重安全","统筹发展和安全，实现高水平安全和高质量发展良性互动","只重发展","发展与安全对立"],"answer":1,"explanation":"中国式现代化坚持统筹发展和安全，实现高质量发展和高水平安全良性互动，以新安全格局保障新发展格局。只重一面、相互对立均与安全观相悖，故选B。","__sub":"习思想"},{"id":"zz-31016","module":"zhengzhi","prompt":"「全过程人民民主」中「民主管理」的实践是：","options":["政府包办管理","精英代管","人民群众依法参与基层公共事务管理","资本主导"],"answer":2,"explanation":"民主管理的实践是人民群众依法通过村民委员会、居民委员会等组织参与基层公共事务和公益事业管理。政府包办、精英代管、资本主导均非民主管理实践，故选C。","__sub":"习思想"},{"id":"zz-31017","module":"zhengzhi","prompt":"「中国式现代化」的世界观是：","options":["弱肉强食","胸怀天下，推动构建人类命运共同体","零和博弈","孤立主义"],"answer":1,"explanation":"中国式现代化坚持胸怀天下的世界观，推动构建人类命运共同体，为世界和平与发展贡献中国智慧。零和博弈、弱肉强食、孤立主义均与世界观相悖，故选B。","__sub":"习思想"},{"id":"zz-31018","module":"zhengzhi","prompt":"「新发展理念」中「开放」发展的内涵之一是：","options":["坚持对外开放基本国策，形成更大范围、更宽领域、更深层次对外开放","闭关锁国","单边主义","保护主义"],"answer":0,"explanation":"开放发展要求坚持对外开放基本国策，依托我国超大规模市场优势，形成更大范围、更宽领域、更深层次对外开放格局。闭关锁国、单边主义、保护主义均与开放发展相悖，故选A。","__sub":"习思想"},{"id":"zz-31019","module":"zhengzhi","prompt":"「中国式现代化」的治理观是：","options":["制度倒退","坚持中国特色社会主义制度，推进国家治理体系和治理能力现代化","照搬西方制度","治理失效"],"answer":1,"explanation":"中国式现代化坚持和完善中国特色社会主义制度，推进国家治理体系和治理能力现代化，发挥制度优势。照搬西方、制度倒退、治理失效均与治理观相悖，故选B。","__sub":"习思想"},{"id":"zz-31020","module":"zhengzhi","prompt":"「全过程人民民主」中「民主选举」的要求是：","options":["依法保障人民选举权和被选举权","指定候选人","取消选举","操纵选举"],"answer":0,"explanation":"民主选举要求依法保障人民的选举权和被选举权，通过民主选举产生代表人民意志的人大代表等。指定、取消、操纵选举均违背民主选举要求，故选A。","__sub":"习思想"},{"id":"zz-31021","module":"zhengzhi","prompt":"「中国式现代化」的发展观是：","options":["粗放式发展","完整、准确、全面贯彻新发展理念，实现高质量发展","单一GDP导向","牺牲环境发展"],"answer":1,"explanation":"中国式现代化坚持完整、准确、全面贯彻新发展理念，实现高质量发展，摒弃单一GDP导向、粗放式发展和牺牲环境的发展。故选B。","__sub":"习思想"},{"id":"zz-31022","module":"zhengzhi","prompt":"「国家安全」中「统筹外部安全和内部安全」的要求是：","options":["内外对立","对外维护主权安全发展利益，对内维护政治安全和社会稳定","只顾内部","只顾外部"],"answer":1,"explanation":"统筹外部安全和内部安全，要求对外维护国家主权、安全、发展利益，对内维护政治安全和社会稳定，二者统筹兼顾。只顾一面、内外对立均违背统筹要求，故选B。","__sub":"习思想"},{"id":"zz-31023","module":"zhengzhi","prompt":"「中国式现代化」的民生观是：","options":["民生靠市场解决","增进民生福祉，提高人民生活品质","民生让位于增长","民生是负担"],"answer":1,"explanation":"中国式现代化坚持增进民生福祉，在发展中保障和改善民生，提高人民生活品质。民生让位、靠市场、视为负担均与民生观相悖，故选B。","__sub":"习思想"},{"id":"zz-31024","module":"zhengzhi","prompt":"「新发展理念」中「协调」发展的方法论要求是：","options":["单边突进","局部优先","正确处理发展中的重大关系，增强发展整体性","碎片发展"],"answer":2,"explanation":"协调发展要求正确处理发展中的重大关系（城乡、区域、经济与社会、人与自然等），增强发展的整体性协调性。单边突进、局部优先、碎片发展均违背协调发展方法论，故选C。","__sub":"习思想"},{"id":"zz-31025","module":"zhengzhi","prompt":"「中国式现代化」的法治观是：","options":["坚持全面依法治国，在法治轨道上推进现代化","人治优先","法治倒退","选择性法治"],"answer":0,"explanation":"中国式现代化坚持全面依法治国，在法治轨道上全面建设社会主义现代化国家。人治优先、法治倒退、选择性法治均与法治观相悖，故选A。","__sub":"习思想"},{"id":"zz-31026","module":"zhengzhi","prompt":"「全过程人民民主」中「民主协商」的形式之一是：","options":["封闭协商","政党协商、人大协商、政府协商、政协协商、人民团体协商、基层协商、社会组织协商","单向协商","形式协商"],"answer":1,"explanation":"我国协商民主形式包括政党协商、人大协商、政府协商、政协协商、人民团体协商、基层协商、社会组织协商等，形成广泛多层制度化的协商体系。封闭、单向、形式协商均非规范形式，故选B。","__sub":"习思想"},{"id":"zz-31027","module":"zhengzhi","prompt":"「中国式现代化」的人才观是：","options":["人才是第一资源，实施人才强国战略","人才可有可无","人才靠引进解决","人才靠自然成长"],"answer":0,"explanation":"中国式现代化坚持人才是第一资源，深入实施人才强国战略，聚天下英才而用之。人才可有可无、只靠引进、自然成长均与人才观相悖，故选A。","__sub":"习思想"},{"id":"zz-31028","module":"zhengzhi","prompt":"「国家安全」中「统筹传统安全和非传统安全」的要求是：","options":["只重传统安全","二者对立","只重非传统安全","既重视传统安全领域，又重视非传统安全领域"],"answer":3,"explanation":"统筹传统安全和非传统安全，要求既重视政治、军事、国土等传统安全，又重视经济、文化、科技、网络、生物等非传统安全。只重一面、对立均违背统筹要求，故选D。","__sub":"习思想"},{"id":"zz-31029","module":"zhengzhi","prompt":"「中国式现代化」的共同富裕观是：","options":["只讲效率","先发展后分配","在高质量发展中促进共同富裕","只讲公平"],"answer":2,"explanation":"中国式现代化坚持在高质量发展中促进共同富裕，正确处理效率和公平的关系，构建初次分配、再分配、第三次分配协调配套的制度体系。先发展后分配、只讲一面均与共同富裕观相悖，故选C。","__sub":"习思想"},{"id":"zz-31030","module":"zhengzhi","prompt":"「新发展理念」中「共享」发展的方法论要求是：","options":["超越阶段","一步到位","只顾当前","坚持全民共享、渐进共享，既尽力而为又量力而行"],"answer":3,"explanation":"共享发展要求坚持全民共享、全面共享、共建共享、渐进共享，既尽力而为又量力而行，不超越阶段。一步到位、只顾当前、超越阶段均违背共享发展方法论，故选D。","__sub":"习思想"},{"id":"zz-31031","module":"zhengzhi","prompt":"习近平新时代中国特色社会主义思想中，明确中国特色社会主义制度的最大优势是：","options":["人民代表大会制度","中国共产党领导","社会主义市场经济体制","民主集中制"],"answer":1,"explanation":"党的十九届六中全会决议「十个明确」第一条明确：中国特色社会主义最本质的特征是中国共产党领导，中国特色社会主义制度的最大优势是中国共产党领导。其余三项是具体制度或原则，不是「最大优势」的表述。","__sub":"习思想"},{"id":"zz-31032","module":"zhengzhi","prompt":"「六个必须坚持」中，排在首位的是：","options":["必须坚持守正创新","必须坚持自信自立","必须坚持人民至上","必须坚持系统观念"],"answer":2,"explanation":"党的二十大报告提出继续推进理论创新的科学方法，即必须坚持人民至上、自信自立、守正创新、问题导向、系统观念、胸怀天下，其中人民至上排在首位，体现马克思主义人民性的根本立场。","__sub":"习思想"},{"id":"zz-31033","module":"zhengzhi","prompt":"「六个必须坚持」中的「守正」，其基本内涵是：","options":["固守传统经验和既有做法不作改变","坚持马克思主义基本原理不动摇，坚持党的全面领导不动摇，坚持中国特色社会主义不动摇","只继承不发展，拒绝一切理论创新","以新说法替代基本原理"],"answer":1,"explanation":"守正才能不迷失方向、不犯颠覆性错误。守正就是坚持马克思主义基本原理不动摇，坚持党的全面领导不动摇，坚持中国特色社会主义不动摇；创新才能把握时代、引领时代，二者不可割裂。","__sub":"习思想"},{"id":"zz-31034","module":"zhengzhi","prompt":"「六个必须坚持」中的「系统观念」要求不断提高的思维能力不包括：","options":["辩证思维","战略思维","直觉思维","底线思维"],"answer":2,"explanation":"系统观念要求不断提高战略思维、历史思维、辩证思维、系统思维、创新思维、法治思维、底线思维能力。直觉思维不属于其中任何一项，其余三项均在要求之列。","__sub":"习思想"},{"id":"zz-31035","module":"zhengzhi","prompt":"「六个必须坚持」中的「胸怀天下」，强调的是：","options":["以本国利益为唯一出发点处理一切问题","只专注国内发展，不参与国际事务","拓展世界眼光，关注人类前途命运，推动构建人类命运共同体","照搬外国经验解决中国问题"],"answer":2,"explanation":"胸怀天下要求拓展世界眼光，深刻洞察人类发展进步潮流，积极回应各国人民普遍关切，为解决人类面临的共同问题作出贡献，以海纳百川的胸怀推动构建人类命运共同体。","__sub":"习思想"},{"id":"zz-31036","module":"zhengzhi","prompt":"「六个必须坚持」中的「问题导向」，强调聚焦的是：","options":["实践遇到的新问题和改革发展稳定存在的深层次问题等","脱离实际的抽象概念问题","已经彻底解决的历史旧账","与工作无关的个人偏好问题"],"answer":0,"explanation":"坚持问题导向，就是聚焦实践遇到的新问题、改革发展稳定存在的深层次问题、人民群众急难愁盼问题、国际变局中的重大问题、党的建设面临的突出问题，不断提出真正解决问题的新理念新思路新办法。","__sub":"习思想"},{"id":"zz-31037","module":"zhengzhi","prompt":"「六个必须坚持」中的「自信自立」，要求坚定的是：","options":["对马克思主义的信仰、对中国特色社会主义的信念和「四个自信」","对西方理论模式的迷信","对他国发展道路的照搬","对既有成绩的盲目乐观"],"answer":0,"explanation":"自信自立要求坚持对马克思主义的坚定信仰、对中国特色社会主义的坚定信念，坚定道路自信、理论自信、制度自信、文化自信，把国家和民族发展放在自己力量的基点上。","__sub":"习思想"},{"id":"zz-31038","module":"zhengzhi","prompt":"「江山就是人民、人民就是江山」，揭示的根本立场是：","options":["人民立场","资本立场","精英立场","部门立场"],"answer":0,"explanation":"「江山就是人民、人民就是江山，打江山、守江山，守的是人民的心」，集中体现了党坚持人民至上的根本立场，说明党领导人民打下的江山与人民血肉相连、不可分割。","__sub":"习思想"},{"id":"zz-31039","module":"zhengzhi","prompt":"中国梦的本质是：","options":["人均收入全球最高","经济总量世界第一","军事力量全球领先","国家富强、民族振兴、人民幸福"],"answer":3,"explanation":"习近平总书记指出，中国梦的本质就是国家富强、民族振兴、人民幸福。它把国家的追求、民族的向往、人民的期盼融为一体，其余选项均把中国梦窄化为单一指标。","__sub":"习思想"},{"id":"zz-31040","module":"zhengzhi","prompt":"全面建成社会主义现代化强国「两步走」战略安排中，从二〇二〇年到二〇三五年的目标是：","options":["建成社会主义现代化强国","全面建成小康社会","基本实现社会主义现代化","实现国内生产总值翻两番"],"answer":2,"explanation":"党的十九大和党的二十大都明确：从二〇二〇年到二〇三五年基本实现社会主义现代化；从二〇三五年到本世纪中叶把我国建成富强民主文明和谐美丽的社会主义现代化强国。全面建成小康社会已于二〇二一年宣告实现。","__sub":"习思想"},{"id":"zz-31041","module":"zhengzhi","prompt":"二〇三五年我国发展的总体目标之一是：","options":["人均国内生产总值达到中等发达国家水平","人均国内生产总值达到发达国家最高水平","国内生产总值位居全球第一","实现全体人民同等富裕"],"answer":0,"explanation":"党的二十大报告提出，到二〇三五年人均国内生产总值达到中等发达国家水平。表述是「中等发达国家水平」，不是发达国家最高水平；共同富裕也不是「同等富裕」。","__sub":"习思想"},{"id":"zz-31042","module":"zhengzhi","prompt":"加快构建的新发展格局是指：","options":["国内国际两个市场彼此封闭的格局","以国际大循环为主体的外向型格局","以国内大循环为主体、国内国际双循环相互促进","以区域小循环替代全国大循环的格局"],"answer":2,"explanation":"构建以国内大循环为主体、国内国际双循环相互促进的新发展格局，是把握发展主动权的先手棋。国内大循环为主体不是封闭的国内循环，而是与开放的国际循环相互促进。","__sub":"习思想"},{"id":"zz-31043","module":"zhengzhi","prompt":"党的二十大报告指出，全面建设社会主义现代化国家的首要任务是：","options":["扩大对外开放","高质量发展","加快城镇化","壮大数字经济"],"answer":1,"explanation":"党的二十大报告明确：高质量发展是全面建设社会主义现代化国家的首要任务。发展是党执政兴国的第一要务，没有坚实的物质技术基础，就不可能全面建成社会主义现代化强国。","__sub":"习思想"},{"id":"zz-31044","module":"zhengzhi","prompt":"新质生产力的显著特征是：","options":["高科技、高效能、高质量","高投入、高消耗、高排放","低技术、低效率、低质量","高负债、高杠杆、高周转"],"answer":0,"explanation":"新质生产力是创新起主导作用，摆脱传统经济增长方式、生产力发展路径，具有高科技、高效能、高质量特征，符合新发展理念的先进生产力质态。","__sub":"习思想"},{"id":"zz-31046","module":"zhengzhi","prompt":"全面依法治国要求坚持依法治国、依法执政、依法行政共同推进，坚持：","options":["立法、司法、执法各自为政","法治城市、法治乡村、法治家庭分层建设","法治国家、法治政府、法治社会一体建设","普法、执法、守法相互脱节"],"answer":2,"explanation":"习近平法治思想强调坚持依法治国、依法执政、依法行政共同推进，法治国家、法治政府、法治社会一体建设，使法治建设各环节、各领域协同发力。","__sub":"习思想"},{"id":"zz-31047","module":"zhengzhi","prompt":"全面依法治国必须坚持的原则之一是：","options":["以德治国取代依法治国","依法治国和以德治国相结合","法律与道德相互对立","只靠重刑治理社会"],"answer":1,"explanation":"坚持依法治国和以德治国相结合，既重视发挥法律的规范作用，又重视发挥道德的教化作用，实现法律和道德相辅相成、法治和德治相得益彰。","__sub":"习思想"},{"id":"zz-31048","module":"zhengzhi","prompt":"培育和践行社会主义核心价值观，要注重：","options":["一阵风式宣传","喊口号、贴标语","落细、落小、落实","只在特定节日开展"],"answer":2,"explanation":"习近平总书记强调，培育和践行社会主义核心价值观要注重落细、落小、落实，使之融入社会生活，让人们在实践中感知它、领悟它，避免形式主义。","__sub":"习思想"},{"id":"zz-31049","module":"zhengzhi","prompt":"意识形态工作在党和国家事业全局中的定位是：","options":["完全交给市场调节的工作","可有可无的辅助性工作","党的一项极端重要的工作","只属于宣传部门内部的工作"],"answer":2,"explanation":"习近平总书记指出，意识形态工作是党的一项极端重要的工作，事关党的前途命运、事关国家长治久安、事关民族凝聚力和向心力，必须牢牢掌握意识形态工作领导权。","__sub":"习思想"},{"id":"zz-31050","module":"zhengzhi","prompt":"提升生态系统多样性、稳定性、持续性，要求坚持：","options":["先污染后治理","山水林田湖草沙一体化保护和系统治理","只保护森林单一要素","把开发置于保护之前"],"answer":1,"explanation":"习近平总书记强调坚持山水林田湖草沙一体化保护和系统治理，因为生态是统一的自然系统，是相互依存、紧密联系的有机链条，治理必须遵循系统观念。","__sub":"习思想"},{"id":"zz-31051","module":"zhengzhi","prompt":"实现「双碳」目标，能源领域必须坚持的原则是：","options":["立破并举、以破为主","先破后立","只破不立","先立后破"],"answer":3,"explanation":"习近平总书记强调，实现「双碳」目标要坚持先立后破，传统能源逐步退出必须建立在新能源安全可靠的替代基础上，不能未立先破，防止运动式「减碳」。","__sub":"习思想"},{"id":"zz-31052","module":"zhengzhi","prompt":"统筹发展和安全的关系，正确的理解是：","options":["只要安全不要发展","只要发展不要安全","发展是安全的基础，安全是发展的条件","安全与发展相互对立"],"answer":2,"explanation":"统筹发展和安全要求坚持发展和安全并重：发展是安全的基础，安全是发展的条件，以高质量发展促进高水平安全，以高水平安全保障高质量发展。","__sub":"习思想"},{"id":"zz-31054","module":"zhengzhi","prompt":"党在新时代的强军目标中，作为人民军队之魂的是：","options":["能打胜仗","听党指挥","作风优良","装备先进"],"answer":1,"explanation":"听党指挥是灵魂，决定军队建设的政治方向；能打胜仗是核心，反映军队根本职能；作风优良是保证，关系军队的性质、宗旨、本色。","__sub":"习思想"},{"id":"zz-31055","module":"zhengzhi","prompt":"与特别行政区高度自治权相统一、必须坚持的是：","options":["中央全面管治权","外国干预权","司法终审权归外国","无限期搁置国安立法"],"answer":2,"explanation":"把坚持中央全面管治权和保障特别行政区高度自治权统一起来，落实「爱国者治港」「爱国者治澳」，是坚持「一国两制」、推进祖国统一的重要原则。","__sub":"习思想"},{"id":"zz-31056","module":"zhengzhi","prompt":"新时代党解决台湾问题的总体方略中，坚持的政治基础是：","options":["「两个中国」的提法","一个中国原则和「九二共识」","「一中一台」的安排","无限期搁置两岸交流"],"answer":1,"explanation":"坚持一个中国原则和「九二共识」，是两岸关系和平发展的政治基础，也是新时代党解决台湾问题总体方略的重要内容。「台独」分裂行径注定失败。","__sub":"习思想"},{"id":"zz-31057","module":"zhengzhi","prompt":"构建人类命运共同体，就是要建设一个：","options":["弱肉强食、赢者通吃的世界","由少数国家主导的世界","阵营对抗、封闭排他的世界","持久和平、普遍安全、共同繁荣、开放包容、清洁美丽的世界"],"answer":3,"explanation":"构建人类命运共同体，就是建设持久和平、普遍安全、共同繁荣、开放包容、清洁美丽的世界，推动共商共建共享的全球治理，不搞霸权霸道霸凌。","__sub":"习思想"},{"id":"zz-31058","module":"zhengzhi","prompt":"新时代党的建设总要求明确，要以什么为统领：","options":["党的组织建设","党的思想建设","党的政治建设","党的纪律建设"],"answer":2,"explanation":"新时代党的建设总要求提出以加强党的长期执政能力建设、先进性和纯洁性建设为主线，以党的政治建设为统领，把党的政治建设摆在首位，因为政治建设是党的根本性建设。","__sub":"习思想"},{"id":"zz-31059","module":"zhengzhi","prompt":"新时代好干部标准之外，习近平总书记还强调干部要：","options":["忠诚干净担当","多谋善断圆滑","敢闯敢吹敢报","唯上唯书唯情面"],"answer":0,"explanation":"习近平总书记强调干部要忠诚干净担当：忠诚是政治品格，干净是廉洁底线，担当是履职要求，三者构成新时代干部素质的核心要求。","__sub":"习思想"},{"id":"zz-31060","module":"zhengzhi","prompt":"党的最大政治优势是：","options":["密切联系群众","党员数量庞大","历史传统悠久","组织层级繁多"],"answer":0,"explanation":"党章指出，党的最大政治优势是密切联系群众，党执政后的最大危险是脱离群众，必须坚持全心全意为人民服务的根本宗旨。","__sub":"习思想"},{"id":"zz-31061","module":"zhengzhi","prompt":"学习贯彻习近平新时代中国特色社会主义思想主题教育的总要求是：","options":["先表态、后落实、再观望","学思想、强党性、重实践、建新功","多读书、少干事、不出错","学文件、写体会、开大会、交总结"],"answer":1,"explanation":"学习贯彻习近平新时代中国特色社会主义思想主题教育的总要求是学思想、强党性、重实践、建新功，坚持学思用贯通、知信行统一。","__sub":"习思想"},{"id":"zz-31062","module":"zhengzhi","prompt":"习近平总书记强调，调查研究是：","options":["谋事之基、成事之道","可有可无的形式","给基层添负担的活动","只听汇报不看现场"],"answer":0,"explanation":"习近平总书记指出，调查研究是谋事之基、成事之道，没有调查就没有发言权，没有正确的调查同样没有发言权，强调在全党大兴调查研究。","__sub":"习思想"},{"id":"zz-31063","module":"zhengzhi","prompt":"面对风险挑战，习近平总书记强调要发扬：","options":["妥协退让，息事宁人","回避态度，减少接触","斗争精神，增强斗争本领","观望等待，听天由命"],"answer":2,"explanation":"习近平总书记强调必须进行具有许多新的历史特点的伟大斗争，发扬斗争精神、增强斗争本领，在原则问题上寸步不让、寸土不让。","__sub":"习思想"},{"id":"zz-31064","module":"zhengzhi","prompt":"坚持底线思维，就是要做到：","options":["麻痹大意、心存侥幸","事后补救、被动应付","遇事绕行、矛盾上交","居安思危、未雨绸缪"],"answer":3,"explanation":"坚持底线思维，就是要从最坏处着眼、做最充分准备、朝好的方向努力、争取最好结果，做到居安思危、未雨绸缪，牢牢掌握主动权。","__sub":"习思想"},{"id":"zz-31065","module":"zhengzhi","prompt":"面对复杂形势和繁重任务，要求各级干部保持：","options":["短期投机心态","战略定力","频繁摇摆立场","随波逐流"],"answer":1,"explanation":"习近平总书记强调要保持战略定力，在道路方向、立场原则等根本问题上不动摇，既只争朝夕又保持历史耐心，稳中求进推进各项事业。","__sub":"习思想"},{"id":"zz-31066","module":"zhengzhi","prompt":"中国式现代化的特征之一是：","options":["少数人富裕的现代化","人口规模巨大的现代化","以牺牲环境为代价的现代化","照搬外国模式的现代化"],"answer":1,"explanation":"中国式现代化是人口规模巨大的现代化、全体人民共同富裕的现代化、物质文明和精神文明相协调的现代化、人与自然和谐共生的现代化、走和平发展道路的现代化。","__sub":"习思想"},{"id":"zz-31067","module":"zhengzhi","prompt":"全面深化改革要坚持的改革方向之一是：","options":["社会主义市场经济改革方向","全面私有化方向","计划经济回归方向","去市场化方向"],"answer":0,"explanation":"全面深化改革要坚持社会主义市场经济改革方向，使市场在资源配置中起决定性作用、更好发挥政府作用，既不能走封闭僵化的老路，也不能改旗易帜。","__sub":"习思想"},{"id":"zz-31068","module":"zhengzhi","prompt":"全面深化改革要坚持的科学方法，包括处理好：","options":["试点与推广互相排斥的关系","改革与稳定完全对立的关系","顶层设计与摸着石头过河的关系","效率与公平不可兼得的关系"],"answer":2,"explanation":"全面深化改革要坚持顶层设计和基层探索良性互动、有机结合，既发挥顶层设计的引领作用，又发挥摸着石头过河的探索作用，二者不是对立关系。","__sub":"习思想"},{"id":"zz-31069","module":"zhengzhi","prompt":"党的二十大报告指出，教育、科技、人才是全面建设社会主义现代化国家的：","options":["局部性、单一性支撑","边缘性、补充性支撑","临时性、过渡性支撑","基础性、战略性支撑"],"answer":3,"explanation":"党的二十大报告首次把教育、科技、人才一体部署，指出它们是全面建设社会主义现代化国家的基础性、战略性支撑，必须坚持科技是第一生产力、人才是第一资源、创新是第一动力。","__sub":"习思想"},{"id":"zz-31070","module":"zhengzhi","prompt":"习近平总书记强调，引领发展的第一动力是：","options":["劳动力规模","资本","土地","创新"],"answer":3,"explanation":"习近平总书记指出，创新是引领发展的第一动力，抓创新就是抓发展，谋创新就是谋未来，必须把创新摆在国家发展全局的核心位置。","__sub":"习思想"},{"id":"zz-31071","module":"zhengzhi","prompt":"创新驱动发展战略的实质是：","options":["资本驱动","人才驱动","资源驱动","政策驱动"],"answer":1,"explanation":"习近平总书记指出，创新驱动实质上是人才驱动，谁拥有一流的人才队伍，谁就能在科技创新中占据优势，要聚天下英才而用之。","__sub":"习思想"},{"id":"zz-31072","module":"zhengzhi","prompt":"巩固拓展脱贫攻坚成果，必须坚决守住的底线是：","options":["不增加农民收入","不发展乡村产业","不推进城镇化","不发生规模性返贫"],"answer":3,"explanation":"党中央要求巩固拓展脱贫攻坚成果，增强脱贫地区内生发展动力，坚决守住不发生规模性返贫的底线，让脱贫基础更加稳固、成效更可持续。","__sub":"习思想"},{"id":"zz-31073","module":"zhengzhi","prompt":"下列属于我国实施的区域重大战略的是：","options":["各地区各自为战、以邻为壑","取消区域分工搞同质化竞争","以行政级别决定发展顺序","京津冀协同发展、长江经济带发展、粤港澳大湾区建设"],"answer":3,"explanation":"京津冀协同发展、长江经济带发展、粤港澳大湾区建设、长三角一体化发展、黄河流域生态保护和高质量发展等属于区域重大战略，旨在增强区域发展的协调性、联动性。","__sub":"习思想"},{"id":"zz-31074","module":"zhengzhi","prompt":"推进高水平对外开放，要求稳步扩大：","options":["规则、规制、管理、标准等制度型开放","只扩大商品进口数量","只扩大外资准入负面清单","只扩大沿海地区开放"],"answer":0,"explanation":"党的二十大报告提出稳步扩大规则、规制、管理、标准等制度型开放，推动货物贸易优化升级，创新服务贸易发展机制，发展数字贸易。","__sub":"习思想"},{"id":"zz-31075","module":"zhengzhi","prompt":"习近平总书记强调，最大的民生是：","options":["住房","就业","出行","娱乐"],"answer":1,"explanation":"就业是最大的民生，是最基本的民生。党中央强化就业优先政策，健全就业公共服务体系，促进高质量充分就业。","__sub":"习思想"},{"id":"zz-31076","module":"zhengzhi","prompt":"教育的根本任务是：","options":["规模扩张","升学率最大化","立德树人","应试训练"],"answer":2,"explanation":"习近平总书记强调，教育的根本任务是立德树人，要培养德智体美劳全面发展的社会主义建设者和接班人，落实立德树人根本任务。","__sub":"习思想"},{"id":"zz-31077","module":"zhengzhi","prompt":"习近平总书记指出，人民健康是：","options":["只属于卫生部门的事务","可有可无的软指标","与经济发展对立的目标","民族昌盛和国家强盛的重要标志"],"answer":3,"explanation":"习近平总书记指出，人民健康是民族昌盛和国家强盛的重要标志，要把保障人民健康放在优先发展的战略位置，完善人民健康促进政策。","__sub":"习思想"},{"id":"zz-31078","module":"zhengzhi","prompt":"加强和创新社会治理，要健全的社会治理制度是：","options":["共建共治共享","政府包办一切","放任自流","各自为政"],"answer":0,"explanation":"党的二十大报告提出健全共建共治共享的社会治理制度，建设人人有责、人人尽责、人人享有的社会治理共同体，提升社会治理效能。","__sub":"习思想"},{"id":"zz-31079","module":"zhengzhi","prompt":"保护生态环境必须依靠的制度手段是：","options":["口头倡议","最严格制度、最严密法治","道德感化为主","事后追责即可"],"answer":1,"explanation":"习近平总书记强调，保护生态环境必须依靠制度、依靠法治，只有实行最严格的制度、最严密的法治，才能为生态文明建设提供可靠保障。","__sub":"习思想"},{"id":"zz-31080","module":"zhengzhi","prompt":"依法治国首先要坚持：","options":["逐利违法","以言代法","以权压法","依宪治国"],"answer":3,"explanation":"习近平总书记强调，依法治国首先要坚持依宪治国，依法执政首先要坚持依宪执政，维护宪法权威，保证宪法法律有效实施。","__sub":"习思想"},{"id":"zz-31081","module":"zhengzhi","prompt":"巩固和发展最广泛的爱国统一战线，要求完善：","options":["大统战工作格局","小圈子协商格局","部门分割格局","临时拼凑格局"],"answer":0,"explanation":"党的二十大报告提出完善大统战工作格局，坚持大团结大联合，动员全体中华儿女围绕实现中华民族伟大复兴中国梦一起来想、一起来干。","__sub":"习思想"},{"id":"zz-31082","module":"zhengzhi","prompt":"促进民族团结，要促进各民族广泛：","options":["交往交流交融","隔离分居","同化替代","彼此封闭"],"answer":0,"explanation":"铸牢中华民族共同体意识要求促进各民族广泛交往交流交融，推动各民族共同走向社会主义现代化，构筑中华民族共有精神家园。","__sub":"习思想"},{"id":"zz-31083","module":"zhengzhi","prompt":"提高宗教工作水平，要求推进宗教事务治理：","options":["境外化","随意化","商业化","法治化"],"answer":3,"explanation":"党的宗教工作基本方针是全面贯彻党的宗教信仰自由政策，依法管理宗教事务，坚持我国宗教中国化方向，积极引导宗教与社会主义社会相适应，提高宗教事务治理法治化水平。","__sub":"习思想"},{"id":"zz-31084","module":"zhengzhi","prompt":"习近平总书记强调，没有网络安全就：","options":["没有国家安全","不影响国家安全","只是技术问题","交给市场解决"],"answer":0,"explanation":"习近平总书记指出，没有网络安全就没有国家安全，没有信息化就没有现代化，要树立正确的网络安全观，筑牢国家网络安全屏障。","__sub":"习思想"},{"id":"zz-31085","module":"zhengzhi","prompt":"促进数字经济发展，要求推动数字经济和：","options":["实体经济深度融合","虚拟经济脱实向虚","泡沫经济相互助长","传统模式原样保留"],"answer":0,"explanation":"党中央要求促进数字经济和实体经济深度融合，打造具有国际竞争力的数字产业集群，加快建设网络强国、数字中国。","__sub":"习思想"},{"id":"zz-31086","module":"zhengzhi","prompt":"总体国家安全观强调，以什么为根本：","options":["经济安全","政治安全","军事安全","文化安全"],"answer":1,"explanation":"总体国家安全观坚持以人民安全为宗旨、以政治安全为根本、以经济安全为基础、以军事科技文化社会安全为保障、以促进国际安全为依托。","__sub":"习思想"},{"id":"zz-31087","module":"zhengzhi","prompt":"推进供给侧结构性改革，主攻方向是：","options":["刺激短期需求","压减所有产能","提高供给质量","放松质量监管"],"answer":2,"explanation":"推进供给侧结构性改革，主攻方向是提高供给质量，减少无效和低端供给，扩大有效和中高端供给，增强供给结构对需求变化的适应性和灵活性。","__sub":"习思想"},{"id":"zz-31088","module":"zhengzhi","prompt":"加快实现高水平科技自立自强，要求强化：","options":["重复低水平建设","单打独斗式创新","国家战略科技力量","重引进轻消化"],"answer":2,"explanation":"党中央要求强化国家战略科技力量，健全新型举国体制，打好关键核心技术攻坚战，加快实现高水平科技自立自强，把科技命脉牢牢掌握在自己手中。","__sub":"习思想"},{"id":"zz-31089","module":"zhengzhi","prompt":"建设现代化产业体系，要求坚持把发展经济的着力点放在：","options":["虚拟经济上","实体经济上","房地产上","金融投机上"],"answer":1,"explanation":"党的二十大报告提出建设现代化产业体系，坚持把发展经济的着力点放在实体经济上，推进新型工业化，加快建设制造强国、质量强国、航天强国等。","__sub":"习思想"},{"id":"zz-31090","module":"zhengzhi","prompt":"中国式现代化的本质要求包括：","options":["牺牲精神文明换取物质增长","照搬西方现代化模式","以资本增值为唯一目标","实现高质量发展，发展全过程人民民主，丰富人民精神世界等"],"answer":3,"explanation":"党的二十大报告概括了中国式现代化的本质要求：坚持中国共产党领导，坚持中国特色社会主义，实现高质量发展，发展全过程人民民主，丰富人民精神世界，实现全体人民共同富裕，促进人与自然和谐共生，推动构建人类命运共同体，创造人类文明新形态。","__sub":"习思想"},{"id":"zz-31091","module":"zhengzhi","prompt":"习近平总书记强调，发展是党执政兴国的：","options":["可选任务","次要任务","临时任务","第一要务"],"answer":3,"explanation":"习近平总书记强调，发展是党执政兴国的第一要务，没有坚实的物质技术基础，就不可能全面建成社会主义现代化强国，必须坚持以经济建设为中心。","__sub":"习思想"},{"id":"zz-31092","module":"zhengzhi","prompt":"新时代十年伟大变革在党和国家发展史上的意义是：","options":["具有里程碑意义","意义有限","只是量的积累","与历史进程无关"],"answer":0,"explanation":"党的二十大报告指出，新时代十年的伟大变革，在党史、新中国史、改革开放史、社会主义发展史、中华民族发展史上具有里程碑意义，党在革命性锻造中更加坚强有力。","__sub":"习思想"},{"id":"zz-31093","module":"zhengzhi","prompt":"党执政后的最大危险是：","options":["脱离群众","党员老龄化","文件数量多","会议时间长"],"answer":1,"explanation":"党章指出，党执政后的最大危险是脱离群众。全党必须坚持群众路线，反对形式主义、官僚主义，始终保持同人民群众的血肉联系。","__sub":"习思想"},{"id":"zz-31094","module":"zhengzhi","prompt":"全面从严治党，基础在全面，关键在严，要害在：","options":["治","宽","松","软"],"answer":0,"explanation":"全面从严治党，基础在全面，覆盖党的建设各领域各方面各部门；关键在严，真管真严、敢管敢严、长管长严；要害在治，解决管党治党宽松软问题。","__sub":"习思想"},{"id":"zz-31095","module":"zhengzhi","prompt":"习近平总书记强调，全党要牢记的「三个务必」是：","options":["务必多干少说，务必快干蛮干，务必先干再说","务必不忘初心、牢记使命，务必谦虚谨慎、艰苦奋斗，务必敢于斗争、善于斗争","务必个人服从，务必局部服从，务必眼前服从","务必多报喜，务必少报忧，务必不担责"],"answer":1,"explanation":"党的二十大报告提出「三个务必」：务必不忘初心、牢记使命，务必谦虚谨慎、艰苦奋斗，务必敢于斗争、善于斗争，这是对「两个务必」的传承与升华。","__sub":"习思想"},{"id":"zz-31096","module":"zhengzhi","prompt":"新质生产力由什么催生：","options":["单纯的资本投入和规模扩张","劳动力数量的简单增加","技术革命性突破、生产要素创新性配置、产业深度转型升级","土地要素的集中投放"],"answer":2,"explanation":"新质生产力由技术革命性突破、生产要素创新性配置、产业深度转型升级而催生，以劳动者、劳动资料、劳动对象优化组合为基本内涵。其余三项仍属传统要素投入型增长方式。故选C。","__sub":"习思想"},{"id":"zz-31097","module":"zhengzhi","prompt":"新质生产力的基本内涵是：","options":["生产规模的持续扩大","劳动者、劳动资料、劳动对象及其优化组合的跃升","劳动密集程度的提高","资源消耗总量的增长"],"answer":1,"explanation":"新质生产力的基本内涵是劳动者、劳动资料、劳动对象及其优化组合的跃升，强调质态跃升而非数量扩张，故规模扩大、密集提高、消耗增长均不正确。故选B。","__sub":"习思想"},{"id":"zz-31098","module":"zhengzhi","prompt":"新质生产力的核心标志是：","options":["国内生产总值总量翻番","全要素生产率大幅提升","劳动力投入总量增加","固定资产投资高速增长"],"answer":1,"explanation":"以全要素生产率大幅提升为核心标志，是新质生产力区别于传统生产力的重要特征，强调依靠创新驱动而非要素投入实现增长。故选B。","__sub":"习思想"},{"id":"zz-31099","module":"zhengzhi","prompt":"发展新质生产力要防止的倾向是：","options":["因地制宜、分类指导","先立后破、稳中求进","一哄而上、泡沫化，搞一种模式","从实际出发、突出特色"],"answer":2,"explanation":"习近平总书记强调发展新质生产力要防止一哄而上、泡沫化，也不要搞一种模式，各地要因地制宜。其余三项正是正确的方法论要求。故选C。","__sub":"习思想"},{"id":"zz-31100","module":"zhengzhi","prompt":"新质生产力的主要产业载体是：","options":["传统重化工业","战略性新兴产业和未来产业","劳动密集型加工业","高耗能基础产业"],"answer":1,"explanation":"发展新质生产力要加快发展战略性新兴产业和未来产业，它们代表新一轮科技革命和产业变革方向；传统重化工业、劳动密集型加工业不属于主要载体。故选B。","__sub":"习思想"},{"id":"zz-31101","module":"zhengzhi","prompt":"对传统产业在发展新质生产力中的正确态度是：","options":["不能将其当作「低端产业」简单退出","全部淘汰、腾笼换鸟","维持原状、不作改造","任其自然萎缩"],"answer":0,"explanation":"习近平总书记指出，发展新质生产力不是忽视、放弃传统产业，要用新技术改造提升传统产业，不能将其当作「低端产业」简单退出。故选A。","__sub":"习思想"},{"id":"zz-31102","module":"zhengzhi","prompt":"习近平总书记强调，新时代的硬道理是：","options":["高速增长","规模扩张","投资拉动","高质量发展"],"answer":3,"explanation":"把坚持高质量发展作为新时代的硬道理，是党中央对发展规律的深刻把握；高速增长、规模扩张、投资拉动均属旧有发展方式，不符合新时代要求。故选D。","__sub":"习思想"},{"id":"zz-31103","module":"zhengzhi","prompt":"高质量发展体现的发展理念是：","options":["速度、规模、总量","创新、协调、绿色、开放、共享","投入、产出、利润","效率、公平、稳定"],"answer":1,"explanation":"高质量发展就是体现新发展理念的发展，即创新成为第一动力、协调成为内生特点、绿色成为普遍形态、开放成为必由之路、共享成为根本目的的发展。故选B。","__sub":"习思想"},{"id":"zz-31104","module":"zhengzhi","prompt":"在社会主义市场经济中，市场在资源配置中起：","options":["辅助性作用","次要作用","决定性作用","完全替代政府的作用"],"answer":2,"explanation":"使市场在资源配置中起决定性作用、更好发挥政府作用，是社会主义市场经济体制改革的基本方向。辅助、次要均降低了市场地位，「完全替代政府」则否认政府作用。故选C。","__sub":"习思想"},{"id":"zz-31105","module":"zhengzhi","prompt":"建设全国统一大市场旨在：","options":["分割区域市场、地方保护","提高市场准入门槛","打通制约经济循环的关键堵点，促进商品要素资源畅通流动","取消市场调节功能"],"answer":2,"explanation":"建设全国统一大市场，就是要打通制约经济循环的关键堵点，促进商品要素资源在更大范围内畅通流动，为构建新发展格局提供支撑。故选C。","__sub":"习思想"},{"id":"zz-31106","module":"zhengzhi","prompt":"党的二十大报告要求，把实施扩大内需战略同什么有机结合起来：","options":["扩大出口规模","增加财政赤字","深化供给侧结构性改革","放松宏观调控"],"answer":2,"explanation":"把实施扩大内需战略同深化供给侧结构性改革有机结合起来，增强国内大循环内生动力和可靠性，实现需求牵引供给、供给创造需求的更高水平动态平衡。故选C。","__sub":"习思想"},{"id":"zz-31107","module":"zhengzhi","prompt":"新型城镇化的核心是：","options":["以人为核心","以房地产为核心","以土地扩张为核心","以基建投资为核心"],"answer":0,"explanation":"推进以人为核心的新型城镇化，提高城市规划、建设、治理水平，加快农业转移人口市民化，是提高城镇化质量的关键。故选A。","__sub":"习思想"},{"id":"zz-31108","module":"zhengzhi","prompt":"「两个毫不动摇」的基本内涵是指：","options":["毫不动摇巩固和发展公有制经济，毫不动摇鼓励、支持、引导非公有制经济发展","毫不动摇扩大投资，毫不动摇扩大消费","毫不动摇对外开放，毫不动摇对内改革","毫不动摇发展重工业，毫不动摇发展轻工业"],"answer":3,"explanation":"「两个毫不动摇」即毫不动摇巩固和发展公有制经济，毫不动摇鼓励、支持、引导非公有制经济发展，二者相辅相成；重轻工业、投资消费、内外改革均非其内涵。故选D。","__sub":"习思想"},{"id":"zz-31109","module":"zhengzhi","prompt":"对资本健康发展的正确要求是：","options":["放任资本无序扩张","全面取缔各类资本","依法规范和引导资本健康发展","只鼓励不监管"],"answer":2,"explanation":"要发挥资本作为生产要素的积极作用，依法规范和引导资本健康发展，防止资本无序扩张；放任扩张、全面取缔、只鼓励不监管均不正确。故选C。","__sub":"习思想"},{"id":"zz-31110","module":"zhengzhi","prompt":"加快建设制造强国，要推进：","options":["去工业化","重化工业化","低水平扩张","新型工业化"],"answer":3,"explanation":"推进新型工业化，加快建设制造强国、质量强国，是建设现代化产业体系的重要内容；去工业化、低水平扩张均与制造强国目标相悖。故选D。","__sub":"习思想"},{"id":"zz-31111","module":"zhengzhi","prompt":"建设现代化产业体系的方向是：","options":["粗放化、单一化、封闭化","高耗能、高排放、高污染","低端化、同质化、分散化","智能化、绿色化、融合化"],"answer":3,"explanation":"建设现代化产业体系要坚持智能化、绿色化、融合化方向，推动产业转型升级；其余三项均与高质量发展要求背道而驰。故选D。","__sub":"习思想"},{"id":"zz-31112","module":"zhengzhi","prompt":"习近平总书记强调，要把握的新机遇是：","options":["新一轮科技革命和产业变革","新一轮房地产扩张","新一轮粗放增长","新一轮要素堆积"],"answer":0,"explanation":"要把握新一轮科技革命和产业变革新机遇，促进数字经济和实体经济深度融合，抢占发展制高点；房地产扩张、粗放增长均非新机遇。故选A。","__sub":"习思想"},{"id":"zz-31113","module":"zhengzhi","prompt":"推动经济社会发展绿色化、低碳化是实现高质量发展的：","options":["次要环节","关键环节","临时任务","附加要求"],"answer":1,"explanation":"党的二十大报告指出，推动经济社会发展绿色化、低碳化是实现高质量发展的关键环节，必须加快发展方式绿色转型。故选B。","__sub":"习思想"},{"id":"zz-31114","module":"zhengzhi","prompt":"建设现代化产业体系，要求保持：","options":["制造业合理比重","房地产超高比重","虚拟经济主导比重","初级产品出口比重"],"answer":0,"explanation":"建设现代化产业体系要保持制造业合理比重，巩固壮大实体经济根基；虚拟经济主导、初级产品出口比重过高均不利于产业体系现代化。故选A。","__sub":"习思想"},{"id":"zz-31115","module":"zhengzhi","prompt":"强化科技创新的主体地位，其主体是：","options":["政府","个人","企业","中介机构"],"answer":2,"explanation":"强化企业科技创新主体地位，推动创新要素向企业集聚，促进产学研深度融合；政府主要提供制度环境，个人和中介机构不是创新主体。故选C。","__sub":"习思想"},{"id":"zz-31116","module":"zhengzhi","prompt":"金融「五篇大文章」不包括：","options":["科技金融","绿色金融","普惠金融","房地产金融"],"answer":3,"explanation":"做好科技金融、绿色金融、普惠金融、养老金融、数字金融五篇大文章，是建设金融强国的重要任务；房地产金融不在其中。故选D。","__sub":"习思想"},{"id":"zz-31117","module":"zhengzhi","prompt":"京津冀协同发展的「牛鼻子」是：","options":["扩大北京城市规模","统一三地财政","疏解北京非首都功能","取消区域规划"],"answer":2,"explanation":"疏解北京非首都功能是京津冀协同发展的「牛鼻子」，通过功能疏解优化区域空间布局和经济结构，带动三地协同发展。故选C。","__sub":"习思想"},{"id":"zz-31118","module":"zhengzhi","prompt":"我国正在建设的中国特色自由贸易港是：","options":["海南自由贸易港","深圳自由贸易港","浦东自由贸易港","雄安自由贸易港"],"answer":0,"explanation":"海南自由贸易港是我国唯一的中国特色自由贸易港，按照总体方案分步骤、分阶段推进建设，打造引领我国新时代对外开放的鲜明旗帜。故选A。","__sub":"习思想"},{"id":"zz-31119","module":"zhengzhi","prompt":"营造的一流营商环境是：","options":["行政化、封闭化、区域化","人情化、随意化、地方化","保护化、壁垒化、单一化","市场化、法治化、国际化"],"answer":3,"explanation":"营造市场化、法治化、国际化一流营商环境，是高水平对外开放的重要内容，有利于稳定市场预期、提振发展信心。故选D。","__sub":"习思想"},{"id":"zz-31120","module":"zhengzhi","prompt":"新时代东北振兴的定位是：","options":["单一产业振兴","局部振兴","阶段性振兴","全面振兴"],"answer":3,"explanation":"推动新时代东北全面振兴，要扬长补短、发挥优势，形成对国家重大战略的坚强支撑；单一产业振兴、局部振兴均不完整。故选D。","__sub":"习思想"},{"id":"zz-31121","module":"zhengzhi","prompt":"长江经济带发展的基本要求是：","options":["先开发后保护","大开发大发展","共抓大保护、不搞大开发","只保护不发展"],"answer":2,"explanation":"长江经济带发展坚持共抓大保护、不搞大开发，把生态修复摆在压倒性位置，走生态优先、绿色发展之路。故选C。","__sub":"习思想"},{"id":"zz-31122","module":"zhengzhi","prompt":"下列属于战略性新兴产业的是：","options":["传统纺织业","低端加工业","新一代信息技术产业","高耗能采掘业"],"answer":2,"explanation":"战略性新兴产业包括新一代信息技术、新能源、新材料、高端装备、生物医药等，代表新一轮科技革命和产业变革方向。故选C。","__sub":"习思想"},{"id":"zz-31123","module":"zhengzhi","prompt":"围绕发展新质生产力布局产业链，要提升：","options":["产业链供应链韧性和安全水平","产业链的封闭程度","单一环节的垄断地位","对外依赖程度"],"answer":0,"explanation":"围绕发展新质生产力布局产业链，提升产业链供应链韧性和安全水平，保证产业体系自主可控、安全可靠。故选A。","__sub":"习思想"},{"id":"zz-31124","module":"zhengzhi","prompt":"国资国企改革的目标是：","options":["全面私有化国有企业","冻结国企改革","削弱国有经济功能","做强做优做大国有资本和国有企业"],"answer":3,"explanation":"深化国资国企改革，推动国有资本和国有企业做强做优做大，增强核心功能、提升核心竞争力，发挥国有经济战略支撑作用。故选D。","__sub":"习思想"},{"id":"zz-31125","module":"zhengzhi","prompt":"支持中小企业发展的方向是：","options":["专精特新","大而全","同质化","低水平重复"],"answer":0,"explanation":"支持中小企业走专精特新发展道路，提升专业化、精细化、特色化、新颖化水平，培育更多专精特新「小巨人」企业。故选A。","__sub":"习思想"},{"id":"zz-31126","module":"zhengzhi","prompt":"打通从科技强到产业强、经济强的通道，关键环节是：","options":["科技成果转化","论文数量增长","实验室封闭运行","成果束之高阁"],"answer":0,"explanation":"加强科技成果转化，打通从科技强到产业强、经济强的通道，让创新成果加快转化为现实生产力；论文导向、封闭运行、束之高阁均阻碍转化。故选A。","__sub":"习思想"},{"id":"zz-31127","module":"zhengzhi","prompt":"我国控制温室气体排放的市场化手段是：","options":["全国碳排放权交易市场","全面禁止工业生产","取消能源消费","停止经济发展"],"answer":0,"explanation":"建设完善全国碳排放权交易市场，利用市场机制控制和减少温室气体排放，是实现「双碳」目标的重要政策工具。故选A。","__sub":"习思想"},{"id":"zz-31128","module":"zhengzhi","prompt":"构建新型能源体系的方向是：","options":["高碳粗放、单一依赖","高耗能、高排放","低效、分散、无序","清洁低碳、安全高效"],"answer":3,"explanation":"加快构建清洁低碳、安全高效的能源体系，推动能源生产和消费革命，保障国家能源安全。故选D。","__sub":"习思想"},{"id":"zz-31129","module":"zhengzhi","prompt":"高标准市场体系建设的基础制度包括：","options":["价格管制、配额分配","行政垄断、地区封锁","审批限制、准入歧视","产权保护、市场准入、公平竞争、社会信用"],"answer":3,"explanation":"产权保护、市场准入、公平竞争、社会信用等基础制度是高标准市场体系的基石，为要素市场化配置提供制度保障。故选D。","__sub":"习思想"},{"id":"zz-31130","module":"zhengzhi","prompt":"健全宏观经济治理体系，要求加强：","options":["逆周期和跨周期调节","顺周期放任调节","单一工具调节","临时性突击调节"],"answer":0,"explanation":"健全宏观经济治理体系，加强逆周期和跨周期调节，提高宏观调控的科学性、有效性，保持经济运行在合理区间。故选A。","__sub":"习思想"},{"id":"zz-31131","module":"zhengzhi","prompt":"实施质量强国建设的要求是：","options":["数量第一、规模优先","速度第一、成本优先","质量第一、效益优先","产量第一、价格优先"],"answer":2,"explanation":"实施质量强国建设，坚持质量第一、效益优先，提升产品和服务质量水平，增强产业质量竞争力。故选C。","__sub":"习思想"},{"id":"zz-31132","module":"zhengzhi","prompt":"共同富裕的定位是：","options":["少数人先富的代名词","社会主义的本质要求，是中国式现代化的重要特征","平均主义的翻版","遥不可及的口号"],"answer":1,"explanation":"共同富裕是社会主义的本质要求，是中国式现代化的重要特征，体现了社会主义制度的优越性；平均主义、少数人富裕均曲解其内涵。故选B。","__sub":"习思想"},{"id":"zz-31133","module":"zhengzhi","prompt":"促进共同富裕要靠：","options":["在高质量发展中实现","杀富济贫","等靠要","高福利养懒汉"],"answer":0,"explanation":"要在高质量发展中促进共同富裕，做大做好「蛋糕」是基础，分好「蛋糕」是关键；杀富济贫、等靠要、高福利养懒汉均不可取。故选A。","__sub":"习思想"},{"id":"zz-31134","module":"zhengzhi","prompt":"对共同富裕的正确理解是：","options":["同步同等富裕","不是整齐划一的平均主义","劫富济贫","政府包办分配"],"answer":1,"explanation":"共同富裕不是整齐划一的平均主义，也不是少数人的富裕，要允许一部分人先富起来，先富带后富、帮后富，分阶段促进。故选B。","__sub":"习思想"},{"id":"zz-31135","module":"zhengzhi","prompt":"实现共同富裕的途径是：","options":["鼓励先富带后富、帮后富","限制先富、均贫富","坐等分配","取消市场机制"],"answer":0,"explanation":"共同富裕要靠共同奋斗，鼓励先富带后富、帮后富，构建初次分配、再分配、第三次分配协调配套的制度体系。故选A。","__sub":"习思想"},{"id":"zz-31136","module":"zhengzhi","prompt":"共同富裕的内涵是：","options":["只有物质富裕","人民群众物质生活和精神生活都富裕","只有精神富足","少数群体富裕"],"answer":1,"explanation":"共同富裕是人民群众物质生活和精神生活都富裕，既要「富口袋」也要「富脑袋」，促进人的全面发展。故选B。","__sub":"习思想"},{"id":"zz-31137","module":"zhengzhi","prompt":"构建协调配套的分配制度体系包括：","options":["单一工资分配","实物分配","初次分配、再分配、第三次分配","配给制分配"],"answer":2,"explanation":"构建初次分配、再分配、第三次分配协调配套的制度体系，提高发展的平衡性、协调性、包容性，扩大中等收入群体。故选C。","__sub":"习思想"},{"id":"zz-31138","module":"zhengzhi","prompt":"乡村振兴包括的「五个振兴」是：","options":["农业、农村、农民、农民工、农地","种植、养殖、加工、销售、物流","产业振兴、人才振兴、文化振兴、生态振兴、组织振兴","县、乡、村、组、户"],"answer":2,"explanation":"乡村「五个振兴」即产业振兴、人才振兴、文化振兴、生态振兴、组织振兴，统筹推进乡村全面振兴。故选C。","__sub":"习思想"},{"id":"zz-31139","module":"zhengzhi","prompt":"全面推进乡村振兴要加快的目标是：","options":["农村城镇化","农业农村现代化","农业工业化","农村商业化"],"answer":1,"explanation":"全面推进乡村振兴，加快农业农村现代化，是新时代「三农」工作的总目标，促进农业高质高效、乡村宜居宜业、农民富裕富足。故选B。","__sub":"习思想"},{"id":"zz-31140","module":"zhengzhi","prompt":"脱贫攻坚胜利后要做的衔接是：","options":["同城镇化衔接","同乡村振兴有效衔接","同工业化衔接","同信息化衔接"],"answer":1,"explanation":"巩固拓展脱贫攻坚成果，同乡村振兴有效衔接，让脱贫基础更加稳固、成效更可持续，防止规模性返贫。故选B。","__sub":"习思想"},{"id":"zz-31141","module":"zhengzhi","prompt":"保障国家粮食安全的耕地底线是：","options":["十亿亩耕地红线","三十亿亩耕地红线","十八亿亩耕地红线","五亿亩耕地红线"],"answer":2,"explanation":"牢牢守住十八亿亩耕地红线，落实最严格的耕地保护制度，确保中国人的饭碗牢牢端在自己手中。故选C。","__sub":"习思想"},{"id":"zz-31142","module":"zhengzhi","prompt":"落实粮食安全责任的要求是：","options":["只由农业部门负责","只由农民负责","无人负责","党政同责"],"answer":3,"explanation":"实行粮食安全党政同责，压实地方党委和政府保面积、保产量的责任，调动农民种粮积极性。故选D。","__sub":"习思想"},{"id":"zz-31143","module":"zhengzhi","prompt":"种业振兴的目标是：","options":["依赖进口种源","种源自主可控","放弃种业研发","任由种源外流"],"answer":1,"explanation":"把种源安全提升到关系国家安全的战略高度，实现种业科技自立自强、种源自主可控，从源头上保障粮食安全。故选B。","__sub":"习思想"},{"id":"zz-31144","module":"zhengzhi","prompt":"第二轮土地承包到期后的政策是：","options":["再延长三十年","重新收回承包地","全面私有化","终止承包关系"],"answer":0,"explanation":"保持土地承包关系稳定并长久不变，第二轮土地承包到期后再延长三十年，给农民吃下「定心丸」。故选A。","__sub":"习思想"},{"id":"zz-31145","module":"zhengzhi","prompt":"农村基本经营制度的核心是：","options":["土地私有化","土地集体所有、家庭承包经营","土地国有化经营","集体统一耕种"],"answer":1,"explanation":"坚持农村土地集体所有、家庭承包经营基础性地位，是农村基本经营制度的核心，必须长期坚持并不断完善。故选B。","__sub":"习思想"},{"id":"zz-31146","module":"zhengzhi","prompt":"新型农业经营主体包括：","options":["单一散户","家庭农场和农民合作社","行政村委会","城市工商资本独营"],"answer":1,"explanation":"培育家庭农场、农民合作社等新型农业经营主体，健全农业社会化服务体系，带动小农户融入现代农业发展。故选B。","__sub":"习思想"},{"id":"zz-31147","module":"zhengzhi","prompt":"建设农业强国的头等大事是：","options":["保障粮食和重要农产品稳定安全供给","扩大农业对外依存度","压缩农业投入","放弃粮食自给"],"answer":0,"explanation":"保障粮食和重要农产品稳定安全供给始终是建设农业强国的头等大事，必须全方位夯实粮食安全根基。故选A。","__sub":"习思想"},{"id":"zz-31148","module":"zhengzhi","prompt":"党的二十大后乡村建设的目标是：","options":["整齐划一的样板村","千村一面的新村","单纯景观化村庄","宜居宜业和美乡村"],"answer":3,"explanation":"建设宜居宜业和美乡村，是农业强国的应有之义，要体现农村特点、保留乡村风貌、留住田园乡愁。故选D。","__sub":"习思想"},{"id":"zz-31149","module":"zhengzhi","prompt":"城乡融合发展的关键是：","options":["城乡要素单向流动","农村单向输出","促进城乡要素平等交换、双向流动","城市封闭发展"],"answer":2,"explanation":"健全城乡融合发展体制机制，促进城乡要素平等交换、双向流动，推动公共服务向农村延伸、社会事业向农村覆盖。故选C。","__sub":"习思想"},{"id":"zz-31150","module":"zhengzhi","prompt":"「三农」工作的中心任务是：","options":["增加农民收入","增加财政投入","扩大城镇规模","提高工业产值"],"answer":0,"explanation":"把增加农民收入作为「三农」工作的中心任务，多渠道促进农民增收，让农民腰包越来越鼓。故选A。","__sub":"习思想"},{"id":"zz-31151","module":"zhengzhi","prompt":"乡村治理体系的「三治」是：","options":["人治、法治、心治","乡治、村治、民治","自治、法治、德治","官治、民治、共治"],"answer":2,"explanation":"健全党组织领导的自治、法治、德治相结合的乡村治理体系，建设充满活力、和谐有序的善治乡村。故选C。","__sub":"习思想"},{"id":"zz-31152","module":"zhengzhi","prompt":"农村精神文明建设的重点之一是：","options":["大操大办红白喜事","攀比铺张浪费","推进移风易俗","封建迷信活动"],"answer":2,"explanation":"加强农村精神文明建设，推进移风易俗，培育文明乡风、良好家风、淳朴民风，焕发乡村文明新气象。故选C。","__sub":"习思想"},{"id":"zz-31153","module":"zhengzhi","prompt":"新型城镇化建设的重要载体是：","options":["县城","超大城市","偏远乡村","开发区"],"answer":0,"explanation":"推进以县城为重要载体的城镇化建设，增强县城综合承载能力，带动乡村发展和县域经济壮大。故选A。","__sub":"习思想"},{"id":"zz-31154","module":"zhengzhi","prompt":"党中央支持建设共同富裕示范区的是：","options":["广东","浙江","江苏","山东"],"answer":1,"explanation":"支持浙江高质量发展建设共同富裕示范区，探索有效路径、总结实践经验，为全国提供省域范例。故选B。","__sub":"习思想"},{"id":"zz-31155","module":"zhengzhi","prompt":"推进共同富裕要促进：","options":["公共服务差异化","服务特权化","服务商品化","基本公共服务均等化"],"answer":3,"explanation":"促进基本公共服务均等化，加大普惠性人力资本投入，兜牢民生底线，让发展成果更多更公平惠及全体人民。故选D。","__sub":"习思想"},{"id":"zz-31156","module":"zhengzhi","prompt":"优化收入分配结构，要扩大：","options":["低收入群体","中等收入群体","贫困群体","特权群体"],"answer":1,"explanation":"扩大中等收入群体规模，形成橄榄型分配结构，是实现共同富裕的重要途径，有利于扩大内需、促进社会稳定。故选B。","__sub":"习思想"},{"id":"zz-31157","module":"zhengzhi","prompt":"过渡期内对脱贫地区的政策要求是：","options":["全部取消帮扶政策","保持主要帮扶政策总体稳定","立即停止支持","只给资金不帮扶"],"answer":1,"explanation":"过渡期内保持主要帮扶政策总体稳定，严格落实「四个不摘」要求，确保脱贫成果持续巩固。故选B。","__sub":"习思想"},{"id":"zz-31158","module":"zhengzhi","prompt":"守住不发生规模性返贫底线的机制是：","options":["事后救济机制","临时性慰问机制","单一补贴机制","防止返贫动态监测和帮扶机制"],"answer":3,"explanation":"健全防止返贫动态监测和帮扶机制，对脱贫不稳定户、边缘易致贫户早发现、早干预、早帮扶。故选D。","__sub":"习思想"},{"id":"zz-31159","module":"zhengzhi","prompt":"做好乡村产业，要念好的「土特产」三字诀是指：","options":["土法生产、特产专卖、土地买卖","依托乡土资源、发展特色产业、打造优质品牌","土地流转、特产加工、产业外包","土坯房、特产店、产业园"],"answer":1,"explanation":"做好「土特产」文章，即依托农业农村特色资源，发展特色产业，打造优质品牌，推动乡村产业全链条升级。故选B。","__sub":"习思想"},{"id":"zz-31160","module":"zhengzhi","prompt":"深化农村集体产权制度改革，要发展：","options":["私人集体经济","新型农村集体经济","行政化集体经济","外资集体经济"],"answer":1,"explanation":"深化农村集体产权制度改革，发展新型农村集体经济，盘活集体资产，拓宽农民增收渠道。故选B。","__sub":"习思想"},{"id":"zz-31161","module":"zhengzhi","prompt":"耕地保护要坚决遏制和防止的是：","options":["耕地撂荒复垦","高标准农田建设","耕地质量提升","耕地「非农化」、「非粮化」"],"answer":3,"explanation":"坚决遏制耕地「非农化」、防止「非粮化」，规范耕地占补平衡，确保耕地数量不减、质量提升。故选D。","__sub":"习思想"},{"id":"zz-31162","module":"zhengzhi","prompt":"建设教育强国的龙头是：","options":["高等教育","学前教育","职业教育","成人教育"],"answer":0,"explanation":"建设教育强国，基点在基础教育，龙头是高等教育，要加快建设中国特色、世界一流的大学和优势学科。故选A。","__sub":"习思想"},{"id":"zz-31163","module":"zhengzhi","prompt":"建设教育强国的基点是：","options":["高等教育","研究生教育","继续教育","基础教育"],"answer":3,"explanation":"建设教育强国，基点在基础教育，基础教育搞得越扎实，教育强国步伐就越稳、后劲就越足。故选D。","__sub":"习思想"},{"id":"zz-31164","module":"zhengzhi","prompt":"教育的根本问题是：","options":["建多少学校、招多少学生","发多少文凭、评多少职称","投多少经费、盖多少楼","培养什么人、怎样培养人、为谁培养人"],"answer":3,"explanation":"培养什么人、怎样培养人、为谁培养人是教育的根本问题，要培养德智体美劳全面发展的社会主义建设者和接班人。故选D。","__sub":"习思想"},{"id":"zz-31165","module":"zhengzhi","prompt":"落实立德树人根本任务的关键课程是：","options":["专业课","选修课","思政课","体育课"],"answer":2,"explanation":"思政课是落实立德树人根本任务的关键课程，要办好思想政治理论课，用习近平新时代中国特色社会主义思想铸魂育人。故选C。","__sub":"习思想"},{"id":"zz-31166","module":"zhengzhi","prompt":"高等教育发展的目标是：","options":["建设中国特色、世界一流大学和优势学科","照搬国外大学模式","扩大招生规模为主","追求论文数量"],"answer":0,"explanation":"加快建设中国特色、世界一流的大学和优势学科，提升原始创新能力和人才培养质量，服务国家重大战略需求。故选A。","__sub":"习思想"},{"id":"zz-31167","module":"zhengzhi","prompt":"促进教育公平要缩小的差距是：","options":["师生年龄差距","城乡、区域、校际差距","教材版本差距","考试科目差距"],"answer":1,"explanation":"促进教育公平，缩小城乡、区域、校际差距，让每个孩子都能享有公平而有质量的教育。故选B。","__sub":"习思想"},{"id":"zz-31168","module":"zhengzhi","prompt":"教师队伍建设要弘扬的是：","options":["功利化倾向","逐利心态","躺平风气","教育家精神"],"answer":3,"explanation":"大力弘扬教育家精神，即心有大我、至诚报国的理想信念，言为士则、行为世范的道德情操等，建设高素质专业化教师队伍。故选D。","__sub":"习思想"},{"id":"zz-31169","module":"zhengzhi","prompt":"建设学习型社会、学习型大国，要构建的是：","options":["一次性学历教育体系","封闭培训体系","单一学校教育体系","全民终身学习体系"],"answer":3,"explanation":"建设全民终身学习的学习型社会、学习型大国，推进教育数字化，让每个人随时随地都能学习。故选D。","__sub":"习思想"},{"id":"zz-31170","module":"zhengzhi","prompt":"我国建成科技强国的目标年份是：","options":["2030年","2035年","2040年","2050年"],"answer":1,"explanation":"到2035年建成科技强国，是党中央对科技事业作出的战略安排，要求高水平科技自立自强取得重要进展。故选B。","__sub":"习思想"},{"id":"zz-31171","module":"zhengzhi","prompt":"实现高水平科技自立自强，要加强的基础环节是：","options":["应用外包","技术引进","设备采购","基础研究"],"answer":3,"explanation":"加强基础研究，突出原创，鼓励自由探索，筑牢科技创新根基，实现更多「从0到1」的突破。故选D。","__sub":"习思想"},{"id":"zz-31172","module":"zhengzhi","prompt":"关键核心技术的特点是：","options":["随时可以引进","要不来、买不来、讨不来","完全依赖进口","可有可无"],"answer":1,"explanation":"关键核心技术是要不来、买不来、讨不来的，必须依靠自主创新，把科技命脉牢牢掌握在自己手中。故选B。","__sub":"习思想"},{"id":"zz-31173","module":"zhengzhi","prompt":"关键核心技术攻关的组织方式是：","options":["新型举国体制","单打独斗","完全市场化放任","依赖外部援助"],"answer":0,"explanation":"健全关键核心技术攻关新型举国体制，集中力量办大事，发挥国家作为重大科技创新组织者的作用。故选A。","__sub":"习思想"},{"id":"zz-31174","module":"zhengzhi","prompt":"推动创新链、产业链、资金链、人才链深度融合，目的是：","options":["割裂创新与产业","资金空转套利","人才闲置浪费","提高科技成果转化和产业化水平"],"answer":3,"explanation":"推动创新链产业链资金链人才链深度融合，促进创新要素高效配置，提高科技成果转化和产业化水平。故选D。","__sub":"习思想"},{"id":"zz-31175","module":"zhengzhi","prompt":"深入实施人才强国战略，要求坚持：","options":["党管人才原则","放任人才流动","封闭人才使用","限制人才引进"],"answer":0,"explanation":"坚持党管人才原则，深入实施人才强国战略，聚天下英才而用之，加快建设世界重要人才中心和创新高地。故选A。","__sub":"习思想"},{"id":"zz-31176","module":"zhengzhi","prompt":"全面提高的是人才工作的：","options":["自主培养质量","引进依赖度","外购比例","存量闲置率"],"answer":0,"explanation":"全面提高人才自主培养质量，着力造就拔尖创新人才，夯实高质量发展和高水平科技自立自强的人才根基。故选A。","__sub":"习思想"},{"id":"zz-31177","module":"zhengzhi","prompt":"科技领军人才中特别需要培养使用的是：","options":["战略科学家","单一技术员","行政管理者","纯理论家"],"answer":0,"explanation":"大力培养使用战略科学家，形成大批一流科技领军人才和创新团队，支撑国家重大科技任务。故选A。","__sub":"习思想"},{"id":"zz-31178","module":"zhengzhi","prompt":"推进职普融通、产教融合、科教融汇，是为了：","options":["取消职业教育","普教职教对立","优化职业教育类型定位","教育与产业脱节"],"answer":2,"explanation":"统筹职业教育、高等教育、继续教育协同创新，推进职普融通、产教融合、科教融汇，培养高素质技术技能人才。故选C。","__sub":"习思想"},{"id":"zz-31179","module":"zhengzhi","prompt":"义务教育发展的方向是：","options":["重点校优先","优质均衡","择校热加剧","城乡分化"],"answer":1,"explanation":"推进义务教育优质均衡发展，加快缩小办学条件差距，办好人民满意的教育。故选B。","__sub":"习思想"},{"id":"zz-31180","module":"zhengzhi","prompt":"科技创新与科学普及的关系是：","options":["科普可有可无","科普替代创新","科学普及与科技创新同等重要","创新无需科普"],"answer":2,"explanation":"科技创新、科学普及是实现创新发展的两翼，要把科学普及放在与科技创新同等重要的位置。故选C。","__sub":"习思想"},{"id":"zz-31181","module":"zhengzhi","prompt":"教师评价的第一标准是：","options":["师德师风","论文数量","课时多少","职称高低"],"answer":0,"explanation":"把师德师风作为教师评价第一标准，引导广大教师以德立身、以德立学、以德施教。故选A。","__sub":"习思想"},{"id":"zz-31182","module":"zhengzhi","prompt":"国家战略科技力量的重要组成部分包括：","options":["国家实验室","地方小作坊","个人工作室","中介咨询机构"],"answer":0,"explanation":"组建国家实验室，重组国家重点实验室体系，强化国家战略科技力量，打造原始创新策源地。故选A。","__sub":"习思想"},{"id":"zz-31183","module":"zhengzhi","prompt":"人才工作的重要原则是：","options":["闭关自守","聚天下英才而用之","人才壁垒","任人唯亲"],"answer":1,"explanation":"聚天下英才而用之，实行更加积极、开放、有效的人才政策，形成具有国际竞争力的人才制度体系。故选B。","__sub":"习思想"},{"id":"zz-31184","module":"zhengzhi","prompt":"支持青年科技人才的要求是：","options":["只当配角","挑大梁、当主角","论资排辈","坐等提拔"],"answer":1,"explanation":"支持青年科技人才挑大梁、当主角，在重大科技任务中给机会、搭平台，让青年人才脱颖而出。故选B。","__sub":"习思想"},{"id":"zz-31185","module":"zhengzhi","prompt":"与教育强国建设相关的三大战略是：","options":["区域协调战略、乡村振兴战略、新型城镇化战略","科教兴国战略、人才强国战略、创新驱动发展战略","制造强国战略、质量强国战略、贸易强国战略","海洋强国战略、航天强国战略、网络强国战略"],"answer":1,"explanation":"深入实施科教兴国战略、人才强国战略、创新驱动发展战略，坚持教育优先发展、科技自立自强、人才引领驱动。故选B。","__sub":"习思想"},{"id":"zz-31186","module":"zhengzhi","prompt":"科技创新的国际合作方向是：","options":["主动融入全球创新网络","闭门造车","技术封锁","单边孤立"],"answer":0,"explanation":"深化国际科技交流合作，主动融入全球创新网络，用好国内国际两种创新资源，提升开放创新能力。故选A。","__sub":"习思想"},{"id":"zz-31187","module":"zhengzhi","prompt":"培养大国工匠和高技能人才，属于：","options":["行政人才建设","理论人才建设","技能人才队伍建设","外交人才建设"],"answer":2,"explanation":"培养更多大国工匠、高技能人才，壮大技术技能人才队伍，支撑制造强国、质量强国建设。故选C。","__sub":"习思想"},{"id":"zz-31188","module":"zhengzhi","prompt":"人才发展体制机制改革的方向是：","options":["强化行政管制","增加审批环节","向用人主体授权、为人才松绑","束缚人才活力"],"answer":2,"explanation":"深化人才发展体制机制改革，向用人主体授权、为人才松绑，让人才创新创造活力充分迸发。故选C。","__sub":"习思想"},{"id":"zz-31189","module":"zhengzhi","prompt":"坚持教育优先发展、科技自立自强、人才引领驱动，是为了：","options":["割裂三者关系","单一发展教育","形成推动高质量发展的倍增效应","只重科技投入"],"answer":2,"explanation":"坚持教育优先发展、科技自立自强、人才引领驱动，统筹推进教育科技人才一体化发展，形成倍增效应。故选C。","__sub":"习思想"},{"id":"zz-31190","module":"zhengzhi","prompt":"完善党中央对科技工作的统一领导体制，体现的是：","options":["党对科技事业的全面领导","科技工作无序发展","部门各自为政","地方分散决策"],"answer":0,"explanation":"完善党中央对科技工作统一领导的体制，发挥党总揽全局、协调各方的领导核心作用，集中力量推进科技自立自强。故选A。","__sub":"习思想"},{"id":"zz-31191","module":"zhengzhi","prompt":"加快建设世界重要人才中心和创新高地，是人才强国战略的：","options":["次要任务","临时安排","重要目标","放弃目标"],"answer":2,"explanation":"加快建设世界重要人才中心和创新高地，是深入实施人才强国战略的重要目标，为实现高水平科技自立自强提供人才支撑。故选C。","__sub":"习思想"},{"id":"zz-31192","module":"zhengzhi","prompt":"我国社会主义民主的两种重要形式是：","options":["直接民主和间接民主","党内民主和党外民主","选举民主和协商民主","城市民主和农村民主"],"answer":2,"explanation":"我国社会主义民主有两种重要形式：选举民主和协商民主，二者相互补充、相得益彰，共同构成全过程人民民主的实践形态。故选C。","__sub":"习思想"},{"id":"zz-31193","module":"zhengzhi","prompt":"全国人大及其常委会的职权包括：","options":["行政权、审判权、检察权","立法权、监督权、决定权、任免权","军事指挥权、外交权","司法终审权、赦免权"],"answer":1,"explanation":"全国人大及其常委会行使立法权、监督权、决定权、任免权等职权，行政权、审判权、检察权分别由行政机关和司法机关行使。故选B。","__sub":"习思想"},{"id":"zz-31194","module":"zhengzhi","prompt":"人大代表的职责是：","options":["只代表部门利益","只参加一年一次会议","当好党和国家联系人民群众的桥梁","不联系群众"],"answer":2,"explanation":"人大代表要密切同人民群众的联系，当好党和国家联系人民群众的桥梁，倾听民声、反映民意、汇聚民智。故选C。","__sub":"习思想"},{"id":"zz-31195","module":"zhengzhi","prompt":"协商民主的精髓是：","options":["少数人说了算","暗箱操作","形式主义协商","有事好商量，众人的事情由众人商量"],"answer":3,"explanation":"协商民主的精髓在于有事好商量、众人的事情由众人商量，通过广泛协商凝聚共识，找到全社会意愿和要求的最大公约数。故选D。","__sub":"习思想"},{"id":"zz-31196","module":"zhengzhi","prompt":"人民政协是社会主义协商民主的：","options":["行政机关","立法机关","重要渠道和专门协商机构","司法机关"],"answer":2,"explanation":"人民政协是社会主义协商民主的重要渠道和专门协商机构，在国家政治生活中发挥重要作用。故选C。","__sub":"习思想"},{"id":"zz-31197","module":"zhengzhi","prompt":"人民政协的主要职能是：","options":["立法、执法、司法","决策、执行、监督","选举、任免、罢免","政治协商、民主监督、参政议政"],"answer":3,"explanation":"政治协商、民主监督、参政议政是人民政协的主要职能，立法、执法、司法分别属于人大和司法机关。故选D。","__sub":"习思想"},{"id":"zz-31198","module":"zhengzhi","prompt":"基层群众自治制度的主要形式包括：","options":["乡镇政府","村民委员会、居民委员会、职工代表大会","县人大常委会","省级政协"],"answer":1,"explanation":"村民委员会、居民委员会和职工代表大会是基层群众自治的主要形式，实现人民直接行使民主权利。故选B。","__sub":"习思想"},{"id":"zz-31199","module":"zhengzhi","prompt":"设立基层立法联系点的目的是：","options":["增加立法层级","限制公众参与","使立法直达基层、听取原汁原味的民意","形式化走过场"],"answer":2,"explanation":"设立基层立法联系点，使国家立法直达基层，听取原汁原味的民意，是发展全过程人民民主的生动实践。故选C。","__sub":"习思想"},{"id":"zz-31200","module":"zhengzhi","prompt":"统一战线的主题是：","options":["小圈子协商","部门利益联合","大团结大联合","临时性联合"],"answer":2,"explanation":"统一战线的主题是大团结大联合，坚持一致性和多样性统一，动员全体中华儿女共同致力于民族复兴。故选C。","__sub":"习思想"}]);